/**
 * FAQ data for top calculators.
 * Used for FAQPage schema + rendered FAQ section.
 */
export interface FAQ {
  question: string
  answer: string
}

export const CALCULATOR_FAQS: Record<string, FAQ[]> = {
  'income-tax-calculator': [
    { question: `What is the Personal Allowance for 2026/27?`, answer: `The Personal Allowance for 2026/27 is £12,570, the amount of income you can earn each tax year before any income tax is due, and it applies automatically to most UK residents. It is not the same for everyone, though. People with certain tax codes, for example those carrying unpaid tax from a previous year, may have a reduced effective allowance, and it is withdrawn entirely from the highest earners. The figure is published by HMRC at gov.uk/income-tax-rates.` },
    { question: `What are the UK income tax bands for 2026/27?`, answer: `For England, Wales and Northern Ireland, income tax is charged in three main bands above the £12,570 Personal Allowance. The Basic Rate of 20% applies to taxable income from £12,571 to £50,270, so a salary of £35,000 attracts 20% on approximately £22,430, equalling £4,486. The Higher Rate of 40% runs from £50,271 to £125,140, and the Additional Rate of 45% applies above £125,140. These bands cover employment income, self-employment profits, rental income and most other sources, while dividends and capital gains are taxed under their own rates.` },
    { question: `How does the Personal Allowance taper work above £100,000?`, answer: `Once your adjusted net income exceeds £100,000, the allowance is reduced by £1 for every £2 above that threshold and reaches zero at £125,140. The result is an effective marginal rate of 60% on income in between. You pay 40% Higher Rate tax on the income itself, and the loss of each £1 of allowance means an additional £1 that was previously untaxed becomes taxable at 40%, adding a further 20p in tax per £2 earned. Making additional pension contributions reduces adjusted net income and can restore part or all of the allowance.` },
    { question: `Does this calculator work for Scottish taxpayers?`, answer: `No. It uses the standard UK rates for England, Wales and Northern Ireland. Scotland has its own six-band system set by the Scottish Parliament, and for 2026/27 the rates are Starter 19% from £12,571 to £16,537, Basic 20% to £29,526, Intermediate 21% to £43,662, Higher 42% to £75,000, Advanced 45% to £125,140 and Top 48% above that. Scottish taxpayers should use the dedicated Scottish Income Tax Calculator on this site, which applies those bands and thresholds correctly.` },
  ],
  'national-insurance-calculator': [
    { question: `What are the employer and self-employed NI rates for 2026/27?`, answer: `Employer Class 1 secondary contributions run at 15% on earnings above the £5,000 Secondary Threshold, up from 13.8% and a £9,100 threshold before April 2025, and the Employment Allowance of £10,500 a year cuts that bill for eligible small employers. Self-employed people pay Class 4 at 6% on profits between £12,570 and £50,270, then 2% above, using the same thresholds as employees. Class 2 was abolished from 6 April 2024 and is no longer payable.` },
    { question: `Why am I paying NI but my colleague isn't?`, answer: `Several things can explain it. You may be over the £12,570 Primary Threshold while they are not, or they may have passed State Pension age at 66 and become exempt. Different NI categories also apply, including apprentices under 25 and the married women's reduced rate for anyone who elected into it before 1977. Salary sacrifice can pull someone's pay below the threshold, statutory absence such as SMP or SSP reduces the earnings NI is charged on, and staff working overseas under a bilateral agreement may contribute elsewhere.` },
    { question: `How many NI years do I need for the full State Pension?`, answer: `You need 35 qualifying years for the full amount, which is £241.30 a week in 2026/27. Each year of contributions adds roughly £6.89 a week to what you eventually receive, so individual years count rather than only the total. Any year in which you actually pay NI is recorded automatically. Your record and forecast are at gov.uk/check-state-pension, and it is worth looking well before retirement while gaps can still be dealt with.` },
    { question: `Can I earn NI credits without paying contributions?`, answer: `Yes. Credits fill the gap when you are not earning enough to contribute in cash. They are available while you receive Child Benefit up to your youngest child's 12th birthday, and while claiming Universal Credit, Carer's Allowance, Jobseeker's Allowance or Statutory Sick Pay. Employees earning between the Lower Earnings Limit of £6,708 and the Primary Threshold of £12,570 also build qualifying years without paying anything. A year with neither contributions nor a credit shows on your record as a gap.` },
  ],
  'vat-calculator': [
    { question: `When do I need to register for VAT?`, answer: `Registration is compulsory once taxable turnover passes £90,000 in any rolling 12-month period, the 2026/27 threshold, raised from £85,000 in April 2024, and you have 30 days to complete it. A forward test also applies: if you expect £90,000 in the next 30 days alone, register immediately. Voluntary registration is permitted at any level. Once registered you charge VAT on your supplies and submit MTD-compliant quarterly returns, and you can deregister if turnover drops below £88k.` },
    { question: `What is the difference between zero-rated and exempt supplies?`, answer: `Neither puts VAT on the customer's invoice, but they behave very differently for the business. Zero-rated supplies are taxable at 0%, so they count towards your turnover and you can still reclaim the input VAT on the costs behind them. Most food, children's clothing, books, prescription medicines and public transport sit here. Exempt supplies such as insurance, finance, education and healthcare fall outside the VAT system, and input VAT on them cannot be reclaimed. Confusing the two is one of the most common VAT errors.` },
    { question: `How do I find the VAT inside a gross price?`, answer: `Divide it by 6. VAT at 20% is 20/120 of a gross figure, so one sixth of any VAT-inclusive total is the tax itself: £120 gross contains £20 of VAT and £100 of net. What does not work is subtracting 20% from the gross, which gives £96 and understates the net amount. For the 5% reduced rate the equivalent shortcut is to divide the gross by 21, or divide by 1.05 to get back to the net figure.` },
    { question: `Has the standard UK VAT rate always been 20%?`, answer: `No. It has been 20% since January 2011. Before that the standard rate was 17.5% from 1991 to 2010, with a temporary cut to 15% between 2008 and 2010. The reduced rate of 5% and the zero rate have been far more stable over the same period. The 20% figure is what the Add VAT and Remove VAT modes on this page assume unless you pick one of the other rates.` },
  ],
  'stamp-duty-calculator': [
    { question: `What are the Stamp Duty rates for 2026/27?`, answer: `SDLT in England and Northern Ireland for standard residential purchases in 2026/27 is charged in bands: 0% on the first £125,000, 2% on £125,001 to £250,000, 5% on £250,001 to £925,000, 10% on £925,001 to £1.5 million and 12% above £1.5 million. Each rate applies to the portion of the price within that band, not to the whole amount. On a £400,000 purchase that gives £0 on the first £125,000, £2,500 on the next £125,000 and £7,500 on the remaining £150,000, a total of £10,000.` },
    { question: `Do first-time buyers get a Stamp Duty discount?`, answer: `Yes. First-time buyers in England and Northern Ireland pay 0% on the first £300,000 and 5% on the portion from £300,001 to £500,000. Above £500,000 the relief falls away completely and standard rates are charged on the full amount. A first-time buyer purchasing at £450,000 pays £7,500, where standard rates would have produced £12,500. Scotland uses Land and Buildings Transaction Tax and Wales uses Land Transaction Tax, each with different rates and reliefs of their own.` },
    { question: `What is the additional property surcharge?`, answer: `A 5% SDLT surcharge applies when you buy an additional residential property while already owning one or more homes, which catches buy-to-let investors, second-home buyers and anyone who has not yet sold their previous main residence. It is charged on the full purchase price across all bands, so a buy-to-let at £250,000 attracts £2,500 of standard SDLT plus £12,500 of surcharge, £15,000 in total. Sell the original property within 36 months and the surcharge portion can be reclaimed. Corporate bodies and funds buying residential property face a 17% flat rate above £500,000.` },
  ],
  'take-home-pay-calculator': [
    { question: `What deductions come out of my salary?`, answer: `Four main deductions come off your gross salary. Income tax is worked out from your tax code and the UK bands of 20%, 40% and 45%. Employee National Insurance is charged at 8% on earnings between £12,570 and £50,270 and 2% above that. Workplace pension contributions under auto-enrolment are typically 5% of qualifying earnings between £6,240 and £50,270, though many people pay more. Student loan repayments apply if you have a loan: Plan 2 takes 9% above £29,385, Plan 5 takes 9% above £25,000 and a Postgraduate Loan takes 6% above £21,000. Salary sacrifice reduces gross pay before any of these are calculated.` },
    { question: `How is take-home pay calculated in the UK?`, answer: `The deductions run in a set order. Salary sacrifice contributions come off first to give a reduced taxable gross. Income tax is then calculated by deducting the £12,570 Personal Allowance and taxing what remains at 20% up to £37,700, then 40%, then 45%. Employee NI is worked out separately on gross earnings after salary sacrifice at 8% and 2%. Finally, student loan repayments and any pension contributions not made through salary sacrifice are taken off. On a £35,000 salary the result is roughly £27,000–£28,000 a year.` },
    { question: `What is a tax code and how does it affect my pay?`, answer: `A tax code tells your employer how much tax-free income you get each year and drives the PAYE calculation. The most common code is 1257L: the number 1257 means a £12,570 allowance (multiply by 10) and L signals a standard Personal Allowance. M and N indicate Marriage Allowance, K codes mean deductions exceed allowances, T or 0T mean HMRC is reviewing your affairs, BR taxes all income from that source at basic rate (common for second jobs) and D0 deducts 40% on everything. A wrong code causes over- or underpayment, which HMRC can correct once you contact them or update your account at gov.uk.` },
    { question: `Can I work out the gross salary I need for a target take-home pay?`, answer: `Yes. Switch the calculator into reverse mode, enter the monthly or annual take-home figure you want, and it works back through income tax, National Insurance, pension and any student loan to find the gross salary that produces it. The reverse result respects the same toggles as the forward calculation, so you can include salary sacrifice, a particular student loan plan or Scottish tax bands when you are negotiating a salary or comparing job offers.` },
  ],
  'mortgage-repayment-calculator': [
    { question: `What is the difference between repayment and interest-only mortgages?`, answer: `A repayment mortgage covers both the monthly interest and a slice of the capital, so the balance falls each month and reaches zero at the end of the term. Early on, most of the payment is interest. Later, most of it is capital. On £200,000 at 4.5% over 25 years that is roughly £1,112 a month. Interest-only charges the interest alone, £750 a month on the same loan, and the full £200,000 is still owed at the end. Most residential lenders want a credible repayment plan, such as an investment ISA or pension, before agreeing to it. Source: FCA Mortgage Conduct of Business rules.` },
    { question: `How much deposit do I need for a UK mortgage?`, answer: `Most UK residential lenders want a minimum of 5% of the property value, which makes 95% the maximum loan-to-value. Rates improve sharply as the deposit grows, so 95% LTV might attract 5.5-6% while a 25% deposit at 75% LTV could secure 4-4.5%. On a £300,000 property, a 5% deposit of £15,000 leaves repayments near £1,900 a month at 5.5% over 25 years, whereas a £75,000 deposit brings that to about £1,530 at 4.25%. First-time buyers can reach 5% deals through the Mortgage Guarantee Scheme, and buy-to-let usually needs 20-25%.` },
    { question: `What happens to my payments if interest rates rise?`, answer: `It depends entirely on your mortgage type. On a standard variable rate or tracker, payments move as soon as the Bank of England base rate does. On a fix, nothing changes until the deal ends, at which point you revert to the lender's SVR, which averaged 7.13% in September 2026 (Moneyfacts), about 3.4 points above the 3.75% Bank Rate, unless you remortgage. A 2-year fix taken in 2022 at 2% and expiring in 2024 renewed at 4.5-5.5%, which for many borrowers meant £300-£500 more each month on the same balance. Source: Bank of England, FCA.` },
    { question: `Can I overpay my mortgage without paying a penalty?`, answer: `Most UK fixed-rate deals let you overpay up to 10% of the balance each year with no early repayment charge, and once the fixed period ends that ceiling usually disappears, subject to your lender's own terms. The saving justifies the effort: £100 a month on a £200,000 mortgage at 5% over 25 years takes 3 years 6 months off the term and £24,505 off the interest bill, while £200 a month removes 6 years 2 months and £41,843.` },
  ],
  'pension-calculator': [
    { question: `How much should I save into my pension?`, answer: `The legal auto-enrolment minimum is 8% of qualifying earnings between £6,240 and £50,270, split between at least 3% from your employer and 5% from you, and it is unlikely to fund a comfortable retirement on its own. The Pensions Policy Institute suggests a gross contribution of 12-15% of salary from age 25 to reach roughly two-thirds of final salary. A simpler rule is to halve your starting age and save that percentage, giving 12.5% at 25 or 20% at 40. Source: The Pensions Advisory Service, DWP.` },
    { question: `What is the pension annual allowance for 2026/27?`, answer: `It is £60,000, covering your contributions plus your employer's, and anything above it attracts an Annual Allowance Charge at your marginal income tax rate. Carry forward can lift the limit using unused allowance from the three previous tax years, provided you were a scheme member then. High earners face the taper, which removes £1 of allowance for every £2 of adjusted income above £260,000, with a threshold income test at £200,000 and a floor of £10,000. Flexibly accessing a pot instead brings in the £10,000 Money Purchase Annual Allowance. Source: HMRC.` },
    { question: `When can I access my pension?`, answer: `The minimum access age for defined contribution pensions is 55, rising to 57 from 6 April 2028, although a protected pension age can allow earlier access. From then you can normally take 25% as a tax-free lump sum and draw the other 75% as taxable income through annuity, drawdown or lump sums. Defined benefit schemes set their own ages, typically 60 or 65. Drawing before State Pension age at 66 stretches the pot further, so the FCA points to a sustainable withdrawal rate of about 3.5-4% a year. Source: HMRC, FCA.` },
  ],
  'capital-gains-tax-calculator': [
    { question: `Do I pay CGT at 18% or 24% on my gain?`, answer: `It depends on how much of your basic rate band is still free. Gains falling inside the remaining band are taxed at 18%, and anything above it at 24%. Since 30 October 2024 the same pair of rates covers every asset type, so shares, crypto, business assets and residential property are treated alike. A higher-rate taxpayer with a £25,000 gain on shares deducts the £3,000 exemption and pays 24% on £22,000, which comes to £5,280.` },
    { question: `Can my spouse and I share a capital gains exemption?`, answer: `Not share one, but you each have your own. The £3,000 annual exempt amount is per person, so an asset held jointly can shelter £6,000 of gains in a tax year. Transfers between spouses and civil partners are made on a nil-gain, nil-loss basis, which means an asset can be moved to a partner before a sale so that their exemption is used too. Anything left unused at the end of the year cannot be carried forward.` },
    { question: `Do I have to report a property sale within 60 days?`, answer: `UK residential property disposals must be reported within 60 days of completion through the gov.uk Capital Gains Tax on UK Property service, and the tax is payable in the same window. Other disposals, including shares, crypto and non-residential property, go on your Self Assessment return by 31 January. Missing the deadline brings a £100 penalty immediately, then £10 a day once you are 3 months late, with interest running on the unpaid tax.` },
    { question: `How much Business Asset Disposal Relief can I claim?`, answer: `The lifetime limit is £1m of qualifying gains and it has not moved. What has changed is the rate. BADR was charged at 10% before April 2025, rose to 14% for 2025/26 and reaches 18% in 2026/27, which brings it level with the standard basic-rate CGT charge. Anyone planning a business sale across several tax years should look closely at when the disposal actually completes.` },
  ],
  'inheritance-tax-calculator': [
    { question: `How much can I leave before Inheritance Tax is due?`, answer: `An estate has a nil-rate band of £325,000, plus a residence nil-rate band of £175,000 where the family home goes to direct descendants, so £500,000 for one person. Because both bands transfer to a surviving spouse or civil partner, a married couple can pass £1,000,000 between them with proper planning. Above those thresholds the rate is 40%, or 36% where 10% or more of the net estate goes to charity. The residence band tapers away above a £2m estate and is eliminated at £2.35m.` },
    { question: `Do I pay Inheritance Tax on gifts made before death?`, answer: `Only on gifts made within 7 years of death. Anything given earlier is outside the estate altogether. Gifts inside that window are potentially exempt transfers and are counted back in, with taper relief cutting the charge by 8% a year from year 3, so the full amount applies in years 0 to 3, then 80% in year 4, falling to 20% by year 7. Separately, the £3,000 annual allowance, small gifts of £250 per person and wedding gifts are exempt from the outset.` },
    { question: `Will my pension count towards Inheritance Tax from 2027?`, answer: `Most undrawn pensions will. Until 5 April 2027 a defined contribution pension sits outside the estate and passes to nominated beneficiaries free of IHT, with income tax applying only if you die after 75. From 6 April 2027 that protection largely ends and the pension is counted alongside everything else. It ranks as one of the biggest IHT changes in decades, and the responses under discussion include drawing down earlier and gifting the proceeds, buying an annuity, or using trusts.` },
    { question: `What changed for farms and family businesses in April 2026?`, answer: `Since 6 April 2026, Business Property Relief and Agricultural Property Relief give 100% exemption only on the first £2.5m of combined qualifying property: BPR on unlisted trading company shares held for 2 years or more and on sole trader and partnership assets, APR on farmland farmed for 2 years, or 7 where it is let. Anything above £2.5m attracts 50% relief, an effective IHT rate of 20%, and any unused allowance can pass to a surviving spouse or civil partner. AIM shares get 50% relief outside the allowance. Estates near or over that line are the ones where planning matters most.` },
  ],
  'dividend-tax-calculator': [
    { question: `How much dividend income is tax-free in 2026/27?`, answer: `The dividend allowance is £500. Above it, the rates are 10.75% up to £50,270 of total income, 35.75% from £50,271 to £125,140 and 39.35% above that. Because dividends stack on top of your other income, the band that applies depends on everything else you earn rather than on the dividends alone. The allowance has fallen a long way from the £5,000 available in 2017/18, which is why shareholders who once paid nothing now see a bill.` },
    { question: `Should I pay myself in salary or dividends?`, answer: `For most owner-managers it is a mix rather than one or the other. Dividend rates sit 9.25 points below income tax at the basic rate, 4.25 at the higher rate and 5.65 at the additional rate, and escape National Insurance entirely. They are paid from profit after Corporation Tax, though, so the saving is smaller than the rates suggest and can disappear for a higher-rate taxpayer. Salary still earns its place, because it is deductible for the company, uses up the Personal Allowance and preserves pension and statutory benefit entitlement. The common shape is a salary set at a level that costs little or nothing in NI, with dividends on top.` },
    { question: `Are dividends inside an ISA really tax-free?`, answer: `Yes, entirely, and they do not use up your £500 allowance either. With a £20,000 annual ISA allowance, a substantial dividend-paying portfolio can be sheltered over a few years. The difference is easy to quantify. A higher-rate taxpayer holding £5,000 of dividend income outside an ISA pays 35.75% on the £4,500 above the allowance, which is £1,609, while the same dividends inside an ISA cost nothing at all. Pensions work the same way.` },
    { question: `Do I pay National Insurance on dividends?`, answer: `No. Dividends are not earnings, so neither employee National Insurance at 8% or 2% nor employer National Insurance at 15% applies, and the 0.5% apprenticeship levy does not touch them either. That is most of the dividend advantage, although it is partly offset by Corporation Tax, which salary avoids and dividends do not. The trade-off appears in the salary decision instead, since setting pay too low gives up some pension and statutory benefit accrual.` },
  ],
  'student-loan-repayment-calculator': [
    { question: `Which UK student loan plan am I on?`, answer: `Your plan is set by where and when you started studying, not by anything you chose. Courses begun before September 2012 in England and Wales fall under Plan 1, along with Northern Ireland borrowers. Plan 2 covers English courses started from September 2012 to July 2023 and Welsh courses started from September 2012 onwards. Scottish borrowers moved to Plan 4 in 2021, and English courses started from 1 August 2023 are Plan 5. If you are unsure, your Personal Tax Account on gov.uk shows what has been recorded.` },
    { question: `Will I ever repay my student loan in full?`, answer: `Many will not. Department for Education forecasts from July 2026 expect 55% of full-time undergraduates who started in 2025/26, on Plan 5, to repay in full before the 40-year write-off, so 45% will not. For those who do not clear it the loan behaves as a 9% graduate tax on income above the threshold. Voluntary overpayments only make sense if you expect to earn well above the threshold consistently for 25 years or more.` },
    { question: `How do I check my student loan deductions are correct?`, answer: `Your payslip should show a Student Loan line taking 9% of pay above the weekly or monthly threshold. Check in your Personal Tax Account on gov.uk that the Student Loans Company and HMRC hold the right plan, because being recorded on Plan 1 instead of Plan 2 costs up to £223.65 a year in extra deductions, which is 9% of the £2,485 gap between the two thresholds. Deductions continuing after the loan is cleared, or starting before you reach the threshold, need correcting through your employer's payroll.` },
    { question: `Do I still repay my student loan if I move abroad?`, answer: `Yes. The Student Loans Company issues a repayment schedule using thresholds adjusted for the country you live in, so the £29,385 Plan 2 threshold translates to roughly $40,000 in the United States or €34,000 across much of Europe. Overseas employment should be declared within 30 days, because failing to do so can lead the SLC to apply the UK threshold and charge 9% on that basis instead.` },
  ],
  'self-assessment-tax-calculator': [
    { question: `Do I still need to file if I earn over £100,000?`, answer: `Not on income alone. The old £100,000 test rose to £150,000 and was scrapped entirely from 2024/25, so a high salary taxed through PAYE no longer triggers a return by itself. What decides it now is the type of income you receive: self-employment over £1,000, property income over £1,000, dividends outside PAYE, foreign income, savings interest above the Personal Savings Allowance, or capital gains above the annual exempt amount. If HMRC sends you a notice, you file whether or not any tax is due.` },
    { question: `What do people most often get wrong on a Self Assessment return?`, answer: `A handful of errors come up year after year. Dividends received inside an ISA are not taxable and should not be entered, and employer pension contributions have already been treated pre-tax. Savings interest below the £1,000 Personal Savings Allowance still goes on the form even though no tax follows. On the reporting side, always give gross income rather than net, work to the tax year rather than the calendar year, and keep personal and business accounts apart, because mixing them turns a short return into a long one.` },
    { question: `Can I reduce my Payments on Account?`, answer: `Yes. If you expect the coming year to be less profitable, you can apply to reduce both instalments rather than paying 50% of last year's bill twice over. The risk is cutting them too aggressively, because if the eventual bill lands higher, interest is charged on the shortfall. Payments on Account only arise where your bill exceeds £1,000 and less than 80% of your tax was collected at source, so a modest side income taxed mostly through PAYE often escapes them.` },
    { question: `How much does filing a tax return late actually cost?`, answer: `£100 lands immediately, even when no tax is owed. From 1 May a daily £10 penalty runs for up to 90 days, adding £900, and at 6 months a further 5% of the tax owed or £300 applies, repeated again at 12 months. Registering late brings its own £100 charge on top of that. For someone who keeps putting it off, the total commonly reaches £600 to £1,600 before the tax itself is settled, which is why filing between May and August is the usual advice.` },
  ],
  'corporation-tax-calculator': [
    { question: `Why is the effective rate 26.5% between £50,000 and £250,000?`, answer: `Marginal Relief tapers away as profits rise, and the way it unwinds means each extra pound of profit inside that band is taxed more heavily than the headline main rate. The slice therefore carries an effective 26.5%, and the overall effective rate only settles at 25% once profit reaches £250,000 exactly. The fraction used to work out the relief for 2026/27 is 3/200. It explains why a company sitting just above £50,000 often looks at deferring income or bringing expenses forward.` },
    { question: `What counts as an associated company for Corporation Tax?`, answer: `The £50,000 and £250,000 limits are divided by the number of associated companies in your control group, so two companies share £25,000 and £125,000 while three split £16,667 and £83,333. The point of the rule is to stop one business being spread across several companies to keep each below the small profits threshold. Association is defined by control rather than by trade, so companies controlled by the same person, family group or spouse are caught even with no commercial relationship between them.` },
    { question: `Which business costs can I deduct from Corporation Tax?`, answer: `Most genuine running costs come off profit before tax: staff salaries including a director's salary, employer pension contributions, rent, utilities, software, insurance, professional fees, travel and marketing. Equipment is handled through Capital Allowances or the £1m Annual Investment Allowance rather than as a straight expense. Qualifying research and development work attracts R&D Tax Credits worth a 20% above-the-line credit. Where a cost is genuinely incurred for the trade and properly recorded, it will normally qualify.` },
    { question: `When is my Corporation Tax return and payment due?`, answer: `They fall on different dates, and the payment comes first. Corporation Tax is due 9 months and 1 day after the end of your accounting period, while the CT600 return is not required until 12 months after that same date. Companies with profits of £1.5m or more sit outside this pattern and pay in quarterly instalments instead. Working the figure out early, even if you file later, is what stops the payment deadline arriving before the accounts are finished.` },
  ],
  'salary-sacrifice-calculator': [
    { question: `How does salary sacrifice reduce my tax and National Insurance?`, answer: `You agree with your employer to give up part of your gross salary in return for a non-cash benefit such as a pension contribution, a bike or an electric car. The sacrificed amount is taken off before income tax and NI are worked out, so both bills fall. A basic-rate taxpayer giving up £100 saves £20 of income tax and £8 of NI, a £28 saving, compared with £20 through a relief-at-source pension. A higher-rate taxpayer saves £48 per £100.` },
    { question: `Which salary sacrifice schemes are available in 2026?`, answer: `Pension is the most popular, typically 5% of salary. Cycle-to-work covers bikes worth £1,000-£3,000 repaid over 12-18 months. Electric vehicles carry a benefit-in-kind rate of just 4% in 2026/27, rising to 9% by 2029/30. Workplace nursery is uncapped where the employer provides the care, and annual leave purchase and technology schemes also exist, the latter with limited tax advantage since 2017. Childcare vouchers closed to new joiners in October 2018 and were replaced by Tax-Free Childcare.` },
    { question: `Can salary sacrifice take my pay below the minimum wage?`, answer: `No. Your pay after the sacrifice must stay at or above the National Minimum Wage, which is £12.71 an hour in 2026 for workers aged 21 and over, so lower earners have a hard ceiling on how much they can give up. Sacrifice also lowers the qualifying earnings used for State Pension accrual, Statutory Maternity Pay and mortgage affordability checks, so anyone near those thresholds or planning maternity leave should weigh the timing carefully.` },
    { question: `Will my employer pass on its National Insurance saving?`, answer: `Only if the scheme includes NI passback, so it is worth asking HR or payroll. Your employer saves 15% NI on everything you sacrifice, which is £150 on £1,000, plus 0.5% Apprenticeship Levy where that applies. Many employers add some or all of that saving to your pension, turning a £1,000 sacrifice into £1,150-£1,155 invested. Because the passback costs the employer nothing beyond admin, it is a reasonable request if your scheme does not offer it yet.` },
  ],
  'child-benefit-calculator': [
    { question: `How much is Child Benefit per week in 2026/27?`, answer: `The eldest or only child attracts £27.05 a week, which is £1,406.60 a year, and each additional child £17.90 a week, or £930.80 a year. A family with three children therefore receives £62.85 a week, or £3,268.20 a year. Payment is normally every 4 weeks, or weekly for single parents and certain benefit recipients, and the rates rise roughly in line with inflation each April. A child qualifies until 16, or until 20 in approved education such as A-levels or NVQ Level 3, but not at university or on an employer-paid apprenticeship.` },
    { question: `Is the High Income Child Benefit Charge based on joint household income?`, answer: `No. The charge is triggered by the higher earner's adjusted net income alone, which is income after pension contributions and Gift Aid; the two parents' incomes are never combined. Between £60,001 and £80,000, 1% of the Child Benefit is repaid for every £200 over £60,000, and at £80,000 or more the whole amount is clawed back through Self Assessment. Pension contributions cut the charge: every £1,000 paid in by someone on £80k or more saves roughly £500 of HICBC, and salary sacrifice for pensions or childcare vouchers reduces both gross salary and the charge.` },
    { question: `Why claim Child Benefit if I'll be charged HICBC?`, answer: `For the National Insurance credits. The parent at home caring for a child under 12 receives automatic NI years towards the State Pension when Child Benefit is registered, even if they tick 'don't pay me'. Without a claim, each missed year permanently cuts the State Pension by £6.89 a week, roughly £358 a year, so 5 missed years costs about £1,790 a year for life, or £30,000-£50,000 over a typical retirement. Always register the claim; simply opt out of the payments if the charge would take them back.` },
    { question: `How does Child Benefit affect Universal Credit?`, answer: `Child Benefit is not counted as income for Universal Credit, unlike the older Working Tax Credit and Child Tax Credit, which it does affect. UC has its own child element of £303.94 a month per child in 2026/27, with the higher £351.88 for a first child born before April 2017. You receive both together: Child Benefit from HMRC and UC from the DWP. Child Benefit stops at 16 (or 20 in approved education), while the UC child element can continue to 19. Some council tax reduction schemes do count Child Benefit as income.` },
    { question: `How do I claim Child Benefit and can it be backdated?`, answer: `Complete form CH2 online at gov.uk/child-benefit or use the HMRC app. You need the child's birth certificate, your National Insurance number, your partner's NI number where applicable and your bank details. A first claim takes 6-12 weeks; claims for additional children are processed faster. Only one parent in a household can claim, and changing the claimant later requires a letter to HMRC and an 8-10 week wait. Backdating is limited to 3 months from the date you claim, so register as soon as the birth is registered.` },
  ],
  'redundancy-pay-calculator': [
    { question: `How is statutory redundancy pay calculated in 2026/27?`, answer: `For each full year of service you receive 0.5 weeks' pay if you were under 22, 1 week if aged 22-40 and 1.5 weeks if aged 41 or over. A maximum of 20 years count and weekly pay is capped at £751, so the most anyone can receive is 30 weeks at £751, or £22,530. You need at least 2 years of continuous service to qualify. The whole payment is tax-free as long as it stays within the £30,000 limit.` },
    { question: `Is redundancy pay tax-free up to £30,000?`, answer: `Yes. The first £30,000 of statutory, enhanced and ex gratia redundancy pay combined is free of income tax and NI. Above that, income tax applies at your marginal rate, but you pay no employee NI, although your employer has paid NI on the excess since April 2020. Notice pay, including Payment In Lieu of Notice, has been fully taxable since April 2018 however it is packaged, so it never counts towards the £30,000 exemption.` },
    { question: `Can my employer pay more than statutory redundancy pay?`, answer: `Many do, through the contract or staff handbook. Common enhanced schemes pay 2-4 weeks per year of service with no weekly cap, or a multiple of the statutory amount such as 3 times. Public sector employers in the NHS, civil service and local government have traditionally offered around a month per year. Whatever the scheme, statutory redundancy pay is the floor, so an enhanced package can never leave you with less than the statutory formula produces.` },
    { question: `What are my rights when I am made redundant?`, answer: `If 20 or more redundancies are planned within 90 days, your employer must consult collectively, giving 30 days' notice for fewer than 100 redundancies and 45 days for 100 or more. Selection must use fair criteria, and picking people because of age, gender or disability is unlawful. You are owed at least 1 week's notice per year of service, capped at 12 weeks, and with 2 or more years' service you can take reasonable paid time off to look for work. Appeal internally first, then to an employment tribunal within 3 months.` },
  ],
  'employer-ni-calculator': [
    { question: `Why did employer National Insurance rise in April 2025?`, answer: `The Autumn 2024 Budget raised employer Class 1 NI from 13.8% to 15% and cut the Secondary Threshold from £9,100 to £5,000 in the same package. Those two moves together add roughly £900 of employer NI for each employee earning £40,000 or more compared with the previous regime. The Employment Allowance went up to £10,500 from £5,000 to offset the cost for small employers, but the measure was still the largest single business tax rise in recent memory and the political argument about it has not settled.` },
    { question: `How much employer NI do I pay on a £30,000 salary?`, answer: `The charge applies to earnings above the £5,000 Secondary Threshold, so a £30,000 salary leaves £25,000 within scope. At 15% that produces £3,750 for the year. Under the previous 13.8% rate with its £9,100 threshold the same employee cost £2,884.20, so the annual increase is £865.80. If your business qualifies for the Employment Allowance, the first £10,500 of your total employer NI across all staff is covered, which on a very small payroll can remove the charge altogether.` },
    { question: `Can a sole-director company claim the Employment Allowance?`, answer: `No. The allowance needs either at least one employee besides the director, or two directors who both earn above the Secondary Threshold, so a company with one director and no other staff is the main group shut out. You also have to be running a trade or business, which excludes public sector employers unless they qualify under a specific rule. Everyone else claims through PAYE on the Employer Payment Summary, and it is usually applied automatically once eligibility is recorded.` },
    { question: `How much does salary sacrifice save the employer?`, answer: `On £1,000 of sacrificed salary the business avoids 15% NI, which is £150, plus the 0.5% Apprenticeship Levy where it applies, another £5. That is £155 which would otherwise have gone to HMRC. Employers running best practice return the saving as an additional pension contribution, so a £1,000 sacrifice arrives in the scheme as £1,155 and costs the company nothing beyond the administration. It is worth asking HR whether your scheme includes that NI passback.` },
  ],
  'car-tax-calculator': [
    { question: `How is car tax worked out for a car registered after 2017?`, answer: `Tax comes in two stages. The first-year rate follows CO2 emissions, starting at £10 for a zero-emission car and climbing to £5,690 for the highest-emission models in 2026/27. From year two the car switches to the standard annual rate of £200, whatever it burns, since the £10 alternative-fuel discount ended in April 2025. A list price above £40,000 adds the £440 expensive car supplement for years two to six.` },
    { question: `Do electric cars have to pay road tax in the UK now?`, answer: `Yes, since April 2025. An EV registered from that point pays the £10 first-year rate and then the standard rate, £200 in 2026/27. One registered between 2017 and 2025 had a free first year and now pays £200 a year, and an EV registered before 2017 sits on £20. The expensive car supplement applies too, but from April 2026 the EV threshold is £50,000 rather than £40,000.` },
    { question: `Which vehicles are exempt from vehicle tax altogether?`, answer: `The nil-rate list covers vehicles for disabled drivers on the higher rate mobility component of DLA or PIP, vehicles used by disabled veterans on the war pension supplement, historic vehicles over 40 years old that are not used commercially, agricultural vehicles, mobility scooters and powered wheelchairs, and electric vehicles registered before April 2017. Exempt does not mean forgotten: you still have to tax the vehicle every year at £0, or the DVLA record shows it as untaxed.` },
    { question: `What happens if I drive without taxing my car?`, answer: `Cameras do the enforcing. ANPR systems read number plates against the DVLA database and pick up an untaxed vehicle on a public road in seconds, which brings an £80 fine or clamping. If the car genuinely is not being driven, a Statutory Off-Road Notification removes the duty to tax it, though the vehicle then has to stay off public roads entirely.` },
    { question: `Can I spread my car tax over monthly payments?`, answer: `You can, through Direct Debit, but it costs more. Paying the whole year up front is the cheapest option, six-monthly carries a 5% surcharge, and monthly Direct Debit carries 10%. Everything is set up at gov.uk/vehicle-tax, and the DVLA sends a reminder around three weeks before the current period runs out so the renewal does not slip past you.` },
  ],
  'maternity-pay-calculator': [
    { question: `What is the difference between Statutory Maternity Pay and Maternity Allowance?`, answer: `SMP is paid by your employer for 39 weeks and requires 26 weeks of continuous service by the 15th week before the due date plus average earnings of at least £129 a week. Maternity Allowance is for people who miss those conditions, such as the self-employed, recent starters and agency workers. It pays £194.32 a week for 39 weeks, claimed from Jobcentre Plus on form MA1 from 26 weeks of pregnancy, provided you worked for 26 of the 66 weeks before the due date and earned £30 or more a week in 13 of them.` },
    { question: `How much enhanced maternity pay do employers typically offer?`, answer: `Many UK employers pay more than SMP. A typical public sector package is 8 weeks at full pay, 18 weeks at half pay and then 13 weeks of SMP. Banks and large consulting firms often pay 6 months at full pay followed by 3 months of SMP, and 16-26 weeks at full pay is common in tech companies. Check your contract and staff handbook, and look out for clauses requiring repayment if you do not return to work after your leave.` },
    { question: `Can I work during maternity leave without losing SMP?`, answer: `Yes, for up to 10 Keeping In Touch (KIT) days. Each KIT day is paid in addition to SMP, at your normal rate or a rate agreed with your employer, and can be used for training, meetings, handovers or a gradual return. They are voluntary on both sides. Parents on Shared Parental Leave have 20 SPLIT days between them. Keep a careful count, because working more than 10 KIT days may end your SMP entitlement.` },
    { question: `Is Statutory Maternity Pay taxed?`, answer: `Yes. SMP counts as earnings, so income tax, National Insurance and pension contributions can still be deducted from it in the usual way through payroll. Your employer pays it but recovers 92% from HMRC, or 109% under Small Employers' Relief, so the cost to the business is small. The figures this calculator shows are gross, so your actual payments will be a little lower once those deductions are applied.` },
  ],
  'mortgage-overpayment-calculator': [
    { question: `How much can I overpay before an early repayment charge?`, answer: `Most UK fixed-rate mortgages allow overpayments of up to 10% of the balance each year with no penalty, though some deals cap it at 5% and a few allow 20%. Above the limit an early repayment charge of 1-5% of the overpayment usually applies, often tapering through the fix at 5% in year 1, 4% in year 2 and 3% in year 3. The allowance resets on the mortgage anniversary, and after the fix ends or on the SVR you can normally overpay without limit.` },
    { question: `Should I overpay the mortgage or invest the money instead?`, answer: `Below a mortgage rate of 4%, investing in a Stocks and Shares ISA usually wins on expected return, since long-term returns of 7-10% are plausible. Above 5%, overpaying wins on a risk-adjusted view, because the saved interest is guaranteed while investment returns are not. A mixed approach often makes sense, clearing a high-rate fix first and investing the remainder. Higher-rate taxpayers should also look at pension contributions, where 40% relief frequently beats both.` },
    { question: `Is it better to cut the term or reduce the monthly payment?`, answer: `Cutting the term almost always saves more. Take a £200,000 mortgage at 5% over 25 years with £100 a month extra. Directed at the term, it clears the debt in 21 years 6 months and saves £24,505 in interest. Directed at the payment instead, with the lender recalculating the monthly figure each time and the end date kept at 25 years, it saves only about £10,700. Same money, about £13,800 difference, so choose the shorter term unless monthly cashflow is genuinely tight.` },
    { question: `Does a lump sum beat regular monthly overpayments?`, answer: `Usually, because money paid earlier has longer to reduce the balance. A £10,000 lump sum at year 5 of a £200,000 mortgage at 5% over 25 years saves about £15,900 in interest and cuts 22 months from the term. Spreading the same £10,000 at £100 a month from year 5, which takes 8 years 4 months, saves about £11,400 instead. Bonuses, inheritance and existing savings are the natural source, and lenders generally accept lump sums online at any time.` },
  ],
  'universal-credit-calculator': [
    { question: `What are the Universal Credit standard allowance rates for 2026/27?`, answer: `The monthly standard allowance is £338.58 for a single claimant under 25 and £424.90 for a single claimant aged 25 or over. Couples receive £528.34 when both partners are under 25 and £666.97 when at least one is 25 or over. Everything else is added to that base, including the child element of £351.88 or £303.94, the carer element of £209.34 and the housing element, which follows the LHA rate where you live.` },
    { question: `How much is the Universal Credit health element in 2026/27?`, answer: `There are two rates from 6 April 2026. If you are newly assessed as having limited capability for work and work-related activity, the health element is £217.26 a month. A protected rate of £429.80 applies if you were already receiving the element before April 2026, if you meet the Severe Conditions Criteria, or if you are terminally ill. The Universal Credit Act 2025 created the split, so two people with the same condition can be paid different amounts depending on when they were assessed.` },
    { question: `How does the work allowance and 55% taper affect my payment?`, answer: `A work allowance is only given to claimants who have responsibility for children or limited capability for work. It is £710 a month if your award includes no housing element and £427 a month if it does. Earn above that and Universal Credit falls by 55p for every £1 of net earnings. Claimants without children or limited capability are tapered from the first pound they earn, which is why effective marginal tax rates of 75-85% show up in some cases.` },
    { question: `How much can I have in savings before Universal Credit stops?`, answer: `Capital of £16,000 or more ends a Universal Credit claim outright. Below £6,000 your savings are ignored. In between, tariff income applies and the award drops by £4.35 a month for every £250 above £6,000. Savings, investments, business assets and property other than your main home all count, as do ISAs and pension pots held before retirement, while personal possessions and certain disability-related capital are disregarded.` },
    { question: `What is the minimum income floor for self-employed claimants?`, answer: `Once you have been trading for 12 months or more, Universal Credit assumes you earn 35 times the National Minimum Wage each week, which is £444.85 in 2026/27, whatever your accounts actually show. The rule stops people underemploying themselves in order to claim. A start-up exemption keeps the floor off for your first 12 months of self-employment, provided the business is your main source of income.` },
  ],
  'compound-interest-calculator': [
    { question: `Does it matter whether interest is paid monthly or yearly?`, answer: `Less than the headline rate does. A 5% gross rate paid monthly is equivalent to 5.12% AER, which is why AER is the figure to compare accounts on. On £10,000 over 10 years at 5%, monthly compounding produces £16,470 against £16,289 compounded annually. That is a real but small advantage, and it should not persuade you to accept a lower rate in exchange for more frequent interest.` },
    { question: `How long does it take to double my money at a given rate?`, answer: `Divide 72 by the annual rate and you have a close approximation in years. At 6% money doubles in about 12 years, at 8% in about 9 years, and at 10% in roughly 7.2 years. The shortcut is accurate enough for rates between 4% and 15%, and it is a fast way to sanity-check a projection before running the full calculation.` },
    { question: `Why does starting ten years earlier make such a difference?`, answer: `Because the earliest contributions have the longest to compound. Saving £100 a month at 7% from age 25 builds £262,000 by 65. The same £100 a month started at 35 reaches £122,000, and from 45 only £52,000. The pattern shows up with lump sums too: £10,000 at 7% gains £9,672 in its first decade but £73,622 in its fourth. Delay costs growth, not just contributions.` },
    { question: `Will compound interest keep up with inflation?`, answer: `Only if the rate beats it. £10,000 at 5% for 30 years reaches £43,219 with annual compounding, but at 3% average inflation that buys what £17,806 buys today. When cash pays 3% and inflation runs at 4%, the balance rises while purchasing power falls, which is the trap of judging savings on the nominal figure alone. Comparing the rate against expected inflation before you commit is more useful than comparing accounts against each other.` },
  ],

    'premium-bonds-calculator': [
    { question: `What return should I actually expect from Premium Bonds?`, answer: `The prize fund rate from the September 2026 draw is 4.35%, and that figure is an average across every bondholder rather than a promise to any one of them. The median is lower, because infrequent large prizes pull the mean upwards. A £1,000 holding can go months without winning anything, while £50,000 tracks the headline rate fairly closely. Set against easy access savings at 4.5-5.0%, Premium Bonds generally need a large holding and a higher tax rate before they come out ahead.` },
    { question: `Are Premium Bond prizes really tax-free?`, answer: `Yes, every prize including the £1 million jackpot, and none of it uses up your Personal Savings Allowance. That matters most to higher-rate taxpayers, who have only £500 of allowance, and to additional-rate taxpayers, who have none. Put £50,000 in a savings account at 4.5% and it pays £2,250 gross, which is £1,350 after higher-rate tax. For a basic-rate taxpayer whose interest fits inside the £1,000 allowance, the advantage largely disappears.` },
    { question: `Can I lose money on Premium Bonds?`, answer: `Not in cash terms. Every £1 bond is redeemable at £1 whenever you want it, and NS&I is backed by HM Treasury. What can be lost is purchasing power. A year of winning nothing on a £10,000 holding while inflation runs at 3% leaves the real value at £9,709. That outcome is unusual on a large holding but quite ordinary on £100-£1,000, where the variance is wide enough to trail the average for years at a time.` },
    { question: `How can I improve my odds of winning a prize?`, answer: `The only lever that genuinely works is holding more bonds, since each £1 is one independent entry. Going to the £50,000 maximum reduces the variance and brings your result closer to the 4.35% average, and reinvesting prizes rather than banking them adds entries every month. Checking regularly is worth the trouble because unclaimed prizes sit waiting instead of expiring. Small holdings of £100-£1,000 remain a lottery, and a regular savings account will often beat them over several years.` },
  ],
  'fuel-cost-calculator': [
    { question: `How do I calculate the fuel cost per mile for my car?`, answer: `Take the fuel price per litre, multiply by 4.546 to convert to a UK gallon, then divide by your car's mpg. With petrol at £1.72 a litre, the UK average in the week commencing 21 September 2026, a gallon costs £7.82, so a 40 mpg car spends 19.5p on fuel per mile, a 50 mpg car 15.6p and a 30 mpg car 26.1p. The calculator does this for you and multiplies by the journey distance, so you only need the distance, your real-world mpg and the current pump price.` },
    { question: `How much of the UK petrol price is tax?`, answer: `Just under half. Fuel Duty is 52.95p per litre, the rate since the 5p cut of March 2022, now extended to 31 December 2026, and VAT at 20% is charged on both the duty and the fuel itself, so it is one sixth of the pump price. On the UK average of 172.01p for petrol in the week commencing 21 September 2026 (DESNZ), VAT was 28.67p and the two taxes together took 81.62p, about 47% of what you pay. The remaining 90.39p covers the fuel, delivery and the retailer's margin. On diesel at 195.53p the tax share was about 44%.` },
    { question: `Does the HMRC 55p mileage rate only cover fuel?`, answer: `No. The 55p per mile rate for the first 10,000 business miles (25p thereafter) is intended to cover fuel, insurance, depreciation and wear together, which is why it is nearly three times the 19.5p a mile of fuel a 40 mpg car burns with petrol at £1.72 a litre (UK average, week commencing 21 September 2026). Motorcycles get 24p, bicycles 20p and each passenger adds 5p a mile. Employees whose employer reimburses less than these rates can claim tax relief on the shortfall, and the self-employed claim the allowance through Self Assessment.` },
    { question: `What are the easiest ways to cut my fuel bill?`, answer: `Smooth driving is the biggest single win, since aggressive acceleration burns 30-40% more fuel. Keep tyres at the right pressure (0.5 bar under costs 5-10%), take roof racks off when not in use, avoid idling and use cruise control on the motorway. Air conditioning at low speeds uses about 10% more fuel, and combining short trips helps because a cold engine uses 50% more. Supermarket forecourts such as Asda and Tesco are often 2-5p a litre cheaper than branded stations. Switching to an EV charged at home cuts fuel to around 2p a mile against roughly 20p for petrol at £1.72 a litre.` },
  ],
  'energy-bill-calculator': [
    { question: `How does the Ofgem energy price cap work?`, answer: `The cap is reset quarterly, in January, April, July and October, and it limits the unit rate in pence per kWh and the daily standing charge a supplier can apply on a default tariff. It caps those rates rather than the bill itself, so what you pay still depends on how much gas and electricity you get through. Around 50 to 60% of the level reflects wholesale energy costs, with networks at 20 to 25%, policy costs at 10 to 15% and the supplier's margin at 3 to 5%.` },
    { question: `Should I fix my energy tariff or stay on the price cap?`, answer: `Fixed deals carry a premium of 5 to 15% over the current cap, so a fix pays off if the cap climbs 20% or more during the term and costs you if it falls, which it has done several times across 2024 and 2025. Wholesale gas futures and Ofgem announcements are the signals to watch. Fixing suits anyone who wants certainty when prices are stable or easing, while the cap suits volatile periods that are trending downwards. Many regular switchers re-fix every 12 to 18 months.` },
    { question: `Is a time-of-use tariff worth it if I drive an electric car?`, answer: `Usually, yes. Octopus Go charges 7 to 9p per kWh between 00:30 and 05:30 against around 30p at peak, so charging overnight saves EV drivers £600 to £1,200 a year compared with a flat rate. Octopus Agile works differently, tracking the wholesale market every half hour from 0 to 30p per kWh and occasionally going negative. Either one needs a smart meter, and solar owners on these tariffs export surplus at 15 to 20p per kWh.` },
    { question: `Why am I charged a standing charge when I use no energy?`, answer: `The standing charge pays for keeping your property connected to the gas and electricity networks, so it applies every day whatever the meter reads. It is capped separately from the unit rate, at 54.83p a day for electricity and 29.68p a day for gas from 1 October to 31 December 2026, which adds up to a sizeable share of a low user's annual bill. Comparing tariffs on the unit rate alone can therefore be misleading.` },
  ],

    'bmi-calculator': [
    { question: `Is BMI accurate for athletes and bodybuilders?`, answer: `Not reliably. BMI cannot separate muscle from fat, so a rugby player or bodybuilder can read 28 or more and be classed as overweight while carrying very little fat. The reverse happens too, where someone at 22 has a high fat percentage and poor metabolic health behind a normal-looking number. For anyone training seriously, body fat percentage and waist circumference say more. BMI does its job well enough for the roughly 80% of UK adults who are sedentary or moderately active.` },
    { question: `Do BMI thresholds differ for South Asian or Black adults?`, answer: `Yes. Since 2013 the NHS has applied adjusted thresholds for people of South Asian, Chinese, Black African and African-Caribbean background, treating overweight as starting at 23 rather than 25 and obesity at 27.5 rather than 30. These groups develop diabetes and heart disease at lower BMIs because of differences in body composition, carrying proportionally more visceral fat. NICE guideline NG7 recommends the ethnic-specific figures, so use them when judging your own risk.` },
    { question: `How is BMI assessed for children and teenagers?`, answer: `Adult categories do not apply to under-18s. The UK90 BMI-for-age centile charts are used instead, placing a child below the 2nd centile as underweight, between the 2nd and 91st as healthy, between the 91st and 98th as overweight and above the 98th as obese. Because BMI swings with growth spurts, one reading means little on its own. The NHS Healthy Weight Calculator produces age and sex-appropriate centiles, and for under-5s other measures such as the pattern of weight gain are more informative.` },
    { question: `What is a healthy weight range for my height?`, answer: `It comes from turning the healthy BMI band back into kilograms. A BMI of 18.5 to 24.9 counts as healthy, so at 175 cm that means a weight between 56.7 and 76.6 kg. Below 18.5 is underweight, 25 to 29.9 is overweight and 30 or above is obese. For a second reading that is less sensitive to muscle, measure your waist, since more than 94cm in men or 80cm in women signals raised risk on its own.` },
  ],

  // === Auto-generated FAQs for remaining calculators ===
  'scottish-income-tax-calculator': [
    { question: `How much more income tax do Scottish taxpayers pay?`, answer: `Scotland has six bands where the rest of the UK has three rates above the Personal Allowance, and the 42% rate begins at £43,663 instead of £50,271. The gap widens as income rises. Someone earning £100,000 pays £30,732 in Scotland against £27,432 in England, a difference of £3,300. National Insurance is identical UK-wide, so the divergence comes entirely from income tax on earnings, and dividends and savings interest are unaffected.` },
    { question: `How do I know if I am a Scottish taxpayer?`, answer: `Your status depends on where your main home is, not where you work. If your closest connection is to a Scottish address for the greater part of the tax year, or you spend more of the year in Scotland than elsewhere in the UK, you pay Scottish rates. HMRC assigns this automatically from the address it holds and your PAYE code picks up an S prefix, as in S1257L. Someone living in England and commuting into Scotland pays UK rates. A Scot commuting to London still pays Scottish ones. Disputed cases come down to where you spent most nights.` },
    { question: `Is pension tax relief better for Scottish taxpayers?`, answer: `For higher earners, yes, because relief follows your marginal rate. A Scottish taxpayer in the 42% band sees a £100 net contribution cost £58, against £60 for an English 40% taxpayer. At the 45% Advanced rate the cost falls to £55, and at the 48% Top rate to £52. The Annual Allowance of £60,000 is the same UK-wide and the Lifetime Allowance was abolished in April 2024, so the whole advantage sits on the relief side.` },
    { question: `Can Scottish couples still claim Marriage Allowance?`, answer: `Yes, but the qualifying window is narrower. Neither partner can be a higher-rate taxpayer, which in Scotland means neither may be above £43,662 rather than the £50,270 that applies elsewhere in the UK. One partner needs income under £12,570 and transfers part of their Personal Allowance to the other, who must sit in the starter, basic or intermediate band. The claim is worth £252 a year, can be backdated up to 4 years, and ends the moment either partner crosses into the higher rate.` },
  ],
  'stamp-duty-first-time-buyer-calculator': [
    { question: `Do first-time buyers pay any stamp duty in England and Northern Ireland?`, answer: `If you are buying your first home for £500,000 or less, no SDLT is charged on the first £300,000, and the slice from £300,001 to £500,000 is taxed at 5%. A purchase at £425,000 therefore costs £6,250. Properties costing more than £500,000 do not qualify for this relief, and standard rates then apply to the whole price rather than only to the amount above the cap.` },
    { question: `Does inheriting a share of a house end my first-time buyer status?`, answer: `Yes. Any freehold or leasehold interest in a residential property counts, wherever in the world it sits and however small the share, so inheriting even 1% of a house rules you out. The same goes for a property abroad you have never used, and for being named on the deeds of a parent's home as a helping hand. The test is ownership rather than occupation, and it does not matter how the interest came to you.` },
    { question: `What happens if I buy with someone who has owned before?`, answer: `The relief requires every purchaser to be a first-time buyer, so buying with someone who has owned property before means no relief on that purchase and standard SDLT on the full price. It is worth running both figures before you commit, since this calculator shows the relieved and standard bills side by side. A buy-to-let purchase falls outside the relief in the same way, whatever your own ownership history looks like.` },
    { question: `Should I use a Lifetime ISA or a Help-to-Buy ISA?`, answer: `Only the Lifetime ISA is open to new savers. Both pay a 25% government bonus, but the Help-to-Buy ISA closed to new accounts in November 2019 and caps the bonus at £3k on £12,000 of savings, with a £250k property limit outside London and £450k inside it. The LISA takes up to £4k a year and works on properties up to £450k anywhere in the country. Existing Help-to-Buy holders can keep paying in until November 2029, and transferring the balance into a LISA is allowed if your provider supports it. A new First Time Buyer ISA, consulted on in summer 2026, will replace the LISA for new savers once it launches, but LISAs stay open until then.` },
  ],
  'marriage-allowance-calculator': [
    { question: `Who qualifies to transfer Marriage Allowance to their partner?`, answer: `The lower earner must make less than £12,570, and their spouse or civil partner has to be a basic-rate taxpayer earning between £12,571 and £50,270 (in Scotland, starter, basic or intermediate rate, up to £43,662). Moving up to £1,260 of unused allowance across trims the recipient's tax by as much as £252 a year. If either of you was born before 6 April 1935, Married Couple's Allowance usually pays more, and you must be married or in a civil partnership rather than simply living together.` },
    { question: `Can I backdate a Marriage Allowance claim?`, answer: `Yes, to 6 April 2022, so a first claim made in 2026 covers the four earlier years from 2022/23 to 2025/26. Where you were eligible in each of them, the refund arrives as a lump sum of up to £1,008 (4 × £252), paid on top of the reduction of up to £252 for the current year. You apply once at gov.uk/marriage-allowance and the claim renews itself each year until you cancel it.` },
    { question: `What happens if my partner starts earning more?`, answer: `The claim needs to be cancelled. Marriage Allowance is only available while the recipient remains a basic-rate taxpayer, so once their income crosses into the higher rate the entitlement ends and HMRC will recover what was given for the period afterwards. A temporary dip in the lower earner's income works the other way round: it can make you eligible for that single year without carrying into the years that follow.` },
    { question: `Does Marriage Allowance work for Scottish taxpayers?`, answer: `Yes, though the eligibility band is narrower. The receiving partner can pay the starter, basic or intermediate rate (19%, 20% or 21%), which usually means income between £12,571 and £43,662, and anyone paying 42% or more falls outside the scheme. The lower-earning partner still needs income under £12,570, and the saving is the same, up to £252 a year. Applying and backdating work identically, through gov.uk/marriage-allowance and for up to four tax years.` },
  ],
  'company-car-tax-calculator': [
    { question: `How is the tax on a company car worked out?`, answer: `HMRC assigns each car a Benefit-in-Kind percentage from its CO2 emissions and fuel type, running from 4% for pure electric models up to 37% for the most polluting petrol and diesel cars in 2026/27. That percentage is applied to the P11D price, which is the list price with options and delivery but without the first year registration fee and vehicle excise duty. You pay income tax on the result at your marginal rate, and your employer pays Class 1A National Insurance at 15% on the same figure.` },
    { question: `Is an electric company car cheaper than a petrol one?`, answer: `Usually by a wide margin. A £50,000 EV at 4% carries a BiK value of £2,000, costing a higher-rate taxpayer £800 a year, while the same £50,000 as a petrol car at 32% carries £16,000 of BiK and £6,400 of tax, a difference of £5,600. The electric rate is scheduled to rise to 5% in 2027/28, 7% in 2028/29 and 9% in 2029/30, so the advantage narrows over time without disappearing. Salary sacrifice schemes widen it again.` },
    { question: `Should I accept free fuel from my employer?`, answer: `Rarely worth taking. Employer-paid private fuel triggers a separate benefit charge built on a fixed multiplier of £29,200 for 2026/27, applied at your car's BiK percentage and then taxed at your marginal rate. On a car at 32% that produces a £9,344 benefit and £3,738 of tax a year for a higher-rate payer, which is more than most drivers spend on private fuel in the first place. Buying your own and claiming Advisory Fuel Rates for business miles is normally cheaper.` },
    { question: `Is a cash allowance better than a company car?`, answer: `It depends on the car. A cash allowance is typically £4k to £8k a year and is taxed as salary, so income tax, National Insurance and pension all follow it, while the company car brings BiK tax but removes maintenance, insurance and MOT costs. For petrol and diesel cars above 30% BiK, cash usually comes out ahead. For an EV below 10% BiK, the company car wins by £1,000 to £3,000 a year, and an EV salary sacrifice scheme combines both worlds.` },
  ],
  'crypto-tax-calculator': [
    { question: `When do I have to pay tax on my cryptocurrency?`, answer: `Capital Gains Tax bites when you sell, swap, gift or spend crypto at a profit and your total gains for 2026/27 pass the £3,000 annual exempt amount. Above that, basic-rate taxpayers pay 18% and higher or additional-rate taxpayers pay 24%. Separately, income tax can apply at the moment you receive crypto, for instance from mining, staking or salary, which is a different charge from the gain you make when you later dispose of it.` },
    { question: `What counts as a disposal of crypto in the UK?`, answer: `Selling for pounds or another currency is the obvious one, but swapping one token for another, spending crypto on goods or services, and giving it away to anyone other than your spouse all count too. Spending is treated as a disposal at the sterling value on the day. Shifting coins between wallets or exchanges that you own is not a disposal, so no gain arises. Losses are set against gains of the same year in full, and unused losses carry forward indefinitely, though in later years they only bring gains down to the £3,000 exempt amount.` },
    { question: `How do I work out the cost of crypto bought at different prices?`, answer: `Under Section 104 pooling, all your holdings of a given token sit in one pool with a weighted average cost, and a disposal is matched against that average. Two rules come first, since anything bought on the same day is matched before the pool, then anything bought in the following 30 days under the anti-bed-and-breakfasting rule. This is not FIFO or LIFO, and exchange statements rarely show it, which is why people use tools such as Koinly, CoinTracker or Recap.` },
    { question: `Will HMRC know about crypto trades I have not declared?`, answer: `Under the OECD Crypto-Asset Reporting Framework, which extends the existing Common Reporting Standard to digital assets, UK exchanges and other crypto service providers have collected customer and transaction data since 1 January 2026, and their first annual report to HMRC, covering 2026, is due by 31 May 2027. Trades will therefore show up whether or not they appear on your return. If you have unreported gains from earlier years, a voluntary disclosure of a careless mistake more than a year old usually attracts penalties of 10-30% of the tax, against 20-30% once HMRC has contacted you first, and 35-100% where HMRC treats the failure as deliberate.` },
    { question: `Are staking and mining rewards taxed as income or gains?`, answer: `Both are treated as miscellaneous income, valued in sterling on the day the reward lands, and anything above the £1,000 trading allowance goes on a Self Assessment return. Airdrops are taxed the same way only if you received them in return for a service or as part of a trade, and otherwise carry no income tax at receipt. The value taxed as income then becomes the cost basis, so a second charge, this time Capital Gains Tax, can arise when you eventually sell or swap those coins. Crypto paid as salary is employment income through PAYE instead.` },
  ],
  'hourly-to-salary-calculator': [
    { question: `If I know my hourly rate, what will I earn in a year?`, answer: `Multiply your hourly pay by the hours you work each week and then by the number of paid weeks. The default is 37.5 hours a week over 52 weeks (1,950 hours a year), so £15 an hour comes to £29,250 and £18.50 an hour to £36,075. You can change the weekly hours and the paid weeks per year (cut the weeks for unpaid time off), and the calculator also shows 2026/27 income tax, NI and take-home pay: £36,075 leaves £29,493.60 after £4,701 tax and £1,880.40 NI.` },
    { question: `How do I work out my real hourly rate from an annual salary?`, answer: `Dividing by 1,950 hours gives the contractual rate, but you are not at work for all of those hours. Statutory holiday takes 5.6 weeks and unplanned absence typically another 0.4 weeks, leaving about 46 working weeks. Dividing a £30k salary by 37.5 hours across 46 weeks gives an effective £17.39 an hour for the time you actually spend working, which is the fairer figure to compare against a contractor's or hourly worker's rate.` },
    { question: `How much more should a contractor charge than an employee earns?`, answer: `Contractor rates typically sit 50-100% above the equivalent salary because the contractor covers costs the employer would otherwise bear, such as NI, pension, holiday, sick pay, training and equipment, and forgoes statutory protections and pension auto-enrolment. A widely used rule of thumb is annual salary multiplied by 1.6 and divided by 220 working days, so a £40k salary points to a day rate of about £290.` },
    { question: `Is holiday pay included in my hourly rate?`, answer: `Only if your contract says so, and only if you work irregular hours or part of the year. For those workers, in leave years starting on or after 1 April 2024, holiday builds up at 12.07% of hours worked, and the employer may pay rolled-up holiday pay of 12.07% on top of each pay packet, shown as a separate item on the payslip. Workers on regular hours get 5.6 weeks of paid leave at their normal rate instead. A rate that looks high may be quoted with holiday pay rolled in, so ask which basis applies before comparing offers.` },
    { question: `How much is London weighting worth on a salary?`, answer: `London weighting typically adds £4-£6k a year to a salary to offset the higher cost of living in the capital. Employers such as the NHS and the civil service publish explicit London pay bands, while private firms usually fold the uplift into the salary they negotiate with you. It is taxed exactly like the rest of your pay, so the net benefit is smaller than the headline figure once income tax and NI are taken off.` },
  ],
  'employer-cost-calculator': [
    { question: `Beyond the salary, what else does hiring someone cost?`, answer: `On top of gross pay, an employer owes 15% National Insurance on earnings above £5,000 plus a minimum 3% workplace pension on qualifying earnings between £6,240 and £50,270 under auto-enrolment, and at the pension minimum these add roughly 13 to 16% to salaries between £20,000 and £60,000. On a £35,000 salary that is £4,500 of NI and £862.80 of pension (3% of £28,760), taking the total to £40,362.80. Employer's liability insurance, pension administration, recruitment, training and equipment push the overall overhead to 15-25%.` },
    { question: `Does my business have to pay the Apprenticeship Levy?`, answer: `Only if your total annual pay bill exceeds £3m. The levy is 0.5% of the pay bill less a £15,000 annual allowance, so it is a cost for larger employers rather than small businesses. It also means salary sacrifice saves a little levy as well as NI: when an employee sacrifices £5,000 into their pension, the employer saves £750 in 15% NI and a further £25 in levy. From 6 April 2029 the NI saving applies only to the first £2,000 sacrificed each year, which cuts the employer's NI saving on £5,000 to £300.` },
    { question: `Is a contractor cheaper than a permanent employee?`, answer: `Usually not for long-term work. A contractor on £450 a day costs £117,000 a year over 260 working days, whereas a £75,000 permanent employee costs roughly £94,000 fully loaded. The contractor wins on flexibility: no training, no holiday or sick pay, no pension and no redundancy liability, which makes contracting the better choice for engagements under 6 months, rare specialist skills or a rapid scale-up. At full utilisation a permanent hire is generally 10-15% cheaper.` },
    { question: `How much does salary sacrifice save an employer?`, answer: `Every £1,000 an employee sacrifices into their pension saves the employer £150 in 15% NI, plus £5 in Apprenticeship Levy where the payroll is large enough to pay it. Best-practice employers hand that saving back as an extra pension contribution, known as NI passback, which turns the employee's £1,000 into £1,155 in the pension at no cost to the business beyond the admin, and tends to improve retention as a result. From 6 April 2029 only the first £2,000 an employee sacrifices each year stays free of NI, so the NI part of the saving stops at £300 a year per employee.` },
  ],
  'bonus-tax-calculator': [
    { question: `Why does so much tax come off my bonus?`, answer: `Your employer adds the bonus to your normal pay for the period and runs PAYE on the combined amount, which can push you into a higher marginal bracket that month and make the deduction look steep. A £10k bonus on a £40k salary is taxed that month as if you earned £13,333 every month, an annualised £160k. Over the full year the cumulative system evens it out, so the real effect is often smaller than the bonus payslip suggests.` },
    { question: `Can I pay my bonus into my pension to avoid the 60% tax trap?`, answer: `Yes, and it is the most common form of bonus sacrifice. Once salary plus bonus passes £100,000, every £2 of income removes £1 of Personal Allowance, giving an effective 60% rate on the slice up to £125,140. Sacrificing the whole bonus into a pension keeps you out of that band. If all of a £20,000 bonus falls between £100,000 and £125,140, sacrificing it saves £12,000 of income tax (60%) plus £400 of NI at 2%, £12,400 in all. Many employers offer a bonus-time pension election to arrange it.` },
    { question: `Will a bonus increase my student loan repayment?`, answer: `For that pay period, yes. Student loan deductions of 9% (Plans 1, 2, 4 and 5) or 6% (Postgraduate) are taken from pay above the threshold for each pay period, such as £2,448 a month on Plan 2, so the bonus month takes 9% of everything above that figure. The deduction is not cumulative, so later months do not balance it out and the extra comes off your loan balance. You can only claim a refund from the Student Loans Company if your income for the whole tax year ends up below your plan's annual threshold, and it is paid after the year ends.` },
    { question: `Does it matter whether my bonus is paid in March or April?`, answer: `It can, if you are close to a band threshold. A bonus paid in March is taxed under the current year's rates and allowances, while one paid after 5 April falls into the next tax year, and it is the date you are paid, not the date the bonus was earned, that counts. The Budget in November or December may change the brackets for the following April, so ask HR whether the payment date is flexible before deciding.` },
  ],
  'rental-yield-calculator': [
    { question: `What is a good rental yield in the UK in 2026?`, answer: `It depends on the region. Gross yields average 4-5% in London, 4-6% in the South East, 5-7% in the Midlands, 6-9% across the North of England, Wales and Northern Ireland, and 6-8% in Scotland, with northern cities such as Hull, Sunderland and Liverpool showing 8-12%. Net yield is typically 50-70% of gross once costs are paid. At current buy-to-let mortgage rates of 5.5-6.5% you generally need 7%+ gross to be cash-flow positive. A quick benchmark is the 1% rule, where monthly rent equals 1% of the purchase price (12% a year), though that is rarely achievable in the UK.` },
    { question: `Why is my net yield so much lower than the gross figure?`, answer: `Gross yield is simply annual rent divided by property value, so it ignores every outgoing. Net yield deducts the annual costs first: agent fees, landlord insurance at £200-£500 a year, a gas safety certificate at £80-£120, an EPC, repairs, void periods and, for higher-rate taxpayers, the extra tax created by the Section 24 mortgage interest restriction. On the example used on this page, £3,500 of costs turns a 6% gross yield into 4.25% net. Cost estimates need to be brutally honest, because many buy-to-let purchases lose money once Section 24 is taken into account.` },
    { question: `How does Section 24 affect a higher-rate landlord's tax bill?`, answer: `Before 2017 mortgage interest was fully deductible from rental income, so £15,000 of rent with £8,000 of interest left a taxable profit of £7,000 and a £2,800 bill for a 40% taxpayer. Since 2020 only a 20% basic-rate credit applies. The same landlord is taxed on the full £15,000, pays £6,000 and gets £1,600 back as a credit, leaving £4,400. That is £1,600 less relief on identical figures, and the effective rate on the real profit jumps from 40% to 63%. Buying through a limited company preserves the full interest deduction.` },
    { question: `Which UK cities are best for buy-to-let in 2026?`, answer: `For a mix of high yield and decent growth, Manchester offers 7-8% yields with 4-5% growth, Liverpool 8-9% with 4-6%, Leeds 6-7% with 4-5%, Sheffield 7-8% with 3-4%, and Glasgow 7-8% with 3-4%. Hull, Burnley and Sunderland give very high gross yields of 10-12% but slow growth. Bristol (5-6% yield, 5-6% growth), Edinburgh (5-6% and 4-5%) and Cambridge (4-5% and 5-7%) are growth plays with lower yields. Avoid areas with declining populations, weak job growth or oversupply, as Aberdeen has shown over the last decade, and always check the 5-year rental trend and the planning pipeline.` },
  ],
  'rent-vs-buy-calculator': [
    { question: `Is renting or buying cheaper over the years I plan to stay put?`, answer: `Property prices, rents, mortgage rates, house price growth, the return a deposit could earn if invested elsewhere, and the length of time you stay all shape the answer. Both options are modelled across the horizon you choose, so you can see the year in which one overtakes the other rather than relying on a rule of thumb that may not fit your area.` },
    { question: `How many years do I need to stay for buying to pay off?`, answer: `There is no fixed number. Stamp duty, legal fees and selling costs have to be earned back before ownership starts paying, so very short stays rarely favour buying, but the crossover depends on rent relative to price, the mortgage rate and your growth assumptions. For a £300,000 first-time purchase with a £30,000 deposit at 5.73%, against £1,200 a month rent, buying pulls ahead in year 2 with 3% house price growth and in year 6 with 2%, while at 1% renting is still ahead after 10 years.` },
    { question: `What ongoing costs should I add on top of the mortgage?`, answer: `Budget 2-3% of the property value a year for the full cost of ownership. That covers buildings insurance at £200-£400, maintenance at 1% of value, which is £2k a year on a £200k home, and a boiler service at about £100. Flats add service charges of £1k-£5k and leasehold ground rent of £100-£500. Big-ticket repairs sit outside that figure, with a boiler replacement at roughly £3k, a roof at £8k and a kitchen at £10k.` },
    { question: `Am I better off renting and investing my deposit instead?`, answer: `That depends on the returns on each side. A £50k deposit invested in a Stocks and Shares ISA averaging 7% grows to £272k over 25 years. The same £50k used to buy a £250k home rising 3% a year produces a property worth £523k, although on an interest-only basis £200k is still owed at the end of the term. Renting also avoids stamp duty, legal fees and selling costs, which is why it tends to win over short horizons and lose over long ones.` },
  ],
  'state-pension-calculator': [
    { question: `What is the full new State Pension worth in 2026/27?`, answer: `The full new State Pension is £241.30 a week for 2026/27, which comes to £12,547.60 over a full year. That figure is the maximum rather than a default. It rose 4.8% from £230.25 under the triple lock, and how much you actually receive depends on how many qualifying National Insurance years sit on your record.` },
    { question: `How many National Insurance years do I need for the full State Pension?`, answer: `Thirty-five qualifying years earns the full £241.30 a week, and ten years is the floor below which nothing is paid at all. Between those points the pension is scaled, so 25 years produces £158.00 a week. Check the position at gov.uk/check-state-pension, then price up any gaps: voluntary Class 3 contributions cost £18.40 a week, around £957 for a year, and each year bought back adds about £6.89 a week for life.` },
    { question: `Can I claim my State Pension while I carry on working?`, answer: `Yes. Once you reach State Pension age, currently 66 and rising to 67 between 6 April 2026 and 5 April 2028, you can draw the pension and stay in your job. Employee National Insurance stops at that point, a saving of 8% or 2% of earnings depending on the band. If the extra income would push you into a higher tax band, deferring may suit you better, since every 9 weeks deferred adds 1% to the pension, or 5.8% a year, with breakeven falling somewhere around age 80.` },
    { question: `Do I pay income tax on my State Pension?`, answer: `It counts as taxable income, but the full new State Pension of £12,547.60 a year sits just inside the £12,570 Personal Allowance, so someone with no other income pays nothing. Where there is other income, the State Pension uses up the allowance first and the rest is taxed at 20, 40 or 45%. HMRC collects anything due by adjusting the tax code applied to your employer or pension provider rather than billing you directly.` },
  ],
  'pension-tax-relief-calculator': [
    { question: `Can a higher-rate taxpayer claim extra pension tax relief?`, answer: `Yes. Relief at source adds 20% automatically, turning £80 of net pay into £100 in the pension, and a 40% taxpayer reclaims the other £20 on a £100 gross contribution through self-assessment, giving £40 of relief in total. An additional-rate taxpayer reclaims 25% the same way. With income between £100,000 and £125,140 the contribution also restores Personal Allowance, so relief there reaches 60%.` },
    { question: `What is the difference between net pay and relief at source?`, answer: `A net pay arrangement takes the contribution out of gross salary before income tax is worked out, so relief at your own marginal rate is given straight away and there is nothing to reclaim. Relief at source works the other way round: you pay from net income, the provider adds 20% from HMRC, and anyone taxed above the basic rate has to ask for the rest through self-assessment. The same £100 gross contribution ends up costing £80, £60 or £55.` },
    { question: `How much can I pay into a pension before a tax charge applies?`, answer: `The annual allowance is £60,000, and it counts your contributions, your employer's and the tax relief together. Separately, tax relief on your own contributions is limited to 100% of your UK earnings, or £3,600 gross if you earn less. Anything above the allowance is added to your taxable income and taxed at your marginal rate. Unused allowance from the previous three tax years can be carried forward, while high earners with threshold income over £200,000 lose £1 of allowance for every £2 of adjusted income over £260,000, down to a minimum of £10,000.` },
    { question: `Do Scottish taxpayers get pension tax relief at Scottish rates?`, answer: `Yes. Relief follows the Scottish rates of 19, 20, 21, 42, 45 and 48%, so the amount recovered differs band by band from the rest of the UK. In a net pay arrangement the correct relief is given automatically, because the contribution leaves gross pay before tax is calculated. Under relief at source the provider claims the basic 20% as usual, even for a starter-rate (19%) taxpayer, and anyone paying above 20% claims the difference through self-assessment: 1% for the intermediate rate, 22% for the higher rate, 25% for the advanced rate and 28% for the top rate.` },
  ],
  'isa-calculator': [
    { question: `How much can I pay into an ISA each tax year?`, answer: `You can put in up to £20,000 a year across all your ISAs combined, with all the growth staying tax-free. The money can go into one type or be split between Cash, Stocks and Shares, Innovative Finance and Lifetime ISAs, though the Lifetime ISA takes no more than £4,000 of that total. Whatever you have not used by 5 April is lost, because the allowance does not carry forward.` },
    { question: `Can I pay into more than one Cash ISA in the same year?`, answer: `Yes. Since April 2024 you can subscribe to several ISAs of the same type within one tax year, so you might hold an easy-access Cash ISA alongside a fixed-rate one, provided the total paid in stays within £20,000. Children under 18 are treated separately and have their own Junior ISA allowance of £9,000, which does not eat into a parent's £20,000.` },
    { question: `Can I withdraw money from my ISA and put it back later?`, answer: `Only if the account is a flexible ISA. Flexible ISAs let you withdraw money and replace it within the same tax year without the replacement counting against your annual allowance, which is handy for emergency liquidity. Not every ISA offers this, so check before you withdraw: most Cash and Stocks and Shares ISAs are flexible, while Lifetime ISAs, Junior ISAs and many fund platforms are not. Money replaced after 5 April counts as a new contribution against the new year's allowance.` },
    { question: `How do I move my ISA to a different provider?`, answer: `Always use the formal ISA transfer process rather than withdrawing the money and redepositing it, which would strip previous years' contributions of their tax-free wrapper. Transfers are usually free. A Cash ISA transfer typically takes 7-15 working days and a Stocks and Shares transfer 15-30. You can move between the same type or across types, for example Cash to Stocks and Shares, and contributions from earlier years can be split, so you do not have to transfer the whole balance.` },
  ],
  'personal-loan-calculator': [
    { question: `Why might my personal loan rate be higher than the advertised APR?`, answer: `The advertised figure is a representative APR, and FCA rule CONC 3.5 only obliges the lender to give it to 51% of accepted applicants. The remaining 49% can be quoted a personalised rate reflecting credit score, income and existing debt. Loan size matters too, since rates are usually keenest between £7,500 and £15,000. A soft search with Experian, ClearScore or MoneySavingExpert's eligibility tool shows your likely rate without leaving a mark on your file.` },
    { question: `Is it better to take a longer loan term to lower monthly payments?`, answer: `Longer terms reduce the monthly cost and increase the total interest, often sharply. A £10,000 loan at 8% APR costs £203/month over 5 years, with £2,166 of interest, against £121/month over 10 years with £4,557 of interest. You more than double the interest to halve the monthly figure. Take the shortest term you can comfortably afford. FCA persistent debt rules also penalise borrowers who stay in expensive credit for too long.` },
    { question: `Can I repay a UK personal loan early?`, answer: `Yes. The Consumer Credit Act 1974 gives you a statutory right to settle at any time. Lenders can apply an early settlement charge of up to one month's interest plus 28 days on loans under £8,000, or 1% of the amount repaid on loans of £8,000 or more. Ask for a settlement quote, which must arrive within 14 days of your request. In most cases the interest you avoid comfortably exceeds the charge.` },
    { question: `Which is cheapest: a personal loan, a 0% card or an overdraft?`, answer: `For a one-off purchase under £5,000 repaid within 18-24 months, a 0% purchase credit card usually wins, as long as the balance is gone before the promotional rate ends. From £5,000-£25,000 over 2-7 years a personal loan at 8-15% APR is normally cheaper. Authorised overdrafts have charged a single APR since April 2020 and sit at 35-40% EAR, which suits a short emergency rather than planned borrowing.` },
    { question: `Should I use a secured homeowner loan instead of an unsecured one?`, answer: `A secured or homeowner loan borrows against your property, which is how it stretches to £10,000-£500,000+, terms of up to 30 years and rates of 5-10%. If you default, the lender can force the sale of your home, so the cheaper rate carries a real cost. Logbook loans secured on a car are worse still at typically 200%+ APR and sit outside the Consumer Credit Act. An unsecured personal loan is usually the safer route even at a higher APR.` },
  ],
  'credit-card-repayment-calculator': [
    { question: `How long will it take to pay off £3,000 of card debt?`, answer: `At 19% APR, paying only a minimum of interest plus 1% of the balance, about £74 in the first month and never less than £25, takes 14 years 2 months and £3,433 of interest. Lift the payment to a fixed £100 a month and it is 3 years 4 months and £976. At £200 a month it is 18 months and £411, and at £300 a month, 11 months and £267. Even £50 above that first minimum, £124 a month, saves about £2,700 and more than 11 years of repayment.` },
    { question: `Is a 0% balance transfer cheaper than paying down my current card?`, answer: `Compare the totals. Clearing £3,000 at 19% on the original card at £150 a month takes 24 months and £574 in interest. Transferring the same £3,000 for a 3% fee of £90 and paying £128.75 a month clears the £3,090 in 24 months for £90 in total, saving £484. You need a good credit score to qualify, you must finish before the 0% window closes or the rate reverts to 22-30% APR, and new spending on the transfer card may sit at a different rate.` },
    { question: `What does Section 75 cover on credit card purchases?`, answer: `Section 75 of the Consumer Credit Act 1974 makes your card issuer jointly liable with the retailer when a single item has a cash price over £100 and up to £30,000, covering both retailer failure and goods or services not as described. The limits apply to the item's price, not to how much you put on the card, so paying even part of it by card, such as a £50 deposit on a £5,000 holiday, protects the whole booking, while an item costing £100 or less is not covered however you pay. Debit cards only get chargeback, which is weaker.` },
    { question: `Which UK credit cards are best for spending abroad?`, answer: `Most UK cards add a non-sterling transaction fee of about 2.99%, but a few travel credit cards charge nothing on foreign spending, so look for a 0% non-sterling fee in the card's summary box before you go. Always pay in the local currency and decline dynamic currency conversion at the terminal, which hides a 5-12% margin. Avoid cash advances abroad even on a fee-free card, because interest starts from day 1.` },
    { question: `Should I use the avalanche or snowball method on multiple cards?`, answer: `Avalanche pays the minimum on every card and throws the rest at the highest APR, which saves the most interest, usually £100-£500 on a typical debt load. Snowball clears the smallest balance first, so the early wins keep you going. Pick avalanche unless staying motivated has defeated you before, and let standing orders or direct debits carry the payments so the choice is not remade every month.` },
  ],
  'sole-trader-tax-calculator': [
    { question: `How much tax does a sole trader pay on £55,000 profit?`, answer: `On a net profit of £55,000 the first £12,570 is covered by the Personal Allowance, the next £37,700 is taxed at 20% (£7,540) and the remaining £4,730 at 40% (£1,892), giving Income Tax of £9,432. Class 4 NI adds 6% on profits between £12,570 and £50,270 (£2,262) and 2% on the slice above £50,270 (£94.60). The combined bill is £11,788.60, leaving £43,211.40 to take home.` },
    { question: `How does sole trader tax differ from PAYE?`, answer: `As a sole trader you pay tax on profits (revenue minus allowable expenses), not on gross income. You file once a year via Self Assessment by 31 January, with Payments on Account due 31 January and 31 July if your bill exceeds £1,000. PAYE employees have tax deducted automatically each pay period. Sole traders also pay Class 4 NI at 6% and 2% (Class 2 was abolished in April 2024) instead of the 8% and 2% Class 1 rates employees pay.` },
    { question: `Can I claim my home office and car as a sole trader?`, answer: `Yes, within limits. Working from home is claimed either at HMRC's simplified flat rate of £10, £18 or £26 a month, depending on how many hours a month you work at home, or as a proportion of your actual bills, worked out from the rooms you use and the time you spend. Business mileage is claimed at the HMRC rates of 55p and 25p, and train fares and parking also count, but the ordinary commute never does. Everyday clothes are not allowable either; only uniforms are.` },
    { question: `Do I still pay Class 2 National Insurance as a sole trader?`, answer: `Not compulsorily. Mandatory Class 2, the flat £3.65 a week, was abolished from 6 April 2024. If your profits reach the Small Profits Threshold of £7,105 you are treated as having paid, so your State Pension record is protected at no cost. You can still pay voluntary Class 2 at £3.65 a week if you want to. Class 4 remains: 6% on profits from £12,570 to £50,270 and 2% above that.` },
    { question: `Do I need to register for VAT?`, answer: `VAT registration is compulsory once your taxable turnover exceeds £90,000 in any rolling 12 months. Voluntary registration below this can be worthwhile if your customers are VAT-registered (they reclaim the VAT you charge) or if you make zero-rated supplies. Once registered, you charge VAT on sales and reclaim VAT on purchases. The Flat Rate Scheme simplifies the sums for small businesses with turnover under £150,000.` },
  ],
  'ir35-calculator': [
    { question: `What happens to my take-home pay if a contract falls inside IR35?`, answer: `Inside IR35 the fee-payer deducts income tax and employee National Insurance before you are paid. Paid through an umbrella company, as this calculator assumes, employer NI at 15% also comes out of the rate the agency pays. You lose what a limited company gives you outside the rules, including dividends, most travel and subsistence claims, the Annual Investment Allowance and the option of deferring income into a later tax year. If all profit would otherwise be paid out, the cash gap is often small: about £1,157 a year on £500 a day.` },
    { question: `How is IR35 status decided in practice?`, answer: `Three tests do most of the work. Control asks whether the client dictates how, when and where you work. Substitution asks whether you could genuinely send someone else in your place. Mutuality of obligation asks whether the client must offer work and you must accept it. Financial risk, equipment ownership, integration into the business and exclusivity all count as well. The CEST tool gives a first view, but a contract review from Qdos or Bauer & Cottrell is wiser for anything borderline.` },
    { question: `Who decides my IR35 status, me or the client?`, answer: `Medium and large clients have decided status since April 2021 in the private sector and 2017 in the public sector, and must issue a Status Determination Statement. The fee-payer, usually the agency or end client, becomes liable for unpaid tax if the assessment is wrong. Small clients are exempt where they meet 2 of 3 tests: turnover of not more than £15m, a balance sheet of not more than £7.5m and not more than 50 employees (limits for financial years beginning on or after 6 April 2025). Then the decision, and the risk, is yours.` },
    { question: `How much does being inside IR35 actually cost me?`, answer: `On a £500 day rate across 220 working days with £5,000 of company costs, the calculator gives £67,570.81 outside IR35 against £66,413.92 inside, a difference of about £1,157 a year, assuming all profit is paid out as dividends. Inside, £13,695.65 of employer NI comes out of the £110,000 before your salary is set, which is how umbrella pay works. If the fee-payer pays your own company and adds employer NI on top of the fee, as the rules require, inside take-home is higher than shown.` },
  ],
  'dividend-vs-salary-calculator': [
    { question: `What salary should a limited company director take in 2026/27?`, answer: `£12,570 is the usual answer, matching both the Personal Allowance and the NI Primary Threshold. At that level there is no income tax and no employee National Insurance, and the company pays about £1,135 of employer NI, which is itself deductible against Corporation Tax. Staying above the Lower Earnings Limit of £6,708 matters as well, because that is what earns the year a State Pension credit. The Employment Allowance of £10,500 does not help single-director companies.` },
    { question: `How much tax will I pay on dividends?`, answer: `The first £500 is covered by the dividend allowance. After that the rates are 10.75% at basic, 35.75% at higher and 39.35% at additional rate, and dividends stack on top of salary when the bands are worked out. A director on a £12,570 salary taking £37,700 of dividends stays within the basic rate band and pays £3,999. Corporation Tax at 19% or 25% has already been charged on the underlying profit.` },
    { question: `Do dividends count towards my State Pension record?`, answer: `No. Only salary counts as pensionable earnings and builds State Pension entitlement, which is one reason the low-salary approach stops at £12,570 rather than going lower still. Pay yourself below the Lower Earnings Limit of £6,708 and the year does not qualify for a National Insurance credit at all, so a small saving in employer NI can cost you a qualifying year towards the State Pension.` },
    { question: `Is a pension contribution better than paying a dividend?`, answer: `Often, yes. An employer pension contribution is fully deductible against Corporation Tax, attracts no National Insurance on either side and counts as a company expense rather than director income. The Annual Allowance is £60,000 a year. Swapping £27k of a £67k dividend into the pension saves roughly £4,000 of employer NI and £6,750 of Corporation Tax and defers income tax to drawdown, which for a mid-career director often adds up to £15k to £25k.` },
  ],
  'calorie-calculator': [
    { question: `How many calories do I burn in a day?`, answer: `Start from your Basal Metabolic Rate, which the Mifflin-St Jeor equation predicts from age, weight, height and sex, then scale it by an activity factor between 1.2 for sedentary and 1.9 for extra active. A 30-year-old man of 80kg and 180cm training moderately lands at about 2,760 kcal a day. For comparison, the UK reference intakes are 2,000 kcal for women and 2,500 kcal for men, which are population figures rather than personal targets.` },
    { question: `What is the difference between BMR and TDEE?`, answer: `BMR is what your body burns at complete rest, keeping organs running, the brain working and temperature stable, typically 1,400 to 1,800 kcal a day for an adult. TDEE is BMR multiplied by an activity factor, taking in deliberate exercise, everyday walking and fidgeting, plus the energy spent digesting food, which is roughly 10% of intake. Eat at TDEE to hold your weight, 15 to 25% below it to lose, and 10 to 20% above it to gain.` },
    { question: `Should I count calories to lose weight?`, answer: `It works for some people, though it is not the only route. A sustained deficit of 500 to 750 kcal a day produces 0.5 to 0.75 kg of loss a week, and the NHS advises staying under 1 kg a week. Portion control, more protein and fibre, and cutting ultra-processed food often prove easier to keep up. NICE treats 800 to 1,200 kcal a day as a low-calorie diet and under 800 as a very-low-calorie diet, and advises both only with support from a specialist weight management service, so talk to your GP before going that low.` },
    { question: `How accurate are the calorie counts on food labels?`, answer: `Less accurate than the printed numbers imply. Manufacturer figures can be 8 to 25% out, because the FDA allows a tolerance of 20%, and restaurant meals frequently exceed what the menu states. That is one reason to treat any daily total as an estimate rather than a measurement. Tracking about 80% of your meals is enough to reveal the pattern, and MyFitnessPal, Cronometer and Lose It! all handle UK foods, with MyFitnessPal holding the largest database.` },
  ],
  'concrete-calculator': [
    { question: `How do I work out how much concrete a slab needs?`, answer: `For a rectangular slab, multiply length by width by depth. For round post holes, use pi times the radius squared times depth. The result in cubic metres tells you how much ready-mix to order, and a 25 kg bag of post-mix makes about 0.011 cubic metres. Add 5-10% on top for wastage, spillage and uneven ground before you place the order.` },
    { question: `Should I use bags or order ready-mix concrete?`, answer: `Under 1 m³ the bags usually win, because the minimum ready-mix load is 1 m³ for mini-mix and 6 m³ for a standard truck, though some suppliers will deliver 0.5 m³ at a premium. Above that, ready-mix is both cheaper and more consistent, at roughly £100-£140 per cubic metre delivered in 2026. A shed base needing 0.6 m³ is the awkward case, since paying for a full cubic metre may cost more than about 40 bags at £6 and 4 hours of mixing.` },
    { question: `Which concrete mix should I use for a driveway?`, answer: `A domestic driveway normally takes C25, and the C20/25 grade covering residential slabs and driveways is mixed 1:2:4 by volume as cement, sand and aggregate, at around £110-£130 per cubic metre. Garage and shed foundations manage on C20 at £100-£115. Footpaths and light foundations only need C7.5 at 1:4:6, while structural work and beams call for C25/30 at 1:1.5:3 and heavy industrial slabs for C30/40 at 1:1:2. If you are mixing under 0.5 m³ yourself, bagged general purpose ballast at 1 part cement to 5 parts ballast is simplest.` },
    { question: `How long does concrete take to cure properly?`, answer: `Concrete reaches 70% of its strength at 7 days and 95% at 28 days, which is the point used for testing. You can walk on it after 24-48 hours, drive a car on it after 7 days, and load it fully after 28 days. Ideal conditions are 10-25°C with 60-90% humidity. Below 5°C it will not cure properly, so use an accelerator or wait, and above 30°C mist the surface with water for the first 3 days to stop it cracking.` },
    { question: `Do I need mesh reinforcement in a concrete slab?`, answer: `Slabs larger than 4m², or any slab that will carry weight, should have A142 or A193 steel mesh, around 1.5kg per square metre. A142 is the standard choice for driveways and A193 suits areas taking vehicle loads. Position the mesh a third of the way up from the bottom of the slab rather than resting it on the base. Keep the finished pour moist for 7 days or more under polythene or wet hessian while it hardens.` },
  ],
  'paint-calculator': [
    { question: `How far does a litre of paint actually go?`, answer: `Coverage varies by product rather than by brand alone. Wall emulsion reaches 10 to 12 m² per litre, gloss and satin for woodwork 12 to 16, and masonry paint only 5 to 7 because exterior render drinks it. A bare, textured or porous surface adds 20 to 30% to the first coat. Quality changes the sum too, since a cheap tin that needs three coats can cost more per wall than a premium one covering in two.` },
    { question: `How much paint do I need for one room?`, answer: `Measure each wall as length by height, add them up, then subtract the doors and windows before dividing by the coverage rate of your chosen paint. Double the litres if you are applying two coats. A standard room of 4 m by 4 m with a 2.4 m ceiling has about 38 m² of wall once a door is deducted, so expect 6 to 8 litres for two coats, plus 10 to 15% spare for touch-ups.` },
    { question: `Do I need to prime before painting?`, answer: `Primer earns its place on bare wood, metal or plaster, on glossy surfaces, on heavily patched walls, when going from a dark colour to a light one, and over water damage where a stain-blocking primer is the only thing that will hold the mark back. You can skip it when staying within the same colour family, on sound walls with a similar finish, or with modern self-priming paint. Stain-block primers cost £15 to £30 a litre and often save one or two topcoats.` },
    { question: `Is trade paint better value than retail paint?`, answer: `Trade ranges such as Dulux Trade, Crown Trade and Johnstone's Trade cost more per litre but cover better, frequently in one coat where a retail tin from Wilko or B&Q needs two. The cost per square metre works out similar, so the real saving is time and days of disruption. Trade lines are sold to the public at Wickes Pro, Toolstation and Brewers, and on a full repaint the extra outlay is generally worth it.` },
  ],
  'percentage-calculator': [
    { question: `How do I work out the percentage change between two numbers?`, answer: `Subtract the old value from the new one, divide by the old value and multiply by 100. Going from £80 to £100 gives a change of plus 25%. The direction of travel matters, because coming back down from £100 to £80 is minus 20%, not minus 25%, since the base you divide by has changed. Identifying the base before you start is the habit that prevents most percentage mistakes.` },
    { question: `How do I remove 20% VAT from a gross price?`, answer: `Divide by 1.2 rather than subtracting 20%. A gross price of £120 comes down to £100 net, leaving £20 of VAT, which is one-sixth of the gross figure. Subtracting 20% from the gross gives the wrong answer, because the VAT was added to the smaller net amount, not to the larger gross one. The standard rate has been 20% since 4 January 2011, and the reduced 5% rate on domestic energy works identically by dividing by 1.05.` },
    { question: `Why does a 50% loss need a 100% gain to recover?`, answer: `Gains and losses are multiplicative rather than additive. £100 falling by 50% leaves £50, and getting £50 back up to £100 means doubling it, which is a 100% gain. The same asymmetry runs down the scale, so a 30% fall needs about 43% to break even rather than 30%. That is why drawdowns hurt twice over, and why a 30% market fall close to retirement does far more damage than the same fall early in a working life.` },
    { question: `What are the quickest mental shortcuts for percentages?`, answer: `For 10% of any number, divide by 10, and for 1%, divide by 100. A quarter is 25%, a half is 50%, and dividing by 3 gets you close to 33%. Adding 20% VAT means multiplying by 1.2, and stripping it out means dividing by 1.2. To increase a figure by a percentage, multiply by one plus that percentage over 100. Stacked discounts multiply rather than add, so 25% off followed by 10% off leaves 0.675 of the price, which is 32.5% off in total, not 35%.` },
    { question: `How long does money take to double at 5% a year?`, answer: `Roughly 14.4 years, on the Rule of 72, which divides 72 by the annual return to estimate doubling time. At 8% it takes 9 years and at 10% about 7.2. Working the compound formula properly, £10,000 at 5% grows to £10,500 after one year, £11,025 after two, £16,289 after ten and £43,219 after thirty. Inflation runs the same machinery in reverse, so at 3% a pound holds only 41p of its buying power after thirty years.` },
  ],
  'age-calculator': [
    { question: `How is age calculated when the months and days roll over?`, answer: `Take the current year minus the birth year, then subtract one if you have not yet reached your birthday this year. Months work the same way, current month minus birth month, borrowing from the years if that goes negative, and days borrow from the months. UK convention is that you turn 18 on the anniversary of your birth, not the day before. Someone born on 29 February is treated as celebrating on 28 February in non-leap years for most UK legal purposes.` },
    { question: `At what age can I take my pension and State Pension?`, answer: `A defined contribution pension can be accessed from 55, rising to 57 in April 2028. State Pension age is currently 66, moving to 67 between 2026 and 2028, and to 68 from 2044. The claim window for the State Pension opens 4 months before you reach pension age, so it is worth diarising rather than waiting to be contacted. A free TV licence at 75 has been limited to Pension Credit recipients since 2020.` },
    { question: `How many days old am I at 18, 30 or 65?`, answer: `Using an average year of 365.2425 days, 18 years works out at roughly 6,575 days, which is 939 weeks or 216 months. Thirty years is about 10,957 days, 1,565 weeks and 360 months, and 65 years comes to around 23,741 days. State Pension age at 66 is about 24,107 days, while reaching 100 means clocking up 36,525 days. The calculator gives the exact figure for your own date of birth rather than these averages.` },
    { question: `Does an age gap between partners affect pensions or tax?`, answer: `It can. Pension survivor benefits, life insurance pricing and inheritance tax planning all weigh the gap between two dates of birth. A difference of ten years or more to a spouse usually attracts higher annuity rates, since a younger survivor means a longer payout, though upfront pension transfer values tend to be lower. Marriage Allowance is unaffected by the gap and is worth £252 a year where one partner is a non-taxpayer and the other pays basic rate. Spousal State Pension top-ups ended under the New State Pension rules in 2016.` },
    { question: `When exactly does my age go up for insurance purposes?`, answer: `Most insurers treat you as a year older from 23:59 on the day before your birthday, so a quote run on the wrong side of that line can come back at a different price. Other date-driven events are fixed rather than personal. DVLA licence renewal falls at 70 and then every 3 years, a Child Trust Fund for anyone born between 2002 and 2011 becomes available at 18, a Junior ISA becomes an adult ISA at 18, and the ISA contribution year resets on 6 April regardless of when you were born.` },
  ],
  'currency-converter': [
    { question: `How do live exchange rates differ from tourist rates?`, answer: `The figure quoted by Google or XE is the mid-market rate, the midpoint at which banks deal with each other. Tourist and retail rates add a markup of 2% to 5% on top. Wise, Revolut and Chase sit close to mid-market with low or no fees, while airport bureaux de change run a spread of 5% to 12%, and credit card cash advances charge 3% plus interest from day one. Comparing providers means adding the margin and any fixed fee together rather than judging by the headline rate.` },
    { question: `What do UK banks charge me for spending abroad?`, answer: `A standard UK debit card adds a non-sterling transaction fee of 2.75% to 2.99%, and cash withdrawals attract an ATM operator fee of 1% to 3% on top. Credit cards charge 2.99% for non-sterling spending plus a 3% cash advance fee, with interest running from the day of withdrawal. Chase, Starling, Monzo Plus, Revolut and Wise avoid most of this. Whatever card you carry, pay in the local currency and decline Dynamic Currency Conversion at the terminal, which hides a 5% to 12% margin.` },
    { question: `Why does the pound rise and fall against the euro?`, answer: `The main driver is the Bank of England base rate set against the Fed and ECB, since a higher UK rate tends to support sterling. Inflation relative to trading partners and the persistent current account deficit pull the other way. Political shocks act fastest, with the 2016 Brexit vote taking roughly 15% off the pound and the Truss mini-budget removing 8% within days in September 2022. Sterling has free-floated since the ERM exit in 1992, and the long-run trend against the dollar runs from $4.03 in 1947 to about $1.27 in 2026.` },
    { question: `Do I pay tax on foreign currency gains in the UK?`, answer: `Only where the currency was held as an investment. Notes bought for holiday spending are exempt from Capital Gains Tax entirely. Currency sitting in a foreign savings account or in foreign bonds is chargeable, with gains above the £3,000 annual exempt amount for 2026/27 taxed at 18% or 24% depending on your band. Crypto-to-stablecoin trades count as a disposal each time. Businesses take forex gains and losses through the profit and loss account. An ISA cannot hold foreign currency directly, although it can hold US or EU shares with conversion done at the point of trade.` },
    { question: `What is the cheapest way to send a large sum abroad?`, answer: `Specialist brokers beat high-street banks by a wide margin on larger sums. CurrencyFair and OFX typically work at 0.4% to 0.6% where a bank takes 2% to 3%, which on a property deposit runs into thousands of pounds. Wise is the usual choice where you want transparent fees at the mid-market rate. A forward contract fixes today's rate for a future settlement date, which suits a completion date that is known but still distant. Avoid converting at weekends, when the market is shut and the spread widens.` },
  ],
  'discount-calculator': [
    { question: `Why is 20% off then 10% off not 30% off?`, answer: `Because the second discount is taken from the already-reduced price rather than the original. Multiplying 0.80 by 0.90 leaves 0.72 of the ticket price, which is 28% off in total, not 30%. The same effect turns 50% plus 25% into 62.5% off rather than 75%. Order makes no mathematical difference, but retailers sometimes apply a code only to certain lines, or only after sale prices, so the basket total is what to check.` },
    { question: `How do I find the original price from a sale price?`, answer: `Divide the sale price by one minus the discount over 100. Something marked £60 at 25% off started life at £80, because £60 divided by 0.75 is £80. Entering the sale price and the original price the other way round gives you the percentage that was applied, which is the quickest way to test whether a reduction is as large as the sign claims or whether the original was inflated first.` },
    { question: `Do UK retailers have to prove a was price is genuine?`, answer: `Yes. The Consumer Protection from Unfair Trading Regulations 2008 require honest reference pricing, meaning the higher price must have been genuinely charged for a meaningful period beforehand, usually 28 or more consecutive days within the previous 6 months. Trading Standards investigate complaints, misleading pricing can void a sale, and the ASA rules on advertising. CamelCamelCamel covers Amazon UK price history, while PriceSpy and Idealo show 90-day tracking elsewhere.` },
    { question: `Does a discount come off before or after VAT?`, answer: `It depends which side of the till you are on. Consumer prices already include VAT, so the discount comes off the gross figure and the VAT inside it falls with it. Take 20% off £120 and you pay £96, with the VAT dropping from £20 to £16. On a B2B invoice quoted net, the discount comes off first and VAT is added afterwards, so £100 less 20% is £80 and adding 20% VAT gives £96. Trade and bulk discounts reduce the VAT base, and a prompt-payment discount means adjusting the invoice if the customer takes it.` },
    { question: `When are the best times to buy discounted goods in the UK?`, answer: `Bank holiday weekends in May and August, late November for Black Friday, and Boxing Day into January for white goods and clothing. Treat up to 80% off headlines carefully, since they usually cover a few clearance lines only. First-order codes from retailer email sign-ups are typically 10-15%, cashback through TopCashback or Quidco adds another 3-8% on top of a code, Tesco Clubcard prices cut selected items by 50% for members, and UNiDAYS or Student Beans add 10-15% for students, often valid up to 25.` },
  ],
  'tip-calculator': [
    { question: `How much should I tip in a UK restaurant?`, answer: `Tipping is a personal choice rather than a requirement, with 10 to 12.5% of the bill being typical. Many restaurants add an optional 12.5% service charge, rising towards 15% in London, and you can ask to have it removed if the service was poor or simply because you would rather tip another way. On an £85 bill for two, 10% comes to £8.50, 12.5% to £10.63 and 15% to £12.75.` },
    { question: `Can I refuse the discretionary service charge on my bill?`, answer: `Yes, and no reason is required. Service charges have had to be labelled discretionary or optional in the UK since the 1980s, so you can ask for the line to come off for poor service or simply because you prefer to tip in cash. Since 1 October 2024 the Employment (Allocation of Tips) Act 2023 has required employers to pass 100% of tips to staff, so refusing the charge is no longer the only way to stop an employer keeping a share.` },
    { question: `Do restaurant staff pay tax on cash tips and card tips?`, answer: `Both count as taxable income, but they reach HMRC by different routes. Cash tips are the employee's own responsibility to declare through Self Assessment, and no National Insurance is due on money handed over directly. Card tips distributed through a tronc have PAYE deducted before staff are paid, and NI is payable because the employer treats them as wages. A service charge added to the bill and then shared out attracts both PAYE and NI, exactly like ordinary pay.` },
    { question: `How should we split a bill and its service charge?`, answer: `An even split is fairest when everyone ordered roughly the same. A group of 8 with a £200 bill plus 12.5% service comes to £225, which is £28.13 a head. Where one person had the £80 steak and another the £15 pasta, itemising through Splitwise or Tricount saves an argument. The person being celebrated traditionally has their share covered by the group, service included, and parties of 8 or more often face an automatic service charge, so check the menu before ordering.` },
    { question: `How much should I tip a taxi driver or delivery rider?`, answer: `Taxi fares are usually rounded up to the nearest pound, or tipped at 10% on a longer journey, and Uber offers 10 to 15% in the app. Delivery riders for Uber Eats or Deliveroo generally get 5 to 10% where the service was good. A collected takeaway needs nothing at all. Elsewhere, hotel porters take £1 to £2 a bag, housekeeping £1 to £3 a night, a hairdresser or barber 10 to 15%, and a tour guide £5 to £10 a day.` },
  ],
  'vat-flat-rate-calculator': [
    { question: `When is the VAT Flat Rate Scheme worth using?`, answer: `It works best for service businesses with very little input VAT, such as consultants, freelancers and designers. Retailers, manufacturers and anyone reclaiming VAT worth 5% or more of turnover usually do better on standard accounting. Compare what you would reclaim under standard accounting with what the flat rate leaves you from the 20% you charge. Since the limited cost trader rule arrived in 2017, many service businesses turning over £85k-£150k have found standard VAT cheaper.` },
    { question: `Who counts as a limited cost trader?`, answer: `You are a limited cost trader if you spend less than 2% of turnover on goods, or less than £1,000 a year on goods where turnover is under £50,000. Goods means physical items, so services, food, motor fuel, vehicle leasing and capital items over £2,000 are excluded from the test. Most consultants, accountants and IT contractors buy software, training and travel, all services, so they fail it and pay 16.5% of gross turnover instead of their sector rate.` },
    { question: `Can I reclaim VAT on equipment while on the Flat Rate Scheme?`, answer: `Yes, on a single capital purchase of more than £2,000 including VAT shown on one invoice. A £2,500 laptop with £500 of VAT is fully reclaimable even though you are on the flat rate, and property, vehicles and machinery normally qualify. Purchases below £2,000 per invoice do not, and separate smaller invoices cannot be added together to reach the threshold. Where one invoice lists several unrelated items, get advice before claiming, because HMRC applies the test strictly.` },
    { question: `How do I leave the Flat Rate Scheme?`, answer: `Write to HMRC and the change takes effect from the start of a VAT period, since you cannot switch part way through a quarter. Leaving is voluntary at any time, though it becomes compulsory once turnover including VAT passes £230,000, and you cannot rejoin for 12 months. Common reasons to go are rising input VAT on equipment or vehicles, a change in what the business sells, or the limited cost trader rule making the scheme uneconomic. On the way out you account for VAT on closing stock at the standard 20%.` },
  ],
  'flooring-calculator': [
    { question: `How much extra flooring should I buy to cover wastage?`, answer: `Add 10% on top of the room area for a straight laminate or engineered wood layout, rising to 15% for diagonal or herringbone patterns or rooms with many corners. Tiles need about 10% for cuts, and large vinyl sheets only 5%. Vinyl and carpet come off rolls (usually 2 m or 4 m wide), so the amount you need depends on roll width against your room size rather than a simple percentage.` },
    { question: `How do I work out how many packs or tiles to order?`, answer: `Measure the room in metres and multiply length by width to get the area in m², then add your waste allowance. Most laminate and vinyl plank packs cover 2-2.5 m² each, so divide the area including waste by the pack coverage and round up. For tiles, a standard 600×600mm tile covers 0.36m². Underlay is bought separately in rolls of around 10-15m², and you will need one door bar or transition strip per doorway.` },
    { question: `How long do laminate, LVT, engineered wood and carpet last?`, answer: `Laminate typically lasts 10-20 years. LVT is waterproof and lasts 20-30 years. Engineered wood gives a real timber surface that can be sanded and refinished 2-3 times, while solid wood can be refinished many times over. Carpet is the warmest underfoot but is usually replaced every 8-12 years, so a cheaper product does not always work out cheaper across the life of the room.` },
    { question: `Can I fit laminate or LVT myself, or should I hire a fitter?`, answer: `Click-together laminate, click LVT and click engineered wood are realistic DIY jobs for a confident amateur. Around £100 buys the tools (saw, cutter, spacers and hammer), and a 20m² room is a 1-2 day project. Solid wood that has to be nailed or glued is better fitted professionally at £15-£30/m² labour, carpet is nearly always laid by a professional with a free measure, and tiling is a job for a tiler. Whichever route you take, match the underlay to the floor: a vapour barrier over solid floors, foam under laminate, stick-down under vinyl.` },
    { question: `Can I lay laminate or wood flooring over underfloor heating?`, answer: `Yes, provided the underlay is chosen for it. Underfloor heating needs a thin, conductive underlay with a tog value under 1.0 so the warmth reaches the room. Most thick foam or felt underlays are designed to insulate, which means they hold the heat in the floor and make the system slow and expensive to run. Over a concrete subfloor you still need a damp-proof membrane beneath everything.` },
  ],
  'tile-calculator': [
    { question: `How many tiles do I need to cover a wall or floor?`, answer: `Divide the area you are tiling by the size of one tile, for example 0.09 m² for a 300 by 300 mm tile or 0.36 m² for a 600 by 600 mm one. Include 10% for cuts and breakages, or 15% if you are laying a diagonal or complex pattern. Measure walls individually and take off windows and doors, and measure floors at their longest and widest points so alcoves are not missed.` },
    { question: `How much tile adhesive and grout do I need?`, answer: `Allow roughly 2–3 kg of adhesive per m² for wall tiles and 3–5 kg per m² for large floor tiles. Grout comes in 5kg bags and each covers 5-15 m², with narrow 2mm wall joints at the top of that range and wide rustic stone joints at the bottom. For a small 4.5 m² bathroom floor that works out at about 15 kg of adhesive and 2 kg of grout, so one bag of each is usually enough.` },
    { question: `How much does it cost to tile a bathroom in the UK?`, answer: `Materials for a 12 m² floor in mid-range porcelain come to about £650 including tiles with waste, adhesive, grout, spacers and sealant. Labour is the bigger cost at £60-£90/m² for floors and more for walls, so a floor plus 30 m² of walls at £75/m² adds £3,150. A full mid-range bathroom re-tile therefore tends to cost £3,500-£5,000, and doing it yourself saves £2,500-£4,000 in exchange for 3-5 days of work.` },
    { question: `Can I use ceramic tiles on a bathroom floor?`, answer: `Ceramic tiles at £15-£40/m² are softer than porcelain and are best kept to walls and light-traffic floors, so a small bathroom floor is possible but a busy family bathroom or wet room is better served by porcelain at £25-£70/m², which is harder, denser and frost-proof. Whatever the material, check the anti-slip rating: R9 covers an indoor wet area, while R10-R11 is the safer choice for wet rooms and kitchens.` },
  ],
  'gravel-calculator': [
    { question: `How deep should a gravel driveway be?`, answer: `A driveway usually wants 40 to 50 mm of gravel over a compacted sub-base, while paths and borders need only 25 to 40 mm. Multiply the area by that depth to get the volume, then convert to tonnes using a bulk density of roughly 1.5 to 1.8 t/m³. Going deeper than needed wastes money, while going shallower lets the sub-base show through once the gravel settles.` },
    { question: `How many bulk bags of gravel do I need for a driveway?`, answer: `A standard bulk bag holds about 0.5 m³, or 0.8–0.9 tonnes. Work out the volume (area × depth), multiply by the density to get tonnes, then divide by the weight of one bag and round up. An 8 m × 3 m drive at 50 mm deep is 1.2 m³, which at 1.7 t/m³ is 2.04 tonnes, so 3 bulk bags. Once you get to 5 tonnes or more, a loose tipper delivery is much cheaper per tonne if the lorry can get in.` },
    { question: `Do I need planning permission for a gravel driveway?`, answer: `Usually not. Since 2008 a new front-garden driveway over 5 m² in England must either drain naturally or have planning permission, and loose gravel is permeable, so it qualifies as permitted development. Resin-bound porous gravel also passes, while bonded resin, which is impermeable, needs a planning application. Local rules can differ, so check with the council before the delivery arrives.` },
    { question: `What goes under the gravel on a driveway?`, answer: `Gravel tipped straight onto soil sinks and ruts. Excavate 250-300mm, lay a weed membrane, then compact 150mm of Type 1 MOT sub-base at £40-£60/tonne before the gravel goes on top. A honeycomb gravel grid such as Nidagravel or X-Grid at £15-£30/m² is optional but holds the stones in place under car tyres, and without one you should expect to top up the surface every year. Edging at £8-£20 per metre stops the gravel escaping onto the lawn.` },
    { question: `How much does gravel cost per tonne in the UK?`, answer: `Standard aggregates delivered cost around £50–£80 per tonne and premium decorative gravel £80–£150 per tonne. By the bulk bag, 10mm pea gravel is £45-£75, 20mm Cotswold buff £60-£100, limestone chippings £55-£90, granite £70-£110 and slate £80-£140. Haulage is a big part of the bill, so a quarry within 20 miles is normally noticeably cheaper than a national supplier.` },
  ],
  'wallpaper-calculator': [
    { question: `Does a large pattern repeat mean I need more rolls of wallpaper?`, answer: `Yes. A standard UK roll is 10.05 m long and 0.53 m wide (about 5 m²) and gives four drops in a 2.4 m room with a plain paper, but a large repeat such as 64 cm cuts that to two or three drops per roll because each length has to be trimmed to line the pattern up. A half-drop match wastes the most, so budget for it when comparing papers.` },
    { question: `How many rolls of wallpaper do I need for a bedroom?`, answer: `Measure the perimeter of the room and divide by the roll width of 0.53 m to get the number of drops, take off roughly half a drop for each door and window, then divide by the drops you get per roll at your ceiling height and pattern repeat. A 4 m × 3 m room with a 2.4 m ceiling and a 32 cm repeat has a 14 m perimeter, which is 27 drops, or 25 after one door and one window. At 3 drops per roll that is 9 rolls, and a single feature wall is usually 1-2 rolls.` },
    { question: `What is the difference between paste-the-wall and paste-the-paper wallpaper?`, answer: `With traditional paste-the-paper you cut the length, paste the back, fold it, let it soak for 5-10 minutes and then hang it. It is messy but works for every type of paper. Paste-the-wall papers have a non-woven backing, so you paste the wall and hang the dry paper straight onto it, which is faster, cleaner and far easier for a first-timer. Most modern wallpapers are paste-the-wall, but check the label before you buy paste.` },
    { question: `Should I hang wallpaper myself or hire a decorator?`, answer: `Simple patterns, straight walls and a single feature wall are sensible DIY jobs, with no labour cost and around £40 of tools. A professional decorator charges £200-£400 a day plus materials and needs about 1.5 days for a typical bedroom. Paying for one is worth it for complex patterns, high ceilings, bay windows, intricate corners or expensive paper at £50 or more a roll, because a poor DIY job costs more to redo than the decorator would have charged.` },
    { question: `Do I need lining paper before hanging wallpaper?`, answer: `Not always, but it is cheap insurance on old plaster. Lining paper costs £3-£5 a roll and hides small imperfections that would otherwise show through the finished wall. Before it goes up, strip the old paper, wash the walls with sugar soap, fill and sand any cracks, and size the surface with diluted paste. Any water stains should be primed with shellac first, or they will bleed through both the lining and the wallpaper.` },
  ],
  'decking-calculator': [
    { question: `How long does a UK decked area last?`, answer: `Pressure-treated softwood lasts 10-15 years if it is cleaned and oiled every year, and less if it is untreated or constantly wet. Hardwood such as oak, ipe or balau reaches 25-40 years with annual maintenance and can pass 50 with care. Composite decking from Trex, Millboard or Ecoscape typically carries a 25-30 year warranty and lasts 30-40 years. Shaded, north-facing decks rot about 2× as fast as south-facing ones, so ground clearance of 150mm and a fall for drainage matter more there.` },
    { question: `Do I need planning permission for decking?`, answer: `Not if the deck is under 300mm above ground level, is not in front of the house, does not overlook neighbours and, with any extensions and sheds, covers no more than 50% of the garden. Higher than 300mm it becomes a raised platform and needs permission. Listed buildings need listed building consent for any external work, and conservation areas apply tighter rules. Building Regulations only come in when a deck is attached to the house and more than 600mm above ground. Retrospective permission costs more than asking first.` },
    { question: `Is composite decking worth the extra cost over timber?`, answer: `Composite boards cost £40–£80 per m² against £20–£40 for treated softwood, but they skip the annual oiling and generally work out cheaper over 20 years or more. They do not rot, splinter, warp or fade, and the textured surface grips better than wet timber, although dark colours can reach 50°C or more in direct sun. Timber feels warmer and more natural and, if FSC-certified, has the lower carbon footprint. Composite is often made from recycled plastic but is harder to recycle at the end of its life.` },
    { question: `Is a deck or a patio better for a British garden?`, answer: `A deck is warmer underfoot, does not crack, copes better with uneven ground and goes down faster. A paved patio costs £80-£200/m² installed depending on whether you choose concrete or natural stone, lasts 40-100 years or more, needs only an annual wash and is not slippery when wet. Stone patios also tend to add more to a property's value than softwood decking. Many people settle on a patio at ground level with a small composite deck for any raised section.` },
  ],
  'fencing-calculator': [
    { question: `Who owns the fence between gardens?`, answer: `The Title Deeds settle it, and they cost £3 to download from the Land Registry. A 'T' mark on the boundary plan on your side means the fence is yours. Builders often gave each house the left-hand boundary as you face it, but there is no legal default, so always check the deeds. Many boundaries are shared. You are not legally obliged to repair a fence unless the deed or lease says so, or the fence has become a nuisance or danger to your neighbour, and even a fence you do not own can be painted on your side.` },
    { question: `How high can a garden fence be without planning permission?`, answer: `Up to 2m in a rear or side garden, and up to 1m where the fence fronts a public road or footpath. Any trellis fixed on top counts towards the limit. Conservation areas often cap fences at 1m on every side, and listed buildings need listed building consent for any new fence. Hedges are treated separately: under the High Hedges Act 2003 (Part 8 of the Anti-Social Behaviour Act) a neighbour can complain to the council about a hedge over 2m that blocks their light.` },
    { question: `How much does it cost to have a fence installed?`, answer: `Materials run from £25-£100 per panel, £15-£35 per post and £5-£8 of postcrete per post, so a 12m fence of 7 panels and 8 posts costs about £640 if you fit it yourself. A professional charges £20-£40 per metre on top, depending on complexity and ground conditions, taking the same fence to £900-£1,400. Gates add £150-£400 each plus £80-£150 to hang. Concrete posts and gravel boards add £100-£200 but stretch the fence's life by 50-100%, and it is the posts and groundwork, not the panels, that cost the most.` },
    { question: `Which fence panels are best for privacy, wind or budget?`, answer: `For privacy and security choose closeboard (featheredge) or hit-and-miss panels at 1.8m. On an exposed site go for hit-and-miss or open-slat panels, since wind passes through rather than pushing the fence over. Lap panels at £25-£50 each are the cheapest but last only 7-10 years. For dogs or chickens pick solid panels with no gap at the bottom. The longest-lived combination is concrete posts, concrete gravel boards and closeboard panels at 25 years or more, against 10-12 for an all-timber fence. Agree the plan with your neighbour first, and sharing the cost is common.` },
  ],
  'body-fat-calculator': [
    { question: `Which measurements does the US Navy body fat method use?`, answer: `Men supply neck and waist measurements, while women also add a hip measurement. The formula combines those circumferences with your height to estimate body fat percentage. Take the neck at its narrowest, the waist at the navel for men or at the narrowest point for women, and the hips at their widest, on bare skin and standing relaxed. Morning, before eating, gives the most consistent reading.` },
    { question: `What body fat percentage is healthy for men and women?`, answer: `For men, 6 to 13% is the athlete range, 14 to 17% is fit, 18 to 24% is acceptable and 25% or more counts as obese. For women the equivalents are 14 to 20%, 21 to 24%, 25 to 31% and 32% or more. Essential fat, the level below which health is compromised, is around 3 to 5% for men and 10 to 13% for women. Distribution matters as well, since a waist above 94cm in men or 80cm in women flags raised risk on its own.` },
    { question: `Is body fat percentage more useful than BMI?`, answer: `Both are screening tools with limits. BMI needs only height and weight but cannot tell muscle from fat, so a 100kg rugby player at 1.85m reads 29.2 and looks overweight while sitting at perhaps 12% body fat. Body fat percentage means more for anyone athletic, though it is harder to measure well. A DEXA scan is the most reliable at 1 to 2% and reports bone density too, callipers manage 3 to 5% in skilled hands, and tape formulas such as the Navy and Jackson-Pollock come in at 5 to 8%.` },
    { question: `How accurate are home body fat scales and callipers?`, answer: `Home methods vary more than their displays suggest. Bioelectrical impedance in gym and smart scales drifts by 5 to 10% and moves with your hydration, so the same person can read differently morning and evening. Skinfold callipers over 3 to 7 sites reach 3 to 5% once the technique is practised, which makes them the best option at home. Tape measure formulas including the Navy method land at 5 to 8%, and a DEXA scan at £80 to £150 gets you to 1 to 2%.` },
  ],
  'pregnancy-due-date-calculator': [
    { question: `How accurate is a due date based on my last period?`, answer: `Nägele's rule adds 280 days to the first day of your last period, which gives a good estimate but no more than that. Only about 4% of babies arrive on the exact date and 80% are born within 2 weeks either side. The NHS dating scan at 8 to 14 weeks is more accurate, and the due date is moved if the two differ by 7 days or more. Full term starts at 37 weeks, late term at 41 and post-term at 42, with induction usually offered between 41 and 42.` },
    { question: `What maternity pay am I entitled to in the UK?`, answer: `Statutory Maternity Leave runs to 52 weeks, split into 26 weeks Ordinary and 26 weeks Additional. Statutory Maternity Pay covers the first 6 weeks at 90% of your earnings, then £194.32 a week or 90% of earnings if that is lower, for a further 33 weeks, so 39 weeks are paid and 13 unpaid. You need 26 weeks of continuous employment with the same employer by 15 weeks before the due date, and earnings above the Lower Earnings Limit of £129 a week. Otherwise Maternity Allowance pays £194.32 for 39 weeks through Jobcentre Plus.` },
    { question: `When are my NHS antenatal appointments and scans?`, answer: `The booking appointment falls at 8 to 12 weeks, with history, bloods and screening offered. The dating scan and Down's screening come at 11 to 14 weeks and the anomaly scan at 18 to 21. A first pregnancy adds midwife checks at 25, 31, 34 and 36 weeks. Week 28 brings blood tests and anti-D for Rh-negative women, and there are appointments at 38, 40 and 41 weeks before induction is discussed. Most take place at the GP surgery or hospital antenatal clinic, with some home visits late on.` },
    { question: `How much folic acid should I take in pregnancy?`, answer: `The NHS advises 400mcg of folic acid daily from 3 months before conception until week 12, which reduces neural tube defects by 70%. A 5mg prescription dose applies if you have diabetes, a BMI of 30 or more, a family history of neural tube defects or you take certain medications. Vitamin D at 10mcg daily runs through pregnancy and breastfeeding. Avoid liver and high-dose vitamin A, unpasteurised dairy, undercooked meat and eggs, high-mercury fish, pâté and alcohol, and keep caffeine under 200mg a day. Prescriptions and dental care are free during pregnancy and for 12 months afterwards, applied for at your GP.` },
  ],
  'alcohol-units-calculator': [
    { question: `Is a pint of lager more units than a glass of wine?`, answer: `One 175 ml glass of 12% wine works out at 2.1 units, a pint of 4% lager at 2.3 units and a single 25 ml measure of 40% spirits at exactly 1 unit, so the pint edges it. Units come from volume in millilitres times ABV, divided by 1,000, with one unit equal to 10 ml of pure alcohol. Strength decides the outcome, and a pint of 5% craft beer reaches 2.8 units.` },
    { question: `What's the UK low-risk drinking guideline?`, answer: `The UK Chief Medical Officers set 14 units a week for both men and women in 2016, spread over 3 or more days with several alcohol-free days. That is about 6 pints of average strength beer, 10 small 125ml glasses of low-strength wine, or 14 single 25ml measures of spirits. Pregnant women are advised to drink nothing at all. No level is completely safe and risk rises with consumption, but 14 units is the threshold below which it is considered low.` },
    { question: `What is the drink-drive limit in Scotland versus England?`, answer: `England, Wales and Northern Ireland allow 80 mg of alcohol per 100 ml of blood, among the highest limits in Europe. Scotland cut its limit to 50 mg per 100 ml in 2014. For a man of 75kg that is roughly 3 to 4 units south of the border, about 2 pints of lager, and nearer 1.5 to 2 units in Scotland, so a single pint. Tolerance varies with sex, weight, food and timing, and 6 or more units in an evening can still show 8 hours later.` },
    { question: `What are the health risks of exceeding 14 units?`, answer: `Above 14 units a week the risks of liver disease, including fatty liver and cirrhosis, of seven types of cancer covering bowel, breast, mouth, throat, oesophagus, liver and voice box, and of heart disease, stroke, mental health problems and accidents all rise. The NHS estimates 80% of alcoholic liver disease occurs in people drinking above the guidelines. Dependence builds gradually, with warning signs such as needing alcohol to function, drinking before noon and hiding consumption. Drinkline is free on 0300 123 1110.` },
  ],
  'sleep-calculator': [
    { question: `When should I go to bed to wake up refreshed?`, answer: `Aim to wake at the end of a 90-minute cycle rather than in the middle of one, since sleep runs through light, deep and REM stages in roughly 90-minute blocks. Most adults need four to six full cycles a night, which is about six to nine hours. Working back from a 7:00am alarm and allowing 15 minutes to fall asleep, that puts bedtime at 11:15pm for 5 cycles or 9:45pm for 6.` },
    { question: `Why does the calculator use 90-minute sleep cycles?`, answer: `Ninety minutes is the average length of an adult sleep cycle, though the real span runs from 75 to 120 minutes. Each cycle moves through light sleep in stages N1 and N2, deep restorative sleep in N3, and REM, where dreaming and memory consolidation happen. Surfacing at the end of a cycle is far easier than being pulled out of deep sleep, where sleep inertia can leave you groggy for 30 to 60 minutes. Because individual cycles vary, track your own over 2 weeks.` },
    { question: `How much sleep do adults really need?`, answer: `The NHS recommends 7 to 9 hours for adults aged 18 to 64, and 7 to 8 for the over-65s. Teenagers need 8 to 10 hours, school-age children 9 to 11 and toddlers 11 to 14. Only about 3% of people are genuine short sleepers who manage on 6 hours, and most who believe they are simply carry a sleep debt. Regularly sleeping under 6 hours is linked to obesity, cardiovascular disease and impaired cognitive function.` },
    { question: `Which sleep hygiene habits actually make a difference?`, answer: `Holding your bedtime within 30 minutes of the same point every night, weekends included, does more than any single evening ritual, because the circadian rhythm responds to regularity. Keep the bedroom at 16 to 19°C, dark enough that no stray LED is visible, and under 30 dB. Stop caffeine well before bed, since its half-life is 5 to 6 hours, so a 7pm sleeper should finish by 2pm. Avoid screens for 1 hour beforehand, and treat alcohol as a false friend, because it fragments REM sleep.` },
  ],
  'date-calculator': [
    { question: `How many working days are there between two dates?`, answer: `Working days exclude weekends and the bank holidays of whichever nation you select, which is eight a year in England and Wales, nine in Scotland and ten in Northern Ireland. Between 1 January and 31 March 2026 there are 89 calendar days, falling to 63 once weekends come out and 61 once bank holidays go as well. HMRC and Companies House count business days for many filing deadlines, so the distinction matters more than it first appears.` },
    { question: `What does one month from a date mean in a contract?`, answer: `UK contract law generally reads it as the same date in the following month, or the last day of that month if the date does not exist. So 31 January plus one month is 28 February, or 29 in a leap year. Years work identically, with 29 February 2024 plus a year giving 28 February 2025. Legal drafting should say whether it means calendar months or 30-day blocks, since the two answers separate whenever a month runs short.` },
    { question: `What are the main UK legal deadlines counted in days?`, answer: `Consumer cooling-off on distance contracts is 14 calendar days from delivery, and a mortgage offer usually carries a 7-day reflection period. An Employment Tribunal claim must be filed within 3 months less 1 day of the incident. Capital Gains Tax on a residential property disposal has a 60-day reporting and payment window. Limitation runs 6 years on a simple contract, 12 years on a deed and 3 years for personal injury, while HMRC can assess 4 years back as standard, 6 where you were careless and 20 where the error was deliberate.` },
    { question: `How much notice applies to redundancy or a tenancy?`, answer: `Statutory redundancy notice is one week for less than 2 years of service, then a week for each further year up to a maximum of 12. A section 21 tenancy notice is 2 months as a minimum, though 4 months applies under the current 2025 rules while the Renters Rights Act awaits implementation. A statutory holiday year can be any 12-month period the employer defines, and an executor's year means 12 months from the grant of probate.` },
    { question: `Why write dates as 2026-03-15 rather than 15/03/2026?`, answer: `Because the UK and the United States disagree about the order. The same day is 15/03/2026 in Britain and 03/15/2026 in America, which causes real confusion in contracts, invoices and bookings that cross borders. ISO 8601 puts the year first and removes the ambiguity entirely. Within the UK, writing 15 March 2026 out in full does the same job, and either is safer than a slash-separated string in anything that will be read abroad.` },
  ],
  'weight-converter': [
    { question: `How many pounds and kilograms are there in a stone?`, answer: `One stone is 14 pounds, or 6.350 kg. A pound is 16 ounces, 0.4536 kg or 453.6 g, and a kilogram works back to 2.205 lb or 0.1575 st. In practice that makes 70 kg equal to 11st 0.4lb, and 75 kg equal to 11 stone 11.35 lb. For rough mental work, multiply kilograms by 2.2 for pounds, divide by 2.2 to reverse it, and multiply stones by 6.35 to reach kilograms.` },
    { question: `What is a healthy weight for my height in stones?`, answer: `BMI divides weight in kilograms by height in metres squared. At 1.75m, or 5'9", the healthy range runs 56.7kg to 76.6kg, which is 8st 13lb to 12st 0lb, with overweight from 76.6kg and obese at 91.9kg, or 14st 6lb. The band moves with height, covering 47-64kg at 1.60m, 53-72kg at 1.70m and 60-81kg at 1.80m. Asian populations use lower thresholds, with overweight starting at BMI 23. BMI cannot separate muscle from fat, so a waist under 94cm for men and 80cm for women is a useful companion check.` },
    { question: `How do I convert US cup measurements into grams?`, answer: `It depends on the ingredient, because cups measure volume and grams measure weight. A US cup of flour is 125g, sugar 200g, butter 227g, rice 200g and milk 240g. Watch which cup a recipe means as well, since a UK Imperial cup is 284ml against 237ml for the US version. Spoons cause less trouble, with a tablespoon at 15ml in both countries, though Australia uses 20ml, and a teaspoon at 5ml everywhere. Weighing in grams is the reliable route for British baking.` },
    { question: `What weight can I drive or post in the UK?`, answer: `A category B licence covers vehicles up to 3,500kg maximum authorised mass, C1 runs from 3,500kg to 7,500kg with an additional test, and category C covers HGVs above 7,500kg. Bridge limits are posted in tonnes, where one tonne is 1,000kg, equal to 0.984 long tons or 1.102 US tons. Royal Mail counts up to 2kg as a small parcel and up to 20kg as medium, with anything over 30kg going by pallet courier. Airline hand luggage typically allows 7kg to 10kg.` },
    { question: `Where does the UK use kilograms rather than stones?`, answer: `Metric is the legal standard for shops and packaging, so supermarkets price produce in kilograms and grams. Gyms label their plates in kilograms, NHS records are kept in kilograms alone, driving licences have used kilograms for vehicle weights since 2014, and aviation cargo is measured in kilograms only. Personal body weight is the stubborn exception, still given as 12st 5lb in conversation. Babies fall in between, weighed in pounds and ounces at birth, with 7lb 5oz typical, before records switch to kilograms by the age of 1.` },
  ],
  'wedding-budget-calculator': [
    { question: `How much does the average UK wedding cost?`, answer: `The Hitched 2025 survey put the average at £20,775, excluding rings and honeymoon, with the median couple spending £18,500. Venue and catering take 55-60% between them, photography 8-12%, attire and accessories 6-10%, entertainment 5-8%, flowers 4-7% and transport 2-3%. A honeymoon adds £3,500-£8,000 on top, and rings usually run £1,000-£3,000. London and the South East sit 25-40% above the national figure, while Scotland, Wales and Northern England come in 15-25% below.` },
    { question: `How much should I budget per wedding guest?`, answer: `Food and drink at UK venues typically runs £60-£150 a head, and the calculator works out your own figure by dividing the catering budget by guest numbers. Evening-only guests cost around 40% of a full day guest. Because catering scales directly with numbers, cutting 20 people from the list saves £2,000-£4,000 depending on venue tier, which is normally the quickest way to bring an over-budget plan back into line.` },
    { question: `What wedding costs do couples usually forget to include?`, answer: `Giving notice at a register office is £35 per person, or £70 a couple, with the ceremony at £46-£64 and a Church of England service carrying a statutory fee of £570 or more in 2026. Then come corkage at £8-£15 a bottle, cake-cutting fees of £2-£5 a slice, a tasting menu at £75-£150 a couple, dress alterations of £100-£300, hair and makeup trials at £100-£200, a videographer at £1,200-£3,500, invitation postage over £100 and bridal party gifts of £200-£500.` },
    { question: `Are wedding gifts from parents free of inheritance tax?`, answer: `Up to a point. Parents can each give £5,000, grandparents £2,500 and anyone else £1,000 free of Inheritance Tax under the relief for gifts in consideration of marriage. Anything above those limits falls back on the ordinary £3,000 annual exemption. Cash received on the day is not taxable income for the couple, and honeymoon registry payments count as gifts as well. Marriage Allowance is separately worth £252 a year and can be backdated up to four years, and civil partnerships have had identical treatment since 2014.` },
    { question: `Does wedding insurance cover a failed supplier or closed venue?`, answer: `Policies costing £80-£250 typically cover cancellation through illness, supplier failure, venue closure, weather on some products, and public liability. What they never cover is a change of heart. Since supplier deposits run 25-50% on booking and are non-refundable, paying them on a credit card adds Section 75 protection on anything above £100. Insist on the full contract in writing, with cancellation terms and force majeure clauses set out, and read any flex policy carefully before relying on it.` },
  ],
  'visa-points-calculator': [
    { question: `How many points do I need for a UK Skilled Worker visa?`, answer: `Seventy in total. Fifty are mandatory and cover sponsorship by a licensed employer, a job at the appropriate skill level and English at B2 (B1 for applications made before 8 January 2026). The final 20 are tradeable and normally come from salary, either at the general threshold of £41,700 or the reduced £33,400 available through the Immigration Salary List, the new entrant route or a relevant PhD. Reaching 70 secures the visa subject to documentation and payment of the health surcharge.` },
    { question: `What salary do I need for a Skilled Worker visa?`, answer: `The general threshold is £41,700 a year, raised from £38,700 on 22 July 2025. A reduced threshold of £33,400 applies for occupations on the Immigration Salary List, for new entrants under 26 or recent graduates and those switching from a study visa, and for applicants with a relevant PhD. Health and Care visa roles sit lower, typically around £25,000. You have to meet whichever is higher, the threshold or the published going rate for your occupation code.` },
    { question: `Which English tests are accepted for a Skilled Worker visa?`, answer: `B2 on the CEFR scale has been the minimum for new applications since 8 January 2026, up from B1, and it has to be shown in reading, writing, speaking and listening, so B1-only tests such as IELTS Life Skills B1 and Trinity GESE Grade 5 no longer qualify. Approved B2 Secure English Language Tests include IELTS for UKVI, Pearson PTE Academic UKVI and LanguageCert. A degree taught in English and verified by UK ENIC works instead, as does citizenship of a majority English-speaking country. Results last 2 years and a test costs around £200. Workers who proved B1 in an earlier grant on the route do not have to retest to extend.` },
    { question: `When can I apply for settlement on a Skilled Worker visa?`, answer: `After 5 continuous years on the route, or 10 years under the long residence rules if your time in the UK spans several visa types. You will need the Life in the UK test at £50, English at B1 (B2 for settlement applications made on or after 26 March 2027), continuous employment in an eligible role and no absence longer than 180 days in any rolling 12-month period. The fee is £3,226, with no health surcharge on the settlement application itself, and citizenship follows 12 months later at £1,709 with a £130 ceremony fee.` },
  ],
  'court-fee-calculator': [
    { question: `What does it cost to issue a money claim in court?`, answer: `Fees start at £35 for claims up to £300 and rise to 5% of the claim value for anything over £10,000, with that percentage capped at £10,000, a ceiling reached once the claim exceeds £200,000. Filing online through Money Claim Online (MCOL) costs the same as a paper claim, so a £5,000 claim costs £205 by either route.` },
    { question: `Can I get help paying court fees if I am on a low income?`, answer: `Yes, through the Help with Fees scheme, which you apply for on form EX160 when you start court action. It is income-based: your gross monthly income must not exceed £1,420 as a single person or £2,130 as a couple, plus £425 for each child aged 0 to 13 and £710 for each child aged 14 or over. Savings must be under £4,250 for a fee of £1,420 or less, rising in steps to £16,000 for fees over £7,000, and anyone aged 66 or over, or with a partner who is, can have up to £16,000 whatever the fee. Successful applicants pay reduced or zero fees, and roughly 40-50% of applications succeed.` },
    { question: `What is the court fee for a divorce application in 2026?`, answer: `A divorce application costs £628 and an application for a financial order costs £321, following the fee changes that took effect on 6 July 2026. Elsewhere in the civil courts, a possession claim costs £415 and general application fees range from £126 to £321 depending on the type of application. These sit outside the money-claim scale, which runs from £35 up to a £10,000 maximum.` },
    { question: `Do I need a solicitor for a small claims court case?`, answer: `Usually not. Claims under £10,000 go on the small claims track, which is designed for litigants in person. The court fee is scaled by the amount claimed, and because there is no 'loser pays' rule on legal costs, each side generally bears only its own fixed costs, so paying a solicitor rarely makes sense. Expect a wait: Ministry of Justice figures for April to June 2026 put the median time from issue to a small claims trial at 41 weeks, and the decision is binding on both sides.` },
    { question: `Are employment tribunal claims free to bring?`, answer: `Yes. Fees for employment tribunals were abolished in 2017, so bringing an employment claim costs nothing. Employment disputes are one of several areas dealt with by tribunals rather than courts: the First-tier Tribunal covers tax, immigration and mental health, and the Upper Tribunal hears appeals from it. Tribunals are generally faster, less formal and cheaper than the equivalent court process. This calculator does not cover tribunal fees, only civil court fees.` },
  ],
  'probate-fee-calculator': [
    { question: `Do I pay a fee to apply for a grant of probate?`, answer: `In England and Wales, estates worth more than £5,000 pay a £526 application fee, and anything valued at £5,000 or below pays nothing. Extra sealed copies of the grant are £2 each if ordered with the application, or £16 each if ordered later. The fee is flat, so it does not rise with the size of the estate.` },
    { question: `When is probate actually needed for an estate?`, answer: `A grant is generally needed once a single asset holds more than somewhere between £15,000 and £50,000, since banks set their own thresholds, and also where property is held in a sole name or investments sit outside an ISA. Jointly owned property passes automatically by survivorship, and genuinely small estates often need no grant at all.` },
    { question: `Is it cheaper to handle probate myself than use a solicitor?`, answer: `Doing it yourself costs only the £526 application fee plus 20 to 50 hours of your own time. A solicitor charges 1% to 5% of the estate value on top, so a £500k estate at 2% comes to £10,000. That is worth paying for complex estates, several properties, business or foreign assets, inheritance tax disputes and contentious or missing wills.` },
    { question: `How do I pay inheritance tax before probate is granted?`, answer: `The tax has to be paid or arranged before the grant is issued, even though the estate's money is not yet accessible. HMRC can issue a grant on credit and take payment from the estate later, the Direct Payment Scheme allows banks to pay the tax directly from the deceased's accounts, and a short-term bridging loan against the estate is a third option. Above £325,000, plus £175,000 of residence nil-rate band where it applies, the rate is 40%.` },
  ],
  'life-insurance-calculator': [
    { question: `How much life cover do I actually need?`, answer: `Start from the debts and the years rather than a multiple. Add your outstanding mortgage to the years until your dependants can support themselves multiplied by annual living costs, add funeral costs, then subtract savings and investments. As a shortcut, UK term policies are usually written at 5 to 7 times salary, so £250k to £350k on a £50k income. Critical illness lump sums are often set at 1 to 2 times salary, and income protection at 50 to 65% of salary up to retirement.` },
    { question: `Level term or decreasing term, which should I choose?`, answer: `Level term holds the same payout for the whole policy, which suits income replacement and providing for a family, so £500k of cover for 25 years pays £500k whenever death occurs within the term. Decreasing term falls in step with a repayment mortgage and costs 30 to 50% less, making it the cheaper choice for pure mortgage protection. Steer clear of decreasing term for an interest-only mortgage, where the balance never falls, or for replacing income.` },
    { question: `Should I write my life insurance into a trust?`, answer: `Usually yes. The payout goes straight to your beneficiaries instead of into your estate, which keeps it out of the inheritance tax calculation and avoids the probate wait of 6 to 12 weeks. It is also protected from creditors. Most UK insurers provide trust documents free, with a discretionary trust the most flexible and an absolute trust the simplest. Set it up when the policy starts, since that is easier than retrofitting it, and expect £150 to £300 in solicitor fees only if the arrangement is complex.` },
    { question: `Why do life insurance claims get rejected?`, answer: `Non-disclosure heads the list, whether of a health condition, smoking or a dangerous hobby, and an insurer can refuse a claim even where the omission had no bearing on the cause of death. Misstating occupation, income or address on the application has the same effect. A policy that lapses after 30 days of missed premiums pays nothing, and most exclude suicide within the first 12 to 24 months. Answer the form honestly, disclose anything you are unsure about, and revisit the policy every 5 years.` },
  ],
  'square-root-calculator': [
    { question: `Can I calculate cube roots and nth roots here too?`, answer: `Cube roots and nth roots are covered as well as square roots. A square root is the value that gives your starting number when multiplied by itself, which is why the square root of 25 is 5, while a cube root multiplies three times, so the cube root of 27 is 3. Cube roots of negative numbers behave normally, giving -2 for -8, whereas negative square roots exist only as imaginary numbers.` },
    { question: `Why does the square root of 2 never end?`, answer: `Because it is irrational, meaning it cannot be written as a fraction of two whole numbers. Its decimal expansion runs on without repeating, starting 1.41421356 and continuing indefinitely, and √3 = 1.7320508... behaves the same way. Only perfect squares, the numbers 1, 4, 9, 16, 25 and so on, produce whole-number roots. Everything in between has to be approximated, which is why results are shown to up to 10 decimal places.` },
    { question: `How do I work out a square root without a calculator?`, answer: `Guess, square the guess and adjust. For √50, start at 7, which squares to 49, then try 7.1, which squares to 50.41, and that is close enough for most purposes. For an exact answer, factorise instead, since √72 is √(36×2), which simplifies to 6√2, or 6 × 1.4142 = 8.485. GCSE questions usually want the surd form, asking you to simplify √50 to 5√2 or rationalise 1/√2 into √2/2.` },
    { question: `What is the 3:4:5 rule builders use for square corners?`, answer: `It comes straight from Pythagoras' Theorem, where c² = a² + b². A triangle with sides of 3 and 4 has a hypotenuse of √(9+16), which is √25, which is 5. Measure 3 units along one wall and 4 along the other, and if the diagonal between the marks is exactly 5 the corner is square. The same square-root step gives straight-line distances in surveying and route-finding, and vector magnitudes in physics.` },
  ],
  'fraction-calculator': [
    { question: `Will my fraction answer be simplified automatically?`, answer: `Every answer is reduced to its lowest terms by dividing the top and bottom by their greatest common divisor, so 6/8 comes back as 3/4. Improper results are also shown as mixed numbers, so 17/12 appears as 1 5/12, and the decimal equivalent is given alongside. Addition, subtraction, multiplication and division all accept whole fractions or mixed numbers such as 2 3/4.` },
    { question: `How do I add fractions with different denominators?`, answer: `Find a common denominator first, then add the numerators. For 2/3 + 3/4 the least common denominator is 12, so the fractions become 8/12 and 9/12, and 8 + 9 = 17 gives 17/12, or 1 5/12. Where there is no obvious common multiple, multiplying the two denominators always works, though it leaves more simplifying to do at the end. Subtraction follows the same steps, so ¾ − ⅓ = (3×3 − 4×1)/12 = 5/12.` },
    { question: `How do you divide one fraction by another?`, answer: `Flip the second fraction and multiply. Dividing ¾ by ½ becomes ¾ × 2/1, which is 6/4, then 3/2, then 1½. Multiplication itself is straightforward, with numerators multiplied together and denominators multiplied together, so ½ × ⅔ = 2/6 = 1/3. Cancelling common factors before you multiply keeps the numbers small, since in 4/9 × 3/8 the 4 cancels against the 8 and the 3 against the 9, leaving 1/6.` },
    { question: `How does the calculator handle mixed numbers like 2 3/4?`, answer: `It converts them to improper fractions before doing anything else, so 1½ becomes 3/2 and 2 3/4 is treated on the same footing. The operation runs on those, and the result is converted back, which is why 7/3 is shown as 2⅓. You get the improper form, the mixed form and the decimal together, so you can check the answer against a rough estimate before writing it down.` },
  ],
  'lawn-seed-calculator': [
    { question: `When is the best time to sow grass seed in the UK?`, answer: `April and May are the strongest window, with soil at 8 to 12°C and reliable spring rain, and September to October comes a close second because the soil is still warm and weed competition is weaker. June to August is risky, since drought stress kills seedlings, and from November to March the soil is too cold for germination to get going. On bare soil expect 7 to 14 days to germinate at 10 to 15°C. Wildflower meadow seed is better sown in autumn, as native species need cold stratification.` },
    { question: `How do I sow grass seed evenly on bare soil?`, answer: `Dig the ground over 100 to 150mm deep, take out weeds and stones, rake level, tread firm and rake again to a fine tilth. Mix the seed 50:50 with sand so you can see the coverage, then sow half of it walking north to south and half walking east to west at 35 to 50 g per m² for a new lawn. Rake in to 1 to 2cm, water with a fine spray and keep the soil moist for 2 to 3 weeks.` },
    { question: `Which grass seed mix suits a family lawn with dogs?`, answer: `A hard-wearing family mix with a high perennial ryegrass content is the one to buy, because it establishes fast and tolerates wear from children and pets. Shade-tolerant blends lean on creeping red fescue and smooth-stalked meadow grass for dappled light under trees. Fine ornamental seed uses chewings fescue and slender creeping red fescue, looks superb and needs weekly mowing. Tall fescue varieties, Festuca arundinacea, root more deeply and survive a summer drought without watering.` },
    { question: `How do I overseed a thin or worn existing lawn?`, answer: `Late summer to early autumn is the best moment, with spring as the alternative. Mow short to 25 or 30mm, then scarify to rake out moss and thatch, because seed cannot germinate sitting on top of thatch. Aerate compacted ground with a hollow-tine aerator, which hires for £30 to £50 a day. Sow at 20 to 25 g per m², top-dress with about 5mm of compost or sandy loam and water until established. Seedlings show in 7 to 14 days and the patch knits together in 4 to 6 weeks.` },
  ],
  'topsoil-calculator': [
    { question: `Is a bulk bag or a loose load cheaper for topsoil?`, answer: `A bulk bag holds 0.7 to 0.9 m³, weighs around 875kg and costs £35 to £80 delivered, which works out at £40 to £100 per m³. A loose tipper load of 10 to 30 m³ costs £30 to £50 per m³ delivered, so it is 30 to 50% cheaper by volume. The catch is access, since you need a path at least 3.5m wide, somewhere to tip the pile and the labour to barrow it across. Under 2 m³ bagged is more practical, while above 5 m³ a loose load saves real money.` },
    { question: `What is the difference between topsoil and subsoil?`, answer: `Topsoil is the upper 200 to 300mm, dark brown or almost black, crumbly, earthy-smelling and full of organic matter, microbes and nutrients, which is what plants need. Subsoil lies from about 300mm down to a metre, is clay or sand based, pale brown, yellow or grey, and holds little organic matter, so it suits bulk filling but not planting. Cheap topsoil is often subsoil in disguise. Squeeze a wet sample: good topsoil holds its shape briefly then crumbles, while clay subsoil forms a tough ball. Reputable suppliers test to BS3882.` },
    { question: `How deep should topsoil be for a lawn or vegetable bed?`, answer: `A lawn wants 100 to 150mm as a minimum, and deeper if you want it to shrug off dry spells. Vegetable beds want 300 to 400mm, with carrots and parsnips happier at the deeper end. Salad and herbs cope with 200mm, fruit bushes want 400 to 500mm, and trees need 600 to 1000mm, more again for a large root ball. Levelling an existing lawn takes only 25 to 50mm of top dressing. Over-order by about 10%, because soil compacts down 10 to 15% in the first year.` },
    { question: `Where can I buy good topsoil in the UK?`, answer: `Builder's merchants such as Travis Perkins, Jewson and Wickes sell mainstream bulk bags at £30 to £60. Garden centres charge two to three times that for branded multi-purpose bags. Local soil suppliers give the best value on loose loads, and construction sites often have surplus that turns up free on Freecycle, Olio or Facebook Marketplace if you collect it yourself. Premium graded topsoil, sieved and low in stone and clay, comes from specialist suppliers at £60 to £120 per m³ delivered. Always see a sample before committing to 5 m³ or more.` },
  ],
  'paving-calculator': [
    { question: `Do I need planning permission for a patio or driveway?`, answer: `For a front garden in England the deciding factor is drainage rather than size alone. Gravel, permeable block paving and porous concrete count as permitted development, whereas sealed concrete or traditional block paving on an impermeable base over 5 m² needs permission unless the run-off goes to a lawn or border. Back garden patios are normally fine below 50% coverage. Listed buildings need consent for external work, and an Article 4 direction can remove those rights street by street.` },
    { question: `How long does laying a 20 m² patio usually take?`, answer: `Two people doing it themselves should allow 3 to 5 days including the base, while a professional crew will finish 20 m² in 2 to 3 days. The first day covers excavation, weed membrane and MOT Type 1 compacted in 50mm layers. The second is edging, laying the slabs on a mortar bed and levelling. The third is pointing the joints, finishing the edges and cleaning down. Leave it 48 hours before walking on it and 7 days before putting furniture out. Block paving runs slightly quicker, as the joints only need sand swept in.` },
    { question: `Which paving material works best in a British garden?`, answer: `Concrete slabs are the cheapest at £8 to £20 per m², reliable but plain. Indian sandstone is the popular mid-range choice at £30 to £60, warm in colour with a riven texture. Limestone is more uniform and modern at £40 to £80. Porcelain at £40 to £100 is frost-proof, never fades and needs no sealing, though it is harder to cut. Block paving at £20 to £50 takes vehicle traffic and lets you replace single units. Slate is distinctive at £50 to £120 but slippery when wet.` },
    { question: `Why is my patio uneven or rocking underfoot?`, answer: `The usual culprit is the base. A sub-base thinner than 150mm of compacted MOT Type 1, or one that was never properly compacted, settles unevenly. Spot bedding on four blobs of mortar instead of a full 25 to 40mm bed does the same. Clay soils heave when wet, tree roots lift slabs and frost heave pushes water underneath. The fix is to take up the affected slabs and redo the base, because spot repairs rarely hold. On block paving, an edging course that was not concreted in lets the bricks migrate sideways.` },
  ],
  'ev-charging-calculator': [
    { question: `Where is the cheapest place to charge an electric car?`, answer: `Home charging with a 7 kW wallbox is the cheapest route at around 26p per kWh on a standard tariff, dropping to 7 to 10p on an off-peak EV tariff. On standard rates a full charge of a 60 kWh battery costs about £15.80, and on an overnight rate the same charge falls to roughly £4.20.` },
    { question: `Which overnight EV tariffs have the lowest unit rate?`, answer: `Eon Next Drive is the keenest of the named tariffs at 6.7p per kWh, followed by Octopus Go at 7 to 9p in a five-hour window from 00:30 to 05:30, the British Gas EV tariff at 7.9p and EDF GoElectric Overnight at 9p. Octopus Intelligent instead shifts the charging window to whenever the grid is cheapest. Nearly all of them require a smart meter, which your supplier installs free.` },
    { question: `How much more does public rapid charging cost than home?`, answer: `A great deal more. Rapid chargers of 50 to 150 kW typically bill 60 to 80p per kWh and ultra-rapids of 150 to 350 kW ask 70 to 85p, so a 60 kWh battery filled at 60p costs about £36, near 15p a mile. Tesla Superchargers are usually the cheapest public rapids at roughly 45 to 55p. Charging almost entirely in public at 15 to 20p a mile puts running costs level with petrol.` },
    { question: `What does it cost to fit a home EV charger?`, answer: `A 7 kW wallbox comes to £400 to £800 fitted now that the homeowner grant has gone, and choosing a tethered unit with the cable permanently attached adds £50 to £100. A 22 kW charger needs a three-phase supply, which few UK houses have, so 7 kW is the practical ceiling on a driveway. Homes built since June 2022 have to include charging infrastructure from new.` },
    { question: `How much of my charging should I do at home?`, answer: `As much as you can. The average UK EV driver charges 80 to 90% at home and uses public chargers for the remaining 10 to 20%, which is what keeps the cost per mile low. A long trip built on 80% home charging and 20% rapid still comes in at less than half the cost of an equivalent petrol car, and workplace charging, where it exists, is often free or subsidised.` },
  ],
  'commute-cost-calculator': [
    { question: `How much does the average UK commuter spend getting to work?`, answer: `ONS Family Spending data for 2024 puts the median outside London at £1,750 a year, or £146 a month, and London commuters at £3,480, around £290 a month. That is 4 to 7% of disposable income regionally and 8 to 12% in London. Drivers often see only the fuel, about £700 to £1,400 a year on a 15 to 30 mile round trip at 40 mpg and £1.72 a litre (UK average petrol, late September 2026), while the full cost of running the car reaches £3,000 to £5,000.` },
    { question: `Is an annual season ticket worth it if I commute three days a week?`, answer: `Usually yes at three days or more, because annual tickets charge for 40 weeks and cover the full year. On a London Zone 1-6 route that is £3,000 against £5,302 in daily Travelcards, a 43% saving. Monthly tickets save less, the equivalent of 8 to 12 weeks a year. At two office days a week, daily tickets normally work out cheaper than either, and a flexible arrangement suits an irregular pattern better.` },
    { question: `How much can the Cycle to Work scheme actually save me?`, answer: `The bike and accessories come out of pre-tax salary, so a basic-rate taxpayer saves 32% from income tax at 20% and National Insurance at 12%, and a higher-rate taxpayer saves 42%. You repay over 12 months, then buy the bike at fair market value, typically 7% after a year, 13% at 18 months and 3% after four years. On a £2,000 e-bike a higher-rate taxpayer saves about £840, and the cycling itself removes £800 to £1,500 of annual commuting cost. Your employer has to run the scheme.` },
    { question: `Can I claim the working from home tax relief?`, answer: `Not for 2026/27 onwards, because employee tax relief for working from home was abolished from 6 April 2026. You can still claim for 2022/23 to 2025/26 if home working was required rather than chosen, meaning an office was unavailable or your contract specified it, at a flat £6 a week (£312 a year) with no receipts, worth £125 a year to a higher-rate taxpayer and £62 at the basic rate. An employer can still pay you £6 a week tax free instead.` },
  ],
  'mileage-allowance-calculator': [
    { question: `At what rate can I claim mileage for using my own car?`, answer: `Cars and vans are paid 55p a mile for the first 10,000 business miles (up from 45p on 6 April 2026) and 25p after that. Motorcycles get a flat 24p per mile and bicycles 20p, with no distance threshold, for the whole 2026/27 tax year. The car and van increase, announced on 21 May 2026, was the first since 2011, and the other rates did not change.` },
    { question: `What counts as business mileage for HMRC?`, answer: `Journeys between offices, to client sites, to training and to meetings away from your regular workplace all count. The trip from home to your normal office is commuting and never qualifies, and if you detour from that commute for work, only the extra miles above the usual journey count. Under the temporary workplace rule, travel to a single site on an assignment of under 24 months qualifies provided the site is not your normal base.` },
    { question: `What if my employer pays less than the HMRC mileage rate?`, answer: `You can claim tax relief on the shortfall between what you were paid and the AMAP rate, either on a P87 form or through Self Assessment, and the same applies if your employer pays nothing for business mileage. If your employer pays exactly the AMAP rate there is nothing to claim, and if it pays more than AMAP the excess is taxable as a benefit in kind through the P11D. Employers are allowed to pay less than the HMRC figure.` },
    { question: `Can I claim 55p a mile for an electric car?`, answer: `Yes. A privately owned EV used for business earns the same AMAP rates as a petrol or diesel car, so 55p a mile for the first 10,000 miles and 25p after that, and with running costs of roughly 2p a mile the surplus is large. Company-car drivers use the separate Advisory Electricity Rate instead, which from 1 June 2026 is 7p a mile for home charging and 15p for public charging and is reviewed quarterly.` },
    { question: `Can I claim extra for carrying a colleague on a business trip?`, answer: `Yes, the passenger payment adds 5p per mile for each fellow employee you carry on a qualifying business journey in a car or van, and it is tax-free for the driver. The passenger makes no separate claim as long as they travel in the same vehicle on the same trip. Carrying a colleague for 3,200 business miles in a year, for instance, adds £160 to the driver's allowance. The supplement is not available for motorcycles or bicycles.` },
  ],
  'radiator-btu-calculator': [
    { question: `How is the BTU size of a radiator worked out?`, answer: `The starting figure comes from room volume (length times width times height in metres) multiplied by a base factor of about 153 BTU per cubic metre. That base is then adjusted for external walls, window type and size, insulation, the room's position and the temperature you want. A 48 m³ living room starts at 7,344 BTU/h and rises to 9,547 BTU/h once two external walls are counted at 15% each.` },
    { question: `How do I convert radiator BTU to watts?`, answer: `Multiply BTU/hr by 0.293 to get watts, or remember that 1 kW is 3,412 BTU/hr. As a check, a 1,000mm × 600mm Type 11 single panel rated at 920W is 3,140 BTU/hr, and a Type 22 double panel of the same size at 1,700W is 5,800 BTU/hr. Manufacturers list both units, but make sure the figures you compare are all at Delta T50.` },
    { question: `What does Delta T50 mean on a radiator?`, answer: `It is the standard test condition under which UK manufacturers publish outputs, a 50°C ΔT between the radiator water and the room. Older catalogues quoted outputs at 75°C ΔT, which looks far more generous but bears no relation to a modern boiler running at 50-60°C flow. Comparing radiators at Delta T 50 tells you what they will actually put out on your system, and a heat pump at 35-45°C will deliver less again.` },
    { question: `Will my existing radiators work with a heat pump?`, answer: `Often not without changes. A heat pump runs at 35-45°C rather than the 70-80°C of a gas boiler, so a double panel that gives 1,500W on gas drops to roughly 500W, and you need 2-3× the surface area to heat the same room. The usual fixes are bigger radiators, fan-coil units or underfloor heating. The £7,500 Boiler Upgrade Scheme grant depends on the installer confirming that heat emission is sufficient, so radiator sizing is checked during the survey.` },
    { question: `Is it better to oversize or undersize a radiator?`, answer: `A small shortfall is easier to live with than a big surplus. If a radiator is 10-20% under, turning the TRV up and giving the room longer to warm up usually covers it. Go much further under and the room never reaches temperature. Oversizing costs more up front, overshoots the target and leaves the radiator cycling on and off, so aim for an output that matches or just exceeds the calculated BTU/h figure.` },
  ],
  'bricks-calculator': [
    { question: `How many bricks per square metre of wall?`, answer: `A single-skin wall (half-brick, 102.5mm thick) needs 60 bricks per m² using standard 215×102.5×65mm bricks with 10mm joints, and a full-brick wall 215mm thick needs 120 per m². A cavity wall uses 60 facing bricks per m² for the outer skin plus concrete blocks for the inner. A 4m × 1.5m garden wall in a single skin is 6 m² × 60 = 360 bricks, or 380 with 5% waste. Order everything from the same batch, since the shade varies between firings.` },
    { question: `Which mortar mix should I use for brickwork?`, answer: `A 1:5 cement-to-sand mix suits general above-ground walls. Use 1:4 for exposed walls, parapets and chimneys, where weather resistance matters more, and 1:3 for engineering brick footings and retaining walls, which is the strongest. Internal and lightly stressed work can take 1:6 with plasticiser. Solid-wall houses from before the 1920s need lime mortar, NHL 3.5 with sand at 1:3, because cement mortar traps damp that the wall would otherwise release. Use sharp sand for engineering work and soft sand for ordinary bricklaying.` },
    { question: `Do I need planning permission or Building Regulations for a garden wall?`, answer: `Walls under 1m beside a highway and under 2m elsewhere are permitted development, and anything taller needs planning permission. A wall retaining more than 1.2m of soil needs structural calculations and Building Control approval. Even a free-standing wall needs proper foundations: a concrete strip at least 600mm wide and 200mm deep for walls up to 1.5m, rising to 750mm by 300mm for taller ones, with the base at least 750mm below ground to sit under the frost line. Long walls need a movement joint every 6-8m.` },
    { question: `How long does new brickwork take to dry and cure?`, answer: `Mortar reaches an initial set in 1-2 hours, is firm enough for light contact after 24 hours and reaches full strength after 28 days. Keep rain off for the first 24 hours with hessian or polythene, because it washes mortar out of the joints. Do not lay below 5°C, as the mortar will not cure, and above 30°C mist the wall with water as you build to slow drying and prevent shrinkage cracks. Joints are either struck as you go or scraped back and repointed later for a recessed finish.` },
  ],
  'pace-calculator': [
    { question: `If I know my finish time, can I find the pace I need to hold?`, answer: `Give the calculator any two of pace, speed and finish time for your distance and it returns the third, so a goal time plus the distance gives your required pace. It covers common UK races including parkrun (5 km), 10 km, the half marathon (21.1 km) and the marathon (42.2 km). A half marathon target of 1 hour 50 minutes needs 5:13/km, which is 8:23/mile or 11.5 km/h, and the split table shows what each kilometre should read.` },
    { question: `What is a good 5K time for my age?`, answer: `Average UK 5K times run at 26 to 28 minutes for men aged 20 to 30 and 30 to 32 for women, then 28 to 31 and 33 to 35 for those in their 40s, and 33 to 36 and 38 to 42 from 60 onwards. The parkrun average across the UK is around 30 minutes. Improvement against your own history matters more than the absolute figure, and running three days a week typically takes 30 to 60 seconds off a beginner's 5K pace over 3 months.` },
    { question: `Can I predict my marathon time from a 10K?`, answer: `Up to a point. The Riegel formula multiplies your known time by the ratio of the distances raised to the power 1.06, so a 50-minute 10K predicts 230 minutes, or 3:50, for the marathon and 110 minutes, or 1:50, for a half. It assumes equal training for both, and most amateurs finish 5 to 15% slower over the marathon than the maths suggests. The longer the race, the more endurance work counts relative to raw speed.` },
    { question: `How do I convert minutes per km to minutes per mile?`, answer: `Multiply your minutes per kilometre by 1.609, since 1km is 0.621 miles. A pace of 5:00/km becomes 8:03/mile, and the 4:15/km that a sub-3 marathon needs is 6:50/mile. UK runners tend to quote races in min/km and talk about training in min/mile, which is why the calculator shows both alongside speed in km/h and mph. A 30-minute 5K, for reference, is 6:00/km or 9:40/mile.` },
  ],
  'water-intake-calculator': [
    { question: `Should I drink more water on active or hot days?`, answer: `Weight is the usual starting point, at around 30 to 35 ml of water per kilogram, with more needed for exercise and hot weather. The NHS puts the minimum at six to eight glasses, roughly 1.2 litres of fluid a day. Hot weather adds 500 to 1,000 ml, moderate exercise 500 to 750 ml an hour and vigorous exercise more than 1,000 ml an hour. Pregnancy adds 300 ml a day and breastfeeding 700 ml.` },
    { question: `Can I drink too much water?`, answer: `Yes, though it takes some doing. Hyponatraemia, sometimes called water intoxication, happens when blood sodium falls dangerously low, and the risk comes from drinking more than a litre an hour while sweating heavily, which is why it turns up among marathon runners. Symptoms are nausea, headache, confusion and seizures. Healthy kidneys clear roughly 0.8 to 1 litre an hour, so spread your intake through the day. Sports drinks containing sodium help endurance athletes. On an ordinary day, extra water just means more trips to the loo.` },
    { question: `Does tea, coffee, or beer count toward hydration?`, answer: `Yes, and the NHS counts them. The diuretic effect of caffeine is mild and more than offset by the water the drink carries, so tea, coffee, juice and milk all add to your fluid intake. Coffee at 200 to 300 mg of caffeine, two or three cups, remains a net gain. Even beer is net hydrating per millilitre, adding about 95% of its volume in fluid, though metabolising the alcohol uses some of that back. Plain water, herbal tea and milk are the better everyday choices.` },
    { question: `Is UK tap water as good as bottled water?`, answer: `For health purposes, yes. The Drinking Water Inspectorate regulates more than 50 parameters and UK compliance runs at 99.97%, which puts tap water among the safest anywhere. The NHS regards bottled water as unnecessary, and its environmental impact is around 1,000 times that of tap. What varies is hardness, from over 300 mg/L of calcium carbonate in South-East England to under 60 mg/L in Scotland and the South-West. Hard water leaves limescale but is safe, and a filter jug mainly improves the taste by taking out chlorine.` },
  ],
  'overdraft-cost-calculator': [
    { question: `Why do UK overdrafts now cost close to 40% EAR?`, answer: `The FCA reforms of April 2020 made banks quote one flat rate and banned daily fixed fees, monthly fees and tiered charging. The result is easier to compare and higher than most people expect, with Barclays at 35%, NatWest at 39.49%, and Lloyds and HSBC at 39.9%. That is dearer than most credit cards at 20-25% APR, though cheaper than payday lending. The single figure was meant to make the cost obvious, but many customers still assume an overdraft is the cheap option.` },
    { question: `Will using my overdraft damage my credit score?`, answer: `Staying inside your agreed limit does not usually harm your score by itself, but using more than 50% of the facility month after month signals financial stress to other lenders. Running it to 100% can knock 50 to 100 points off temporarily. Repeated unauthorised use is worse, because it can be recorded as arrears. Treat the overdraft as a short emergency tool, clear it within 2-3 months, and try to keep the balance under 30% of the limit.` },
    { question: `What is cheaper than staying permanently in my overdraft?`, answer: `A 0% money-transfer card moves cash into your current account interest-free for 18-24 months for a 3-4% fee. A personal loan at 8-12% APR undercuts a 40% overdraft comfortably, and a credit union loan at 12.7-26.8% APR is an option if your credit file is patchy. Switching account helps too, whether to First Direct with its £250 free buffer or Starling, which charges 15%, 25% or 35% EAR depending on your credit file. A family loan is cheaper still, provided you document the terms.` },
    { question: `How is the daily cost of an overdraft worked out?`, answer: `The EAR already includes monthly compounding, so the cost is the balance × ((1 + EAR)^(days ÷ 365) − 1) for the days you are actually overdrawn. At 39.9% that is about 0.092% a day, so £1,000 costs £27.98 across 30 days. Because the charge tracks days used rather than the month as a whole, dipping in for 5 days on the same £1,000 costs £4.61, which is why the length of the dip matters more than the size of the limit.` },
  ],
  'debt-free-calculator': [
    { question: `Avalanche vs Snowball, which debt payoff method is best?`, answer: `Avalanche saves the most money because it clears the most expensive borrowing first. Snowball wins on follow-through, and Northwestern Kellogg research from 2016 found real-world success rates were higher with it. The practical test is the spread of your rates. With an 8% personal loan, a 39.9% overdraft and a 25% credit card in the mix, avalanche is worth a lot. Where the APRs sit close together the difference shrinks to a month or so, and you should pick the method you will actually finish.` },
    { question: `Should I prioritise paying off debt or saving an emergency fund?`, answer: `Do both, in order. A starter fund of £500-£1,000 comes first, so an unexpected car or boiler bill does not go straight onto a card. After that, clear anything above 10% APR before saving further. Once the expensive debt is gone, build the fund out to 3-6 months of costs. Keeping cash in a 1% account while an overdraft charges 39% is a guaranteed loss. An employer pension match is the exception and should be taken regardless.` },
    { question: `Can making weekly or bi-weekly payments speed up payoff?`, answer: `Yes, and by more than it looks. Two equal bi-weekly payments give you 26 half-payments a year, which is 13 monthly payments instead of 12. On a £15,000 loan at 8% APR over 5 years that trims 5-6 months off the term and saves £400+ in interest. The effect is larger on credit cards, where interest compounds daily. Check the agreement first, because some lenders require a minimum monthly payment on a fixed date.` },
    { question: `Do apps like Plum or Chip really help clear debt faster?`, answer: `They automate the snowflake, which is any small windfall of £5-£20 put straight against a balance rather than spent. Plum, Chip and Snoop can transfer round-ups to a debt account without you deciding each time. The gain is not the round-up itself but the interest that money no longer generates for the life of the debt. Used alongside the snowball method, consistent snowflakes can pull 20-30% off a payoff timeline.` },
    { question: `When should I consider a Debt Management Plan or IVA?`, answer: `A Debt Management Plan suits someone missing minimum payments who still has surplus income. StepChange or PayPlan negotiate reduced payments and frozen interest with a payoff date usually inside 3-7 years, though creditors can refuse and it sits on your credit file for 6 years. An Individual Voluntary Arrangement is the legal route, with fixed payments for 5-6 years, the remainder written off, and also 6 years on file. Both are free through StepChange, National Debtline or Citizens Advice, so never pay a firm to arrange one.` },
  ],
  'car-finance-calculator': [
    { question: `Which is cheapest overall: PCP, HP or a personal loan?`, answer: `A personal loan usually has the lowest total cost, because you finance the actual price and own the car straight away. Hire Purchase is close behind, with the car acting as collateral until the final payment. PCP has by far the lowest monthly payment, since you are only funding the depreciation, but you never own the vehicle unless you pay the balloon, typically £8,000-£15,000. PCP wins if you change car every 3 years, and a loan wins if you keep it.` },
    { question: `Can I hand the car back partway through a PCP deal?`, answer: `Yes, through Voluntary Termination under the Consumer Credit Act 1974, once you have paid 50% of the total amount payable including interest and the balloon. The car is collected and nothing further is owed, subject to fair wear and tear and the agreed mileage. If you are short of the halfway mark you can pay the difference to reach it. VT is reported like a settled account rather than a default, so it is a genuine escape route when payments become unaffordable.` },
    { question: `Could I be owed money over mis-sold car finance?`, answer: `Possibly, if your PCP or HP agreement ran between 2007 and January 2021 and the dealer set your interest rate under a discretionary commission arrangement. The FCA banned DCAs in 2021, and in October 2024 the Court of Appeal held in Johnson v FirstRand Bank that undisclosed commission was unlawful. Compensation across the industry could exceed £30 billion. Ask your lender directly, whether that is Lloyds Black Horse, Motonovo, Close Brothers or another, since eligible agreements attract a refund plus 8% interest.` },
    { question: `Is GAP insurance worth buying on a PCP deal?`, answer: `It depends on how far underwater the finance is likely to go. A new car loses 20-30% of its value in the first year, so early in a PCP the balance often exceeds the market value an insurer would pay out after a write-off or theft. The FCA paused GAP sales in 2024 because most policies returned only 6% of premiums, and prices fell after the market reopened, to around £150-£300 for a 3-year policy. On a used HP deal it rarely pays.` },
    { question: `Does a soft search hurt my score when comparing car finance?`, answer: `No. A soft search is invisible to other lenders and leaves your score untouched, which is why eligibility checkers from Experian, ClearScore or MoneySavingExpert are the right first step. A full application is a hard search, and that stays on your file for 12 months and costs 5-10 points. Several hard searches inside 14 days are often treated as one by scoring models, but applications spread over months do more damage.` },
  ],
  'heat-pump-calculator': [
    { question: `What does the Coefficient of Performance mean for a heat pump?`, answer: `It is the ratio of heat delivered to electricity consumed. Rather than burning fuel, a heat pump moves warmth from the outside air or the ground, returning 2.5 to 4 units of heat for every unit of electricity used, so a COP of 3 gives 3 kWh of heat for each 1 kWh of electricity. Air source units manage that down to -15°C, while ground source machines reach a COP of 4 to 5 because ground temperatures stay steadier through winter.` },
    { question: `Is a heat pump actually cheaper to run than a gas boiler?`, answer: `On a standard tariff the two run close together. At 26.32p per kWh for electricity and a SCOP of 3, heating costs 8.8p per kWh of heat, against 8.9p from a 90% efficient gas boiler on gas at 7.97p (October to December 2026 cap). A time-of-use tariff such as Octopus Cosy changes the picture, bringing a heat pump out 20 to 30% cheaper, and solar panels push it further still. Insulation counts for more than either, because a leaky house is costly to heat whatever the source.` },
    { question: `How much is the Boiler Upgrade Scheme grant worth?`, answer: `In England and Wales the Boiler Upgrade Scheme pays £7,500 towards an air source or ground source heat pump and £2,500 towards an air-to-air heat pump. Until March 2027 homes off the gas grid that are heated by oil or LPG get an extra £1,500, and the Warm Homes Plan funds the scheme to 2030. Set against an air source installation of £8,000 to £15,000, the £7,500 grant leaves a net cost of roughly £500 to £7,500. A replacement gas boiler runs £3k to £4k, so the heat pump ends up anywhere from about £3,500 cheaper to £4,500 dearer, and how quickly any extra cost pays back depends on your tariff and how well the house is insulated.` },
    { question: `Do I need bigger radiators to run a heat pump?`, answer: `Often, yes. Heat pumps work at a flow temperature of 35 to 45°C rather than the 65 to 75°C a boiler uses, so a poorly insulated home usually needs radiators 1.5 to 2 times their current size, which adds £1k to £3k to the job. Underfloor heating suits them well for the same reason. You also need a hot water cylinder rather than a combi, and outdoor space of about 0.8m by 1.0m by 0.6m, ideally 1m from the boundary.` },
  ],
  'savings-goal-calculator': [
    { question: `How much of my income should I be putting aside each month?`, answer: `A common starting point is the 50/30/20 rule, splitting income into 50% needs, 30% wants and 20% savings or debt repayment. On the UK average household disposable income of £33,500 that 20% works out at £6,700 a year, or £558 a month. For younger people in expensive cities, 10-15% is usually the realistic figure. Order matters as much as the amount: build the emergency fund first, take any employer pension match on offer, then put ISAs and specific goals on top.` },
    { question: `Are regular saver accounts worth their higher headline rate?`, answer: `They pay the best advertised rates in the UK at 6-8%, but the conditions limit what that is worth in cash. Deposits are capped at £200-£300 a month and the accounts are normally open only to existing customers of the bank. That makes them a good home for part of a monthly savings habit rather than somewhere to park a lump sum, which does better in an easy access account at 4.0-5.0% or a fixed-rate bond at 4.5-5.5%.` },
    { question: `Do I need a cash ISA if my savings are fairly small?`, answer: `Probably not, while the Personal Savings Allowance still covers the interest. Basic-rate taxpayers can earn £1,000 tax-free, higher-rate taxpayers £500, and additional-rate taxpayers nothing at all. At 4.5%, a balance of £20k produces £900 of interest, which sits comfortably inside a basic-rate allowance but consumes most of a higher-rate one. The ISA wrapper earns its keep once your interest approaches those limits, or immediately if you pay tax at the additional rate.` },
    { question: `Will my savings target still be worth the same in five years?`, answer: `Not unless you adjust it. A £30,000 target 5 years away has to become £34,400 to hold the same purchasing power at 2.8% inflation, so a plan built on the original number quietly falls short. Over longer horizons the effect is much larger, with 3% inflation halving the value of money in about 24 years. Setting the goal at present-day prices and then applying the inflation adjustment is more honest than picking a round figure and hoping.` },
  ],
  'number-to-words-calculator': [
    { question: `Does British English use and when writing out numbers?`, answer: `Yes, after hundreds. British English writes one hundred and twenty-five where American English drops the and and writes one hundred twenty-five. The calculator follows the British form throughout. UK usage matches the US on scale, though, with billion meaning one thousand million, or 10^9, since the old long scale where a billion meant a million million was abandoned in 1974. A trillion is 10^12 and a quadrillion is 10^15.` },
    { question: `How should I write the amount in words on a cheque?`, answer: `Write the pounds in full, then the pence either as a fraction or followed by the word only, so £127.50 becomes one hundred and twenty-seven pounds and fifty pence only. Draw a line through the unused space to prevent anything being added afterwards. Where the numerals and the words disagree the bank rejects the cheque, because the words take legal precedence. Cheques remain valid for 6 months from the date of issue under UK banking practice.` },
    { question: `When do numbers take a hyphen in written English?`, answer: `Compound numbers from 21 to 99 are hyphenated, so twenty-one, thirty-five and ninety-nine. Larger groups are separated by spaces rather than hyphens, giving three hundred and forty-five thousand, six hundred and twenty-one, and there is no hyphen between hundred or thousand and what follows, so two hundred thousand stays open. Whether a comma belongs after the thousands is disputed, with Oxford style using it and AP omitting it. Ordinals behave the same way, with twenty-first hyphenated and one hundredth not.` },
    { question: `Should I write a number in words or in digits?`, answer: `Oxford, the Guardian and The Times all write whole numbers from one to nine in words and use digits from 10 upwards in running text. Digits are used regardless for ages (5-year-old), measurements (3 kg), percentages (8%), times (3pm), money (£25) and anything in a table. Words are used at the start of a sentence, as in Twenty-three people attended, for approximations such as about a thousand, and for fractions in prose such as two-thirds of voters. Mixing both inside one sentence is the mistake to avoid.` },
    { question: `Why do legal documents write an amount twice?`, answer: `Because the duplication makes fraud much harder. Writing two thousand five hundred pounds (£2,500.00) means anyone altering the document has to change the numerals and the words consistently, and a mismatch gives the game away. On a cheque the words prevail where the two disagree. The habit still matters in practice, since cheques, though scheduled for phaseout with no firm UK date, remain in wide use by HMRC, councils and schools.` },
  ],
  'random-number-generator': [
    { question: `Is Math.random() safe enough for a raffle or prize draw?`, answer: `For a raffle, a classroom draw or statistical sampling, yes. Math.random() uses a pseudo-random algorithm such as xorshift128+, which produces a fair spread of results for those purposes. Its weakness is that the sequence is predictable if the seed is known, which only matters when someone has an incentive to attack it. This generator uses a CSPRNG instead, so the same tool is safe for both a charity raffle and a security token.` },
    { question: `Does picking lottery numbers at random improve my chances of winning?`, answer: `No. The odds are fixed by the game: 1 in 45,057,474 for the Lotto jackpot (6 balls from 59), 1 in 139,838,160 for EuroMillions and 1 in 15,339,390 for the Set for Life top prize. What a random pick does change is how many people you are likely to share with. Human choices cluster on birthdays (1 to 31) and favourites like 7, 11 and 13, so a random line is less likely to be duplicated by another ticket.` },
    { question: `Why must password generators use crypto.getRandomValues() instead of Math.random?`, answer: `Because Math.random outputs can be reverse-engineered, which means a password built from them could be reconstructed. crypto.getRandomValues() draws on operating-system entropy and is what the UK ICO and NCSC expect for systems handling personal data. It has been supported by all modern browsers since 2014. The same rule applies to 2FA backup codes, session and CSRF tokens, encryption nonces, UUID v4 values and password salts.` },
    { question: `How does the generator avoid bias when picking from a range?`, answer: `The simple method of multiplying a random fraction by the range size and rounding down is slightly biased for very large ranges, because the generator's values do not divide evenly into the range. For anything under 2^32 the effect is negligible, but a careful implementation uses rejection sampling: it generates full 32-bit integers and throws away any above the largest multiple of the range, so each remaining value has an equal chance.` },
    { question: `Can I generate several numbers without any repeats?`, answer: `Yes. Set the range, say 1 to 59 for a UK Lotto line, ask for 6 numbers and switch off repeats. The tool then draws each number from the values not yet used, so you get a set such as 7, 14, 22, 35, 41, 53. With repeats allowed, each draw is independent and any value can appear more than once, which is what you want for dice rolls or coin flips.` },
  ],
  'shoe-size-converter': [
    { question: `What is my UK shoe size in EU and US sizes?`, answer: `A UK 7 is roughly an EU 41, a US men's 8 or a US women's 9.5, which is JP 26cm. A UK 8 becomes EU 42, US men's 9, US women's 10.5 and JP 27cm. Each whole UK or US size adds 8.5mm, while EU sizes step by about 6.67mm because the Paris point is 2/3 cm. Brands vary around those figures, so check the maker's own chart. Italian labels such as Gucci and Prada often run small, while American athletic brands like Nike and Adidas tend to run true.` },
    { question: `How do I measure my foot length at home?`, answer: `Stand barefoot on a sheet of paper in the evening, when the foot is at its largest, and mark the back of the heel and the longest toe. Measure the gap in millimetres. UK size comes from (length mm − 23.85) ÷ 8.46, and EU size from the length in centimetres × 1.5. Measure across the widest part of the ball as well, since width is graded separately from E for medium through F and G to H.` },
    { question: `Should I size up when buying trainers or running shoes?`, answer: `Usually yes. Trainers fit smaller than formal shoes, so half a size up is the common advice, and running shoes want about 1cm of toe clearance for downhill work, which again means half a size above your walking size. Brand habits differ. Nike runs slim, the Adidas Stan Smith is true to size, New Balance runs wide, and Converse comes up a full size large. Football boots are meant to be tight for control, and cycling shoes tighter again.` },
    { question: `How often should a child's shoes be measured?`, answer: `Every 8-12 weeks once a child is at school, and most UK shoe shops will do it free of charge with a proper gauge. Feet grow by about 2 shoe sizes a year up to three years old, then roughly 1 size a year until seven, then more slowly. Leave 1cm at the front, about a thumb's width, while the child is standing. Avoid handing down well-worn shoes, because the insole has already taken the shape of the first wearer's foot.` },
  ],
  'ratio-calculator': [
    { question: `How do I simplify a ratio to its lowest terms?`, answer: `Divide every term by the greatest common divisor. For 12:18 that divisor is 6, so the ratio simplifies to 2:3, and for 60:36:24 it is 12, giving 5:3:2. The Euclidean algorithm finds the divisor quickly, because GCD(a,b) equals GCD(b, a mod b). Applied to the second example, 60 mod 36 is 24, 36 mod 24 is 12, and 24 mod 12 is 0. Clear decimals before you start, so 0.5:1.5 doubles to 1:3, and convert mixed units, so 50cm:1m becomes 50:100 and then 1:2.` },
    { question: `What does 80% LTV mean on a UK mortgage?`, answer: `Loan-to-value is the size of the loan divided by the value of the property, written as a percentage, so a £160k mortgage on a £200k house is 80% LTV. Lenders price their deals in LTV bands, which is why the ratio matters more to them than the cash figure. Debt-to-income is the other ratio underwriters look at, dividing monthly debt payments by gross monthly income, and most mortgage lenders cap it at about 40-45%. Business lending uses gearing instead, which is debt divided by equity.` },
    { question: `How do I scale a recipe using a ratio?`, answer: `Simplify the ratio first, then multiply. Take 45:60, whose GCD is 15, and it becomes 3:4. If the recipe uses 200 g of flour and the flour to sugar ratio is 3:4, the sugar works out at 200 × (4/3), which is 266.67 g. The method scales a whole recipe up or down safely, as long as every ingredient is multiplied by the same factor rather than adjusted by eye, since changing one item alone breaks the proportion.` },
    { question: `What is the difference between 16:9 and 4:3?`, answer: `Both describe the shape of a picture rather than its size. 16:9 is the widescreen standard used by televisions, monitors and YouTube, while 4:3 is the older and squarer shape. A 16:9 1080p screen measures 1920×1080 pixels, and 4K UHD at 3840×2160 covers 4× the area of that. Cinema goes wider again at 21:9, films are framed at 1.85:1 or 2.39:1, and social video runs vertical at 9:16 or square at 1:1.` },
  ],
  'standard-deviation-calculator': [
    { question: `How do I interpret a high standard deviation?`, answer: `A high figure means the values are widely scattered around the mean, and a low one means they cluster close to it. The number carries the same units as your data, so a standard deviation of 5% on exam marks averaging 60% puts most pupils between 55-65%, while 20% on the same average implies scores stretching from 20% to 95%. Comparing two data sets by mean alone can therefore hide completely different behaviour.` },
    { question: `Should I use population or sample standard deviation?`, answer: `Use the population version, dividing by n, only when your numbers are the entire group, such as the heights of every Premier League player this season. Use the sample version, dividing by n−1, when you are estimating a larger population from a subset, such as 50 randomly selected UK adults. That n−1 adjustment, Bessel's correction, exists because a sample mean sits closer to its own values than the true mean does, so the uncorrected figure understates the spread.` },
    { question: `What does the 68/95/99.7 rule actually tell me?`, answer: `For normally distributed data, 68% of values fall within ±1 SD of the mean, 95% within ±2 SD and 99.7% within ±3 SD. IQ scores illustrate it neatly, with a mean of 100 and a standard deviation of 15, so 68% of people score 85-115 and 95% score 70-130. Mensa's top 2% cut-off of 132+ sits about 2 SD above the mean, and A-level grades of A at 90%+ mark out roughly the top 5-10%.` },
    { question: `What is the difference between variance and standard deviation?`, answer: `Variance is the mean of the squared deviations, and standard deviation is its square root. They hold the same information in different units, so data in pounds gives a variance in pounds squared and a standard deviation in pounds. Reports use the standard deviation because the units match the data, while mathematical work prefers variance, since the variances of independent variables add together and standard deviations do not.` },
  ],
  'ucas-points-calculator': [
    { question: `How many UCAS points is an A-level grade B worth?`, answer: `At A-level a grade B is worth 40 points, with an A on 48, a C on 32 and an A* on 56, down to 16 for an E. AS-levels carry 40% of the A-level value, so an A there is 20 points and a C is 12. BTEC results, Scottish Highers and the International Baccalaureate all convert onto the same scale, which is what lets a mixed set of qualifications be added up as one total.` },
    { question: `Do I still need specific grades if a course lists UCAS points?`, answer: `Often, yes. Many universities, Russell Group institutions among them, make offers in named grades rather than points, so a course might ask for AAB including Maths A. Even where the requirement reads as a total such as 112 UCAS points, the course can still insist on particular subjects, whether that is essay-based subjects for English Literature or Maths and Physics for an AAB engineering offer. Read the course page rather than trusting the total on its own.` },
    { question: `Does an EPQ add to my UCAS points total?`, answer: `It does. The Extended Project Qualification is worth 28 points at A* and 24 at A, and those points sit on top of your A-level total. The alternative offer matters more for most applicants, since a number of universities will lower their main grade requirement by one grade for an A in the EPQ. General Studies, by contrast, is not counted by many universities, and Critical Thinking counts towards very few courses.` },
    { question: `How are UCAS points used during Clearing?`, answer: `Vacancies in Clearing are often advertised in tariff terms, along the lines of AAB or 136 points and above, so having a total to hand speeds up the phone calls. Around 30,000 places go this way each year and the bulk of them are taken within 24 to 72 hours of results day, which means having a shortlist of universities and a decision ready matters as much as the points themselves.` },
  ],
  'speed-fine-calculator': [
    { question: `What speeding fine band applies if I was 15 mph over the limit?`, answer: `It depends on the limit, because the bands are set by recorded speed for each one. At 15 mph over you are in Band B in a 20 or 30 zone (35 or 45 mph) but still in Band A in a 40, 50, 60 or 70 zone. Band A starts at 50% of relevant weekly income (range 25 to 75%) with 3 points, Band B at 100% (75 to 125%) with 4 to 6 points or a 7 to 28 day ban, and Band C at 150% (125 to 175%) with 6 points or a 7 to 56 day ban.` },
    { question: `Will I be offered a speed awareness course instead of points?`, answer: `Only within a narrow window and only if you have not taken one in the last 3 years. Under the 2025 NPCC guidance the windows are 35 to 42 mph in a 30 zone, 46 to 53 in a 40, 57 to 64 in a 50 and 79 to 86 in a 70, with 24 to 31 in a 20 and 68 to 75 in a 60. The course costs £80 to £100 depending on the force, takes 4 hours and is often delivered online, and it leaves you with no fine and no points on your licence.` },
    { question: `How much will three penalty points push up my insurance?`, answer: `An SP30 endorsement typically adds 10 to 25% to the premium, and each further endorsement compounds it. The points sit on your licence for 4 years but have to be declared to insurers for 5. Tell your insurer at the time of the offence, because non-disclosure can invalidate the policy.` },
    { question: `When does a speeding offence mean going to court?`, answer: `Police guidance (NPCC, 2025) switches from a fixed penalty to a court summons from 35 mph in a 20 zone, 50 in a 30, 66 in a 40, 76 in a 50, 86 in a 60 and 96 in a 70, and aggravating circumstances such as a school zone can pull a lower speed in too. Turning down a fixed penalty also takes you to court. The magistrates fine by band, up to 125 to 175% of weekly take-home pay in Band C with 6 points or a ban of 7 to 56 days, and add a victim surcharge of 40% of the fine plus prosecution costs. A solicitor for a contested hearing costs £300 to £800, which is often worth it when a licence is at stake.` },
    { question: `What happens if I speed within two years of passing my test?`, answer: `The New Drivers Act 1995 revokes your licence at 6 points rather than the usual 12, so a single serious offence or two minor ones can end it. You then reapply for a provisional and pass both the theory and practical tests again. The rule stops applying two years after your test date, at which point the ordinary totting-up threshold of 12 points in 3 years takes over.` },
  ],
  'binary-converter': [
    { question: `Can I convert a hexadecimal number back to decimal here?`, answer: `Yes, conversions run in any direction between binary, decimal, octal and hexadecimal. Hex uses the digits 0-9 followed by A to F, and each hex digit represents exactly four bits, so 0xD6 expands to 11010110 and equals 214 in decimal. Binary itself uses only 0 and 1, with each position standing for a power of two, running 1, 2, 4, 8, 16 and upwards from the right.` },
    { question: `How do I convert a decimal number into binary by hand?`, answer: `Divide repeatedly by 2 and read the remainders from the bottom up. For 42 that is 42 ÷ 2 = 21 remainder 0, then 21 ÷ 2 = 10 remainder 1, 10 ÷ 2 = 5 remainder 0, 5 ÷ 2 = 2 remainder 1, 2 ÷ 2 = 1 remainder 0 and 1 ÷ 2 = 0 remainder 1, giving 101010. Subtracting powers of 2 is faster once you know them, since 42 = 32+8+2.` },
    { question: `How are negative numbers stored in binary?`, answer: `Through two's complement, which flips every bit of the positive value and adds 1. To hold −5 in 8 bits, start with 5 as 00000101, flip it to 11111010, then add 1 to get 11111011. The reason for the extra step is practical, because with two's complement the same circuit performs addition and subtraction, so a processor needs no separate hardware for taking one number away from another.` },
    { question: `Why do programmers use hexadecimal instead of plain binary?`, answer: `Because it is far shorter to read while still mapping cleanly onto the underlying bits. Each hex digit covers exactly four binary digits, so 11010110 collapses to D6 rather than eight separate characters. That is why hex turns up in HTML colours, where #FFFFFF is white and equals 16,777,215, as well as in MAC addresses, memory addresses such as 0x7FFE and file dumps. Octal, base-8, plays a similar role, and 255 in octal is 377.` },
  ],
  'mulch-calculator': [
    { question: `How deep should I spread bark mulch on a border?`, answer: `The RHS suggests 50 to 75 mm of organic mulch such as bark or wood chip, enough to suppress weeds and hold moisture without smothering the soil. Gravel mulch needs less, usually 25 to 40 mm, and the amount you order comes from area multiplied by depth. Where weeds have taken hold, 100mm gives stronger suppression. A 20 m² border at 75mm works out at 1.5 m³ of material.` },
    { question: `How many bulk bags of mulch cover a 20 m² border?`, answer: `At 75mm deep a 20 m² border needs 1.5 m³. A UK bulk bag holds 0.7 to 0.9 m³ and covers roughly 12 m² at that depth, so two bags do the job. Small retail bags of 50 to 70 litres hold only 0.05 to 0.07 m³ each and cover 0.7 to 1 m², which makes them expensive for anything beyond a single small bed. Above about 3 m³ a loose truck load is cheaper per cubic metre, provided a lorry can reach you.` },
    { question: `When should I mulch my borders in the UK?`, answer: `Mid-spring, roughly March to May, is the window, once the soil is moist but starting to warm. Mulching then smothers weed seeds before they germinate and holds in the winter's moisture. Avoid hot dry summer days, which trap the dryness underneath, and frozen ground, which the mulch simply insulates. Applying it in midsummer over established weeds achieves little. Organic mulches lose 20 to 50% of their volume a year to decomposition, so plan on topping up each spring.` },
    { question: `Which mulch is best for acid-loving plants like rhododendrons?`, answer: `Composted bracken or pine needles give an ericaceous mulch that suits rhododendrons, azaleas and blueberries. For general borders, composted bark at £55 to £100 a bulk bag improves the soil as it rots. Stone and slate chippings at £60 to £140 last much longer but add no nutrition at all. Straw is the traditional choice under strawberries, and clover or vetch sown as a living mulch between rows can be dug in at the end of the season.` },
  ],
  'ideal-weight-calculator': [
    { question: `Which formulas does this use to work out a healthy weight?`, answer: `Results draw on the BMI healthy range of 18.5 to 24.9 alongside the Devine (1974) and Robinson (1983) formulas, both of which turn your height into a single target weight. Those formulas were first written for drug-dosing calculations, which is why they take no account of how much muscle you carry.` },
    { question: `Why are there so many different ideal weight formulas?`, answer: `They were written at different times for medication dosing rather than for health targets, so each author picked slightly different coefficients. Devine (1974) gives men 50kg plus 2.3kg per inch over 5ft and women 45.5kg plus 2.3kg per inch. Robinson (1983) adjusts those figures, Miller (1983) starts at 56.2kg for men and 53.1kg for women with smaller per-inch steps, and Hamwi (1964) is the least accurate of the set. A BMI-based version simply takes the middle of the healthy 18.5 to 24.9 band.` },
    { question: `Is ideal weight even a useful concept?`, answer: `Less so than most people assume. A healthy weight is a range rather than a single number, and two people of the same height and age can both be well at weights 5 to 10kg apart if one is muscular and the other lean. What the extra kilos are made of matters more than the total. Waist circumference under 94cm for men and 80cm for women, plus a waist-to-height ratio under 0.5, track health better than any formula weight.` },
    { question: `What if I am above ideal weight but feel healthy?`, answer: `If your blood pressure, cholesterol, blood sugar and waist circumference are all normal, you may be metabolically healthy at a higher BMI, sometimes called the overweight paradox. Extra weight still raises the long-term likelihood of joint pain, sleep apnoea and certain cancers, so it is not a free pass. Everyday markers tell you plenty. Can you climb stairs without getting out of breath, walk briskly for 30 minutes and hold your energy through the day?` },
  ],
  'fertiliser-calculator': [
    { question: `How much lawn feed do I need per square metre?`, answer: `Most UK lawn fertilisers call for 35 to 70 grams per square metre, so the total depends on your lawn area and the rate printed on the pack. Spring and summer feeds lean on nitrogen for growth, while autumn feeds carry more potassium for stronger roots.` },
    { question: `What do the three NPK numbers on a fertiliser bag mean?`, answer: `They are the percentages of nitrogen, phosphorus and potassium in the mix. A high-nitrogen 24-4-12 is a lawn feed that pushes leaf growth and colour, a balanced 10-10-10 or Growmore at 7-7-7 does general garden work, a high-potassium 4-4-22 suits tomatoes, peppers and fruit, and a 10-30-10 supports root development. The rate on the label still governs how much you apply.` },
    { question: `When should I feed my lawn through the year?`, answer: `March and April are the window for a nitrogen-rich spring feed, and September or October for the autumn feed, which is higher in potassium and lower in nitrogen to build winter resilience. Vegetables get side-dressed in May and June, and fruit and tomatoes take high-potassium feeds in July and August. Nothing goes on between November and February, when it would simply run off.` },
    { question: `Can too much fertiliser damage a lawn?`, answer: `Yes. Over-application scorches the grass and produces soft growth that disease finds easy, and brown patches are usually nitrogen burn from a spill or a heavy hand. Lush growth with no flowers or fruit means the same imbalance elsewhere in the garden. Weighing the product rather than guessing avoids it, and a soil test every 2 to 3 years at £20 to £40 through the RHS shows whether the ground needs anything at all.` },
    { question: `Which organic fertiliser suits a vegetable bed?`, answer: `Fish, blood and bone is the general choice, a balanced 5-5-5 that releases slowly, at £6 to £15 for 3kg. Chicken manure pellets at 5-3-2 give more nitrogen for £8 to £20 per 8kg, with a smell that fades in 24 to 48 hours. Bone meal at 4-21-0 goes in for autumn planting, seaweed extract adds trace minerals at £10 to £25 a litre, and garden compost at roughly 1-1-1 works as a mulch.` },
  ],
  'crop-yield-calculator': [
    { question: `What yield can I expect from a hectare of winter wheat?`, answer: `Winter wheat typically returns 8.0 to 8.5 tonnes per hectare, with winter barley at 6.5 to 7.0 and potatoes far higher at 40 to 45. The figures come from Defra's annual harvest reports and shift with soil, region and weather.` },
    { question: `How much food can an allotment realistically produce?`, answer: `A standard allotment of 250 m², or 10 rods, can yield £2,000 to £4,000 of food a year when worked intensively, though the national average is nearer £600 to £1,500 because most plots are part-time. A 50 m² patch in a back garden produces 200 to 400 kg, worth £400 to £1,000. Growing all your own vegetables takes about 200m².` },
    { question: `How many courgette plants does one family need?`, answer: `One or two, and rarely more. A single courgette plant produces 8-15kg over a season, which is far more than most households can eat fresh. For comparison, a cordon tomato gives 4-6kg, a greenhouse cucumber 5-10kg, a pepper 1-3kg and runner beans 2-3kg per plant, so planning by plant rather than by bed avoids a glut of one crop and a shortage of another.` },
    { question: `Why rotate vegetables between four beds?`, answer: `The standard rotation moves legumes, brassicas, roots, then potatoes and onions round clockwise each year. It stops soil-borne pests such as clubroot and eelworm building up, spreads nutrients (nitrogen fixed by the legumes feeds the brassicas that follow), and reduces fungal disease. Potatoes gain most from it, and keeping them off the same ground for 4 or more years is the main defence against blight.` },
    { question: `Does a polytunnel actually increase yields?`, answer: `Yes, typically by 30 to 50%, and it extends the growing season by 6 to 8 weeks at both ends. That longer season is what makes succession sowing pay, with salad leaves, radishes and spinach going in every 2 to 3 weeks for a continuous harvest. Raised beds add better drainage and deeper soil, and vertical growing frees ground beneath climbing beans and indeterminate tomatoes.` },
  ],
  'break-even-calculator': [
    { question: `What sales volume do I need to break even?`, answer: `Divide your fixed costs by the contribution margin per unit, that margin being the selling price minus the variable cost of one item. With £20,000 of fixed costs, a £50 price and £20 of variable cost, the margin is £30 and break-even lands at 667 units, or £33,350 of revenue. Sell fewer and you make a loss, sell more and every extra unit contributes £30 of profit.` },
    { question: `What is a healthy margin of safety for my business?`, answer: `Margin of safety is the gap between expected sales and break-even sales, shown either in pounds or as a percentage of expected sales. Most stable businesses sit at 25 to 50%. Under 15% the business is exposed, because a small drop in demand tips it into loss. Over 50% usually signals spare capacity or prices that could be sharper. It answers the practical planning question of how large a sales fall you could absorb.` },
    { question: `What is the difference between cash and accounting break-even?`, answer: `Accounting break-even uses accrual revenue and costs, including non-cash items such as depreciation. Cash break-even strips those out and looks only at money actually leaving the bank. The two diverge when customers pay slowly, which is how a business can look profitable on paper while running short of cash. Short term, the cash figure keeps the doors open, while the accounting figure describes the long-term economics more honestly.` },
    { question: `How do I lower my break-even point?`, answer: `Raise prices, cut variable costs or cut fixed costs. Price is the strongest lever if the market will take it. Variable savings from better suppliers, cheaper materials or automation scale with the volume you sell, whereas fixed savings help from the moment they land. Start with the largest fixed line in the accounts, which is usually payroll or rent, since that is where a small percentage change moves the most money.` },
  ],
  'margin-calculator': [
    { question: `What is the difference between profit margin and markup?`, answer: `Margin measures profit against the selling price, while markup measures the same profit against cost, so one sale produces two different percentages. Sell at £100 on a £60 cost and you have a 40% margin but a 66.7% markup. Margin can never reach 100% while any cost remains, whereas markup passes it easily, which is why a 60% margin needs a 150% markup behind it.` },
    { question: `How do I price a product to hit a target margin?`, answer: `Divide the cost by one minus the target margin rather than multiplying by the margin. A £30 item priced for a 40% margin sells at £50. Aim for a 30% margin and you need a 42.9% markup on cost, not 30%. Getting this backwards is the most common pricing error in small business, because a markup applied as though it were a margin leaves money on the table with every sale.` },
    { question: `What gross margin is normal in my industry?`, answer: `Gross margins cluster by sector. Supermarkets make 25 to 35% on food and 40 to 60% on non-food, restaurants 60 to 70% on food and 75 to 80% on drinks, clothing retail 50 to 60%, manufacturing 25 to 40%, construction 15 to 25% and consultancy 50 to 75%. Software sits at 70 to 90%. Net margins run much lower, typically 5 to 15% for a mature business and under 5% in retail and food service.` },
    { question: `Why does margin matter more than revenue growth?`, answer: `£1m of revenue at a 5% margin produces £50k of profit, while £500k at a 20% margin produces £100k. Doubling sales is hard, whereas lifting margin a few points through pricing, cost control or product mix is often within reach. Buyers and investors price the difference too, paying perhaps 3 to 5 times revenue for software at 70% margin against 0.5 to 1 times for services at 15%.` },
  ],
  'depreciation-calculator': [
    { question: `How is straight-line depreciation calculated each year?`, answer: `Take the original cost, subtract the estimated residual value and divide by the useful life in years. The result is the same charge every year until net book value reaches the residual. A £12,000 van with a £2,000 residual over 5 years depreciates by £2,000 a year, leaving £10,000 on the books after year one. It is the usual method for UK reporting under FRS 102 and the easiest to explain to a lender.` },
    { question: `When should I use reducing balance instead of straight-line?`, answer: `Reducing balance suits assets that lose most of their value early, such as vehicles, computers and equipment, because the charge follows the book value down. Straight-line suits buildings, fittings and anything with a steady life. On a £12,000 van with a £2,000 residual over 5 years, the reducing-balance rate is about 30.12%, giving £3,614 in year one against £2,000 on a straight line. Either is allowed provided it reflects how the asset is actually used.` },
    { question: `How do capital allowances differ from accounting depreciation?`, answer: `Depreciation is an accounting figure and gives no tax relief at all. HMRC ignores your policy and grants capital allowances instead, so the Annual Investment Allowance covers 100% of qualifying plant up to £1,000,000 a year, while the writing down allowance is 14% in the main pool and 6% in the special rate pool. Cars are excluded from the AIA. Depreciation is added back when taxable profit is worked out.` },
    { question: `Do I have to depreciate every asset I buy?`, answer: `No. Items below a de minimis threshold, usually somewhere around £100 to £500 depending on your policy, are expensed straight away. Land is not depreciated. Goodwill is amortised under FRS 102 but tested only for impairment under IFRS. Software is written off over its useful life, commonly 3 to 5 years. Repairs and maintenance go to the profit and loss account, while capital improvements are added to the asset and depreciated.` },
  ],
  'visa-fee-calculator': [
    { question: `Is the Immigration Health Surcharge charged on top of the visa fee?`, answer: `For most routes it is, at £1,035 per year for adults and £776 for children under 18, students and their dependants, and Youth Mobility Scheme applicants, added to the Home Office application fee and paid upfront for the whole visa length. Health and Care Worker visa holders and their dependants are exempt. Many applications also bring priority processing charges and an English language test.` },
    { question: `How much does a Skilled Worker visa cost in total?`, answer: `From outside the UK the application fee is £819 for up to 3 years, or £1,618 for longer (£943 and £1,865 from inside the UK), and the surcharge adds £1,035 a year, so a 3-year application carries £3,105 of surcharge by itself. That makes £3,924 in Home Office charges. Priority processing is another £500 and an English test about £170, which brings a straightforward 3-year application to roughly £4,094, or £4,594 if you pay for priority.` },
    { question: `What extra costs come on top of the visa fee?`, answer: `An English test at £150 to £200, a tuberculosis test at £80 to £200 for applicants from high-TB countries, and document translation at £30 to £100 each. Priority service costs £500 per applicant for a decision usually within 5 working days (30 for family visas from outside the UK and citizenship), and super priority £1,000 per applicant for one usually by the end of the next working day. A solicitor charges £1,000 to £3,000 or more on a complex case. Added together, the real cost runs from a few thousand pounds for one person to £20,000 or more for a family.` },
    { question: `Who pays the sponsorship fees, me or my employer?`, answer: `The Certificate of Sponsorship at £525 and the Immigration Skills Charge, £480 a year for small or charitable sponsors and £1,320 for medium and large ones, belong to the employer and cannot be passed on to you. The health surcharge can be. Sponsoring someone for 5 years costs an employer £2,925 to £7,125, and many UK employers cover the whole package as part of relocation, so it is worth asking before you sign.` },
  ],
  'student-budget-calculator': [
    { question: `Will my maintenance loan cover the cost of university?`, answer: `That depends on whether the loan, plus any work or family support, stretches across the year. Accommodation is the biggest drain at £4,000 to £9,000, followed by food at £2,000 to £3,000, then transport, course materials and everyday spending. The maximum loan is £14,135 in London, £10,830 living away from home elsewhere and £9,118 at home, so where you study matters as much as how you spend, given London runs 40 to 60% above the North and Midlands.` },
    { question: `Which student loan plan am I on?`, answer: `Plan 1 applies if you started before September 2012 in England or Wales, or if you are from Northern Ireland, and repayments start at £26,900. Plan 2 covers English courses begun between September 2012 and July 2023, and Welsh courses begun from September 2012 onwards, with a threshold of £29,385. Plan 4 is the Scottish plan, starting at £33,795, and Plan 5 applies to English students starting from 1 August 2023, with a threshold of £25,000. Each of them takes 9% of income above the threshold.` },
    { question: `Can summer work cover the gap in my student budget?`, answer: `It often has to, because the maintenance loan is paid for term time only and nothing arrives for the vacations. Full-time work from May to September brings in £4,000 to £8,000, and an internship in finance or technology pays £18,000 to £35,000 pro rata. Since the Personal Allowance is £12,570, most students pay no income tax on those earnings, so a summer wage stretches further than the same rate would across a full working year.` },
    { question: `What grants can I get alongside the maintenance loan?`, answer: `Grants do not have to be repaid, which makes them worth chasing. Nursing, midwifery and allied health students get a £5,000 NHS Learning Support Fund grant, and medical and dental students an NHS Bursary in later years. Scotland offers a means-tested Young Students' Bursary of up to £2,000 in 2026-27, alongside a loan of up to £9,400, Wales has the Welsh Government Learning Grant, and Northern Ireland a Maintenance Grant of up to £3,475. Disabled Students Allowance covers equipment and support up to £27,783 a year, and care leavers have a package worth up to £14,000.` },
  ],
  'contractor-day-rate-calculator': [
    { question: `How do I convert an annual salary into a contractor day rate?`, answer: `Divide the annual salary across the days you can bill, normally 220 to 230 once holidays, bank holidays and gaps between contracts are removed, then add a premium for what you give up. A quick version divides the salary by 1,000, turning £60,000 into £300 a day. On a worked example, £65,000 spread over 227 days is £286, and a 30% contractor premium lifts that to £372.` },
    { question: `What expenses can contractors claim through their limited company?`, answer: `Anything incurred wholly and exclusively for the business: laptops, monitors and phones, software subscriptions, professional indemnity and public liability cover, accountancy fees, training, marketing, professional subscriptions and business travel, though not the ordinary commute. There is also a flat rate of £6 a week for working from home. Inside IR35 most of these claims fall away. Keep a paper trail for all of it, because HMRC will eventually ask for one.` },
    { question: `Should I work through an umbrella company or my own Ltd?`, answer: `An umbrella is simpler, with no accounts to file, and its margin of about £25 a week sits alongside employer NI, apprenticeship levy and holiday accrual inside the rate quoted to you. That suits short engagements and first-time contractors. A limited company gives 5 to 10% more take-home outside IR35 and allows company pension contributions of up to roughly £60k a year, at a cost of about £100 a month in accountancy, which starts to pay from around £40k of contracting income.` },
    { question: `What day rates do UK contractors earn in 2026?`, answer: `In IT, mid-level Java, .NET and DevOps contractors see £400 to £700 a day outside IR35. Project managers with PMP command £450 to £800, management consultants £600 to £1,500 and senior architects £800 to £1,500. Locum doctors are paid £80 to £140 an hour and consulting lawyers £500 to £2,000 or more. London adds 30 to 50% to most of these, though rates across the market fell 10 to 20% between 2022 and 2025.` },
  ],
  'electricity-cost-calculator': [
    { question: `What goes into working out an appliance's running cost?`, answer: `Multiply the appliance wattage by hours of daily use, divide by 1,000 for the kWh, then multiply by your unit rate. Under the Ofgem price cap for 1 October to 31 December 2026 that rate averages 26.32p per kWh, with a standing charge of 54.83p a day.` },
    { question: `Which household appliances cost the most to run?`, answer: `Heat and motion are expensive, light is not. A tumble dryer at 2,500W runs to about 61p an hour and an electric oven at 2,000W about 49p, while a 10W LED bulb costs 0.25p an hour. A 3kW heat pump working 12 hours a day through winter is the heaviest single load at £8.40 a day.` },
    { question: `Do time-of-use tariffs actually cut my electricity bill?`, answer: `They can, provided you have a smart meter and appliances you can schedule. Off-peak windows on tariffs such as Octopus Agile, Tracker and Cosy fall to 5 to 15p per kWh against 30 to 60p at peak. Charging an electric car overnight at 7 to 10p instead of 30p in the daytime is the clearest example.` },
    { question: `Why do I pay a standing charge when I use no electricity?`, answer: `The standing charge covers your connection rather than your consumption, so it accrues every day at around 54.83p for electricity regardless of usage. It has doubled since 2020, from about 25p a day to 60p. Zero standing charge tariffs from suppliers such as Utilita charge a higher unit rate instead, which suits holiday homes and very low users.` },
  ],
  'led-savings-calculator': [
    { question: `By how much do LED bulbs cut electricity use compared with incandescents?`, answer: `An LED draws 75 to 85% less power than an incandescent for the same brightness, so a 10W LED matches a 60W old-style bulb at 800 lumens. It also lasts far longer, around 15,000 to 25,000 hours against roughly 1,000.` },
    { question: `How long do LED bulbs take to pay for themselves?`, answer: `Payback usually falls between 12 and 24 months on the cost of the bulbs, and it comes far faster where the old lamps are power-hungry. Replacing 15 halogen downlights of 50W each with 5W LEDs at £4 a bulb costs £60 and cuts the yearly running cost from £285.90 to £28.59, a saving of £241.45, so the outlay is back within three months.` },
    { question: `What does an L80 rating on an LED bulb mean?`, answer: `L80 means the bulb still puts out 80% of its original brightness after 25,000 hours, which is the honest measure of quality. Bulbs carrying it are usually rated for 25,000 to 50,000 hours, or 20 to 40 years of normal home use, while cheap ones manage 5,000 to 15,000 hours and unbranded online bulbs often fail between 1,000 and 3,000 hours. A five-year manufacturer warranty from Philips, Osram or Crompton is the other signal worth checking.` },
    { question: `Which colour temperature suits a kitchen or a living room?`, answer: `Colour temperature changes how the light feels rather than what it costs to run. 2700K is warm and suits cosy living rooms, 4000K is neutral and works well in kitchens and bathrooms, and 6500K daylight is better kept for workshops and retail spaces. Alongside that, a colour rendering index of 80 or above keeps skin tones and fabrics looking natural.` },
    { question: `Do smart LED bulbs use power when they are switched off?`, answer: `They do. A connected bulb still draws 0.3 to 0.5W in standby, so a house with 20 or more of them adds £8 to £15 a year. Philips Hue costs £15 to £35 a bulb plus a hub at £40 to £60, IKEA Tradfri runs at £8 to £15, and hub-free options from LIFX and Govee sit at £12 to £25. Scheduling, away-mode and voice control usually justify that standby cost.` },
  ],
  'lbtt-ltt-calculator': [
    { question: `Do Scotland and Wales charge Stamp Duty on house purchases?`, answer: `No, both nations replaced Stamp Duty with their own taxes, LBTT in Scotland and LTT in Wales. Each works as a progressive slab, taxing every band of the price at its own rate rather than one flat percentage. Which one applies is decided by where the property is, not where the buyer lives, so a Scottish flat bought by a London resident is still an LBTT transaction.` },
    { question: `Do first-time buyers pay less in Scotland or Wales?`, answer: `Scotland has a first-time buyer relief worth up to £175,000, which effectively lifts the point at which LBTT starts. Wales has no equivalent scheme, having raised its main entry threshold to £225,000 for every buyer instead, which is higher than the Scottish nil-rate band of £145,000. A first purchase in Wales can therefore still work out cheaper even without a dedicated relief.` },
    { question: `How are second homes taxed in Wales compared with Scotland?`, answer: `Scotland adds an 8% Additional Dwelling Supplement on top of the normal LBTT, charged on the whole price. Wales works differently, applying a separate higher-rates band table in force since 11 December 2024, running 5% up to £180,000, 8.5% to £250,000, 10% to £400,000, 12.5% to £750,000, 15% to £1.5m and 17% above that. There is no nil-rate band, so the charge starts at the first pound once the price reaches £40,000 and you already own a dwelling.` },
    { question: `How do LBTT and LTT compare with English stamp duty?`, answer: `On a £400,000 purchase the charge is £10,000 in England, £13,350 in Scotland and £10,500 in Wales. Drop to £250,000 and England asks £2,500, Scotland £2,100 and Wales £1,500. The devolved systems put more tax on expensive homes and less on cheaper ones, so buyers below about £325k usually pay least in Wales, while above £400k England is generally the cheapest of the three.` },
    { question: `Who do I send the LBTT or LTT return to?`, answer: `Not HMRC. A Welsh purchase is reported to the Welsh Revenue Authority and a Scottish one to Revenue Scotland, in both cases within 30 days of completion, and your solicitor or conveyancer normally files it for you. Missing that deadline brings an immediate £100 penalty and then £10 a day once the return is 3 months late.` },
  ],
  'sick-pay-calculator': [
    { question: `Who qualifies for Statutory Sick Pay and what is the weekly rate?`, answer: `SSP is paid by your employer at £123.25 a week for 2026/27, or 80% of your normal weekly earnings if that is lower. Since 6 April 2026 any employee qualifies from the first full day they are too ill to work, with no minimum earnings test and no unpaid waiting days, as long as they tell their employer within its deadline.` },
    { question: `How long can I get Statutory Sick Pay for?`, answer: `SSP lasts for up to 28 weeks in a single period of incapacity, which at £123.25 a week is a maximum of £3,451. When it ends, your employer gives you form SSP1 so you can claim Employment and Support Allowance, which pays up to £95.55 a week in the assessment phase if you are 25 or over and up to £145.90 a week in the support group. Personal Independence Payment or Universal Credit may also be available depending on your circumstances.` },
    { question: `Do I need a fit note to get Statutory Sick Pay?`, answer: `Not for the first 7 days, when you self-certify. From day 8 your employer can ask for a fit note (Statement of Fitness for Work), which since the 2022 reforms can be issued by a GP, a hospital doctor or some pharmacists, physiotherapists and occupational therapists. A fit note may state that you 'may be fit for work' subject to conditions, in which case your employer has to consider reasonable adjustments before deciding whether you can return.` },
    { question: `Does my employer have to pay more than Statutory Sick Pay?`, answer: `No, SSP is the legal minimum, but many employers choose to pay Occupational Sick Pay on top. Typical schemes pay full salary for 4-13 weeks and then half salary, and banks and professional services firms often pay 6-12 weeks at full pay. Public sector employers usually offer 1 month full pay plus 2 months half pay in year 1, rising to 6 months full and 6 months half after 5 years. Your contract and staff handbook set out what applies to you.` },
  ],
  'pay-rise-calculator': [
    { question: `How much of my pay rise will I actually keep after tax?`, answer: `You keep 72p of every extra pound as a basic-rate taxpayer, after 20% income tax and 8% National Insurance, dropping to 58p once you are a higher-rate taxpayer paying 40% tax and 2% NI. With no pension contribution, a 4% rise on £35,000 is £1,400 gross but £1,008 net, about £84 a month. If a workplace pension takes 5% of pay before tax, a £4,000 rise from £38,000 to £42,000 costs £200 in pension, £760 in income tax and £320 in NI, leaving £2,720, or 68% of the gross figure.` },
    { question: `What is a typical pay rise in the UK in 2026?`, answer: `The CIPD Labour Market Outlook for summer 2026 found employers expected a median basic pay award of 3% over the next 12 months, the same in the private, public and voluntary sectors. To hold your purchasing power the rise should at least match inflation, and CPI was 3.1% in the 12 months to August 2026 (ONS), so a 3% award is a slight real-terms cut. Anything above inflation is a genuine gain.` },
    { question: `Does a pay rise above £60,000 affect my Child Benefit?`, answer: `Yes. Once your income passes £60,000 the High Income Child Benefit Charge claws back 1% of the benefit for every £200 above the threshold, on top of the 42% marginal rate (40% income tax plus 2% NI) that applies above £50,270. A £60k earner given a £5k rise nets only £2,900 before the charge is counted. Sacrificing part of the rise into a pension lowers the income used for the test and can recover some of the advantage.` },
    { question: `Is an employer pension match worth more than a pay rise?`, answer: `Often, yes, because it arrives free of tax and NI. A 5% employer match on a £40k salary is £2,000 a year. A basic-rate taxpayer on £40k keeps 72p of each extra pound, so it would take a gross rise of about £2,780 to replicate, and a higher-rate taxpayer keeping 58p would need about £3,450. Other perks are worth pricing too: private medical insurance at £400-£1,200 a year is taxed as a benefit in kind at 20-45%, an EV through salary sacrifice saves a higher-rate taxpayer 30-50%, and flexible or home working can be worth £5-£15k a year in commute savings.` },
  ],
  'annuity-calculator': [
    { question: `How is my annuity income worked out?`, answer: `Insurers base your income on pot size, age at purchase, health and the options you pick, then pay a guaranteed amount for life using life expectancy tables and current gilt yields. A bigger pot, an older age or poorer health generally lifts the annual figure, because the insurer expects to make payments for fewer years.` },
    { question: `Should I choose a single-life or a joint-life annuity?`, answer: `A single-life annuity pays the highest starting income but stops when you die, which can leave a surviving spouse badly exposed. Joint-life versions continue at 50, 66 or 100% of the original amount, and a full 100% spouse pension for two 65-year-olds starts around 15% lower. Given UK life expectancy of 82 for men and 85 for women, the joint version almost always pays more in total, particularly where one partner holds most of the couple's pension wealth.` },
    { question: `Can I get a higher annuity rate if I smoke or have a health condition?`, answer: `Yes. Enhanced or impaired-life annuities pay 10 to 40% more because the insurer expects a shorter payment period. Qualifying factors include smoking, diabetes, heart conditions, a cancer history and a high BMI, and around 60% of buyers meet at least one of them. Many never find out, because they accept a standard quote without asking. Declare every condition and lifestyle factor, even minor ones, and use a specialist broker who shops the enhanced market.` },
    { question: `Why are UK annuity rates so much better in 2026?`, answer: `Gilt yields drive annuity pricing, and they spent 15 years at unusually low levels. With the Bank of England base rate at 3.75% since December 2025 and 15-year gilt yields above 4.5%, insurers can promise far more. Someone aged 65 converting £100,000 into a single-life level annuity in May 2026 could expect £7,200 to £7,500 a year, compared with roughly £5,500 in 2020 for the same money.` },
    { question: `How is annuity income taxed?`, answer: `Annuity payments are treated as income and taxed through PAYE, so nothing is due within the £12,570 personal allowance and the rest falls into the 20, 40 or 45% bands alongside your other income. Take your 25% tax-free cash before you buy, within the £268,275 lump sum allowance. The annuity itself is not an asset in your estate, so no inheritance tax arises on it, though a spouse's continuing payments stay taxable for them.` },
  ],
  'pension-vs-isa-calculator': [
    { question: `Should I save into a pension or an ISA?`, answer: `It depends on your tax rate now against the rate you expect in retirement. Pensions give relief on contributions at 20, 40 or 45% but tax withdrawals as income beyond the 25% tax-free lump sum, whereas ISAs offer no relief upfront yet stay completely tax-free on growth and withdrawal. A higher-rate taxpayer who expects to pay basic rate once retired is the clearest case for the pension.` },
    { question: `At what age can I access a pension compared with an ISA?`, answer: `A pension is locked until 55, rising to 57 from April 2028, and only a quarter of it comes out tax-free with the rest taxed as income. An ISA has no age restriction at all, no lifetime limit on withdrawals, and no effect on your State Pension or benefits. That gap drives a common plan: build an ISA large enough to cover the years between finishing work early and reaching State Pension age at 67, then turn to the pension.` },
    { question: `What happens to my pension or ISA when I die?`, answer: `Pensions have the better death treatment for now. A defined contribution pot stays outside inheritance tax until April 2027, and beneficiaries pay no income tax on it if you die before 75, or income tax at their own rate if you die later. An ISA can pass to a spouse through the Additional Permitted Subscription, which keeps the tax wrapper intact, but any other beneficiary loses it, so the capital counts towards inheritance tax and future growth is taxed.` },
    { question: `Where does a Lifetime ISA fit alongside a pension?`, answer: `If you are under 40, a Lifetime ISA sits neatly between the two wrappers. You can pay in up to £4k a year, the bonus adds 25%, and withdrawals come out tax-free, which mirrors pension relief without the tax on the way out. It normally comes after securing the full employer pension match, since employer contributions are money no ISA can replicate, and before the ordinary ISA saving you keep for an emergency fund or a house deposit.` },
  ],
  'lifetime-isa-calculator': [
    { question: `How much can the Lifetime ISA bonus add each year?`, answer: `Pay in up to £4,000 a tax year and the government adds a 25% bonus worth as much as £1,000 annually, credited within four to six weeks of each contribution. The money can go towards a first home up to £450,000 or be taken penalty-free from age 60. Over 5 years at the maximum, that is £20,000 of your own money and £5,000 of bonuses before any growth.` },
    { question: `Who can open a Lifetime ISA and for how long?`, answer: `You have to be between 18 and 39 to open one, and once it is open you can keep paying in until you turn 50. The account can be held in cash or in stocks and shares, and you can switch between them. The £4,000 annual limit sits inside the wider £20,000 ISA allowance rather than being extra, so paying the maximum into a LISA leaves £16,000 for other ISAs that year.` },
    { question: `What happens if I take money out of my LISA early?`, answer: `Withdrawing for anything other than a first home or retirement at 60 costs 25% of the amount taken out. Pay in £4,000, receive the £1,000 bonus for a balance of £5,000, and withdrawing the lot returns £3,750, which is £250 less than you contributed. The charge claws back the bonus and takes a slice of your own money with it. A terminal illness diagnosis is the only exemption, and property withdrawals need 12 months to have passed since your first contribution.` },
    { question: `Is a LISA better than a Help to Buy ISA for a first home?`, answer: `Of the two, only the LISA is open to new savers, since Help to Buy ISAs closed to new accounts in November 2019 and existing holders can only contribute until November 2029. The older account pays 25% on up to £12,000, capping the bonus at £3,000 for life, and limits you to a £250k property outside London. The LISA pays up to £1,000 a year with no lifetime ceiling and works on properties up to £450k across the UK. Transfers from one to the other go through your provider. The government plans a First Time Buyer ISA to replace the LISA for new savers (its consultation closed on 18 August 2026); existing LISAs stay open.` },
  ],
  'child-maintenance-calculator': [
    { question: `How much child maintenance will I have to pay?`, answer: `The CMS starts from your gross weekly income as reported to HMRC and applies 12% for one child, 16% for two and 19% for three or more. Below £7 a week nothing is payable, from £7 to £100 a flat £7 a week applies, and between £100 and £200 the reduced rate is £7 plus a percentage of the income above £100. A parent on £500 a week gross with one qualifying child and no shared care pays 12%, which works out at £60 a week. Other children in your household and overnight care both bring that figure down.` },
    { question: `How long does child maintenance last?`, answer: `Payments continue until the child turns 16, and up to 20 if they remain in approved full-time education such as A-levels or a vocational course at NVQ Level 3 or below. University degrees and employer-paid apprenticeships both end it. Liability also stops if the child marries, joins the armed forces or goes to prison. When a paying parent dies the ongoing maintenance ceases, although arrears can still be recovered from the estate, and a receiving parent who remarries keeps the award unchanged.` },
    { question: `Which is cheaper, Direct Pay or Collect & Pay?`, answer: `Direct Pay is free. The CMS works out the amount and the two parents move the money between themselves, which suits most families. Collect & Pay costs 24% in total, made up of a 20% surcharge on the paying parent and a 4% deduction from the receiving parent, and it is reserved for cases where payments are unreliable or contact is difficult. If payments stop, the CMS can order a deduction from earnings, freeze a bank account, suspend a driving licence or passport for up to 2 years, or send bailiffs.` },
    { question: `What can I do if my ex hides income?`, answer: `The CMS relies on HMRC data, so it sees PAYE earnings and declared self-employment profit but not money kept off the books. A receiving parent who suspects understated income can request a variation, and the CMS will weigh the lifestyle on display, meaning several cars, properties or expensive holidays, against the income declared. Evidence from a forensic accountant sometimes carries the case, and suspected tax evasion can be reported to HMRC separately. Complex business structures usually need a specialist family solicitor charging £200 to £400 an hour.` },
  ],
  'moving-cost-calculator': [
    { question: `How much does it cost to move house in 2026?`, answer: `A Which? survey puts the average UK move at £8,000-£15,000. On a £300k purchase that breaks down as roughly £3,000 in estate agent fees on the sale (1% plus VAT), £1,500 for the solicitor, £600 for a survey, £999 for the mortgage arrangement fee, £1,200 for removals, £80 for an EPC, £200 for broadband and utility setup and £500 in new mortgage product fees, with stamp duty on top. London moves often reach £15-£25k. First-time buyers pay no stamp duty up to £300k and avoid sale-side fees entirely.` },
    { question: `How long does moving home usually take?`, answer: `The average UK move takes 12-16 weeks from accepted offer to completion. A mortgage application typically takes 2-4 weeks, searches and conveyancing 6-10 weeks, exchange of contracts falls around 10-12 weeks, and completion follows 1-4 weeks after exchange. Delays generally come from a chain break, leasehold management company queries, a mortgage valuation problem, or a survey finding that reopens the price. First-time buyers move faster, often in 8-12 weeks, because they have nothing to sell.` },
    { question: `What is the cheapest way to move house?`, answer: `DIY van hire at £100-£200 a day, with friends to help and possibly a parking permit at £20-£40 in London, Bristol or Manchester, brings a 1-bed flat move down to £200-£400 against £600-£900 for a removal company. The trade-off is damage liability, insurance gaps and your own time. A man-and-van at £40-£60 an hour sits in the middle, around £200-£500 for a 2-3 bedroom move. Decluttering first helps, and selling the surplus raises £200-£500 on average.` },
    { question: `Are estate agent fees negotiable when I sell?`, answer: `Always. The average UK fee in 2026 is 1.0-1.5% plus VAT for sole agency, or 1.5-2.5% for multi-agency, while online agents such as Purplebricks, Strike and Yopa charge a fixed £999-£3,500. On properties above £500k there is room to push towards 0.75-1.0%. Ask for a VAT-inclusive quote, keep any tie-in period to 8-12 weeks rather than 16-26, and check whether you are signing sole agency or sole selling rights, because the latter means paying even if you find the buyer yourself.` },
  ],
  'paternity-pay-calculator': [
    { question: `Can I take my two weeks of paternity pay separately?`, answer: `Yes. Since April 2024 the two weeks can be split into two separate one-week blocks and used at any point within 52 weeks of the birth or adoption placement, where the old rules gave you 56 days. Splitting is popular for covering the first fortnight at home and then a later handover at work. The rate is the lower of £194.32 a week or 90% of your average weekly earnings for 2026/27, however you take the time.` },
    { question: `How much tax comes off Statutory Paternity Pay?`, answer: `SPP counts as normal earnings, so income tax and National Insurance are deducted through payroll in the usual way. For an employee on £35,000 a year, average weekly earnings are £673.08 and 90% of that is £605.77, comfortably above the cap, so the rate paid is £194.32 a week. Two weeks therefore comes to £388.64 gross, and after deductions of about 28% the take-home figure is roughly £279.82.` },
    { question: `How does Shared Parental Leave compare with paternity leave?`, answer: `Shared Parental Leave is far longer. Where the mother gives up part of her maternity leave and pay, the other parent can take up to 50 weeks of leave and 37 weeks of pay at £194.32 a week, against the 2 weeks available through paternity leave. It works best where the mother is the higher earner and wants to return to work sooner. The trade-off is administrative, with 8 weeks notice needed for each block and a maximum of 3 blocks per parent.` },
    { question: `Do I need 26 weeks' service to take paternity leave?`, answer: `Not for the leave itself. Since 6 April 2026 fathers and other parents have a day-one right to 2 weeks off for babies due in or after the week beginning 5 April 2026, where the old rule required 26 weeks of service. The pay is a separate test, and for that you still need 26 weeks of continuous service by the 15th week before the due date, plus average earnings of at least £129 a week. Check your contract too, since many employers top the statutory rate up, often to full pay.` },
  ],
  'notice-period-calculator': [
    { question: `Does my notice period grow the longer I have been employed?`, answer: `Between one month and two years of continuous service earns one week's notice. From two years onward you gain an extra week for every complete year worked, capped at 12 weeks once you reach 12 years of service. Anything beyond that adds nothing further, although a contract can always set a longer period than the statutory floor.` },
    { question: `Is payment in lieu of notice taxed?`, answer: `Yes, in full. Since April 2018 every PILON is subject to income tax and National Insurance, whatever the contract calls it, so the old distinction between contractual and non-contractual payments no longer helps. Redundancy pay is treated differently, with the first £30k tax-free. If an employer wants you away from the workplace during notice, garden leave is the alternative, and there you stay employed and paid while keeping out of competitive activity.` },
    { question: `What notice applies during a probation period?`, answer: `Most UK contracts set a probation of 3-6 months, and during it notice is usually one week each way, occasionally cut to a single day within the first month. After probation the normal contractual notice takes over. Failing probation does not strip away statutory rights, so an employee with more than a month's service is still owed the statutory minimum of one week. Protection against discrimination applies from day 1 regardless of probation terms.` },
    { question: `Can my contract give me less notice than the statutory minimum?`, answer: `No. The statutory period is a floor, so where the contract offers less the statutory entitlement applies, and where it offers more the contract wins. That is why someone with five years of service and a one-month contractual notice is entitled to five weeks rather than the 4.3 weeks a month works out at. Notice you owe your employer is a separate sum and is often much shorter, at one week once you have a month's service.` },
  ],
  'work-from-home-tax-relief-calculator': [
    { question: `Who can claim tax relief for working from home?`, answer: `From 6 April 2026 no employee can claim it for current costs, because the relief was abolished for 2026/27 onwards. You can still claim for 2022/23 to 2025/26 if your employer required you to work from home in those years, at a flat £6 a week (£312 a year) with no receipts, worth £62.40 a year to a basic-rate taxpayer or £124.80 at the higher rate, through Self Assessment or form P87. Your employer can still pay you £6 a week tax-free.` },
    { question: `Is it worth claiming actual costs instead of the flat rate?`, answer: `For the years you can still claim, 2022/23 to 2025/26, only where the extra costs are clearly higher. The flat rate gave £312 a year with no paperwork, worth £124.80 to a higher-rate taxpayer. If you can evidence an extra £50 a month on heating and electricity, that is £600 a year and £240 of relief at 40%, so £115.20 better. The catch is proof, since an actual claim needs records and a defensible split of each bill between household and work use.` },
    { question: `Can I claim if I choose to work from home some days?`, answer: `No. For 2026/27 onwards the employee relief no longer exists, and for the earlier years still open to a claim HMRC restricted it, from 2022, to employees who were required to work from home, meaning no office is available to them or the contract specifies homeworking. A voluntary hybrid arrangement does not qualify, however many days you spend at the kitchen table. Days when the office is full or shut make a stronger case. Before 2022 the test was much looser, which is why plenty of people who claimed successfully then would fail today.` },
    { question: `What can I claim if I am self-employed and work from home?`, answer: `Self-employment uses a different route. HMRC's simplified expenses pay £10 a month for 25-50 hours worked at home, £18 for 51-100 hours and £26 for 101+ hours, with no bills to retain. Working from actual costs means apportioning by rooms and time, so one room out of five used 80% for business claims 16% of a £2,400 utility bill, which is £384 a year. That beats the simplified rate for anyone at home most of the week.` },
  ],
  'insulation-calculator': [
    { question: `How quickly does home insulation pay for itself?`, answer: `Loft insulation at the recommended 270mm depth costs £300 to £600 and trims roughly £180 to £250 off yearly bills, while cavity wall work costs £500 to £1,500 for savings of £150 to £300 a year. For a 1960s three-bed semi with neither, £450 of loft insulation saving £220 a year pays back in 2 years, and £800 of cavity wall insulation saving £280 pays back in 2.9 years, a combined saving of £500 a year. Solid wall, floor and draught-proofing measures take longer to recover their cost.` },
    { question: `What U-value does loft or wall insulation need to meet?`, answer: `For an element you are upgrading, Approved Document L Table 4.3 asks for 0.16 W/m²K on a loft or pitched roof, 0.55 on a cavity wall, 0.30 on a solid wall and 0.25 on a floor. New elements such as an extension follow Table 4.2 and are tighter at 0.15 for the roof and 0.18 for walls and floors. Replacement windows need 1.4 W/m²K or Band B. The upgrade is only compulsory where it is technically feasible and pays back within 15 years.` },
    { question: `Can I get a grant for insulation in the UK?`, answer: `The Great British Insulation Scheme closed on 31 March 2026 and ECO4 is winding down, so the main route in England is now the Warm Homes: Local Grant from your council, which can pay for insulation in privately owned or privately rented homes rated D to G where household income is usually £36,000 or less. Insulation is also a condition of other support: the £7,500 Boiler Upgrade Scheme grant for a heat pump requires the home to meet minimum insulation standards first, so the order of works matters.` },
    { question: `How do I know if my house has cavity walls or solid walls?`, answer: `Age is the best clue. Around 90% of UK homes built since 1920 have cavity walls, which can be filled with blown beads or mineral wool. Houses built before 1920 usually have solid 9-inch brick walls with no gap, and these need internal wall insulation at £40-£100/m² or external wall insulation at £80-£200/m² instead. External insulation performs better but changes the look of the house and needs planning permission in a conservation area.` },
    { question: `Can I top up existing loft insulation myself?`, answer: `Yes, and it is one of the easier DIY jobs. If the loft already has 100mm, lay new mineral wool over it to reach 270mm, which costs £150-£300 in materials. Do not squash the layers down, since compressed insulation loses its value, and fit raised access boards if you store things up there. Most lofts are ventilated and need no vapour membrane, but a room in the roof needs more careful detailing.` },
  ],
  'vat-return-calculator': [
    { question: `How do I know whether I owe VAT or get a refund?`, answer: `Compare the output VAT charged on your sales with the input VAT paid on your purchases. If sales VAT is the larger figure, you pay the difference to HMRC. If purchase VAT is larger, HMRC repays you. Most trading businesses owe a modest amount each quarter, while a business buying heavily in equipment or stock ahead of its sales often finds itself in a repayment position instead.` },
    { question: `Which VAT scheme suits a small business best?`, answer: `Standard accounting works for most. Cash Accounting, open below £1.35m of turnover, means you hand over VAT only once the customer has paid, which helps when invoices run late. Annual Accounting gives one return and 9 interim payments. The Flat Rate Scheme charges a sector percentage of gross turnover, between 4 and 16.5%, and a Limited Cost Trader whose goods cost under 2% of turnover pays 16.5%. Margin schemes cover second-hand goods, art and antiques.` },
    { question: `What happens if I file or pay VAT late?`, answer: `For VAT periods starting from 1 January 2023 the default surcharge has gone. VAT paid within 15 days of the deadline attracts no penalty. After that you pay 3% of what was unpaid at day 15, another 3% of what is still unpaid at day 30, then a daily penalty at 10% a year from day 31, plus late payment interest at Bank of England base rate plus 4% from the first day. Late filing earns a point per return, and a £200 penalty once you reach 4 points on quarterly returns. Paying by Direct Debit gives 3 extra days beyond the usual deadline of 1 month and 7 days after the period end, which is often enough to stay clear.` },
    { question: `Do I have to use software to file VAT?`, answer: `Yes. Under Making Tax Digital, returns must be submitted through compatible software such as Xero, QuickBooks, Sage, FreeAgent or Zoho, and the digital records have to reach HMRC through an API. Manual spreadsheet uploads were banned in April 2021. If you would rather stay in a spreadsheet, bridging software connects it to HMRC and submits on your behalf, which keeps existing workbooks usable without breaking the rules.` },
  ],
  'payroll-calculator': [
    { question: `What order are deductions taken off my pay in?`, answer: `Gross pay comes first, then any salary sacrifice pension, then PAYE income tax on your tax code, then employee National Insurance, then a net-pay pension contribution if you are not on salary sacrifice, and student or postgraduate loan repayments last. The order matters because salary sacrifice reduces the figure everything after it is calculated on, which is why it saves National Insurance as well as income tax.` },
    { question: `How often must UK employers report payroll to HMRC?`, answer: `A Full Payment Submission has to reach HMRC on or before every payday under Real Time Information, whatever the pay frequency. Around 70% of UK employers pay monthly and 25% weekly. Late RTI submissions carry penalties of £100 to £400 per occurrence. PAYE and NI must be paid over by the 22nd of the month after the pay period, or the 19th if paying by post, and employers under £1.5m a year can pay quarterly.` },
    { question: `Who has to be auto-enrolled into a workplace pension?`, answer: `Every UK employer must enrol eligible workers, meaning those aged 22 up to State Pension age earning over £10,000 a year, a duty in force since 2018. Minimum contributions are 8% of qualifying earnings between £6,240 and £50,270, made up of 3% from the employer and 5% from the employee. The Pensions Regulator can fine non-compliance up to £10,000 a day. NEST is the government-backed default, with People's Pension, Smart Pension and Aviva among the alternatives.` },
    { question: `How long must I keep payroll records for?`, answer: `HMRC expects payroll records to be kept for 3 years after the end of the tax year, covering gross pay, deductions for tax, NI, student loans and attachment of earnings, employee details such as National Insurance number, address and date of birth, payslips, P60s, P45s, P11Ds and Real Time Information submissions. Pension scheme records run to 6 years, right to work documents to 2 years after employment ends, and statutory pay records to 3 years.` },
  ],
  'late-payment-interest-calculator': [
    { question: `What interest can I charge a business that pays my invoice late?`, answer: `Under the Late Payment of Commercial Debts (Interest) Act 1998 you can add statutory interest at the Bank of England base rate plus 8 percentage points a year, together with compensation. Interest starts the day after the agreed payment date, or 30 days after delivery or the invoice where no terms were set.` },
    { question: `How much fixed compensation can I claim on an overdue invoice?`, answer: `The Act allows a fixed sum for each overdue invoice on top of the interest. Debts up to £999.99 carry £40, debts from £1,000 to £9,999.99 carry £70, and debts of £10,000 or more carry £100. Where your actual recovery costs run higher than that, for example the fee charged by a debt collection agency or the cost of chasing by letter, the reasonable excess can be claimed as well.` },
    { question: `How is daily interest on an overdue invoice worked out?`, answer: `Take the outstanding debt, multiply it by the statutory rate, divide by 365 and multiply by the days overdue. On a £5,500 invoice with the base rate at 3.75%, the statutory rate is 11.75% and daily interest comes to £1.770. Left unpaid for 45 days that is £79.66 of interest, before any fixed compensation is added to the claim.` },
    { question: `Can I charge late payment interest to a private customer?`, answer: `Not under this Act, which covers business-to-business transactions and public authority debts. With a consumer you can charge interest only if your terms and conditions provide for it, and any late penalty has to be reasonable. Should you take court action and win, the court interest rate of 8% under the Judgments Act 1838 applies instead. Collection conduct must also stay within the 2008 unfair commercial practices rules, which prohibit aggressive debt collection.` },
  ],
  'overtime-calculator': [
    { question: `Am I entitled to extra pay for working overtime?`, answer: `There is no statutory right to enhanced overtime pay in the UK, so it comes down to what your contract says. Typical terms are time-and-a-half at 1.5 times your normal hourly rate or double time at twice the rate, though some employers pay the standard rate or give time off in lieu. Whatever the rate, total pay across your hours still has to meet the National Minimum Wage.` },
    { question: `How much tax and National Insurance comes off overtime pay?`, answer: `Overtime is taxed as ordinary income with no special treatment. Ten hours at time-and-a-half on a £16 base rate pays £24 an hour, so £240 gross. A basic-rate taxpayer loses £48 to income tax at 20% and £19.20 to National Insurance at 8%, leaving £172.80. Because PAYE is cumulative, a large one-off payment can be deducted at a higher rate for that month and then correct itself later in the tax year.` },
    { question: `Does overtime count towards my holiday pay?`, answer: `Often, yes. Guaranteed overtime, which the employer must offer and you must accept, counts as normal pay for holiday pay and statutory maternity pay. Voluntary overtime counts too where it is worked consistently, following Bear Scotland in 2014, Lock v British Gas in 2016 and Williams v Brunel University in 2017. Overtime offered only occasionally and worked irregularly sits outside the calculation, which is where most disagreements with employers start.` },
    { question: `Can my employer make me work more than 48 hours a week?`, answer: `Not without your written agreement. The Working Time Regulations 1998 cap the working week at 48 hours averaged over 17 weeks, and you can opt out of that limit in writing, which is still lawful in the UK after Brexit. Under-18s, transport workers, security guards and doctors-in-training cannot opt out at all. Rest rules apply either way, with 11 hours between shifts and 24 hours off a week, or 48 hours across 2 weeks.` },
  ],
  'nhs-pay-calculator': [
    { question: `How much does an NHS Band 5 nurse earn?`, answer: `Agenda for Change sorts England's NHS roles into nine bands, most with two or three pay points that staff move through every 2 or 3 years as service builds up. A newly qualified nurse on Band 5 starts near £32,073 in 2026/27, rising to £39,043 at the top of the band after 4 years. London supplements, unsocial hours premiums and on-call payments sit on top of that basic figure.` },
    { question: `How much is London weighting on NHS pay?`, answer: `High Cost Area Supplements are paid on top of basic pay. Inner London adds 20% of basic salary, with a minimum of £5,794 and a maximum of £8,746, Outer London 15% (£4,870 to £6,137), and the Fringe, a defined list of areas around London, 5% (£1,346 to £2,270). Because the cap bites on higher bands, the percentage is only the headline. A Band 6 at the top of the band on £48,117 in Outer London would get £7,217.55 at 15%, but the cap limits it to £6,137, taking gross pay to £54,254.` },
    { question: `How much do NHS staff pay into the pension scheme?`, answer: `Contributions are tiered from 5.2% to 12.5% of pensionable pay, and the rate for your tier applies to all of your pay, not just the part above the threshold. A Band 6 on £54,254 including Outer London HCAS pays 10.7%, which is £5,805 a year, taken before income tax. In return the scheme builds at 1/54th of pay annually on a career average basis, revalued by CPI + 1.5% each year while you are an active member, and employers pay in a further 23.7% of pensionable pay.` },
    { question: `What do night and weekend shifts add to NHS pay?`, answer: `Saturdays and weekday nights between 8pm and 6am are paid at time plus 47% for Band 1, 41% for Band 2, 35% for Band 3 and 30% for Bands 4 to 9. Sundays and public holidays pay time plus 94%, 83%, 69% and 60%, so the lowest paid staff get the largest uplift. On-call availability is paid separately as a percentage of basic pay, depending on how often you are on call. For staff working regular nights and weekends these supplements make a substantial difference to annual earnings, which is why the band alone is a poor guide to what a role actually pays.` },
  ],
  'childcare-cost-calculator': [
    { question: `Is a childminder cheaper than a nursery?`, answer: `Often, though prices vary a lot by area, so compare quotes for the same hours. For reference, the Coram Childcare Survey 2026 (March 2026) puts a 25-hour nursery place for a child under two in England at £189 a week for families without funded hours. Childminders are also more flexible about start and finish times. The trade-off is holiday cover, because a childminder taking leave leaves you without care while a nursery stays open. For school-age children, after-school clubs, averaging £69 a week in England, and holiday clubs fill the gaps.` },
    { question: `How do the free childcare hours work?`, answer: `Every 3 and 4-year-old gets 15 hours a week in term time, about 38 weeks a year, regardless of what the parents do. Working families where each parent earns over £203 a week and neither earns above £100,000 now get 30 hours from 9 months, following the September 2025 expansion. Apply online through Childcare Choices on gov.uk for a code to give your provider, then reconfirm your details every 3 months to keep it valid. Some settings stretch the hours over 50 or more weeks at a lower weekly figure.` },
    { question: `Can I use Tax-Free Childcare and Universal Credit together?`, answer: `No. You cannot get Tax-Free Childcare while you or your partner claim Universal Credit, though you can switch from one to the other if your circumstances change. Tax-Free Childcare adds £2 for every £8 you pay in, capped at £2,000 a year per child, and suits working parents earning over £203 a week and under £100,000 each. The Universal Credit childcare element reimburses up to 85% of costs, capped at £1,071.09 a month for one child or £1,836.16 for two or more, and generally works out better for lower-income households already claiming UC.` },
    { question: `How can grandparents claim NI credits for childcare?`, answer: `Specified Adult Childcare credits let a grandparent or other family member caring for a child under 12 claim a National Insurance credit towards their own State Pension. The child's parent must be receiving Child Benefit and the carer must be under State Pension age. Only one credit is available per family per week, not one per child. Use form CA9176 on gov.uk, with claims backdated as far as April 2011. Each credited year is worth roughly £360 a year of extra State Pension for life.` },
  ],
  'mot-date-calculator': [
    { question: `When does a new car need its first MOT?`, answer: `A car needs its first MOT once it turns three years old, and every year after that. The test covers roadworthiness items like brakes, lights, steering, suspension, tyres, seatbelts and emissions, with the DVSA maximum fee capped at £54.85 for a standard car in 2026/27. A proposal to push the first test out to four years was rejected, so three years remains the rule.` },
    { question: `Can I take the MOT early without losing days on the certificate?`, answer: `Yes, up to one month before the expiry date. The new certificate runs from the old one's expiry rather than the test date, so nothing is lost, and testing early leaves room to sort out repairs before the current MOT runs out. Check your exact due date free at gov.uk/check-mot-status using the registration number.` },
    { question: `What are my options if the car fails its MOT?`, answer: `It depends on the grading. A dangerous defect means the car cannot leave the garage, a major fail means no driving until it is repaired and retested, and a minor fail is advice only, with the car still road legal. Return to the same garage within 10 working days for a free retest, or pay the full fee again after that. Driving a failed car, except to a booked repair, risks a £1,000 fine and voids your insurance.` },
    { question: `Which vehicles do not need an MOT at all?`, answer: `Vehicles more than 40 years old, meaning registered before 1986 as of 2026, are exempt unless they have been substantially modified. Electric goods vehicles under 3.5 tonnes registered before March 2015 skip emissions testing. Taxis and other hire or reward vehicles need an MOT plus separate annual checks, and agricultural vehicles come under their own regime.` },
    { question: `Is it cheaper to book the MOT and a service together?`, answer: `Usually. An independent garage charging £30 to the £54.85 cap for the test plus an interim service at £100 to £200 is the cheapest route, and some chains sell the pair as a bundle. A dealer MOT at £80 to £120 offers nothing extra for the money, while a test-only outfit may pass the car but miss a fault that is developing. You cannot tax the car without a valid MOT, since the DVLA checks.` },
  ],
  'train-season-ticket-calculator': [
    { question: `Is an annual season ticket cheaper than paying monthly?`, answer: `Yes, in most cases: an annual ticket costs about 40 times the weekly price, which buys twelve months of travel for roughly ten months' worth of fares. A weekly ticket is around 5 times the daily anytime fare and a monthly about 3.84 times the weekly price, so the monthly saves the equivalent of 8 to 12 weeks a year against dailies, where the annual saves twelve.` },
    { question: `Which railcard saves the most on a regular commute?`, answer: `All the main cards take a third off most fares, so the choice is about eligibility rather than value. The 16-25, 26-30, Senior, Two Together, Family and Friends and Disabled Persons Railcards each cost £30 a year, with the Family and Friends card adding 60% off child fares, while the Network Railcard covers off-peak and weekend travel in the South East for £35. The 16-25 and 26-30 discounts can be applied to annual season tickets on some routes.` },
    { question: `Are flexible season tickets worth it for hybrid working?`, answer: `For two or three office days a week, usually yes. A flexible season ticket gives 8 days of travel within any 28 days at a fixed price and saves around 20% against buying daily tickets. At four or five days a week a traditional season ticket wins comfortably. They are sold on most UK networks and activated in the Trainline or operator app, but they are not always cheaper than a weekly ticket plus a few dailies, so check your own pattern.` },
    { question: `Can I get help paying for an annual ticket up front?`, answer: `Many UK employers run an interest-free season ticket loan. HR takes one to three weeks to process it, the employer buys the ticket and then deducts the cost from your net salary over 12 months at no interest, which spreads £3,000 to £5,000 without changing the price. It is not salary sacrifice, so your tax position is unaffected, and it does not show on your credit file. Leaving the job mid-loan means the balance comes out of your final pay or moves to a repayment plan.` },
    { question: `How does split-ticketing make the same journey cheaper?`, answer: `Fares are set leg by leg, so buying two or three tickets that together cover your route can undercut the single through fare even though you stay on the same train. Trainsplit, Splitticketing.com and the Trainline split search find the combinations, and savings of 20 to 50% are common on longer routes. Booking Advance tickets about 12 weeks out helps too: London to Edinburgh can be £30 to £60 early against £150 or more on the day.` },
  ],
  'driving-test-cost-calculator': [
    { question: `What does it cost to learn to drive from start to finish?`, answer: `Expect a provisional licence at £34 online or £43 by post, the £23 theory test, the practical test at £62 on weekdays or £75 evenings and weekends, plus lessons. Most learners take around 45 hours of professional tuition before passing, so at £30 to £40 an hour outside London the tuition is by far the biggest slice, and the whole package usually lands between £1,700 and £2,400.` },
    { question: `What are the chances of passing the practical test first time?`, answer: `The DVSA recorded a first-time pass rate of 47.5% in 2025, with the overall rate including retakes at 49.2%. Where you test matters: London centres often sit at 40 to 45% while rural ones reach 55 to 60%. Budget for the possibility of a second attempt, since a retest costs £62 and most people take another £700 to £1,500 of lessons while they wait for the next slot.` },
    { question: `How long will I wait for a practical driving test slot?`, answer: `Nationally the wait ran from 14 to 20 weeks through 2025, and some areas were beyond six months, a backlog left over from COVID. Booking the test as early as you can, rather than waiting until you feel ready, is the practical response. Cancellation-monitoring services charge £15 to £40 to watch the booking system and flag earlier slots, which works but is not an official DVSA product.` },
    { question: `Why is new driver insurance so expensive, and what cuts it?`, answer: `A driver aged 17 to 19 pays £1,500 to £2,500 in their first year because they have no claims history. A black box policy takes 20 to 40% off, usually landing at £800 to £2,000, and two clean years typically bring the third year down to £900 to £1,400. A 1.0 to 1.2 litre car, off-street parking and a genuine experienced named driver all help. Learners with their own car also need provisional cover at £80 to £200.` },
    { question: `Is an intensive driving course worth the money?`, answer: `It costs £800 to £1,500 for 30 to 40 hours across one or two weeks, usually with the test included, and the daily repetition keeps skills fresh. It suits people who need a licence quickly, such as those changing job or moving. The downsides are the large single payment, the pressure of the format and a first-time pass rate a little below that of learners who spread lessons out, so anxious drivers generally do better week by week.` },
  ],
  'income-protection-calculator': [
    { question: `How much income protection cover do I actually need?`, answer: `Insurers cap cover at around 50-70% of gross salary so that going back to work still pays better than claiming. On a £45,000 salary that works out at roughly £22,500 to £29,250 a year, or £1,875 to £2,440 a month, and the benefit arrives tax-free where you fund the premiums yourself. Before fixing on a figure, subtract any sick pay you already have and set the deferred period to match it. A healthy 35-year-old non-smoker might pay £20-£60 a month for £20,000-£30,000 of annual cover.` },
    { question: `How long will an income protection policy keep paying out?`, answer: `There are two shapes on the market. A long-term policy keeps paying until you return to work, reach retirement, run out of term or die, and costs 2-3 times as much as the alternative. A short-term or budget policy pays for a fixed spell, usually 12-24 months, then stops whether or not you have recovered. Long-term cover is the sensible default for the self-employed and for anyone with thin savings. Short-term cover works better as a top-up where an employer scheme already carries the first stretch of absence.` },
    { question: `What is the difference between own and any occupation cover?`, answer: `Own occupation pays if illness or injury stops you doing your own job, even where you could still do something else, so a surgeon who develops a tremor would have a claim. Suited occupation pays only if you cannot manage a job of similar pay and status. Any occupation is the strictest test, paying only when you cannot do any job at all, which is why so many of those claims are rejected. Own occupation costs roughly 1.5-2 times a suited policy and 2-3 times an any occupation one.` },
    { question: `Which illnesses actually lead to income protection claims?`, answer: `Mental health problems and musculoskeletal conditions such as back pain, stress and depression account for 60-70% of income protection claims. That is a very different picture from critical illness cover, where cancer and heart attacks dominate, and it explains why the two products sit alongside each other rather than competing. Income protection responds to any condition that keeps you off work, including the long, undramatic absences that would never trigger a lump-sum payout.` },
  ],
  'travel-insurance-calculator': [
    { question: `If I have a GHIC, do I still need travel insurance for Europe?`, answer: `Relying on a GHIC alone leaves gaps: it only covers state healthcare in Europe, not repatriation, private treatment or non-medical costs. A policy adds protection for medical emergencies, trip cancellation, lost luggage and personal liability, and it is the only one of the two that does anything on a trip outside Europe.` },
    { question: `Is annual multi-trip cover better value than single trip policies?`, answer: `It depends on how often you go away. Annual multi-trip usually pays for itself from two or three trips a year, with family cover running from £40-£90 for Europe only up to £80-£200 worldwide. The catch is the duration cap, since most annual policies limit any one trip to 31-45 days, so a long sabbatical or gap year needs backpacker or long-stay cover instead. For a single fortnight abroad each year, a one-off policy remains cheaper.` },
    { question: `Do I have to declare a pre-existing medical condition?`, answer: `Yes, and insurers normally ask about anything diagnosed or treated in the past 2-3 years. Declaring conditions typically adds £20-£200 to the premium, or sends you to a specialist provider such as AllClear or Saga where the cover is priced properly. Leaving something off is the most common reason a claim is turned down, and it can void the whole policy rather than just the part relating to that condition, which leaves you exposed on everything else too.` },
    { question: `Does skiing or a cruise need extra travel cover?`, answer: `Both sit outside a standard policy. Winter sports usually add 30-100% to the premium, and without that extension an injury on the slopes is not covered. Cruises need a specialist wording, typically £20-£100 more, which deals with missed port departures and onboard medical care. Adventure activities such as paragliding and skydiving are excluded from basic policies altogether and have to be added separately, so check the activity list before you book anything more energetic than sightseeing.` },
  ],
  'spousal-maintenance-calculator': [
    { question: `Is spousal maintenance paid automatically after a divorce?`, answer: `No, it is never automatic. Whether one ex-spouse pays the other a regular sum turns on two things: whether one party has a financial need they cannot meet from their own resources, and whether the other actually has the means to pay.` },
    { question: `How much spousal maintenance might a court order?`, answer: `There is no formula. Judges decide under section 25 of the Matrimonial Causes Act 1973, and ongoing payments now rest mainly on the recipient's reasonable needs. The old one-third starting point, a third of the combined incomes less the recipient's income, is no longer used. This calculator shows 20% to 33% of the income gap as a rough range, so on £8,000 a month against £3,000 a month it gives £1,000 to £1,650 a month. In Scotland, support for a financially dependent spouse is limited to three years after divorce.` },
    { question: `Do I pay tax on spousal maintenance I receive?`, answer: `No. The recipient takes maintenance tax-free and does not declare it. The payer usually gets no deduction either, since payments come out of post-tax income. Maintenance Payments Relief now applies only where either spouse was born before 6 April 1935, at 10% of up to £4,530 of payments in 2026/27 (£453 at most). That makes the real cost higher than it looks, because funding £1,000 a month takes more than £1,700 a month of gross earnings for a higher-rate taxpayer.` },
    { question: `Does spousal maintenance stop if my ex remarries?`, answer: `Remarriage by the person receiving maintenance ends it automatically. Cohabitation does not, although whether it changes anything depends on how the order was drafted. Either party can also apply to vary an ongoing order where circumstances change materially, such as job loss, a new partner or retirement. A clean break settlement avoids all of this by closing off future claims from the start.` },
  ],
  'gcse-grade-calculator': [
    { question: `What GCSE grade counts as a pass under the 9 to 1 system?`, answer: `On the 9 to 1 scale, grade 4 is a standard pass and matches the old C, while grade 5 counts as a strong pass sitting between the old B and C. Grade 7 lines up broadly with the former A, and 9 is the top mark available. Employers and apprenticeship providers usually look for grade 5 or above in English Language and Maths, which is why the two passes are not interchangeable in practice.` },
    { question: `Is a grade 9 harder to get than the old A star?`, answer: `Yes. The old A* went to roughly the top 7% of candidates, whereas in 2025 only 4.7% of GCSE entries were awarded a grade 9. Candidates at that level are typically scoring 90% or more across their papers. The linear structure that came in with the new grades, where everything is examined at the end of year 11 rather than in stages, makes the top grades harder to reach than they were before 2017.` },
    { question: `Do I have to resit GCSE English and Maths if I miss grade 4?`, answer: `In England, yes. Without grade 4 or above in English Language or Maths you must keep studying that subject until you are 18 or until you reach grade 4. Resits in those two subjects run in November, with full retakes the following summer, and resitting at a sixth form is normally free as part of a 16 to 19 study programme. Only the best grade counts afterwards, so a poor earlier attempt does no lasting damage.` },
    { question: `How do exam boards decide grade boundaries each year?`, answer: `Boundaries are set once the papers have been marked, so they move with the difficulty of the paper and the performance of that year group, and they are published only shortly before results day. That is why an estimate built on last year's figures is a guide rather than a prediction. For illustration, the grade 9 boundary in 2025 Maths was 197 out of 300 while grade 4 sat at 75 out of 300, a spread that will not repeat exactly.` },
  ],
  'university-cost-calculator': [
    { question: `How much does a three-year degree cost beyond the tuition fees?`, answer: `Tuition for a 2026/27 start is £9,790 a year, adding up to £29,370 over three years, and on top of that expect £4,500 to £9,500 for accommodation and £5,000 to £8,000 in living costs each year. Across the whole course the non-tuition side usually reaches £30,000 to £60,000 or more, which is why the true total for a three-year degree lands so far above the fee cap.` },
    { question: `How much of my university costs will the maintenance loan cover?`, answer: `For 2026/27 the maximum maintenance loan is £14,135 in London, £10,830 outside London and £9,118 living at home. Put the outside-London maximum together with tuition and the annual package is £20,620, or £61,860 across three years. A gap still opens up for most students, because first-year halls alone take £4,500 to £10,500 before food, bills and travel are counted.` },
    { question: `Do Scottish and Northern Irish students pay the same tuition fees?`, answer: `No. Scottish students studying in Scotland pay no tuition fee, while students from the rest of the UK at a Scottish university pay £9,790, the same cap as England and Wales. Northern Irish students studying in Northern Ireland pay £4,855. International fees sit far higher, starting at £14,000 in Scotland and running from £15,000 to £40,000 or more in England.` },
    { question: `What is the cheapest way to get through a UK degree?`, answer: `Living at home is the single biggest saving, worth £6,000 to £15,000 a year on accommodation, and picking a cheaper city such as Birmingham, Sheffield or Newcastle takes off more. Part-time work of 10 to 20 hours a week adds £6,000 to £12,000 a year. Merit scholarships of £500 to £3,000 are worth applying for, and a degree apprenticeship removes tuition altogether, since the employer funds it and you earn a salary while studying.` },
  ],
  'greenhouse-size-calculator': [
    { question: `What growing area do I actually get in a 6ft by 8ft greenhouse?`, answer: `A 6ft by 8ft house has 48 square feet of floor, but a central path and staging bring the usable growing area down to roughly 36 to 40 square feet, split between ground beds and shelving. Staging along both long walls adds a further 20 to 24 square feet of bench, which is where seed trays and small pots belong rather than tall crops.` },
    { question: `How many tomato plants fit in a small greenhouse?`, answer: `Cordon tomatoes want about 3 square feet each, spaced 18 inches apart in rows 24 inches apart, so the 36 to 40 square feet of usable floor in a 6ft by 8ft house fills up quickly once you allow for light and air movement. Cucumbers are greedier at 4 square feet each, while peppers and aubergines need 2.5. Tomatoes repay the space best, yielding 10 to 15kg per plant over a season.` },
    { question: `Does a greenhouse need planning permission in the UK?`, answer: `In most gardens it does not. Building regulations normally treat a greenhouse as permitted development where the floor area is under 25 m², the height is under 4m and it stands more than 2m from the boundary. The more useful constraint is siting. Run the long axis east to west, keep it clear of trees, fences and buildings to the south, and stay out of frost pockets on low ground, because partial shade alone can cut yield by 30 to 50%.` },
    { question: `Is it worth heating a greenhouse over a British winter?`, answer: `That depends what you want from it. Left unheated the house works from March to October. Keeping it frost-free at 5°C costs £100 to £300 a year and carries seedlings, citrus and succulents through. A cool house held at a minimum of 10°C runs £400 to £800 and allows tropical plants and off-season tomatoes. Going above 15°C for orchids and exotics costs £800 to £2,000. An electric fan heater is cheap to buy at £150 to £400 and expensive to run.` },
  ],
  'pond-volume-calculator': [
    { question: `Which formula works out my pond's volume in litres?`, answer: `For a rectangular pond you multiply length by width by average depth, and for a round one it is pi times the radius squared times the depth. Multiply the cubic metres by 1,000 for litres, which for most garden ponds lands between 500 and 5,000. Curved or kidney shapes are close enough if you take average length and average width and then multiply by 0.85, and add 5 to 10% where shelves sit at different depths.` },
    { question: `How many fish can a 3,600 litre pond hold?`, answer: `Goldfish are stocked at 1cm of fish per 22 litres, so 3,600 litres supports about 165cm of goldfish in total. Koi need far more room at 1cm per 132 litres, which comes to 27cm, or one young fish. Build up gradually rather than filling the pond on day one, starting at around 10% of capacity and increasing quarterly, since ammonia and nitrate rise fast in a new pond and overstocking can kill fish within weeks. Plants over at least 50% of the surface help.` },
    { question: `What size pump does my garden pond need?`, answer: `Work from turnover. A pond without fish should cycle its full volume every 2 hours, and one with fish every hour, so a 3,600 litre stocked pond needs a pump rated at 3,600 litres an hour or better. UK retail pumps from Hozelock, Oase and All-Pond Solutions run £80 to £400. Match the pressurised filter and UV unit to the same volume, because an undersized filter leaves you with green water, while an oversized one causes no harm at all.` },
    { question: `What does building a garden pond cost in the UK?`, answer: `A typical domestic pond comes to £500 to £1,500 to build, plus £100 to £300 a year to run. Heavy duty butyl liner at 0.75mm is £8 to £12 per m², and a 4m by 3m pond needs roughly 20 m² of it. Underlay adds £2 to £4 per m². Budget £200 to £600 for pump and filter, £80 to £200 for a UV clarifier, £50 to £200 for plants and £100 to £400 for edging. Digging by hand takes a day or two, or hire a mini-digger at £150 to £300 a day.` },
  ],
  'side-hustle-tax-calculator': [
    { question: `Do I need to declare side hustle income?`, answer: `Only if your trading income for the year tops the £1,000 trading allowance. Above that you register as self-employed by 5 October following the tax year, then file a Self Assessment return and pay by 31 January. Registering late can cost up to 100% of the tax that went unpaid as a result, and late filing penalties, starting at £100, can push the total past £1,600. Selling your own second-hand things is not trading, so a clear-out does not count, but selling new items for profit does.` },
    { question: `Does HMRC get my sales data from eBay and Vinted?`, answer: `Yes. Since 2024 the major platforms, including eBay, Etsy, Vinted, Airbnb, Uber, Deliveroo, Patreon, Twitch, YouTube and Just Eat, report seller data to HMRC once you pass 30 sales a year or €2,000 of income, and it is cross-checked against tax returns. If you traded above the allowance in earlier years without declaring it, a voluntary disclosure through HMRC's Digital Disclosure Service usually carries penalties of 10-30% for careless errors more than a year old, against 20-30% if HMRC finds it first, and 35-100% if HMRC treats it as deliberate.` },
    { question: `How is side hustle income taxed?`, answer: `It is added to the top of your other income, so the rate depends on what you already earn. Profits inside the basic rate band are taxed at 20%. Class 4 National Insurance of 6% only starts once the side profits alone pass £12,570, since salary does not count towards that limit, so setting aside 20-25% is usually enough for a basic-rate taxpayer and 40% for a higher-rate one. Allowable expenses such as software, marketing, mileage, supplies and training reduce the profit before tax. On £40,000 of salary and £8,000 of side profit the bill comes to £1,600 of income tax and no Class 4 NI.` },
    { question: `Do I need to register for VAT on a side hustle?`, answer: `Only once taxable turnover reaches £90,000, up from £85k in April 2024, which most side hustles never approach. The test looks back over 12 months and forward 30 days, so register before you cross rather than after. Voluntary registration is possible at any level and can pay off if you sell to businesses that reclaim VAT. Registration also brings Making Tax Digital, meaning quarterly returns filed from compatible software such as Xero, QuickBooks or FreeAgent.` },
  ],
  'employment-tribunal-calculator': [
    { question: `How do the basic award and the compensatory award differ?`, answer: `The basic award mirrors statutory redundancy pay, at half a week's pay per year worked under 22, one week from 22 to 40 and one and a half weeks from 41, with weekly pay capped at £751 and the multiplier capped at 30 weeks. The compensatory award is separate and covers actual financial loss, mainly lost earnings and pension contributions, capped at the lower of 52 weeks' pay or £123,543.` },
    { question: `Do I need two years' service to claim unfair dismissal?`, answer: `For an ordinary unfair dismissal claim, yes, two years of continuous service is the threshold. There is no service requirement at all where the dismissal is automatically unfair, which covers reasons such as trade union activity, pregnancy, whistleblowing or asserting a statutory right. Discrimination claims under the Equality Act 2010 also need no minimum service.` },
    { question: `Is there a cap on compensation for a discrimination claim?`, answer: `No. Financial loss in discrimination claims is uncapped, and serious cases can exceed £100,000. On top of that comes an award for injury to feelings under the Vento bands, running from £1,300 to £12,600 in the lower band, £12,600 to £37,700 in the middle and £37,700 to £62,900 in the upper. Aggravated or exemplary damages are possible in the most serious cases.` },
    { question: `What might I get in a settlement before the hearing?`, answer: `Around 75% of claims settle without a tribunal sitting, and settlements typically fall between 3 and 12 months' salary depending on how strong the claim looks. A settlement agreement is legally binding and the employee has to take independent legal advice first, which the employer usually contributes £500 to £1,500 towards. Acas Early Conciliation, which runs for 6 weeks, is free and comes before any of this.` },
  ],
  'roof-tiles-calculator': [
    { question: `How many roof tiles do I need per square metre?`, answer: `Around 10 concrete interlocking tiles cover a square metre (9-12 depending on the profile), compared with roughly 60 clay plain tiles, 16-18 clay pantiles or 20 to 30 slates depending on size, and each count already allows for the overlap between rows. Add 5-10% for cuts at edges, hips and valleys. A 60 m² roof at 9 concrete tiles per m² needs 540 tiles, or 594 with 10% waste.` },
    { question: `How do I measure my roof area for tiles?`, answer: `Measure on the slope, not the footprint. For each side multiply the rafter length by the eaves-to-eaves width. The rafter is longer than the horizontal distance it covers, by about 15% at a 30° pitch and about 41% at 45°. On an 8 m × 5 m gable roof at 35° the rafter works out at 3.05 m, so each side is 24.4 m² and the roof totals 48.8 m². Hips, valleys and ridges are counted separately in special tiles.` },
    { question: `How much does it cost to re-roof a house in the UK?`, answer: `Materials run from £15-£40/m² for concrete tiles up to £80-£200/m² for clay or slate, and labour adds £40-£90/m². For a 60 m² semi-detached roof that means £3,500-£8,000 in concrete, £6,000-£12,000 in clay and £8,000-£15,000 or more in natural slate. Budget separately for scaffolding at £600-£1,500, a skip at £200-£400 and, if the old roof is asbestos slate, specialist removal at £1,500-£4,000 or more.` },
    { question: `How long do roof tiles last before needing replacement?`, answer: `Concrete tiles manage 30-50 years, clay plain tiles 60-80, clay pantiles 60-100 and natural Welsh slate over 100, which is why many Victorian roofs still carry their original slates. Spanish and Brazilian slate and synthetic slate are in the 30-50 year bracket. Once 15% or more of the tiles are broken or slipped, or the felt is visibly damaged from the loft, a full re-roof usually costs less than repeated patching.` },
    { question: `Are concrete roof tiles heavier than slate?`, answer: `Yes, noticeably. Concrete tiles weigh approximately 43 kg/m² against about 30 kg/m² for natural slate, so replacing a slate roof with concrete adds a large load that the existing rafters may not have been designed for. That is why the calculator reports weight per m², and why a change of material should be checked structurally rather than treated as a straight swap.` },
  ],
  'water-bill-calculator': [
    { question: `Metered or unmetered, how is my water bill worked out?`, answer: `On a meter you pay a standing charge plus a rate for every cubic metre used and a separate sewerage charge, while unmetered bills are set by your property's rateable value. Water UK puts the average combined water and sewerage bill in England and Wales at £639 for 2026/27. Metered tariffs typically combine standing charges of £100 to £200 and volumetric rates of £1.50 to £3.00 per cubic metre.` },
    { question: `Would a water meter save me money in my house?`, answer: `As a rule of thumb, if your home has more bedrooms than occupants a meter is likely to work out cheaper, and single people in large houses gain most. Installation is free on request, and if the metered bill turns out higher than the old rateable value charge you can switch back within 24 months, so the trial costs you nothing but the paperwork.` },
    { question: `What happens if a water meter cannot be fitted at my property?`, answer: `Where the plumbing makes installation impossible, your water company can offer an assessed charge instead. That is a fixed bill based on average usage for a household of your size rather than your property's rateable value, so it still moves you off a valuation set back in 1990 and closer to what a household like yours would typically consume.` },
    { question: `What actually cuts a metered water bill?`, answer: `Fixing a leaking toilet flapper is the cheapest win at £2, since it can waste 200 litres a day. A low-flow showerhead saves about 30%, a dual-flush toilet saves 50% per flush, and swapping a bath at roughly 100 litres for a short shower at 35 litres adds up fast. Many companies supply a free water butt. Combined, these habits save a household £100 to £250 a year.` },
    { question: `Is there help with water bills for low-income households?`, answer: `Yes. WaterSure caps bills in England and Wales for low-income customers with high water needs, such as families with three or more children or people with certain medical conditions. Most water companies also offer a social tariff worth a discount of 50 to 70%, applied for directly. The free Priority Services Register covers elderly, disabled and other vulnerable customers with advance notice of supply problems.` },
  ],
  'buy-to-let-yield-calculator': [
    { question: `Gross yield or net yield, which figure shows the real return?`, answer: `Gross yield is just annual rent divided by the purchase price, so £1,000 a month on a £200k property looks like 6%. Net yield strips out the running costs, including mortgage interest, letting agent fees of 10-15%, maintenance of around 1% of value a year, insurance, void periods and safety certificates, which can pull the same property down to 3-4%. Net is the figure to judge a deal on.` },
    { question: `How does the mortgage interest tax credit affect landlords?`, answer: `Since April 2020 mortgage interest cannot be deducted from rental income. A 20% tax credit on the interest paid applies instead, which leaves higher and additional-rate landlords worse off. A higher-rate landlord with £8k of rent and £3k of interest was once taxed on £5k, or £2k at 40%. The whole £8k is now taxable, giving £3.2k of tax less a £600 credit, so £2.6k, an effective rise of 30%. Limited companies avoid the restriction, paying Corporation Tax at 19% on profits up to £50,000 and 25% above £250,000, with marginal relief in between.` },
    { question: `What rental yield should I aim for in 2026?`, answer: `Yields vary sharply by region. London sits at 4-5% gross and is bought largely for capital growth, the South East at 5-6%, Manchester, Birmingham and Leeds at 6-8%, and Liverpool, Sunderland and Bradford at 8-10% or more. High yields usually come with weaker price growth and heavier management. A common target is a net yield above 5% plus capital growth of 3-5% a year, adding up to a total return of about 8%.` },
    { question: `How does borrowing change the return on a rental property?`, answer: `Gearing amplifies the outcome both ways. A £200k property yielding 4% net returns £8k, and 4% annual appreciation adds another £8k, a total of £16k, or 8% on the full £200k if you paid cash. At 75% LTV with a £50k deposit, 5.5% interest on the £150k loan costs £8,250 and leaves the income at about break-even, −£250. The £8k of capital growth is still yours, so £7,750 on £50k works out at 15.5% on your equity before tax. A 4% fall in prices turns into an £8,250 loss, 16.5% of the deposit, by the same arithmetic.` },
  ],
  'ltv-calculator': [
    { question: `Will a lower loan-to-value ratio cut my mortgage rate?`, answer: `Yes. Lenders price in 5% bands, and each step down is worth roughly 0.2-0.3 percentage points. As of May 2026 that means about 4.20% at 60% LTV, 4.50% at 75%, 4.70% at 85%, 4.90% at 90% and 5.50% at 95%. On a £200,000 loan, an extra 5% deposit saves £20-£60 a month. The biggest jumps sit at 90%, where stress testing tightens, and at 95%, where the choice of products narrows sharply.` },
    { question: `What deposit do I need to reach 75% LTV?`, answer: `Work backwards from the property value. On a £275,000 property, reaching 75% LTV takes a deposit of £68,750. A £35,000 deposit on the same property leaves a £240,000 mortgage and an LTV of 87.3%, which falls in the 85-90% tier and prices roughly 0.3-0.5% above 75%. Closing that gap means finding another £33,750. The calculator runs the sum in either direction, from deposit to LTV or from a target LTV to the deposit required.` },
    { question: `Can first-time buyers still get a 95% mortgage?`, answer: `Yes. The government-backed Mortgage Guarantee Scheme has supported 95% LTV lending since 2021 on properties up to £600,000, with the government insuring lender losses above 80% LTV. It was extended to June 2026 and is expected to be replaced by 'Freedom to Buy'. Expect to pay 0.5-1.0% more than at 90% LTV. Family-assisted products, marketed as springboard, family deposit or guarantor mortgages, can reach 100% LTV where a relative provides the security.` },
    { question: `How is my LTV worked out when I remortgage?`, answer: `On the current market value, not the price you paid. A house bought for £300,000 with a £270,000 mortgage starts at 90% LTV. If it is worth £350,000 five years later and the balance has fallen to £240,000, the LTV is 69% and far better rate bands open up. Where prices have fallen instead, a higher LTV can leave you restricted to a product transfer with your existing lender rather than able to switch away.` },
  ],
  'stamp-duty-additional-property-calculator': [
    { question: `Do I pay the 5% surcharge if I already own a home?`, answer: `Since October 2024, buying an additional home in England or Northern Ireland adds a 5% surcharge on top of standard SDLT, up from 3% before. It covers second homes, holiday homes, buy-to-lets and property bought for relatives, and it bites even when the home you already own is held jointly or sits outside the UK. Companies and trusts pay the higher rates too, from £40,000 with no nil-rate band.` },
    { question: `Can I get the 5% surcharge back if I sell my old home?`, answer: `Yes, if the purchase replaced your main residence. Where you complete on the new home before the old one has sold, the surcharge is payable upfront and refundable once you sell the previous main residence within 36 months. The claim is made through gov.uk and has to reach HMRC within 12 months of that sale. On a £350,000 purchase the sum at stake is £17,500, so the deadline is worth watching.` },
    { question: `Does my partner's property count if we buy together?`, answer: `It depends on whether you are married. An unmarried partner's property is ignored if you buy the new home in your sole name, so no surcharge arises. Buy it jointly with them and the surcharge applies to the whole price. Married couples and civil partners are treated as one unit for this test, so if either of you owns residential property anywhere, a joint purchase attracts the 5% surcharge.` },
    { question: `Can first-time buyer relief be used on a buy-to-let?`, answer: `No. First-time buyer relief is not available on an additional property purchase, so there is nothing to offset the surcharge. A £300,000 second home bought by someone who already owns a main residence attracts £20,000 of SDLT, about 6.7% of the price, made up of £5,000 at standard rates and £15,000 of surcharge charged on the whole price from the first pound.` },
  ],
  'remortgage-calculator': [
    { question: `When should I start looking at a remortgage?`, answer: `Start about 4-6 months before your current deal ends. Most lenders will let you reserve a new rate 3-6 months early, and the switch itself takes 6-12 weeks from application to completion, so an early start costs nothing and protects you from landing on the SVR by accident. Put a reminder in the calendar for the month your fix expires. If you used a broker, check whether they begin the process for you automatically.` },
    { question: `Is it ever worth paying an early repayment charge to switch?`, answer: `Only when the interest saved outweighs the charge. ERCs typically run at 1-5% of the balance, so a 2% charge on a £200k mortgage costs £4,000. If the new rate is 1.5% lower, that saves roughly £3,000 a year and the charge is recovered after about 16 months, which works if you expect to stay put for 18+ months. As a rough test, a rate drop of 1% or more with a good stretch of the fix still to run usually justifies paying.` },
    { question: `What is the difference between a product transfer and a full remortgage?`, answer: `A product transfer keeps you with your existing lender and swaps you onto a new product. There is no valuation, no legal work and no fresh income or credit check, and it can complete in 24-48 hours, though the rate is usually a little above the open market. A full remortgage moves you to a new lender with full underwriting, a valuation and legal work, and often shaves 0.2-0.5% off the rate. Many homeowners alternate, taking a full remortgage every 5-10 years with product transfers in between.` },
    { question: `How much can I borrow when I remortgage?`, answer: `Lenders work from income multiples and an affordability stress test. Expect 4-4.5 times a single income or 3.5-4 times joint income, with specialist lenders reaching 5.5-6 times for high earners on £75k+. Affordability is tested at a stress rate each lender sets, usually 1-3 points above the rate offered or its reversion rate, and the FCA does not require the test on fixes of five years or more. Existing commitments bite hard, since every £100 a month of committed debt cuts borrowing by roughly £13,000 to £16,000, depending on the rate the lender tests at (£15,926 at the September 2026 average two-year fix of 5.73%). Maximum LTV is 90% on a standard remortgage, 95% for first-time buyers and 60-75% for buy-to-let.` },
  ],
  'debt-to-income-calculator': [
    { question: `Why does my debt-to-income ratio matter to a lender?`, answer: `It is one of the first affordability checks a lender makes, showing how much of your gross monthly income already goes on debt repayments. The lower the figure, the more room you have to take on a mortgage or loan, and the better the terms you are likely to be offered. A high ratio does not always mean refusal, but it narrows the number of lenders willing to look at the application.` },
    { question: `Which debts count towards my debt-to-income ratio?`, answer: `Regular credit commitments count: your mortgage or rent, credit card minimum payments, personal loans, car finance, student loan repayments and child maintenance. Household running costs stay out of it, so utilities, council tax, groceries and transport are excluded. That is why a household with a heavy grocery bill can still show a low ratio, while one with modest bills and several credit agreements looks stretched on paper.` },
    { question: `What DTI do UK mortgage lenders actually accept?`, answer: `Housing costs are usually held to 35-40% of gross income, with all debts together capped around 40-45%. The test is usually run at a stress rate the lender sets, typically 1-3 points above the rate you are offered, so a payment that looks affordable today still has to work if rates climb. A ratio in the 15-30% band is comfortable, 40-50% is stretched, and above 50% most mainstream lenders decline. Some specialist lenders go higher for applicants with proven income and clean credit.` },
    { question: `How can I lower my debt-to-income ratio before applying?`, answer: `Because the ratio counts monthly payments rather than balances, the quickest wins come from removing whole commitments. Settling a small car finance agreement outright can help more than overpaying a large mortgage. Attacking the highest interest rate first saves the most money overall, while clearing the smallest balances first gives visible progress sooner. A consolidation loan replaces several agreements with a single payment, often at a lower combined APR. Raising income works too, since every extra £100 a month shifts the figure.` },
  ],
  'apr-calculator': [
    { question: `Does APR include fees as well as interest?`, answer: `It does. APR wraps the interest together with any compulsory fee, whether that is an arrangement, broker or admin charge, into one yearly percentage. That is what makes two loans comparable when their charging structures differ. Optional extras sit outside it, so an add-on insurance policy will not show up in the APR you are quoted. Comparing by APR rather than headline rate is the only reliable way to see which deal actually costs less.` },
    { question: `How does a 5% flat rate compare with a true APR?`, answer: `A flat rate charges interest on the original sum for the whole term, ignoring the fact that you are paying the balance down each month. Borrow £5,000 over 3 years at 5% flat and the interest is £5,000 × 5% × 3, or £750, with monthly payments of £159.72. Expressed properly, that is an APR of approximately 9.4%. Flat rates still appear in some dealer and broker quotes, and they always flatter the deal.` },
    { question: `Why is my personal APR higher than the advertised one?`, answer: `Advertising rules only require the lender to give the representative APR to at least 51% of accepted applicants. FCA rule CONC 3.5 leaves the other 49% open to a personal rate set by credit score, income, debt-to-income ratio and loan amount, so a 6.9% representative offer can arrive at 9-12%. Eligibility tools from Experian, ClearScore or MoneySavingExpert run a soft search, which no other lender sees and which does not touch your score.` },
    { question: `What does APRC mean on a mortgage illustration?`, answer: `APRC stands for Annual Percentage Rate of Charge and is the mortgage equivalent of APR. It rolls the interest together with set-up fees and valuation costs and spreads them across the life of the deal, which is why it usually looks higher than the initial rate on the front of an offer. AER and EAR are different again. AER is what savings earn once compounding is counted, and EAR is what a credit card balance would cost over a year.` },
    { question: `Can a 0% offer still work out expensive?`, answer: `It can. An advertised period of up to 24 months at 0% might only apply to the first month, after which the rate leaps to 39% APR, so read the full term rather than the banner. Balance transfers carry an upfront charge instead of interest, and a 24 month 0% transfer with a 3% fee comes to roughly 1.5% APR effective, which is cheap but not free. Decline optional add-ons, since they sit outside the quoted APR.` },
  ],
  'bnpl-calculator': [
    { question: `What happens if I miss a Buy Now Pay Later instalment?`, answer: `Interest-free plans usually charge a flat late fee of about £5 or £6 for each missed instalment. Clearpay adds a second £6 if the payment is still unpaid 7 days later, capping total fees at 25% of the order value or £24, whichever is lower. For agreements made from 15 July 2026 the lender must tell you the late fee before you sign and offer support if you are struggling. On a £300 plan, one missed payment with a £6 fee takes the total to £306 and two take it to £312.` },
    { question: `Does Buy Now Pay Later show up on my credit file?`, answer: `It can. Klarna has reported Pay in 3 and Pay in 30 days purchases to Experian and TransUnion since June 2022, including payments made on time, and a missed payment with any provider can harm your score. Hard searches from several credit applications are visible to a mortgage lender. Check your report with Experian, Equifax or TransUnion, each of which offers a free version, about 6 months before applying for a mortgage.` },
    { question: `Is a 0% credit card better than Klarna or Clearpay?`, answer: `For anything you cannot clear quickly, yes. A 0% credit card gives 24+ months interest-free against 4 instalments over a few weeks. Both carry Section 75 protection on single items costing over £100 and up to £30,000, but for BNPL only on regulated agreements made from 15 July 2026. BNPL makes more sense for a planned purchase you can comfortably clear over 4-8 weeks, or for a large appliance where the retailer offers no 0% credit of its own.` },
    { question: `Does using BNPL make me spend more than paying outright?`, answer: `Studies suggest it does. People spend 30-50% more on BNPL than with cash, and the average BNPL transaction of £75-£150 compares with £55-£95 for the same person paying outright. The instalments are individually small, which is exactly what makes them easy to accumulate. The average UK user has £350+ running across 2-3 platforms, and because each plan has its own schedule the total commitment is hard to hold in your head.` },
  ],
  'salary-sacrifice-pension-calculator': [
    { question: `Is salary sacrifice really more tax-efficient than relief at source?`, answer: `Where National Insurance applies it is, because sacrificing gross pay avoids both the 8% employee charge and the 15% employer charge, whereas relief at source only hands back income tax. On a £500 monthly contribution from a £40,000 salary, relief at source costs £400 of net pay against £360 under sacrifice, and the gap widens for a higher-rate taxpayer, who saves 42% rather than 40%. From 6 April 2029 the National Insurance saving will apply only to the first £2,000 sacrificed each year.` },
    { question: `Can salary sacrifice affect my maternity pay or mortgage application?`, answer: `Yes, because sacrifice lowers the gross pay that other calculations rely on. Statutory Maternity Pay is worked out from the sacrificed figure, so pausing the arrangement before the reference period begins usually protects the payment. Mortgage affordability assessments and the earnings that count towards your State Pension use the reduced salary too. Sacrifice can never take you below the National Minimum Wage of £12.71 an hour, and dropping under the lower earnings limit of £6,708 puts entitlements at risk.` },
    { question: `What is employer NI passback and should I ask for it?`, answer: `When you sacrifice £1,000 of salary your employer saves 15% National Insurance on it, which is £150, and a large employer also avoids the 0.5% Apprenticeship Levy. Some employers keep that money and some return it as an extra pension contribution, which turns your £1,000 sacrifice into £1,150 in the pot. It is worth asking HR whether your scheme does this, and worth suggesting if it does not, because it costs the business nothing beyond the administration.` },
    { question: `How much does salary sacrifice save if I earn over £100k?`, answer: `More than at any other income level. Between £100k and £125,140 every extra pound is effectively taxed at 60%, since 40% income tax comes with the loss of the Personal Allowance worth another 20 points. Sacrificing £25,140 from an income of £125,140 reduces take-home pay by £9,553.20 while putting the full £25,140 into your pension, relief of 62% once the 2% National Insurance saving is included, and the employer's National Insurance saving sits on top of that.` },
  ],
  'temperature-converter': [
    { question: `How do I convert Celsius to Fahrenheit in my head?`, answer: `The exact formula is °F = (°C × 9/5) + 32, and back the other way °C = (°F − 32) × 5/9. For rough work, anchors beat arithmetic. 0°C is 32°F, 20°C is 68°F, 30°C is 86°F, 37°C is 98.6°F and 100°C is 212°F at sea level. The two scales meet at a single value, −40°C, which is also −40°F. Britain has used Celsius officially since 1972, though forecasts still quote Fahrenheit occasionally for effect.` },
    { question: `What temperature counts as a fever in the UK?`, answer: `The NHS treats 38.0°C (100.4°F) or above as a fever. Normal sits between 36.1-37.2°C (97-99°F), 39.5°C (103.1°F) counts as a high fever, and anything over 40°C (104°F) is heatstroke and a medical emergency. Below 35°C (95°F) is hypothermia, and severe hypothermia is below 32°C. Readings drift through the day by about 0.5°C, lowest near 4am and highest near 6pm, and an armpit reading runs roughly 1°C below an oral one.` },
    { question: `What is Gas Mark 4 in Celsius and Fahrenheit?`, answer: `Gas Mark 4 is 180°C or 350°F, the setting most baking recipes assume. Gas Mark 1 is 140°C or 275°F, Gas 6 is 200°C or 400°F, and Gas 9 is 240°C or 475°F. If the oven is fan-assisted it runs 20°C hotter at the same dial position, so reduce a conventional recipe by 20°C and use 160°C fan in place of 180°C. Ovens vary, and a separate oven thermometer will tell you how far yours drifts.` },
    { question: `What is the hottest temperature ever recorded in the UK?`, answer: `40.3°C, or 104.5°F, at Coningsby in Lincolnshire on 19 July 2022, the first UK day to pass 40°C. The coldest is −27.2°C (−17.0°F) at Braemar and Altnaharra in Scotland. For comparison, an average summer day sits at 16-22°C and an average winter day at 3-8°C. The UK has warmed by roughly 1.0°C since 1980, and the 10 hottest years in the record have all fallen since 2002.` },
    { question: `Why do scientists use Kelvin instead of Celsius?`, answer: `Kelvin starts at absolute zero rather than at the freezing point of water, which makes it the natural scale for thermodynamics. Convert with K = °C + 273.15, so absolute zero is −273.15°C or 0 K, water freezes at 273.15 K, body temperature is around 310 K and water boils at 373.15 K. One kelvin is the same size as one degree Celsius, and the unit takes no degree symbol. Lighting borrows the scale as well, with a warm white bulb at 2700K, a daylight bulb at 6500K and the sun at 5778K.` },
  ],
  'length-converter': [
    { question: `How many centimetres are in an inch exactly?`, answer: `Exactly 2.54 cm, fixed by international agreement in 1959, and every other imperial to metric conversion follows from it. One foot is 12 inches or 30.48 cm, one yard is 3 feet or 0.9144 m, and one mile is 1,760 yards, 5,280 feet or 1.60934 km. In reverse, 1 km is 0.621 miles. A height of 5 ft 10 in comes to 70 inches, so 70 × 2.54 gives 177.8 cm, or 1.778 m.` },
    { question: `Why does the UK still use miles on road signs?`, answer: `Metrication ran from 1965 to 1995, but road signs were exempted along with pints of beer and cider and milk in glass bottles, and the EU stopped demanding metric signs in 2009. The result is a split system that nobody planned. Construction has been metric only since the 1980s, land surveying since 1995, and driving licences have used kg for vehicle weights since 2014, while distances on the road stay in miles and yards.` },
    { question: `Why do builders measure in millimetres rather than centimetres?`, answer: `Because a decimal point in the wrong place costs money on site. A board is called 2400mm rather than 2.4m so no digit can go missing from a cutting list. Standard sizes follow the same habit. A UK internal door is 1981mm tall, or 78 inches, and 762 or 838mm wide, while a brick is 215×102.5×65mm. Timber sold as 2×4 is a nominal name for a piece that measures 38×89mm once planed.` },
    { question: `How far is Land's End to John o'Groats in miles?`, answer: `874 miles by road, which is 1,407 km. Other useful yardsticks sit around it. London to Edinburgh is 405 miles (652 km), the Dover to Calais crossing is 21 miles (34 km), and the London Marathon covers 26.2 miles (42.2 km). The M25 loops 117 miles (188 km) and the London Underground holds 250 miles (402 km) of track. Nationally there are 50,000 miles of public road and 15,500 miles of railway.` },
  ],
  'area-converter': [
    { question: `How many square metres are in an acre?`, answer: `One acre is 4,047 square metres, which is also 4,840 square yards or 0.4047 hectares. Working the other way, one hectare is 10,000 square metres or 2.471 acres, and a square mile is 640 acres or 2.59 km². For a physical sense of the size, a football pitch at 105×68m is about 0.71 hectares, or 1.76 acres. Land Registry documents have used square metres and hectares since the 1980s.` },
    { question: `What does GIA mean in a UK property listing?`, answer: `Gross Internal Area, the RICS measure used for residential listings. It is taken to the internal face of the perimeter walls and includes hallways, but leaves out garages, sheds and any space under eaves below 1.5m. Commercial property is usually quoted as Net Internal Area instead, which also excludes columns and stairs. Knowing which measure you are reading matters, because the same house looks larger or smaller depending on the convention used.` },
    { question: `How big is an average UK house in square metres?`, answer: `A new build averages 76 m², the smallest in Europe, against 113 m² in France and 109 m² in Germany. Across the existing stock, a 1-bed flat is typically 40-50 m², or 430-540 sq ft, a 2-bed flat 55-70 m², a 3-bed semi 80-100 m² and a 4-bed detached 120-160 m². Plots are tight as well, averaging about 200 m², with new estate plots at 75-150 m².` },
    { question: `Does a bigger house always mean a higher Council Tax band?`, answer: `Not directly. Bands were set on 1991 capital values rather than on floor area, although size and band do correlate. Band A usually covers homes under 50 m², Band D sits around 75-110 m², and Band H starts near 200 m², with big regional differences behind those numbers. An extension does not trigger a rebanding while you live there, but the next buyer may be moved up. Wales rebanded in 2003, with another revaluation planned for 2028.` },
  ],
  'cooking-converter': [
    { question: `How many grams is a cup of flour?`, answer: `About 125 g of plain flour in a US cup of 237 ml. Other ingredients fill that same cup very differently, with granulated sugar at 200g, packed brown sugar 213g, butter 227g, rice 200g, oats 95g, cocoa powder 80g, milk 244g, honey 340g and oil 218g. Flour is also the least consistent of them, because scooping instead of spooning changes the weight by 20-30%. Weighing in grams removes the guesswork, which is why UK recipes work that way.` },
    { question: `What is Gas Mark 4 in a fan oven?`, answer: `Gas Mark 4 is 180°C conventional, and a fan oven runs 20°C hotter at the same dial setting, so set it to 160°C. The ladder starts at Gas Mark 1 for 140°C and climbs through 150°C, 160°C, 180°C, 190°C, 200°C, 220°C and 230°C to 240°C at Gas 9, with the fan figure 20°C below each. Allow 10-15 minutes for preheating, and bear in mind that most domestic ovens read 10-20°C away from the dial.` },
    { question: `Is a UK tablespoon the same as a US tablespoon?`, answer: `Not quite. A US tablespoon is 14.79 ml, close enough to 15 ml for most cooking, while the official UK tablespoon is 17.7 ml. Cups differ more sharply, at 237 ml in the US against 284 ml for the old UK cup. Fluid ounces split the same way, 28.41 ml in the UK and 29.57 ml in the US, and a UK pint is 568 ml against a US pint of 473 ml. Across a long recipe those differences add up.` },
    { question: `What is the difference between single, whipping and double cream?`, answer: `Fat content, and it decides what the cream can do. Double cream is 48% fat, whipping cream 36% and single cream 18%, which is why single cream will not hold air and cannot be whipped. American recipes use different names for much the same products, with heavy cream matching UK whipping cream and light cream matching single. If a recipe needs volume from whipped cream, reach for double or whipping rather than single.` },
  ],
  'timezone-converter': [
    { question: `When do the clocks change in the UK in 2026?`, answer: `BST starts on 29 March 2026 and ends on 25 October 2026. The rule behind those dates is fixed rather than announced each year, with clocks going forward one hour at 1am on the last Sunday in March and back at 2am on the last Sunday in October. In winter the UK is on GMT at UTC+0 and in summer on BST at UTC+1. Northern Ireland follows the rest of the UK, and the Republic of Ireland changes at the same moment under the name Irish Summer Time.` },
    { question: `How many hours behind the UK is New York?`, answer: `Five hours through the UK winter, when New York sits at UTC−5. The gap normally holds at five hours in summer too, because both countries shift their clocks, although the American and British changeover dates do not coincide exactly. At 14:00 BST in London it is 09:00 EDT in New York, on UTC−4. For two offices keeping a nine to five day, the shared window is 14:00–17:00 UK time, or 09:00–12:00 in New York.` },
    { question: `What is the best time to call Australia from the UK?`, answer: `Early morning. Sydney runs 9-11 hours ahead of the UK, depending on where both countries sit in their daylight saving cycles, and the widest gap falls between November and April, when the UK is on GMT and Australia on AEDT. The practical overlap is UK 6-9am against Sydney 5-8pm. Outside that window, most UK and Australian teams work by email and messaging instead. AEST is UTC+10 and AEDT UTC+11, so check which applies before fixing a time.` },
    { question: `Will the UK stop changing the clocks twice a year?`, answer: `Not soon. The EU voted in 2019 to abolish the seasonal change from 2021, but member states never agreed which time to keep and the plan stalled. The UK left the EU in 2020 and decides the question for itself, and a government consultation in 2023 found 64% in favour of keeping the changes. Northern Ireland adds a complication, since abolishing daylight saving on one side of the Irish border would open a time gap on the island. No bill is before Parliament.` },
  ],
  'ilr-calculator': [
    { question: `When can I apply for Indefinite Leave to Remain?`, answer: `Most routes let you apply after five years of continuous lawful residence, though some such as the partner route have their own path, and you also need the Life in the UK test and English at B1 level or above, rising to B2 for settlement applications made on or after 26 March 2027. Anyone settling from the Spouse or Family route must additionally meet that route's income requirement, which is £29,000 for partners first granted on or after 11 April 2024.` },
    { question: `How many days can I spend outside the UK before ILR?`, answer: `No more than 180 days in any 12-month period. Since April 2024 the limit has been applied on a rolling basis rather than to fixed years, so trips sitting either side of a visa anniversary can still break the chain. The long residence route now uses the same 180-day rule, with the old 548-day total and 184-day single absence kept only for absences that began before 11 April 2024. Keep a travel record as you go, because reconstructing five years of dates from old boarding passes is the part most applicants dread.` },
    { question: `Can I get ILR after 10 years on different visas?`, answer: `Yes, through the long residence route. Ten continuous years of lawful residence qualifies you however many visa types you have held, provided you had valid leave throughout, since any gap breaks the chain and sinks the application. Absences are limited to 180 days in any 12-month period. It tends to suit people whose history fits none of the 5-year categories, and the application goes in on form SET(LR).` },
    { question: `How much does an ILR application cost?`, answer: `£3,226 per person from 8 April 2026, with no health surcharge on the ILR application itself, although you keep paying the surcharge on any extension needed before you qualify. Add £50 for the Life in the UK test and from £160 for an English test if you are not exempt, giving roughly £3,436 at the point of application. Priority processing costs £500 for a decision usually within 5 working days and super priority £1,000 for a decision by the end of the next working day, against up to 6 months on the standard service.` },
    { question: `What is in the Life in the UK test?`, answer: `Twenty-four multiple choice questions on British history, society, government and culture, sat over 45 minutes at an approved test centre. The pass mark is 75%, which means 18 correct answers, and the fee is £50 with no limit on retakes. Study from the official handbook, Life in the United Kingdom: A Guide for New Residents. A single pass covers both ILR and a later citizenship application.` },
  ],
  'steps-to-miles-calculator': [
    { question: `Roughly how far do my daily steps actually take me?`, answer: `Stride length drives it, roughly 0.71 m for women and 0.76 m for men, or about 41 to 45% of your height, so taller people cover a mile in fewer steps. Multiply your step count by your stride in metres and divide by 1609 for the answer in miles.` },
    { question: `How many steps make up a mile of walking?`, answer: `Around 2,100 for men and 2,440 for women, or roughly 1,300 and 1,520 steps per kilometre. Your own figure depends mostly on height, so multiply your height in centimetres by 0.415 for an estimate of step length. Someone of 1.75 m takes steps of about 73 cm and covers a mile in roughly 2,200 of them. Stride length, measured from one left heel strike to the next, is twice your step length, which is why the two often get muddled.` },
    { question: `Do I really need 10,000 steps a day?`, answer: `The figure came from a Japanese marketing campaign in 1965 rather than from research. Later work puts most of the mortality benefit at 7,000 to 8,000 steps a day, with the curve flattening somewhere around 10,000 to 12,000. Anyone over 60 gets most of the gain at 6,000 to 8,000. Intensity counts for more than the raw total, so aim for 30 minutes or more of moderate walking at roughly 100 steps a minute. The NHS target of 150 minutes a week comes to about 21,000 steps spread across the week.` },
    { question: `Is walking as good as running for cardiovascular fitness?`, answer: `Both work for the heart. Running packs the same benefit into less time, at the cost of joint loading of roughly 2.5 times body weight against about 1.3 times for walking. Brisk walking at 5 to 6 km/h lifts your heart rate enough for an aerobic effect, while a leisurely 3 to 4 km/h counts as general activity rather than training. Mixing the two suits most people: three or four brisk walks with one or two runs a week, or interval walks alternating three minutes brisk with one minute of recovery.` },
  ],
  'heart-rate-zone-calculator': [
    { question: `Zone 1 to Zone 5, what do the training zones mean?`, answer: `Each zone is a percentage of your maximum heart rate, roughly 220 minus your age. Zone 1 at 50 to 60% is warm-up, Zone 2 at 60 to 70% is the fat-burning band, Zone 3 at 70 to 80% is aerobic, Zone 4 at 80 to 90% is threshold and Zone 5 at 90 to 100% is VO2 max work. The Karvonen method narrows those bands to you by working from your heart rate reserve instead.` },
    { question: `How accurate is 220 minus age for maximum heart rate?`, answer: `It is a population average rather than a personal measurement. Very fit people often run 5 to 10 bpm above it, and some genetic variants sit 10 to 20 bpm either side. Tanaka's formula, 208 minus 0.7 times your age, tends to be closer: at 30 it gives 187 bpm where 220 minus age gives 190. The accurate option is a graded exercise test with breath gas analysis, around £100 to £300 privately, and the free approximation is a thoroughly warmed-up all-out sprint recorded on a chest strap.` },
    { question: `What is the fat burning zone and does it help weight loss?`, answer: `Zone 2, at 60 to 70% of maximum, burns the highest proportion of its calories from fat. Total burn is what moves the scale, though, and Zone 2 delivers less of it than Zones 3 and 4. A 30 minute Zone 2 walk burns about 150 calories, roughly 70% of them from fat, while 30 minutes of Zone 4 intervals burns about 350 calories with about 40% from fat, so the harder session burns more fat outright. Keeping most sessions in Zone 2 with one or two in Zone 4 each week is the usual balance.` },
    { question: `Do I need a heart rate monitor to train by zones?`, answer: `For marathon preparation, cycling or triathlon it earns its place. Chest straps such as the Polar H10 or Garmin HRM-Pro read within 1 to 2 bpm of a medical-grade ECG. Optical wrist sensors on an Apple Watch, Garmin or Fitbit handle steady efforts well but lag or miss beats during intervals and weight training. For general fitness, rating your perceived exertion from 1 to 10 is enough, and it trains a feel for pace that a screen never quite teaches.` },
  ],
  'probability-calculator': [
    { question: `Can I work out combinations and permutations with this?`, answer: `Yes. Alongside simple and conditional probability, it handles compound AND/OR events and works out both permutations (nPr), where the order of a selection matters, and combinations (nCr), where it does not. A lottery draw is a combination, because the balls count the same in any order. Both are computed from the factorial formula and shown as whole numbers, so 59 choose 6 gives the 45,057,474 possible Lotto tickets.` },
    { question: `What are the odds of winning the UK Lotto jackpot?`, answer: `Matching all 6 numbers drawn from 59 comes out at 1 in 45,057,474. Winning any prize at all is far more likely, at 1 in 9.3. EuroMillions asks for 5 numbers from 50 plus 2 from 12, which puts its jackpot at 1 in 139,838,160, while the Set for Life top prize sits at 1 in 15,339,390. Premium Bonds give each bond a 1 in 60 billion chance of the £1M prize each month.` },
    { question: `Why does a room of 23 people so often share a birthday?`, answer: `Because the count that matters is pairs rather than people. Twenty-three people form 253 possible pairs, and the chance that at least one pair matches works out at 50.7%. With 50 people it rises to 97%, and with 70 to 99.9%. A UK school class of 30 has a 70.6% chance. The figure does not apply to one specific date, such as your own birthday, where the odds are far longer.` },
    { question: `Does a run of five heads make tails more likely next?`, answer: `No. Successive coin flips are independent, so the coin carries no memory of what came before and the next flip is still 50%. That misreading is the gambler's fallacy, and it applies equally to dice and to roulette. Probabilities only combine when events happen together, which is why two flips both landing heads works out at ¼ and three dice all showing 6 at 1/216.` },
  ],
  'annual-tax-summary-calculator': [
    { question: `Where does my income tax and National Insurance actually go?`, answer: `HMRC's Annual Tax Summary splits what you paid across areas such as the NHS, welfare, state pensions, education, defence, transport, public order and interest on government debt. For 2026/27 Health takes the largest share at around 20%, with Welfare close behind at around 19% and State Pensions at around 13%. The proportions come from published Treasury data on departmental spending, applied to the income tax and National Insurance you personally paid during the year.` },
    { question: `What is the difference between my effective and marginal tax rate?`, answer: `The effective rate is the total tax and National Insurance you pay divided by your total income, which is the figure to use for budgeting or comparing two jobs. The marginal rate is what the next pound of income costs, and that is the one that matters for pension contributions, salary sacrifice or deciding whether extra hours are worth taking. Someone on £100,000 has an effective rate near 31% but a marginal rate of 40%.` },
    { question: `Why is the tax rate 60% between £100,000 and £125,140?`, answer: `The Personal Allowance is withdrawn once income passes £100,000, at the rate of £1 for every £2 earned above it. Losing tax-free income while also paying 40% on the extra earnings produces an effective marginal rate of 60% on that slice, until the allowance disappears entirely at £125,140 and the 45% additional rate takes over. A pension contribution large enough to bring income back under £100,000 restores the allowance.` },
    { question: `How much tax does someone on £50,000 actually pay?`, answer: `On a £50,000 salary the income tax comes to £7,486 and Class 1 National Insurance to £3,000, so £10,486 leaves your pay across the year. That is an effective rate of 21.0%, because the Personal Allowance covers the first £12,570 and the remainder sits inside the basic rate band. Someone on £30,000 pays £4,881 in total, or 16.3%, and the proportion rises steadily with income.` },
  ],
  'business-rates-calculator': [
    { question: `How are my business rates worked out from the rateable value?`, answer: `Take the rateable value and multiply it by the multiplier for the band the property falls in: 43.2p in the pound below £51,000, 48p from £51,000 to £499,999, and 50.8p at £500,000 or above in 2026/27. That gives the gross bill, and any relief you qualify for comes off afterwards. A rateable value of £20,000 at 43.2p works out at £8,640, which the council will usually collect in 10 instalments.` },
    { question: `What is rateable value and how is it set?`, answer: `Rateable value is the Valuation Office Agency's estimate of the annual rent a property would let for on the open market at a common valuation date, which is 1 April 2024 for the 2026 rating list. The agency weighs size, location, condition and evidence from similar premises nearby. It is not your actual rent, and plenty of businesses pay well above or below their rateable value in practice.` },
    { question: `How do I challenge a rateable value I think is wrong?`, answer: `Use the Check, Challenge, Appeal route. Check confirms the property facts recorded on GOV.UK, including square footage and classification. Challenge is where you put in evidence within 4 months that the valuation is incorrect, typically rents from comparable properties or a mistake in how the premises are described. Appeal takes the matter to the Valuation Tribunal if the Challenge fails. About 30% of Challenges succeed, and a refund can reach back up to 6 years.` },
    { question: `Do I pay business rates if I work from home?`, answer: `Usually not, if only a small part of the house is used for occasional work and customers never visit. The Valuation Office Agency may rate part of a home separately where you have employees working there, see customers regularly, have made structural alterations for the business, or use a significant portion of the property exclusively for work. For the great majority of self-employed people and home offices, the property stays entirely domestic.` },
  ],
  'rd-tax-credit-calculator': [
    { question: `What rate of R&D relief can my company claim under the merged scheme?`, answer: `The merged scheme, running since 1 April 2024, gives a taxable above the line credit of 20% of eligible R&D expenditure. Eligible spending covers staff, software, consumables, subcontracted R&D and externally provided workers, the last two counted at 65% of cost, less any grant or subsidised income tied to the project. After the tax charged on the credit itself, the benefit generally works out between 14% and 16.2% of what you spent.` },
    { question: `Who qualifies for R&D tax credits?`, answer: `Only UK limited companies can claim, so sole traders and partnerships are outside the scheme whatever work they do. The project must seek an advance in science or technology by resolving scientific or technological uncertainty, which means genuine technical risk rather than routine improvement. Software work such as new algorithms, machine learning and novel architectures can qualify, and so can biotech, manufacturing process improvement, materials science, AgTech and renewables.` },
    { question: `Is there a cap on a loss making company's payable credit?`, answer: `Payable credits are limited by a PAYE and NI cap of £20,000 plus 3 times the company's total PAYE and NI for the claim period. Companies whose qualifying R&D is 30% or more of total expenditure can surrender losses under Enhanced R&D Intensive Support at 27%, and that is where cash matters most, because a pre revenue business has no Corporation Tax bill for the credit to reduce.` },
    { question: `Does HMRC need telling before I put a claim in?`, answer: `In two situations, yes. Where the company has not claimed in the previous three years, HMRC needs a pre-notification. Separately, an Additional Information Form has to reach gov.uk ahead of the Corporation Tax return, a requirement since August 2023. Both steps are mandatory, so they belong in the year end timetable alongside the technical narrative, the cost breakdown by category and the endorsement from a named senior officer.` },
  ],
  'cis-calculator': [
    { question: `Are materials included when CIS tax is deducted from my invoice?`, answer: `No. The deduction applies to the labour element only, at the standard 20% rate, and the contractor passes that money to HMRC on your behalf. Materials you have bought stay outside it provided you can evidence them with supplier invoices, so itemise them separately. VAT, plant and equipment hire and professional fees such as architects and surveyors are also excluded, as is travel and lodging unless the contract makes it part of the work.` },
    { question: `Who needs to register for CIS?`, answer: `Contractors must register, meaning any business that pays others for construction work, plus any business spending more than £3m on construction over 12 months even where construction is not its trade. Subcontractors should register too, because registration is the difference between a 20% deduction and the 30% rate applied to anyone HMRC cannot verify. Many building firms end up registered in both capacities, paying subcontractors while being paid as one.` },
    { question: `What is gross payment status and how do I get it?`, answer: `Gross payment status means contractors pay you in full with nothing withheld, and you settle the tax yourself through Self Assessment or Corporation Tax. HMRC weighs three things before granting it. Turnover has to reach £30,000 a year for a sole trader or £100,000 for a partnership or limited company, returns and payments must have been on time for 12 months or more, and the business test asks whether you are genuinely independent. Compliance failures see the status withdrawn.` },
    { question: `When are monthly CIS returns due and what happens if they are late?`, answer: `Contractors file a return for every month, due by the 19th of the following month, listing all payments made to subcontractors and the tax deducted from each. Every subcontractor should also receive a payment and deduction statement each month, which is the document they use later to reclaim. A late return costs £100 straight away, a further £200 at 2 months late, and at 6 and 12 months the greater of £300 or 5% of the deductions on it, so the filing date tends to drive the payment run rather than the other way round.` },
  ],
  'pet-insurance-calculator': [
    { question: `Which type of pet insurance policy gives the most cover?`, answer: `Lifetime cover is the fullest of the four policy types, renewing its benefit limit every year, while accident-only sits at the cheaper end and pays out for injuries alone. In between are time-limited policies, where each condition is covered for 12 months, and maximum benefit policies, where each condition is covered up to a fixed sum with no time limit. For a dog, expect roughly £40-£80 a month for lifetime cover against £10-£20 for accident only.` },
    { question: `Are pre-existing conditions ever covered by pet insurance?`, answer: `No. Anything diagnosed or already showing symptoms before the policy started is excluded, and that exclusion does not expire. It also catches conditions that began under an annual policy, because once the 12 months or the £3-£10k limit is used up the condition becomes pre-existing for any new insurer. This is the single strongest argument for taking out lifetime cover while a pet is young and healthy rather than waiting for the first symptom to appear.` },
    { question: `Why does pet insurance get so expensive for older animals?`, answer: `Claims frequency rises steeply with age, so premiums that started at £200-£400 a year for a dog or £150-£300 for a cat can double or triple once the animal is past 8. Many insurers also increase the percentage co-payment on top of the fixed excess for older pets, which shifts more of each bill back to you. Cats commonly need dental work costing £400-£1,500 by the age of 7-10, which is exactly when the cover starts to cost more.` },
    { question: `Would saving up instead of insuring my pet work out cheaper?`, answer: `It can, but the timing has to be kind. Putting £100 a month aside for 5 years builds a fund of £6,000 or more, which comfortably covers the £3,000-£8,000 most pets cost over a lifetime. The problem is a £4,000-£7,000 cruciate ligament operation arriving in year two, before the pot has grown. Around 1 in 4 UK pet-owning households claim, at an average of £800, so the risk is real rather than theoretical.` },
  ],
  'student-maintenance-loan-calculator': [
    { question: `How much maintenance loan can I get living away from home outside London?`, answer: `For 2026/27 the maximum is £10,830 if you live away from home outside London, against £14,135 in London and £9,118 living with your parents. The amount tapers with household income down to a basic rate of £5,048, £7,039 and £4,013 respectively, which is paid however much the household earns. At a household income of £45,000 you would be on £7,739 outside London, £10,991 in London and £6,060 at home. Final-year students receive slightly less.` },
    { question: `At what household income does the maintenance loan stop reducing?`, answer: `The taper bottoms out once the basic rate is reached, and from that point the award no longer moves. That happens at a household income of £58,347 if you live at home, £62,410 living away from home outside London and £70,131 in London. Below £25,000 the full loan is paid. Between those two points the award drops by £1 for every £6.36 to £6.54 of household income, depending on where you live during term.` },
    { question: `When do I start repaying my maintenance loan?`, answer: `Repayments begin once you earn above £25,000 a year on Plan 5, and they take 9% of the amount over that threshold. A £35,000 salary produces £900 a year, or £75 a month, while £45,000 produces £1,800 a year, or £150 a month. Interest runs at RPI with nothing added, the term is 40 years and any remaining balance is written off at the end, although most Plan 5 borrowers are expected to clear theirs.` },
    { question: `Is it worth making voluntary student loan repayments?`, answer: `Usually not. If your balance is heading for write-off after 30 or 40 years, an extra payment cuts the amount eventually written off rather than the amount you pay over your lifetime. The exception is high earners, roughly £75k and above on Plan 5 or £80k and above on Plan 2, who will clear the loan regardless. Most graduates do better putting the same money into a pension for the tax relief, an ISA, or a mortgage deposit.` },
  ],
  'boiler-replacement-calculator': [
    { question: `Is it worth replacing a 15-year-old gas boiler?`, answer: `Once a gas boiler passes 10 to 15 years old, swapping it for a modern condensing model or a heat pump can cut your energy bills noticeably. A new A-rated condensing boiler runs at 90 to 94% efficiency against 60 to 80% for many older units, and costs roughly £2,000 to £4,000 fitted.` },
    { question: `How much is the Boiler Upgrade Scheme grant worth?`, answer: `The scheme pays £7,500 towards an air source or ground source heat pump, up from £5,000 in October 2023, plus £1,500 more until March 2027 for homes heated by oil or LPG with no mains gas. It also pays £2,500 for an air-to-air heat pump and £5,000 for a biomass boiler in a rural off-grid home, and covers England and Wales only. There is no EPC or insulation requirement: you must own the property, which can be a let, a second home or a business, and be replacing fossil fuel or electric heating. Installation typically costs £8,000 to £14,000 before the grant, so £500 to £6,500 is left to find.` },
    { question: `Should I fit a combi or a system boiler?`, answer: `A combi heats water on demand with no tank and suits one or two bathroom homes and small to medium households, sized at 24 to 40 kW. A system boiler stores heated water in a cylinder and gives mains-pressure showers, which matters where two or more bathrooms may run at once, sized at 18 to 30 kW. Heat-only boilers, at 12 to 25 kW, still suit low pressure areas and Victorian conversions.` },
    { question: `How long does a new boiler take to pay for itself?`, answer: `Replacing a 25-year-old boiler cuts 15 to 25% off the heating bill, worth £200 to £500 a year for a typical home. In the worked example, a 20-year-old boiler at 65% efficiency costs £1,130 a year to run, £108 of it the standing charge. A 94% efficient replacement burns 31% less gas, bringing the bill to £815, a saving of £315. Against a combi fitted for £2,800, that is a payback of 8.9 years.` },
    { question: `What are the warning signs that a boiler is failing?`, answer: `Banging, kettling or gurgling usually means scale, limescale or a failing pump. A yellow flame where it should be blue signals incomplete combustion and a carbon monoxide risk, so stop and call an engineer. Two or more breakdowns in a year, or bills climbing while usage stays flat, both point to replacement. Water on the floor under the boiler is close to decisive. Cold radiator tops with hot bottoms is more often trapped air or sludge.` },
  ],
  'double-glazing-calculator': [
    { question: `Does upgrading to double glazing make a real difference to heat loss?`, answer: `A single-glazed window has a U-value of around 5.0 W/m2K, whereas standard double glazing brings that down to 1.4 and triple glazing to 0.8, so far less heat escapes. The gain comes from two sealed panes separated by an insulating gap, typically 16mm of argon gas.` },
    { question: `What does double glazing cost for a three-bed semi?`, answer: `A 3-bed semi with 10 windows comes to £4,000 to £8,000 for full uPVC double glazing. Frame material drives most of the difference, with uPVC at £300 to £600 per window, timber at £400 to £800 and aluminium at £500 to £900. Premium aluminium across the house reaches £6,000 to £12,000 and timber-look composite £8,000 to £18,000, so gather 3 or more quotes.` },
    { question: `How long does double glazing take to pay for itself?`, answer: `The Energy Saving Trust puts the saving from replacing single glazing at £100 to £200 a year, which gives a payback of 20 to 40 years on energy alone. Ten uPVC windows at £550 each cost £5,500 and save £150 a year, or 36.7 years. Most owners justify the spend on the noise reduction of 35 to 50% with acoustic glass, better security and a value uplift of £2,000 to £5,000.` },
    { question: `Can I fit double glazing in a listed building?`, answer: `Not the standard uPVC kind. Grade I, II* and II buildings need listed building consent, which is free, handled by the council and takes 8 to 12 weeks. The accepted routes are timber sash windows with slim-profile double glazing at roughly £1,500 to £3,000 a window, or secondary glazing at £600 to £1,500. Conservation areas need planning permission for front-facing windows, and an Article 4 direction can restrict them all.` },
    { question: `Why must my installer be FENSA or CERTASS registered?`, answer: `Since 2002 replacement windows in homes have had to meet Building Regulations, and only a member of FENSA, CERTASS or another DCLG-approved Competent Person Scheme can self-certify that the work complies. Registration also carries a 10-year insurance-backed guarantee, with the cost already inside the installation price. Skipping it leaves a breach on record that causes trouble when you sell or remortgage.` },
  ],
  'weight-loss-calculator': [
    { question: `What is a safe rate of weight loss?`, answer: `The NHS puts it at 0.5 to 1 kg a week, or 1 to 2 lb, produced by a deficit of 500 to 1,000 kcal a day below your total daily energy expenditure. Anything faster, held for long, tends to cost muscle. Very low calorie diets under 800 kcal belong under medical supervision only, as with the NHS soups and shakes programme for type 2 diabetes. Across a year, 5 to 15 kg is the range most people manage to keep off.` },
    { question: `Why has my weight loss plateaued?`, answer: `Adaptation is the usual culprit. After four to eight weeks in deficit the body lowers its resting rate, non-exercise activity drops by 200 to 400 kcal a day, and any muscle lost pulls the figure down further. What tends to restart progress is a two-week diet break at maintenance every eight to twelve weeks, more daily walking towards 8,000 to 10,000 steps, strength training to hold on to muscle, and honest tracking with scales, since underestimating intake by 20 to 30% is common. Sleeping seven to nine hours helps as well.` },
    { question: `Do calories or macros matter more for fat loss?`, answer: `Calories decide whether you lose weight and macros decide what you lose. A deficit built on 1.6 to 2.2 g of protein per kg of bodyweight preserves muscle, so more of the loss is fat, whereas under 0.8 g/kg can see 30 to 50% of the weight come off as muscle. Carbohydrate and fat are far more flexible and are best set around what you actually enjoy eating, because adherence beats theory. A Mediterranean pattern of whole foods, plenty of vegetables, lean protein and healthy fats holds up well over years.` },
    { question: `Should I consider weight loss medication such as Mounjaro?`, answer: `GLP-1 medicines including Mounjaro, Wegovy and Ozempic are available on the NHS in defined circumstances, broadly a BMI of 35 or above with a weight-related condition, or 30 or above through a weight management service. Privately they cost £150 to £350 a month for branded versions, with cheaper generic semaglutide expected to reach the market in 2026. Average loss is 15 to 20% of body weight. Nausea affects about 60% of users and muscle loss is a risk without exercise, and weight usually returns once people stop, so talk to your GP first.` },
  ],
  'protein-intake-calculator': [
    { question: `Do I need more protein if I lift weights?`, answer: `Sedentary adults are advised to get the UK Reference Nutrient Intake of 0.75 g of protein per kilogram of body weight a day. If you train hard or lift weights, aim higher, around 1.2 to 2.0 g/kg, to support muscle repair and growth. At 70 kg that is the difference between 52.5 g a day and a target well above 100 g, which in practice means building every meal around a protein source rather than hoping to top up later.` },
    { question: `Can you eat too much protein in a day?`, answer: `Beyond about 3.5 g per kg of bodyweight there is no additional muscle benefit, and very high intakes may add strain for anyone with existing kidney disease. For everyone else the real limits are appetite and cost rather than safety. Most people do better aiming at 1.6 to 2.2 g/kg for muscle building, or 1.0 to 1.2 g/kg in later life, then putting the effort into hitting that figure on most days rather than overshooting it on a few.` },
    { question: `Are plant proteins as good as animal proteins?`, answer: `Gram for gram they can be, as long as you vary the sources. Animal proteins are complete, with all nine essential amino acids in good ratios, whereas plant proteins are usually limited in one or two, since grains are low in lysine and legumes low in methionine. Pairing them, as in rice with beans or a lentil curry with roti, gives the full profile. Soya foods such as tofu and tempeh, plus seitan, lentils, chickpeas, hemp seeds, quinoa and peanuts, are the strongest options. Aim for 25 to 30 g at a meal.` },
    { question: `Does it matter when I eat my protein?`, answer: `Less than most people assume. The daily total does the bulk of the work, and the anabolic window of 30 minutes after training is largely a myth, because protein synthesis stays raised for 24 to 48 hours after resistance work. Spreading intake across three to five meals of 25 to 40 g each does beat one or two large servings. A slow-release protein before bed, casein or Greek yoghurt, helps overnight recovery for anyone training seriously.` },
  ],
  'ovulation-calculator': [
    { question: `How long does the fertile window last in each cycle?`, answer: `The fertile window runs for roughly six days: the five days before ovulation, since sperm can survive that long, plus ovulation day itself when the egg lasts 12 to 24 hours. Ovulation usually falls 12 to 16 days before your next period, about day 14 in a 28-day cycle.` },
    { question: `How do I know when I have actually ovulated?`, answer: `The clearest confirmation arrives after the event. Basal body temperature rises by 0.2 to 0.5°C once ovulation has happened, so a temperature chart tells you where you have been rather than where you are going. Ovulation predictor kits work the other way round, picking up the LH surge 24 to 36 hours ahead, with 10 to 20 tests costing £8 to £25. Cervical mucus turning clear, slippery and stretchy is the most reliable sign you can read without buying anything.` },
    { question: `Which days should we time sex for when trying to conceive?`, answer: `The two or three days before ovulation, plus ovulation day itself, carry the best odds, which in a 28-day cycle means days 11 to 14. Sex every one or two days across the fertile window covers those days while leaving time for sperm to recover. No position has been shown to help. Many standard lubricants are spermicidal, so if you use one, pick a sperm-friendly product such as Pre-Seed or Conceive Plus.` },
    { question: `When should we see a GP about not conceiving?`, answer: `The NHS suggests speaking to your GP after 12 months of trying, or 6 months if you are over 35. First-line tests are a semen analysis, blood tests and an ultrasound scan, with referral to a fertility clinic if there is no pregnancy after 18 to 24 months. Around 1 in 7 UK couples run into difficulty, and male factor problems account for 30 to 40% of cases, which is why both partners are assessed rather than one.` },
  ],
  'car-lease-vs-buy-calculator': [
    { question: `What happens if I go over the mileage limit on a car lease?`, answer: `Personal Contract Hire deals set an annual mileage cap, usually between 8,000 and 15,000 miles, and exceeding it costs 5 to 15p per mile at the end of the contract, so being 10,000 miles over on a three-year deal can mean £800 or more. Caps are sold in steps from 5k up to 20k a year, and choosing a realistic one at the outset is cheaper than paying the excess later.` },
    { question: `At what point does buying become cheaper than leasing?`, answer: `Usually around the four to five year mark. Up to that point you are paying for the steepest part of the depreciation curve either way, and the lease has the advantage of predictable costs and often bundled servicing. Keep the car beyond five years and the annual loss in value shrinks while a lease keeps charging the same monthly figure, so long-term owners come out ahead and people who change cars every three years do not.` },
    { question: `How is PCP different from leasing a car?`, answer: `Personal Contract Purchase sits between hiring and buying: you make monthly payments and then face a balloon payment at the end, which you can pay to keep the car or decline and hand it back. Personal Contract Hire has no such option, since the car always returns to the lessor. PCP monthly payments are typically higher than an equivalent lease, and the depreciation risk sits differently because you hold the option to buy.` },
    { question: `How much does EV salary sacrifice save a higher-rate taxpayer?`, answer: `Roughly a third of the monthly cost. A £600 a month electric car sacrifice comes out of gross pay, so a higher-rate taxpayer saves 40% tax plus 2% NI and take-home pay falls by £348. Benefit in kind tax claws some back: at 4% in 2026/27 on a £40,000 car it is about £53 a month, leaving a net cost near £401. A basic-rate taxpayer pays about £459 (£432 plus £27 BiK tax). The BiK rate rises to 5% in 2027/28 and 7% in 2028/29. Your employer has to run a scheme for you to use it.` },
    { question: `What can I be charged for when I hand a lease car back?`, answer: `Two things mainly: excess mileage at 5 to 15p a mile above your agreed cap, and damage beyond the fair wear and tear standard. The handback inspection prices chips, scratches and dents individually at £50 to £500 or more each, which is why cars kept on the street tend to cost more at the end than those on a driveway. Servicing and tyres are covered only if you took the maintenance package at £20 to £50 a month.` },
  ],
  'sole-trader-vs-ltd-calculator': [
    { question: `Which taxes come out of a sole trader's profits?`, answer: `Income Tax applies to the profit itself at 20%, 40% and 45%, with Class 4 National Insurance at 6% and then 2% on the top slice. Class 2 was abolished in April 2024, so there is no longer a flat weekly charge on the side. Everything is reported on one Self Assessment return, and because you and the business are the same legal person, personal assets stand behind business debts.` },
    { question: `Does a limited company still save tax at higher profits?`, answer: `Not on 2026/27 rates, at least for an owner who draws everything out each year. At £100,000 of profit the company route costs £35,990 against £30,689 for the sole trader, a difference of £5,302, because dividends above the basic rate band are taxed at 35.75% and Corporation Tax carries a 26.5% marginal rate between £50,000 and £250,000. The case for incorporating now rests on limited liability, pension contributions and share flexibility rather than a smaller bill.` },
    { question: `What does running a limited company cost each year?`, answer: `A company needs annual accounts, a CT600, a Confirmation Statement and payroll, plus a separate Self Assessment for the director, and the accountancy for all of that typically runs £1,000 to £1,800 a year. Professional indemnity insurance adds £200 to £500 a year, and a business bank account £5 to £15 a month. A sole trader pays nothing to start, spends about £100 to £500 on accountancy and files one Self Assessment by 31 January.` },
    { question: `What salary should a company director take before dividends?`, answer: `With the Employment Allowance available, £12,570 is the usual figure. It sits within the Personal Allowance so no Income Tax arises, stays inside the primary threshold so no employee NI is due, and the salary is deductible, saving the company £3,142.50 of Corporation Tax at 25%. Dividends follow, the first £500 tax free and the rest at 10.75%, 35.75% or 39.35% depending on the band. A sole director without the allowance usually sets salary at the £5,000 Secondary Threshold instead.` },
  ],
  'pension-credit-calculator': [
    { question: `Who qualifies for the Guarantee Credit part of Pension Credit?`, answer: `Guarantee Credit tops your weekly income up to a set minimum, £238.00 for a single person or £363.25 for a couple in 2026/27. If your assessed income from the State Pension, private pensions, earnings and most benefits falls short of that figure, the gap is paid to you as Guarantee Credit. You also need to have reached State Pension age, which is rising from 66 to 67 between 2026 and 2028 for people born on or after 6 April 1960.` },
    { question: `How do my savings affect a Pension Credit award?`, answer: `Savings are treated far more kindly than under working-age benefits. The first £10,000 of capital is ignored altogether, and every £500 above that, or part of £500, counts as £1 a week of deemed income, however much you hold. Nothing disqualifies you outright, because Pension Credit has no upper capital limit. Someone holding £18,000 in savings has £16 a week added to their assessed income rather than losing the claim. Money in an ISA counts as capital in the same way, and the interest it earns is not treated as income.` },
    { question: `Is it worth claiming Pension Credit if the award is tiny?`, answer: `Yes, because the cash award is only part of what a claim brings. An entitlement of even £1 a week opens the door to a free TV licence for the over-75s, Council Tax Reduction, Housing Benefit, Cold Weather Payments, the Warm Home Discount, free NHS prescriptions and dental treatment, glasses vouchers and the £10 Christmas Bonus. Those linked benefits are typically worth £4,000-£8,000 a year, far more than a small weekly top-up on its own.` },
    { question: `How do I apply for Pension Credit and can it be backdated?`, answer: `Claim online at gov.uk/pension-credit or by phone on 0800 99 1234. You will need your National Insurance number, bank details, a breakdown of your income and savings, your housing costs and your partner's details. The form is long, around 60 pages, though help is available to complete it. Claims can be backdated by three months, so apply as soon as you think you qualify. A decision normally takes 4-6 weeks, after which payment reaches your bank weekly or every 4 weeks, free of tax.` },
  ],
  'housing-benefit-calculator': [
    { question: `Can I claim Housing Benefit if I have savings?`, answer: `Savings above £16,000 usually rule you out of Housing Benefit, and anything between £6,000 and £16,000 counts as £1 a week of tariff income for every £250 held. What you receive also rests on your eligible rent, household size and income, and the benefit is only for people who have not yet moved onto Universal Credit.` },
    { question: `Who can still make a new Housing Benefit claim?`, answer: `New claims are only accepted from people who have reached State Pension age or who live in supported or specified accommodation, along with those in temporary accommodation. Everyone else of working age is now on the Universal Credit housing element instead, which applies broadly similar rules but pays as part of the single monthly UC award rather than as a separate benefit.` },
    { question: `How does the Local Housing Allowance rate cap my rent?`, answer: `For private tenants the maximum award is capped at the Local Housing Allowance rate for the area and the size of property the household is entitled to. Rates are set at the 30th percentile of local rents, so they vary sharply by postcode, and a 2-bedroom home in London zone 2 sits at roughly £350-£450 a week for 2026/27. Rent below the LHA figure can be met in full, while rent above it leaves the tenant paying the difference.` },
    { question: `How much does the bedroom tax reduce my Housing Benefit?`, answer: `The under-occupancy penalty cuts the award by 14% where there is one spare bedroom and 25% where there are two or more. It only applies to working-age tenants in social housing, so pensioners and private renters are unaffected. Exemptions cover a disabled person who needs their own bedroom, approved foster carers, children of armed forces personnel who are temporarily away, and same-sex children under 16 who could reasonably share a room.` },
    { question: `Can a Discretionary Housing Payment cover my rent shortfall?`, answer: `A Discretionary Housing Payment is a top-up your council can award when Housing Benefit does not cover the rent. Applications go directly to the local authority and commonly cite a bedroom tax shortfall, an LHA shortfall, rent arrears, moving costs or a deposit. Awards are entirely at the council's discretion, succeed in roughly 40-60% of cases, and normally run for 3-6 months before they need renewing.` },
  ],
  'vat-threshold-calculator': [
    { question: `When does my turnover force me to register for VAT?`, answer: `Once taxable turnover for the last 12 months goes over £90,000. You then have 30 days from the end of the month in which you went over to register, and registration takes effect from the first day of the second month after you went over: go over on 15 July, register by 30 August, and VAT applies from 1 September. Registering online through gov.uk/register-for-vat usually produces a VAT number within about 10 days. From the effective date you charge VAT on standard-rated supplies and file returns, normally quarterly, under Making Tax Digital.` },
    { question: `Do I have to register before I even reach £90,000?`, answer: `Sometimes. If you expect taxable sales in the next 30 days alone to exceed £90,000, registration is required straight away, regardless of what the trailing 12 months show. Winning a £100k contract in early April is the classic case, since you register before the work begins even though the rolling total sits at only £70k. Without that rule a single large job would pull a business into VAT partway through a month.` },
    { question: `What is the penalty for registering for VAT late?`, answer: `HMRC charges a failure-to-notify penalty as a percentage of the VAT lost: up to 30% where the failure was not deliberate, 20% to 70% where it was deliberate, and 30% to 100% where it was deliberate and concealed. Telling HMRC yourself, and within 12 months, keeps it at the low end, and a reasonable excuse means no penalty. Worse than the penalty itself is the backdating, because HMRC treats VAT as due from the date registration should have taken effect. Six months late on £20k of sales means about £3,333 of VAT, a sixth of what you were paid, plus interest, and customers rarely agree to pay a charge raised after the event.` },
    { question: `Should I voluntarily register for VAT below £90,000?`, answer: `It depends who buys from you. Where most customers are VAT-registered businesses they reclaim the tax, so charging it costs them nothing while you recover input VAT on your own costs. Sellers of zero-rated goods such as children's clothes, books and most food gain the most, reclaiming input VAT while customers pay 0%. The answer is usually no when your buyers are consumers or unregistered businesses, when your supplies are exempt, or when admin capacity is already stretched.` },
  ],
  'umbrella-company-calculator': [
    { question: `How much will I take home through an umbrella company?`, answer: `On a £500 a day contract for 220 days, about £9,167 a month, the umbrella margin (£92), employer NI (£1,086), Apprenticeship Levy (£38) and a 3% employer pension (£110) leave a gross salary of about £7,841. After a 5% pension sacrifice (£183), income tax (£2,016) and employee NI (£321), you take home about £5,321 a month, 58% of the contract value, with about £294 a month going into your pension. The same work outside IR35 through a limited company, drawing a £12,570 salary and the rest as dividends, might leave about £5,830 a month, so the umbrella route costs roughly £6,000 a year in cash in exchange for much simpler admin.` },
    { question: `How do I choose a good umbrella company?`, answer: `Start with accreditation from the FCSA (Freelancer and Contractor Services Association) or Professional Passport, both of which audit their members. Established names include Giant Pay, Parasol, NumberMill, Brookson and ClearSky. A flat margin of £15 to £30 a week is the norm, and a percentage-of-contract margin costs more on high-value work. Ask whether holiday pay is banked for you to draw when you take leave rather than rolled up, and read the Key Information Document setting out your pay and deductions.` },
    { question: `Can I claim expenses through an umbrella company?`, answer: `Very few of them. Since April 2016 the Supervision, Direction and Control rules have blocked most contractor expenses, so lunch, everyday mileage and travel to your usual client site cannot be deducted from your taxable pay. Genuine client-instructed costs, such as occasional travel to a meeting away from your regular workplace, can still be reimbursed tax free if you keep receipts and declare them through the umbrella. Working outside IR35 through your own limited company, full expenses stay deductible.` },
    { question: `What employment rights do I get through an umbrella company?`, answer: `The umbrella is legally your employer, so you keep full employee rights, including 5.6 weeks of paid holiday a year, Statutory Sick Pay from the first day of sickness at £123.25 a week or 80% of your average weekly earnings if lower, Statutory Maternity Pay, pension auto-enrolment and redundancy pay after 2 years. A limited company contractor has none of that, being a director rather than an employee, and a worker whose status is decided by the client sits somewhere in between. The Employment Rights Act 2025 will also bring umbrella companies under the rules for employment businesses, enforced by the Fair Work Agency, once those provisions are commenced, which the government expects in 2027.` },
  ],
  'plaster-calculator': [
    { question: `How many square metres does a 25kg bag of plaster cover?`, answer: `One 25 kg bag of multi-finish top-coat plaster spreads across roughly 10 to 11 m² at 2 mm thickness. Base coats cover far less because they go on thicker: bonding manages about 3.5 m² per bag at 8 mm, and browning is similar. A full re-plaster on brick needs both a base coat at 8 to 11 mm and a 2 mm finish, so count the bags for each layer separately.` },
    { question: `How many bags of plaster do I need to skim a room?`, answer: `Measure each wall and the ceiling, subtract doors and windows, and divide the net area by the coverage of one bag. A room with 36 m² of wall to skim needs 36 ÷ 10.5 = 3.4 bags of multi-finish, so you would buy 4 bags of 25 kg, plus about 5 litres of PVA to seal the surface first. If the walls are bare brick you also need a base coat at roughly 3.5 m² per bag before the skim goes on.` },
    { question: `How much does a plasterer charge per day in the UK?`, answer: `Plasterers charge £180-£280 a day and get through roughly 20-40 m² of existing wall in a day, or 30-50 m² when fixing and skimming new plasterboard. Priced by area, a skim over existing walls comes to £40-£80/m². For a 4m × 4m room that means £400-£800 fully finished, compared with £80-£120 in materials and 1-2 days of your own time if you skim it yourself.` },
    { question: `How long should new plaster dry before painting?`, answer: `Leave it at least 7 days. Freshly skimmed plaster looks green while it is still wet, so judge by the colour rather than the calendar and wait until that green tint has gone before opening the paint. Earlier in the process, allow 1-2 days between sealing the wall with PVA and applying the plaster, so the seal has dried properly before the skim goes on.` },
    { question: `Can I plaster straight over painted or wallpapered walls?`, answer: `Not without preparation. Wallpaper must be stripped completely, and a steam stripper hires for about £15 a day. Painted or glossy surfaces are low-suction, so they need a coat of PVA diluted 1:4 with water before the plaster will grip, and any cracks or holes should be filled with bonding or filler and sanded smooth first. Bonding plaster is the base coat designed for painted walls, concrete and engineering brick.` },
  ],
  'staircase-calculator': [
    { question: `What are the Building Regulations limits for a domestic staircase?`, answer: `Approved Document K allows a maximum rise of 220 mm per step and asks for a going of at least 220 mm, with the pitch capped at 42°. Flights must be at least 800 mm wide, and some councils want 900 mm. You also need 2.0 m of headroom above the pitch line, a handrail set 900 mm to 1,100 mm high, and no gap anywhere in the balustrade that would let a 100 mm sphere through.` },
    { question: `How many steps do I need for a 2.6 m floor height?`, answer: `Divide 2,600 mm by 13 risers and each step rises 200 mm, comfortably inside the 220 mm limit. Pair that with a 250 mm going and the comfort check comes to 650 mm, sitting in the middle of the 550 to 700 mm band. Thirteen risers give twelve treads, so the horizontal run is 3,000 mm, and the pitch works out at 38.7°, under the 42° ceiling.` },
    { question: `Why does my staircase creak and can it be fixed?`, answer: `Creaking almost always comes from fixings that have worked loose where a tread meets its riser, letting the timber move under your weight. Re-screwing the joint from below usually cures it, and PVA glue run into the joint helps where access is tight. A flight that sags rather than squeaks is a different problem, because that points to something structural, and a stair surveyor charges £80 to £200 to look at it properly.` },
    { question: `What does a new staircase cost to supply and fit?`, answer: `An off-the-shelf softwood flight comes in at £200 to £500, with fitting adding £400 to £800. Oak in the mid-range is £800 to £2,500 supplied and £500 to £1,000 to install, while anything bespoke in hardwood starts around £3,000. Smaller work is far cheaper, with spindles at £15 to £30 each, a newel post at £80 to £200 and stairlift removal at £150 to £300, so a tired balustrade rarely justifies a whole new staircase.` },
  ],
  'exam-score-calculator': [
    { question: `How do I turn my raw exam marks into a percentage and grade?`, answer: `Enter the marks you scored alongside the total marks available and the calculator returns a percentage. In the worked example, 64 out of 90 gives 71.1%. Line that percentage up against the grade boundaries for your qualification to see which grade it falls into. Under the illustrative A-level boundaries used here (A at 70%+, B at 60%+), 71.1% would sit at an A or a B depending on the year's actual boundaries, which the exam boards set after marking.` },
    { question: `What score counts as a pass at GCSE?`, answer: `Grade 4 is the standard pass and Grade 5 the strong pass. As an illustration, Grade 4 is often placed around 40%, but real boundaries are set per paper and change every year, and they can sit much lower on a demanding paper. In the 2025 Maths Higher sample, Grade 4 fell at 75 out of 300, which is just 25%, and Grade 9 at 197 out of 300 (66%). Foundation tier papers are capped at Grade 5.` },
    { question: `How do I work out my grade when papers carry different weightings?`, answer: `Multiply each paper's mark by its weight, add the results together, divide by the sum of the weights and multiply by 100. GCSE Maths papers carry equal 33% weights, so this is close to a simple average, but A-level Chemistry weights Papers 1 and 2 at 37% each and Paper 3 at 26%, so a strong Paper 3 lifts the total less than a strong Paper 1. Where coursework applies, such as the 20% non-exam assessment in English Literature, it enters the sum in the same way.` },
    { question: `Will universities or employers see that I resat an exam?`, answer: `Generally no. Universities record the best grade on your transcript and apply no penalty for resits, and apprenticeship providers and most employers keep no record of how many attempts you made. UCAS applications report your current best predicted or achieved grades. GCSEs can be resat as often as you like with the best grade counting, though November sittings exist only for English and Maths. A-level resits since 2017 mean retaking all the papers, at £40-£80 per subject privately or free through a sixth form.` },
    { question: `How does the calculator handle a pass mark for a professional exam?`, answer: `Switch to the pass/fail option, enter your score and the pass mark, and the calculator tells you whether you passed and by how many marks. Professional qualifications usually work this way, with a single pass mark rather than a ladder of grades. In the example, a 45% pass mark on a 90-mark paper equals 40.5 marks, so a score of 64 clears it by 23.5 marks.` },
  ],
  'roman-numeral-converter': [
    { question: `Why is IV four and not six in Roman numerals?`, answer: `When a smaller symbol sits before a larger one it is subtracted, so IV reads as 5 minus 1, giving four, and IX is nine. Placed the other way round, the values simply add up from left to right. The seven symbols in play are I, V, X, L, C, D and M, and only three subtractive pairings are allowed: I before V or X, X before L or C, and C before D or M.` },
    { question: `What is the largest number Roman numerals can properly show?`, answer: `The converter handles values from 1 to 3,999. Above that there is no standardised form: one convention adds an overline, so V̄ stands for 5,000, while another simply repeats M until the string becomes unwieldy. There is no zero either, because Roman mathematics had no such concept, and standard notation carries no fractions, since Romans counted in unciae, or twelfths.` },
    { question: `How do I write the year 2026 in Roman numerals?`, answer: `2026 is MMXXVI. The quickest method is greedy: take the largest value that fits, subtract it, and repeat. Here that gives 2000 as MM, 20 as XX and 6 as VI. The same routine turns 1492 into MCDXCII, built from 1000 (M), 400 (CD), 90 (XC) and 2 (II). Nearby years follow the same pattern, with MM for 2000 and MMXX for 2020.` },
    { question: `Why do some clock faces show IIII instead of IV?`, answer: `Traditional dials often use IIII rather than IV because the longer block balances the VIII sitting opposite it and the face reads more symmetrically. The rest of the dial runs I, II, III, V, VI, VII, VIII, IX, X, XI and XII as expected. Clock faces remain one of the most visible uses of the numerals in Britain, from Big Ben at Westminster through to classic watchmaking.` },
  ],
  'capital-allowances-calculator': [
    { question: `How much can my business write off when it buys equipment?`, answer: `The Annual Investment Allowance gives 100% relief on the first £1,000,000 of qualifying plant and machinery, and a company buying new main-rate assets can claim Full Expensing at 100% with no cap at all. New special-rate assets, such as long-life assets and integral features, take a 50% First Year Allowance instead, with what remains dropping into the special rate pool for later years. Since 1 January 2026, sole traders, partnerships and buyers of assets for leasing can also claim a 40% First Year Allowance on new main-rate plant beyond the AIA.` },
    { question: `Which assets go into the special rate pool?`, answer: `Integral features, long-life assets and thermal insulation, together with cars emitting more than 50g of carbon dioxide per kilometre. The pool writes down at 6% a year on a reducing balance, so relief arrives slowly next to the 14% main pool. New special-rate assets can take a 50% First Year Allowance in the year of purchase, and only the balance left over enters the pool.` },
    { question: `How are electric and petrol company cars treated?`, answer: `A new zero-emission car carries a 100% first year allowance until 31 March 2027 (5 April 2027 for sole traders and partnerships), so the whole cost comes off profits in the year of purchase, which is what makes an electric car bought through a company unusually efficient. A car emitting up to 50g per kilometre enters the main pool and attracts 14% a year on a reducing balance. Above that level, covering most petrol and diesel cars, the special rate pool applies at 6% and relief takes many years to work through.` },
    { question: `What happens when I sell an asset I claimed on?`, answer: `The disposal is set against the balance of the pool the asset belonged to. Where the disposal value falls short of that balance, the difference is claimed as a balancing allowance and reduces taxable profits. Where it exceeds the balance, the excess becomes a balancing charge and is added to taxable profits instead. Keeping an accurate written-down value for every pool is what makes those figures come out right.` },
  ],
  'cash-flow-calculator': [
    { question: `Why can a profitable business still run out of cash?`, answer: `Profit is worked out on an accounting basis, sales minus costs, regardless of when anyone pays. Cash flow only counts money that has actually arrived or left. A business can show £100k of profit while its customers still owe £150k on 60-day terms, and if a supplier wants £80k next week there is simply nothing in the account to pay them with. Roughly 80% of UK SME bankruptcies trace back to cash flow rather than a lack of profit.` },
    { question: `How do I work out my cash burn rate and runway?`, answer: `The burn rate is your average monthly outflows minus inflows, counted when outflows are the larger figure, so it measures how much cash the business loses each month. Runway is your current bank balance divided by that monthly burn, giving the number of months before the cash runs out at that rate. The calculator shows both when your monthly expenses exceed your income. If the projection shows a negative closing balance, that gap has to be met by an overdraft, a loan or by deferring payments.` },
    { question: `How often should a small business update its cash flow forecast?`, answer: `Weekly at a minimum, and daily if cash is tight. The standard UK SME approach is a 13-week rolling forecast with weekly columns for opening cash, inflows, outflows and closing cash, rolled forward each week and updated with actual figures. Assume customers pay in 60 days even when the invoice says 30, and hold back 5-10% of monthly outflows for surprises. Looking 12 months ahead on top of that helps you see seasonal dips, such as the January slump after Christmas, well before they arrive.` },
    { question: `Why does collecting VAT cause cash flow problems?`, answer: `When a customer settles a VAT-inclusive invoice, the whole amount lands in your account, but the VAT part belongs to HMRC and is paid over with your return, due 1 calendar month and 7 days after the quarter ends. Businesses that treat it as their own cash face a large, lumpy bill after 3 months of collecting. The fix is to pay yourself net of VAT only and to move VAT and Corporation Tax money into a separate bank account that is never touched.` },
  ],
  'spouse-visa-calculator': [
    { question: `Do I earn enough to sponsor a UK spouse visa?`, answer: `You generally need to meet the £29,000 minimum income threshold, though savings can be counted towards it. The route runs in stages, an initial 2 years and 9 months, then a 2.5-year extension, then Indefinite Leave to Remain after 5 years in total, with a separate fee at each stage.` },
    { question: `How can I meet the £29,000 income requirement?`, answer: `Four routes are open to the sponsor. Employment income counts once you have been earning £29,000 or more gross for at least 6 months. Self-employment counts on profit at the same level with additional evidence. Income and savings can be combined, with savings above £16,000 covering the shortfall at £2.50 for every £1. Cash savings alone must reach £88,500. The threshold rose from £18,600 in April 2024; the planned increases to £34,500 and £38,700 were paused, and the Migration Advisory Committee advised against £38,700 in June 2025.` },
    { question: `Does the income requirement rise if we have children?`, answer: `Not for applications made on or after 11 April 2024, where the requirement is £29,000 whatever the number of children. The extra £3,800 for the first child and £2,400 for each further child belongs to the old £18,600 rules, which still apply to partners extending permission first granted before that date. Each child who needs a visa does pay its own application fee and health surcharge, and many children of UK citizens have the right of abode and need no visa at all.` },
    { question: `How long until my partner can apply for British citizenship?`, answer: `Around 5 to 6 years from the first visa. The initial grant covers 2 years and 9 months, the extension adds 2.5 years, and Indefinite Leave to Remain follows at the 5-year mark once the Life in the UK test, English at B1 and the £29,000 income are all in place. The spouse of a British citizen can apply for citizenship as soon as they have ILR, with 3 years\' UK residence; otherwise you usually wait 12 months after ILR. The good character requirement applies either way.` },
  ],
  'farm-operating-cost-calculator': [
    { question: `Per hectare, what will winter wheat cost me to grow?`, answer: `Variable costs like seed, fertiliser and sprays typically run £500 to £700 per hectare for winter wheat, with fixed costs such as rent, labour and machinery adding another £400 to £700. Putting both together gives the total you need to cover before any profit.` },
    { question: `How do I work out my cost of production per tonne?`, answer: `Add the variable costs per hectare and divide by the yield. On 100 hectares of winter wheat, seed at £70 per hectare, fertiliser at £280, sprays at £200 and fuel and machinery at £180 give £730 per hectare of variable and machinery costs. At a yield of 8.2 t/ha that works out at £89 a tonne, which is the figure to hold against the market price when deciding whether to sell or store.` },
    { question: `What are fertiliser and fuel costing farms in 2026?`, answer: `Ammonium nitrate is £350 to £500 a tonne, well below the 2022 peak above £1,000, and red diesel costs £0.95 to £1.15 a litre. Seed adds £150 to £300 per hectare and spray chemicals £300 to £500 on arable land. General farm labour runs £15 to £25 an hour, rising to £30 to £50 for skilled operators such as combine drivers and herdsmen.` },
    { question: `Will SFI payments replace what BPS used to pay?`, answer: `Partly. The Basic Payment Scheme is being phased out by 2027 and Environmental Land Management payments take over, with SFI rates for 2026 running £36 to £150 per hectare depending on the actions chosen. Farms already doing environmental work generally find SFI pays better than BPS did. Subsidies once covered 35 to 50% of farm income, so the transition changes the shape of the accounts as well as the total.` },
    { question: `How do the April 2026 inheritance tax changes affect farms?`, answer: `Agricultural Property Relief and Business Property Relief now share a combined cap of £2.5M at 100% relief, with 50% relief above that, leaving an effective 20% charge on assets over the cap where it used to be 0%. A farm worth £2M pays nothing extra, while one worth £10M faces about £1.5M, or £1M if a spouse's unused allowance is transferred. The change has applied since 6 April 2026 under the Finance Act 2026, so lifetime gifting and partnership structures matter more as a result.` },
  ],
  'personal-injury-calculator': [
    { question: `How is injury compensation actually worked out?`, answer: `Compensation splits into general damages for the pain, suffering and loss of amenity, plus special damages covering financial losses such as lost earnings, medical costs and travel. The general damages figure comes from the Judicial College Guidelines, which set bracket amounts for each type of injury.` },
    { question: `How much can I claim for whiplash after a car accident?`, answer: `Road traffic whiplash lasting up to 2 years is paid on a fixed tariff introduced in May 2021, not valued by a judge. It runs from £275 for recovery inside 3 months up to £4,830 for 18 to 24 months, with slightly higher amounts, £300 to £4,975, where minor psychological injury sits alongside it. Severe or permanent neck injuries keep their full Guidelines value, and claims under £5,000 go through the online OIC portal.` },
    { question: `What will a no win no fee solicitor take from my compensation?`, answer: `Under a conditional fee agreement you pay nothing if the claim fails. If it succeeds, the solicitor takes a success fee capped at 25% of your general damages plus past financial losses, and After the Event insurance usually costs another £200 to £800 out of the award. Deductions commonly total 20% to 30%, so ask for a written illustration of what you would actually receive before signing.` },
    { question: `How long do I have to make a personal injury claim?`, answer: `The Limitation Act 1980 gives an adult 3 years from the accident, or from the date they knew about the injury where something like an industrial disease surfaces years later. A child has 3 years from their eighteenth birthday, and time does not run at all while someone lacks mental capacity. Criminal injuries claims through CICA must be brought within 2 years, extended only in exceptional cases.` },
  ],
  'investment-return-calculator': [
    { question: `Does a monthly contribution grow as much as a lump sum?`, answer: `Each monthly payment compounds for a different length of time, so later contributions have fewer years to grow than an equivalent lump sum invested at the start. A one-off amount follows Future Value = Present Value x (1 + r)^n, while regular payments use the future value of an annuity formula to add up all those separate growth periods.` },
    { question: `How much do fund and platform charges cost over the long run?`, answer: `Far more than the percentage suggests, because charges compound against you every year. A 1% annual charge on £100,000 growing at 6% over 30 years gives up roughly £132,000 of growth, close to the sum originally invested. Index funds such as Vanguard LifeStrategy 80% Equity at 0.22% or iShares Core MSCI World at 0.20% keep that drag small, while active funds at 0.66% to 0.94% plus a platform fee of 0.15% to 0.45% add up quickly.` },
    { question: `What growth rate should I put into the calculator?`, answer: `Something you can defend from history rather than hope. UK equities have returned 7-9% a year including dividends over long periods, gilts 3-5%, corporate bonds 4-6% and cash 2-4%. Strip out roughly 3% inflation and equities have delivered 4-6% real, bonds 0-2% and cash close to nothing. Using a nominal figure with an inflation assumption alongside it gives a more honest picture than a single optimistic number.` },
    { question: `How much of a final portfolio comes from growth rather than contributions?`, answer: `Most of it, given enough time. Starting with £10,000 and adding £200 a month at 7% produces about £321,000 after 30 years, and only £82,000 of that is money you paid in. The remaining £239,000 is growth. Money compounding at 7% doubles roughly every 10.3 years, so the later years of a long plan do much more for the total than the early ones.` },
  ],
  'savings-interest-tax-calculator': [
    { question: `When does interest on my savings become taxable?`, answer: `Interest becomes taxable once it passes your Personal Savings Allowance, which is £1,000 for basic-rate taxpayers, £500 for higher-rate and £0 for additional-rate. Anything above that is charged at your marginal income tax rate, and it covers bank, building society, NS&I and peer-to-peer interest, though Premium Bond prizes stay tax-free.` },
    { question: `How does HMRC collect the tax on my savings interest?`, answer: `Usually after the event rather than at the bank. Take £2,800 of interest earned by someone on a £55,000 salary. The higher-rate allowance of £500 leaves £2,300 taxable, and 40% of that comes to £920. HMRC collects it either through Self Assessment or by adjusting your PAYE code, using the interest figures banks report to it directly, so the amount is generally already known before you declare it.` },
    { question: `Can I really earn £6,000 of savings interest tax-free?`, answer: `Only if your other income is low. The starting rate for savings adds up to £5,000 on top of the £1,000 Personal Savings Allowance, but it applies only where non-savings income is below £17,570 and it shrinks by £1 for every £1 of income above £12,570. On a £14,000 salary the starting rate band is down to £3,570, which gives £4,570 of tax-free interest once the allowance is added. Pensioners living on the State Pension alone gain the most from it.` },
    { question: `Is a cash ISA worth using if I pay higher-rate tax?`, answer: `Almost always, because the allowance is only £500 at 40% and disappears entirely at 45%. Every £1 of interest sheltered inside an ISA saves 40-45% in tax, and the £20,000 annual allowance is enough to hold most savers' cash. Paying £20k a year into a 5% ISA rather than a taxable account saves a higher-rate taxpayer £2k or more each year, and the benefit repeats for as long as the money stays wrapped.` },
  ],
  'real-return-calculator': [
    { question: `Is my real return just the return minus inflation?`, answer: `Not quite, because the accurate method divides rather than subtracts: (1 + nominal return) divided by (1 + inflation rate), then minus 1. At 8% growth with 4% inflation that works out at 3.85%, not the 4% that simple subtraction suggests. Subtraction is close enough for a quick check at low rates, but the gap widens as both figures rise.` },
    { question: `What inflation rate should I assume for a long projection?`, answer: `The Bank of England targets 2% CPI, which is the defensible figure for a forward projection. Recorded inflation has run higher, averaging roughly 2.5-3% over the past two decades and reaching 11.1% in October 2022, so a plan built on the target alone is an optimistic one. Running the same calculation at both the target and the historic average shows how much of the outcome rests on that single assumption.` },
    { question: `How quickly does inflation eat into a cash lump sum?`, answer: `Faster than the annual percentage suggests, because the effect compounds. At 3% inflation, £100,000 is worth £74,400 at present-day prices after 10 years, £55,400 after 20 and £41,200 after 30. The halving point arrives at about 24 years at 3%, 14 years at 5% and 7 years at 10%. Cash returning between -1% and +1% in real terms does very little to hold that line.` },
    { question: `Do index-linked gilts actually protect against inflation?`, answer: `They track it, which is not the same as profiting from it. Both the principal and the interest are adjusted by RPI, and real yields have been positive again since 2022, roughly 1% to 2% above inflation in 2026, although the price of a gilt still moves when yields change. NS&I Index-Linked Savings Certificates have been shut to new money since 2011. An inflation-linked annuity is the other route, starting 30-50% below a level one and catching up only if you live long enough.` },
  ],
  'rule-of-72-calculator': [
    { question: `How long before my money doubles?`, answer: `Divide 72 by your annual growth rate: at 6% your money roughly doubles in 12 years, and at 8% in about 9 years. The shortcut stays reliable for rates between 2% and 15%.` },
    { question: `Why is 72 used instead of the exact figure of 69.3?`, answer: `The exact doubling time comes from ln(2) / ln(1 + r), which works out at roughly 69.3 divided by the rate. 72 is used in its place because it divides cleanly by 2, 3, 4, 6, 8, 9 and 12, so the sum can be done in your head. The slight overestimate also offsets part of the approximation error, and accuracy stays very good for rates between 4% and 12%.` },
    { question: `What growth rate do I need to double my money in ten years?`, answer: `Divide 72 by the number of years you have. Ten years needs 72 / 10 = 7.2% a year, compounded. Running the rule backwards like this is useful for setting a target return on a deposit or a pension pot, though it assumes the same rate every single year, which markets do not deliver, and it ignores anything you pay in along the way.` },
    { question: `When does the Rule of 72 give a misleading answer?`, answer: `The estimate drifts once rates fall outside the 2% to 15% window, and it is least reliable above 15%, where the Rule of 70 sits closer. It also assumes returns arrive evenly every year and that interest is added annually, so monthly or daily compounding beats the figure slightly. Regular contributions, platform fees of 0.2-1% and inflation are all left out of the sum.` },
  ],
  'cost-of-delay-calculator': [
    { question: `What happens if I put off investing for ten years?`, answer: `Delaying costs far more than the contributions you skip. A single £5,000 invested at age 25 grows to £74,872 over 40 years at 7%, but starting ten years later leaves only 30 years to compound and reaches £38,061, a loss of £36,811. With regular saving the gap is wider still, since £300 a month from 25 builds around £787,000 against £366,000 from 35.` },
    { question: `How much extra would I have to save to catch up?`, answer: `Roughly double, and the multiple grows with the delay. An investor who waits until 35 has to put in about £645 a month to match someone who started at 25 with £300, both at 7% to age 65. On a shorter delay the catch-up is gentler but still steep: someone planning £400 a month from 30 to 65 who waits five years needs about £591 a month afterwards, some 48% more, to arrive at the same place. Contributions can be increased. Lost years cannot.` },
    { question: `Does delaying pension contributions cost as much as delaying investing?`, answer: `It costs the same way, because a pension is simply an invested pot with tax relief attached. Paying £100 a month from age 25 at 6% builds about £199k by 65, while the same £100 a month begun at 35 reaches roughly £100k. The ten missing years of contributions add up to only £12,000, yet the shortfall is about £99,000, and the difference is compounding at work rather than money paid in.` },
    { question: `Should I wait for a better moment before I start investing?`, answer: `Waiting has a measurable price. Each month out of the market at an 8% return costs around 0.67% of the eventual lifetime outcome, and those months accumulate quietly while you look for a good entry point. The calculator makes the trade-off visible by pricing delays of 1, 5 and 10 years against starting today, including the higher monthly contribution each delay would later demand.` },
  ],
  'teacher-pay-calculator': [
    { question: `Where do I sit on the teachers' pay scale?`, answer: `Classroom teachers outside London sit on the Main Pay Range, from £34,069 at M1 to £46,940 at M6 from 1 September 2026, with one spine point gained per year in most schools. Experienced teachers who pass the Threshold move onto the Upper Pay Range, which runs £49,134, £50,956 and £52,835 at U3. Inner London, Outer London and the Fringe have their own higher pay ranges, starting at £41,729, £39,196 and £35,602, and a departmental responsibility adds a separate allowance on top.` },
    { question: `How much do teachers pay into the Teachers' Pension Scheme?`, answer: `Employee contributions are banded from 7.4% to 12% of pensionable pay, so the rate depends on which salary band your scale point falls into. Your employer pays a further 28.68%, which is roughly equivalent to a 25% pay rise in value and far above a typical workplace scheme. Benefits build on a career average basis at 1/57 of pay for each year of service, and the resulting pension is guaranteed and revalued for inflation rather than dependent on investment returns.` },
    { question: `What is take-home pay for a teacher on M6?`, answer: `On the M6 salary of £46,940, income tax takes £6,038, National Insurance £2,750 and a pension contribution at 8.9% takes £4,178, giving total deductions of £12,966. That leaves £33,974 a year, which is £2,831 a month. Someone in a private sector job on the same gross with a 5% pension would end up with around £35,400, about £1,500 more in the hand, but with far less going into their retirement pot.` },
    { question: `How do I move up to the Upper Pay Range?`, answer: `Pay progression has not been automatic since the 2014 reforms, so each point on the Main Pay Range depends on meeting the teaching standards in your annual review. Most teachers still move a point a year and reach M6 in 6 years. Getting onto the Upper Pay Range requires a Threshold application showing consistently good practice over time. Beyond that, a Teaching and Learning Responsibility payment of £3,651 to £17,819 rewards duties such as heading a department.` },
  ],
  'shared-parental-leave-calculator': [
    { question: `Can both parents share the weeks of leave after a birth?`, answer: `Eligible parents can divide up to 50 weeks of leave and 37 weeks of Statutory Shared Parental Pay between them. The mother or primary adopter first has to end their own leave with a binding curtailment notice, and the two compulsory weeks straight after birth cannot be shared. Parents can take their blocks one after the other or be off together, whichever suits the family.` },
    { question: `How much notice must I give before each block of leave?`, answer: `At least eight weeks before every block of leave you intend to take, and each parent may book up to three separate blocks. Continuous blocks have to be accepted if you are eligible, but an employer can turn down a discontinuous request and propose alternative dates instead. Booking early matters when both parents are planning around each other, since a refused pattern can force the whole plan to be redrawn.` },
    { question: `Do both parents need to qualify for shared parental leave?`, answer: `Both have tests to pass, but not the same ones. A parent taking the leave needs 26 weeks of continuous service with their employer by the end of the 15th week before the due date (for adopters, by the end of the matching week) and average earnings of at least £129 a week for ShPP. The other parent only has to have worked in 26 of the 66 weeks before the due date and earned £390 in total in any 13 of them. If both want leave, both must pass the full test. Check this first, before the mother gives a curtailment notice, because ending maternity leave is a binding step.` },
    { question: `Will shared parental leave cost us enhanced maternity pay?`, answer: `It often does. A lot of employers top maternity pay up to full pay for an initial period but pay shared parental leave at the statutory £194.32 a week only, so converting the balance can be an expensive choice. Employers do not have to match the two: the Court of Appeal ruled in 2019 (Ali v Capita and Hextall v Leicestershire Police) that paying less for shared leave is not discrimination. Compare the two figures for your own contracts before curtailing, since the decision cannot easily be undone.` },
  ],
  'high-income-child-benefit-calculator': [
    { question: `At what income do I start repaying Child Benefit?`, answer: `The charge begins once either parent's adjusted net income passes £60,000, with 1% of your Child Benefit repaid for every full £200 above that. By £80,000 the charge equals the full amount you received. Employees can pay it through their PAYE tax code, while anyone who already files a tax return pays it through Self Assessment. A parent on £70,000 with two children is £10,000 over the line, which works out at 50 steps of 1%, so half the benefit goes back and half stays.` },
    { question: `Should I still claim Child Benefit if I have to repay it?`, answer: `Yes, in almost every case. Registering the claim and then ticking the box that stops the payments protects the National Insurance record of the parent at home with a child under 12. Those automatic credits build State Pension, and each qualifying year is worth about £358.50 a year for life at the 2026/27 full rate. Twelve years of caring adds up to around £4,300 a year from age 67, which can exceed £80,000 across a 20-year retirement, so not registering at all is an expensive mistake.` },
    { question: `How can I legally reduce the High Income Child Benefit Charge?`, answer: `The charge measures adjusted net income, and several things come off that figure. Pension contributions are the most direct route, so £5,000 paid into a pension from a £65k income brings the adjusted figure back to £60,000 and keeps the Child Benefit intact. Salary sacrifice for a pension or an electric car achieves the same result and is often more tax-efficient. Gift Aid donations reduce the figure too. Where your partner earns below the threshold, they should be the one making the claim.` },
    { question: `How much Child Benefit will I get in 2026/27?`, answer: `Child Benefit pays £27.05 a week for the eldest child and £17.90 a week for each child after that. Across a full year an eldest child on their own is worth £1,407, and a two-child family receives £2,337.40. Whether you keep it depends on the higher earner's adjusted net income rather than on what the household earns between you.` },
  ],
  'benefit-cap-calculator': [
    { question: `Will the benefit cap reduce what my household receives?`, answer: `It can, once your total working-age benefits pass the limit for your circumstances. For 2026/27 couples and single parents can receive up to £22,020 a year outside London or £25,323 in Greater London, while single people without children are capped at £14,753, or £16,967 in London. Universal Credit, Child Benefit, Child Tax Credit, Housing Benefit, Jobseeker's Allowance and Employment and Support Allowance all count towards that total.` },
    { question: `Which benefits are exempt from the benefit cap?`, answer: `Some benefits take the household out of the cap altogether. Personal Independence Payment at any rate, Disability Living Allowance, Attendance Allowance, Industrial Injuries Disablement Benefit, Carer's Allowance, a war widow's or widower's pension, the ESA support group and the Universal Credit element for limited capability for work and work-related activity all do this, as does Working Tax Credit. Others simply do not count towards the total, including Council Tax Reduction, free school meals, Healthy Start vouchers and Support for Mortgage Interest.` },
    { question: `How much do I need to earn to escape the cap?`, answer: `The cap stops applying once your household earns more than £881 a month from work, which is about 16 hours a week at the National Living Wage of £12.71. Sitting exactly on that line leaves no margin for a quiet week, so 18 hours or more is the safer target. Self-employed earnings count, and the incomes of both partners are added together. Anyone who stops work after at least 50 of the previous 52 weeks in employment keeps a 39-week grace period.` },
    { question: `Where is the benefit cap reduction taken from?`, answer: `The reduction comes out of your housing support, meaning Housing Benefit or the Universal Credit housing element, rather than being spread across the whole award. A couple with 3 children outside London on £26,000 of benefits would be £3,980 over the £22,020 cap, so £76.54 a week comes off the housing element. Single parents with several children in high-rent areas are hit hardest, commonly losing £50-£150 a week.` },
  ],
  'trigonometry-calculator': [
    { question: `Can I work in radians as well as degrees?`, answer: `Yes. Angles can be entered in either degrees or radians, and the setting applies to inputs and results alike. Alongside sine, cosine and tangent it handles the three reciprocal functions, secant, cosecant and cotangent, plus all of the inverse functions. It will also solve a full triangle from three pieces of information, using the sine rule, the cosine rule and the fact that the three angles total 180°.` },
    { question: `When do I use the sine rule instead of the cosine rule?`, answer: `The sine rule, a/sin A = b/sin B = c/sin C, fits cases where you know two angles and one side, or two sides and an angle that is not between them. The cosine rule, a² = b² + c² − 2bc·cos A, covers the other two situations: all three sides known and an angle wanted, or two sides plus the angle between them and the third side wanted. Both are examined at GCSE Higher Tier and at A-Level.` },
    { question: `What does SOHCAHTOA actually stand for?`, answer: `It is the mnemonic for the three ratios in a right-angled triangle. Sine is opposite over hypotenuse, cosine is adjacent over hypotenuse, and tangent is opposite over adjacent. The hypotenuse faces the right angle and is the longest side, the opposite side faces the angle you are working with, and the adjacent side is the other one touching it. In a 3-4-5 triangle with θ between the 3 and the 5, the three ratios come out at 0.8, 0.6 and 1.33.` },
    { question: `How do I find the angle a ladder makes with the ground?`, answer: `Reach for an inverse function. A ladder 5m long with its base 3m from the wall reaches √(5² − 3²) = 4m up it, so the tangent of the angle at the ground is 4/3 and the angle itself is tan⁻¹(4/3), which comes to 53.13°. Inverse functions are what you want whenever two sides are known and the angle is missing, and on a physical calculator they hide behind the second-function key as sin⁻¹, cos⁻¹ or arcsin.` },
  ],
  'freelance-tax-calculator': [
    { question: `When do I need to register as self-employed with HMRC?`, answer: `Once your self-employment income passes £1,000 in a tax year you must register by 5 October following the end of that tax year. Someone who started freelancing in April 2025 and had earned £1,500 by April 2026 would need to register by 5 Oct 2026. Registering is free and takes about 10 min on gov.uk, after which HMRC issues a Unique Taxpayer Reference within 2-4 weeks. Registering late can cost a penalty of up to 100% of the tax left unpaid as a result, on top of any late filing penalties, which start at £100.` },
    { question: `How much of my freelance income should I set aside for tax?`, answer: `For a basic-rate freelancer, 25-30% of net profit after expenses covers income tax and Class 4 NI comfortably. Budget 35-40% if you expect to cross into the higher rate and 40-45% nearer the additional rate. Any VAT you charge is held on HMRC's behalf and belongs in the same pot rather than your working capital. The cleanest method is a separate savings account with an automatic transfer every time a client pays, reviewed each year against your actual bill.` },
    { question: `Should I stay a sole trader or set up a limited company?`, answer: `Sole trader status is simpler and cheaper, with no annual accounts to file and roughly £1,200 to £1,800 a year saved in accountancy, and at 2026/27 rates it usually wins outright for an owner who draws out all the profit: £50k of profit costs £9,732 in tax as a sole trader against about £12,300 through a company after accountancy, and £80k costs £22,289 against about £25,400. A company pays off mainly when you can leave profit inside it or want the company to make pension contributions, so weigh that against the extra admin and any IR35 exposure.` },
    { question: `What are Payments on Account and when are they due?`, answer: `They are advance instalments toward next year's tax bill, triggered when this year's bill exceeds £1,000 and less than 80% of your tax is taken at source. Half is due on 31 January with the balancing payment for the year just ended, and half on 31 July. A first-timer with an £8,000 bill for 2025/26 pays that plus £4,000 on account on 31 Jan 2027, then another £4,000 on 31 July 2027. Form SA303 reduces the instalments if next year will be lower, though HMRC charges interest if you cut them too far.` },
  ],
  'macro-calculator': [
    { question: `Should I eat more protein or carbs to hit my goal?`, answer: `It depends on the split you pick: a balanced 30/40/30, a higher-protein 40/30/30 for muscle gain, or 25/45/30 for endurance. Protein and carbohydrate each give 4 kcal per gram while fat gives 9, so the ratio decides how your daily calories are shared out and, in a deficit, how much of the weight you lose comes off as muscle.` },
    { question: `How many carbs do I need if I train every day?`, answer: `Athletes training more than an hour a day are generally advised to take 4 to 7 g of carbohydrate per kg of bodyweight, well above a general-health intake. Endurance work leans hardest on glycogen, so a split of about 55% carbohydrate, 20% protein and 25% fat suits it. Protein still scales with bodyweight at 1.6 to 2.2 g per kg, and fat is best kept above roughly 0.5 g per kg, because hormone production depends on it.` },
    { question: `How do I count macros without weighing everything?`, answer: `Apps such as MyFitnessPal, Cronometer and Lose It carry UK food databases covering most of what you eat. The hand portion method fills the gaps, using a palm for protein, a fist for vegetables, a thumb for fat and a cupped hand for carbohydrate. Chains including Pret, M&S and Joe and The Juice label their food clearly, and prepared services such as Fresh Fitness Food or MuscleFood arrive with the numbers attached. Aim for around 80% accuracy, since chasing precision can tip into disordered eating.` },
    { question: `Do I need to hit exact macros every day?`, answer: `No. Weekly averages count for more than daily ones, and a few days slightly off will not undo the work, whereas 80% adherence across several weeks shows up clearly. Protein is the one worth hitting most days, because falling short costs muscle while you are in a deficit. Carbohydrate and fat can flex around training and social plans. The split that works is the one you can keep going, rather than the one that looks tidiest on paper.` },
  ],
  'cost-of-living-calculator': [
    { question: `Where is the cheapest place to live in the UK?`, answer: `The North East of England is consistently the cheapest, with Sunderland, Middlesbrough and Hartlepool sitting 40-50% below the UK average. The Welsh Valleys, including Merthyr Tydfil and Rhondda, come in 45-55% below, and Northern Ireland outside Belfast is similarly affordable. Dundee and Aberdeen are the cheaper Scottish cities. Manchester, Liverpool and Leeds run 50-65% below London. At the expensive end sit London, especially Zones 1-3, the South East commuter belt, Cambridge, Oxford, Brighton and Edinburgh.` },
    { question: `How much does it cost to live in London each month?`, answer: `A single person on a basic lifestyle needs £2,200-£3,000 a month as a minimum, a couple £3,200-£4,500, and a family of four £5,000-£8,000 or more. Rent dominates, at £1,800-£2,500 for a one-bedroom flat in Zones 2-4 and £2,500-£3,500 for two bedrooms. A monthly Zone 1-3 Travelcard is £193, Council Tax runs £1,200-£2,500 a year, and gas and electricity together cost £150-£250 a month. Wandsworth has the lowest Band D in England at £1,028 in 2026/27, but rents there wipe out the saving.` },
    { question: `How much less can I earn outside London and stay level?`, answer: `Roughly a third less in the North. Once housing is paid for, £50k in London leaves you around the same position as £30-£35k in Manchester or £25k in Newcastle. Employers rarely bridge the whole gap. London weighting typically adds 10-25% to a national salary, and the civil service version is worth about £3,500-£4,500 a year. Average pay in London sits about 25% above the UK average, which is less than the housing differential, so London workers can end up worse off in real terms.` },
    { question: `Has the UK cost of living crisis eased by 2026?`, answer: `Partly. Between 2022 and 2024 the UK had its sharpest cost shock since the 1970s. The Ofgem cap went from £1,277 in 2021 to £4,279 in January 2023, food inflation peaked at 19.2% in March 2023, the highest since 1977, and mortgage rates rose from 2-3% to 6-7% during 2022, adding £200-£500 a month to an average mortgage. Real wages fell 5-8% across 2021-2024. By 2026 energy bills are 30-40% below the peak, food inflation is 3-5%, mortgage rates are 4-5%, and real wage growth has resumed.` },
  ],
  'smart-meter-calculator': [
    { question: `What can a smart meter tell me that an estimated bill can't?`, answer: `Because it sends automatic readings to your supplier, a smart meter replaces estimated bills with figures based on what you actually use. The in-home display shows your spending in pounds and pence in real time, making wasteful habits easier to spot.` },
    { question: `How much does a smart meter actually save in a year?`, answer: `Awareness alone cuts electricity use by 2 to 4% and gas by 3 to 5%, worth £40 to £90 a year for an average household. On the typical £1,723 bill under the October to December 2026 cap, that works out at £19.74 off the electricity and £30.29 off the gas, or £50.03 in total. Moving on to a time-of-use tariff adds another £30 to £80, giving a combined £80 to £130.` },
    { question: `What is the difference between SMETS1 and SMETS2 meters?`, answer: `SMETS1 is the older generation, and some of these meters lose their smart functions when you move to a new supplier, which means going back to manual readings. SMETS2 is the current standard and keeps working with every supplier, so switching costs you nothing in functionality. The rollout has reached about 70% of homes, short of the original aim of offering every home a meter by 2020.` },
    { question: `Which time-of-use tariff suits overnight EV charging?`, answer: `Octopus Agile prices each half hour against the wholesale market at typically 10 to 25p per kWh, with occasional negative pricing, while Octopus Cosy is built for heat pumps and runs cheapest from 4am to 7am and 1pm to 4pm. Economy 7 still offers 8 to 10p between 11pm and 6am. Charging a car overnight costs £7 to £10 rather than about £30 during the day.` },
    { question: `Can I refuse to have a smart meter fitted?`, answer: `You can decline, and turning the installer away is within your rights, although your supplier may charge slightly higher rates to cover manual readings. If you accept one, it collects half-hourly readings routed through the Data Communications Company, and you can ask to opt out to daily readings instead. On safety, the radio emissions are far below those of a mobile phone or Wi-Fi router.` },
  ],
  'gpa-calculator': [
    { question: `What is a UK 2:1 worth on a 4.0 GPA scale?`, answer: `There is no official conversion, but the mapping in general use puts an Upper Second, meaning 60 to 69%, at about 3.3 on the 4.0 scale. A First from 70% maps to 4.0, a Lower Second to 2.7 and a Third to 2.0. Formal evaluators read it more cautiously and tend to place a 2:1 in a band of 3.3 to 3.7, so the figure you quote can depend on who is doing the converting.` },
    { question: `How do I work out a GPA from module marks and credits?`, answer: `Multiply each module's grade points by its credit value, add the results together and divide by the total credits, which mirrors the weighting UK universities already use for classification. Four three-credit courses at 4.0, 3.0, 3.3 and 3.7 give 42 points across 12 credits, a GPA of 3.5. A UK degree usually runs at 120 credits a year over three years, making 360 credits, so the heavier modules pull the average furthest.` },
    { question: `Who converts a UK degree for a US graduate application?`, answer: `Recognised evaluators such as ECE, the Educational Credential Evaluators, and WES, World Education Services, produce the conversions US graduate schools accept, and they charge $200 to $400 for the service. Their scales are deliberately cautious, placing a UK First at 3.7 to 4.0, a 2:1 at 3.3 to 3.7 and a 2:2 at 3.0 to 3.3. Competitive programmes at schools of the Harvard and Stanford type generally want 3.7 and above.` },
    { question: `Does a First mean the same thing at every UK university?`, answer: `Not quite. Russell Group institutions tend to mark more strictly, awarding First Class degrees to around 15 to 20% of a cohort, while post-1992 universities more often report 25 to 35%. Rates roughly doubled across the sector between 2010 and 2020 before the Office for Students raised concerns and the trend moderated. Assessment style matters as well, since essay-based subjects rarely give the very highest marks whereas STEM papers with objective questions can reach 90% and above.` },
  ],
  'solicitor-fee-calculator': [
    { question: `How much will a solicitor charge me for conveyancing?`, answer: `Conveyancing solicitors usually charge between £850 and £1,800 plus VAT and disbursements such as searches and Land Registry fees. Probate work is often billed at 1% to 4% of the estate value, or as a fixed fee for simpler estates.` },
    { question: `What hourly rate do UK solicitors charge?`, answer: `Provincial firms generally charge from £150 to over £500 an hour, while London magic circle practices run from £400 to £1,500. Family work under the Children Act sits at £200 to £500 an hour. Time is normally recorded in 6 minute units, so one unit costs £30 at a £300 an hour rate, and short calls and emails accumulate quickly.` },
    { question: `What must a solicitor tell me about costs before starting?`, answer: `The Solicitors Regulation Authority requires the best possible information about likely costs at the outset and as the matter progresses, so you should be warned promptly if an estimate is going to be exceeded. You are also entitled to an itemised bill at completion, with a right to have it assessed by the court if you dispute it. Hourly bills must show the time spent on each task, the rate charged, and disbursements such as court and search fees listed separately.` },
    { question: `How can I cut the cost of using a solicitor?`, answer: `Take a fixed fee wherever one is offered, since it removes the risk of an open-ended hourly bill. Online firms such as Conveyancing Direct and Slater and Gordon often charge 30% to 50% less than the high street. Probate on estates up to £5k, a simple uncontested divorce and a basic will costing £30 to £100 online can all be handled yourself, and mediation costs 50% to 80% less than a court fight.` },
  ],
  'divorce-settlement-calculator': [
    { question: `How does a court decide a divorce financial settlement?`, answer: `Courts in England and Wales aim for a fair division of matrimonial assets, putting the welfare of any children first. They then weigh income, earning capacity, financial needs, standard of living, ages, length of marriage and contributions, including non-financial ones such as childcare.` },
    { question: `Are pensions included in a divorce settlement?`, answer: `Yes, and they are often the second most valuable asset after the family home. The figure used is the cash equivalent transfer value at the date of divorce, which for long-serving NHS, civil service, teaching or police scheme members can run from £200k to over £1M. A pension sharing order transfers part into the other spouse's own pension, or offsetting gives them more cash or property instead.` },
    { question: `How much does a divorce cost in the UK?`, answer: `The court filing fee in 2026 is £628, up from £612 on 13 July 2026. Mediation costs £1,000 to £3,000 in total, and a solicitor-negotiated uncontested divorce runs £2,500 to £5,000 per side, with most staying under £5,000 each. A contested case in court costs £15,000 to £100,000 or more per side, and high-asset disputes routinely reach £50,000 to £500,000.` },
    { question: `How long does a no-fault divorce take?`, answer: `The practical minimum is 26 weeks. A 20-week reflection period runs from the application before a Conditional Order, once known as the Decree Nisi, followed by a further 6 weeks before the Final Order, once the Decree Absolute. Financial proceedings run separately and are not covered by that timetable, so a settlement can take considerably longer to conclude.` },
  ],
  'uk-citizenship-calculator': [
    { question: `When can I apply for British citizenship after getting ILR?`, answer: `You can usually apply once you have held ILR for at least 12 months, having lived in the UK for five years, or three if you are married to a British citizen. You also need to pass the Life in the UK test and meet the English language requirements, and to satisfy the good character rules.` },
    { question: `How many days can I have spent outside the UK?`, answer: `No more than 450 days across the 5 years before you apply, and no more than 90 days in the final 12 months. If you are married to a British citizen the qualifying period is 3 years instead, with no more than 270 days outside the UK and 90 in the final 12 months. Absences are among the most common reasons a naturalisation application is refused, so count them from passport stamps and travel records rather than from memory.` },
    { question: `Do I need an English test for naturalisation?`, answer: `Only if you cannot show B1 English another way. Accepted tests include IELTS Life Skills B1, Trinity GESE Grade 5, LanguageCert International ESOL B1 and Pearson PTE Academic UKVI at 51 or above, costing £160 to £182 and valid for 2 years. You are exempt as a citizen of a majority English-speaking country, or if you hold a degree taught in English verified by UK ENIC, are over 65, or have a physical or mental condition that prevents you taking the test.` },
    { question: `How long does a citizenship application take to decide?`, answer: `Six to 12 months is typical, with some cases running to 24. A biometrics appointment comes 2 to 4 weeks after you apply online. Once approved, you have 3 months to book a ceremony with your council, where you take the Oath of Allegiance and receive your certificate. A British passport costs £102 online and takes about 3 weeks after that.` },
    { question: `Can I keep my existing citizenship as well?`, answer: `The UK permits dual citizenship, so nothing on the British side asks you to give up your original nationality. What matters is the law of your other country, and India, China and Japan are among those that do not allow it, which means naturalising as British effectively costs you the first passport. Check that before you apply rather than after the ceremony.` },
  ],
  'free-school-meals-calculator': [
    { question: `Do my children qualify for free school meals if we get Universal Credit?`, answer: `Yes. From September 2026 every child in a household that receives Universal Credit gets free meals in England, whatever the household earns. The £7,400-a-year net earnings test still matters: families at or below it are Targeted FSM and also bring pupil premium and other linked help, while families above it get Expanded FSM, the meals only. The other qualifying benefits are income-related Employment and Support Allowance, the guarantee element of Pension Credit and asylum support under Part VI of the Immigration and Asylum Act 1999.` },
    { question: `How do I apply for free school meals?`, answer: `Apply through the school office or your local council, and in many areas you can do it online via gov.uk. You will need to show which qualifying benefit you receive. Once the application is approved, a letter goes to the parent and the school is told directly. Awards usually run only from the date of application rather than being backdated, so applying as soon as you become eligible avoids losing weeks of meals and school funding.` },
    { question: `Is it worth registering if my child takes packed lunches?`, answer: `Yes, if your family counts as Targeted FSM (Universal Credit with net earnings of £7,400 a year or less, or asylum support). The registration is what counts, not whether the child eats the meal. It brings pupil premium into the school worth £1,550 for a primary pupil or £1,100 for a secondary pupil each year, spent on extra tuition, trips, equipment and mentoring, and opens extended free school travel and holiday activities and food places. Expanded FSM registration gives the meals only.` },
    { question: `Which children get free school meals without a benefits check?`, answer: `Every child in Reception, Year 1 and Year 2 in England receives universal infant free school meals whatever the family income, a separate scheme that has run since 2014 and needs no benefits check. Scotland feeds all P1 to P5 pupils, and P6 and P7 pupils whose family gets Scottish Child Payment. Wales offers free meals to every primary pupil. From Year 3 onwards in England the benefits-based test applies instead, which since September 2026 means any household on Universal Credit.` },
  ],
  'loft-conversion-calculator': [
    { question: `Which type of loft conversion is the cheapest?`, answer: `A roof-light or Velux conversion is the least expensive at £20,000 to £35,000, because it puts windows into the existing roof rather than rebuilding any part of it. Costs climb as soon as you change the roof shape, reaching £35,000 to £60,000 for a dormer, £40,000 to £65,000 for hip-to-gable work and £50,000 to £75,000 for a mansard. Per square metre, build costs run £1,200 to £2,500.` },
    { question: `Do I need planning permission for a loft conversion?`, answer: `Many conversions count as permitted development, which allows 40 m³ on a terraced house and 50 m³ on a semi or detached one, provided nothing projects beyond the front roof slope and the materials resemble the existing ones. Side dormers and anything facing the street need an application, conservation areas are tighter, and listed buildings always need listed building consent. Building Regulations approval is mandatory whether or not planning permission is.` },
    { question: `Is my roof tall enough for a loft conversion?`, answer: `You need 2.0 m of headroom above the staircase, and in England a habitable room wants at least 2.3 m over 50% of its floor area, with Scotland set a little differently. Roof structure counts as much as height. Trussed roofs, used in houses built after the 1960s, must be replaced with a rafter and joist system at £8,000 to £15,000 extra, while an older cut roof is generally straightforward to work with.` },
    { question: `How long does a loft conversion take from start to finish?`, answer: `Budget 8 to 12 weeks. Scaffolding and deliveries take the first 2 weeks, structural work and the dormer run from weeks 3 to 6, insulation, plasterboard, plumbing and electrics from weeks 7 to 10, and finishing and snagging fill weeks 11 to 12. You can stay in the house throughout, although noise, dust and scaffolding make it uncomfortable, and emptying the loft beforehand often means paying £80 to £200 a month for storage.` },
  ],
  'extension-cost-calculator': [
    { question: `What does a single-storey extension cost per square metre?`, answer: `Single-storey rear extensions run about £1,800 to £2,800 per m² in 2026. A double-storey is cheaper per m² at £1,500 to £2,400, because the foundations and roof are shared between two floors, and a wrap-around is dearest at £2,500 to £4,000. Where you build matters as much as what you build, since London and the South East add 20 to 40% over prices in the Midlands and the North.` },
    { question: `Do I need planning permission for a rear extension?`, answer: `Many single-storey rear extensions are permitted development, up to 6 m on a detached house and 3 m on an attached one, provided height stays under 3 m for single-storey work or 4 m for anything taller, nothing sits forward of the property and materials match. Side extensions are limited to half the width of the original house. Two-storey work usually needs permission, and a householder application costs £258.` },
    { question: `What do professional fees add to an extension budget?`, answer: `An architect takes 7 to 12% of the build cost and a structural engineer 3 to 5%, with a Building Regulations application on top at £200 to £900 and planning at £258 where it applies. Together these normally come to 5 to 10% of the project, or £4,000 to £8,000. Set aside a further 10% as contingency, because the ground under a British house rarely behaves the way the drawings assume.` },
    { question: `Will an extension add more value than it costs?`, answer: `A kitchen extension typically lifts a property by 10 to 20%, and in most areas the money comes back within 3 to 5 years. Turning a 3-bed into a 4-bed produces the sharpest jump. Over-extending is the trap, as a £100k extension on a £200k house seldom recovers its cost, and a loft conversion often returns more for less outlay. Check the ceiling price on your street on Rightmove or Zoopla before committing.` },
  ],
  'childcare-entitlement-calculator': [
    { question: `How many free childcare hours can I claim for a toddler?`, answer: `Since September 2025 working parents of children aged 9 months to 3 years can claim 30 hours a week of free childcare during term time, which is 38 weeks a year and 1,140 hours in total. The same entitlement can instead be spread across more weeks at fewer hours. Every 3 and 4-year-old also has a universal 15 hours regardless of what their parents do, with working parents topped up to 30.` },
    { question: `What do I need to earn to qualify for 30 hours?`, answer: `Each parent needs to earn at least £10,575 a year, which is 16 hours a week at the National Living Wage, or £203 a week. Neither parent can earn more than £100,000. In a couple, both have to meet the floor, whereas a single parent is judged on their own income only. Self-employed parents use Self Assessment or business accounts as evidence, and parents on maternity or paternity leave stay eligible if they are returning to work.` },
    { question: `Can my 2-year-old get free hours if I am not working?`, answer: `Some 2-year-olds qualify for 15 hours a week even where neither parent works. The route covers families receiving certain benefits, looked-after children, and children with an Education Health and Care Plan. It runs separately from the working-parent entitlement, so a household that fails the £10,575 earnings test can still qualify on this basis. Checking both routes is worthwhile, because the eligibility rules have little in common beyond the child's age.` },
    { question: `Should I choose Tax-Free Childcare or the Universal Credit element?`, answer: `You cannot claim both at the same time, so it comes down to income. Tax-Free Childcare adds £2 for every £8 you pay in, up to £2,000 a year per child, and suits parents earning over £203 a week and under £100,000 each. The Universal Credit childcare element reimburses 85% of costs, capped at £1,071.09 a month for one child or £1,836.16 for two or more, but pays in arrears. Lower-income families usually do better on the UC element, mid-income families on the top-up.` },
  ],
  'stock-unit-calculator': [
    { question: `How are livestock units worked out for different animals?`, answer: `Each animal carries a coefficient measured against a reference dairy cow rated at 1.0, so a beef suckler cow counts as 0.75, a ewe as 0.12 and a horse as 0.80. That lets you compare the grazing demand of a mixed herd on one scale.` },
    { question: `What stocking density counts as extensive grazing?`, answer: `Divide your total Livestock Units by the forage hectares available. Extensive grazing generally targets 0.5 to 1.0 LU per hectare, while intensive grassland systems can carry 1.5 to 2.5 LU/ha. A mixed farm running 94.5 LU over 65 hectares comes out at 1.45 LU/ha, which sits comfortably within the grassland range rather than at the extensive end.` },
    { question: `How do I adjust livestock units for seasonal grazing?`, answer: `Multiply the coefficient by the fraction of the year the animals are actually present. A flock of 200 ewes on the ground for 8 months is calculated as 200 x 0.12 x 8/12, which gives 16.0 adjusted Livestock Units. Applying that adjustment stops summer grazing stock inflating a stocking density figure that will later be checked against a scheme threshold.` },
    { question: `Why do Defra and the RPA care about stocking density?`, answer: `Stocking density is the measure used to test eligibility for agri-environment schemes, to run cross-compliance checks and to set the terms of Countryside Stewardship agreements. Because it combines every class of animal on one scale, it lets an assessor compare a dairy herd, a beef enterprise and a flock of ewes on the same basis, and it decides whether the grazing pressure on a holding is judged extensive or intensive.` },
  ],
  'agricultural-worker-wage-calculator': [
    { question: `Is there a special minimum wage for farm workers in England?`, answer: `Every agricultural worker in England must be paid at least the National Living Wage, currently £12.71 an hour for those aged 21 and over, with £10.85 at 18 to 20 and £8.00 under 18 or on an apprenticeship. The Agricultural Wages Board for England was abolished in 2013, though some older Agricultural Wages Orders still set higher rates for specialist grades.` },
    { question: `What is the minimum agricultural wage in Scotland?`, answer: `Scotland uses one rate rather than grades. The Agricultural Wages (Scotland) Order, 30th edition, effective 1 April 2026, sets £12.71 an hour for all agriculture workers. Apprentices get £8.00 for their first 18 months, and anyone holding an SCQF Level 6/7 or higher agricultural qualification earns a premium of at least £1.91 an hour. Overtime is paid at 1.5x the hourly rate.` },
    { question: `What do the Welsh agricultural wage grades pay?`, answer: `Grades A and B, the Agricultural Development Worker and Agricultural Worker, pay £12.71 for those 21 and over, £10.85 at 18 to 20 and £8.00 at 16 to 17. Grade C, the Advanced Worker, earns £13.48, Grade D, the Senior Worker, £14.79 and Grade E, the Manager, £16.23. First-year apprentices are on £8.00, under the 2025 Order that continues from 1 April 2026.` },
    { question: `What allowances do Welsh farm workers receive on top of pay?`, answer: `A dog allowance of £11.18 per dog per week, an extra £2.12 an hour for night work, and a birth or adoption grant of £87.85 per child. Where the employer provides housing, the accommodation offset is £1.97 a week for a house or £6.31 a day for other accommodation. These are paid alongside the grade rate rather than counted within it.` },
    { question: `What does the Seasonal Worker Visa pay and cost in 2026?`, answer: `It allows up to 6 months of horticultural work at a minimum of £12.71 an hour with at least 32 paid hours a week guaranteed. The application fee is £340, with no Immigration Health Surcharge on visas of 6 months or less. The 2026 quota is 42,900 places, 41,000 in horticulture and 1,900 in poultry. Accommodation deductions are capped at £11.10 a day, and the visa cannot be extended.` },
  ],
  'mean-median-mode-calculator': [
    { question: `What sets the mean, median and mode apart?`, answer: `The mean is the sum of the values divided by how many there are, so it gets pulled around by outliers. The median is the middle value once the numbers are sorted and shrugs those outliers off, while the mode is simply the value that appears most often. On the set [2, 4, 4, 5, 8] the mean is 4.6, the median is 4 and the mode is 4, which is about as close as the three usually come.` },
    { question: `Why is the average UK salary usually quoted as a median?`, answer: `Because pay is positively skewed, with a long tail of very high earners pulling the mean upwards. UK median household income in 2024 was £35,000 while the mean was £40,000, a gap created almost entirely by the top of the distribution. The ONS therefore uses medians and the interquartile range for most income and wealth statistics, and a 'median worker' means the 50th percentile, with half of workers earning more and half less.` },
    { question: `How badly can a single outlier distort the mean?`, answer: `Badly enough to make it useless. Six salaries of 25k, 28k, 30k, 35k, 40k and 250k produce a mean of 68k, which is higher than five of the six people actually earn. The median of 32.5k describes the same group honestly, and the set has no mode at all because every value appears once. That is why sales and salary data are normally reported as a median alongside the interquartile range.` },
    { question: `Can a set of numbers have more than one mode?`, answer: `Yes, and it can also have none. The mode is whichever value appears most often, so a set where two values tie has two modes, and a set of entirely unique values has no mode at all. The calculator sorts your numbers, marks the middle position for the median and lists every mode it finds, alongside the range, which is the highest value minus the lowest.` },
  ],
  'prime-number-calculator': [
    { question: `Can I check whether a large number is prime quickly?`, answer: `Any whole number above 1 with no divisors besides 1 and itself is prime, and testing divisibility only up to its square root keeps the check fast, because any larger factor would already have appeared paired with a smaller one. Checking 97 means trying divisors up to √97, about 9.85, so 2, 3, 5 and 7 are the only candidates and none of them divide it. Composite numbers are broken down into their full prime factorisation instead.` },
    { question: `Why is 1 not counted as a prime number?`, answer: `A prime has exactly two divisors, 1 and itself, and 1 fails that test because its only divisor is 1. Excluding it also keeps the Fundamental Theorem of Arithmetic tidy, since every integer above 1 then has one unique prime factorisation rather than endless variants padded out with 1s. By the same logic 2 is the only even prime, because every other even number divides by 2.` },
    { question: `How do prime numbers keep online banking secure?`, answer: `RSA encryption multiplies two large primes together and publishes the product. Recovering the original primes from that product, a semiprime, is so slow with known methods that the encryption holds up. RSA-2048, the current standard, uses 617-digit primes. The same mathematics underpins error-correcting codes, hash functions and random number generation, all of which lean on properties of primes.` },
    { question: `What is the largest prime number found so far?`, answer: `As of 2024 it is 2^136,279,841 − 1, a Mersenne prime running to 41 million digits, discovered through the Great Internet Mersenne Prime Search, which spreads the work across volunteers' computers. Records of that size rely on Miller-Rabin style testing rather than trial division, which would take impossibly long. Plenty about primes is still unsettled: Goldbach's conjecture, that every even number above 2 is the sum of two primes, has been verified to 4 × 10^18 but never proved.` },
  ],
  'waist-hip-ratio-calculator': [
    { question: `How is waist-to-hip ratio linked to health risk?`, answer: `Dividing your waist measurement by your hip measurement gives a ratio the World Health Organisation uses to flag central obesity and linked risks such as cardiovascular disease and type 2 diabetes. Above 0.90 for men or 0.85 for women counts as abdominal obesity, and for some conditions the ratio predicts risk better than BMI alone.` },
    { question: `Where exactly should I measure my waist?`, answer: `Midway between your lowest rib and the top of your hip bones, which usually sits above the belly button and well above your trouser line. Stand relaxed, put a flexible tape on bare skin, keep it horizontal, exhale gently and resist pulling your stomach in. Snug is right, compressed is not. Measure your hips at the widest point of the buttocks, and take both readings at the same time of day, ideally in the morning before you eat.` },
    { question: `Is waist-to-hip ratio more useful than BMI?`, answer: `For several purposes, yes. The ratio picks up visceral fat around the organs, which links most strongly to heart disease, type 2 diabetes and stroke, whereas BMI only sets weight against height. A muscular athlete can show a high BMI with a healthy ratio, and someone with a normal BMI but a high ratio often fares worse than an overweight person with a low one. Reading both together, alongside the NHS waist limits of 94 cm for men and 80 cm for women, gives the fuller picture.` },
    { question: `How quickly can I reduce my waist measurement?`, answer: `Often faster than the scale suggests, since visceral fat comes off two to three times more quickly than subcutaneous fat, so the tape moves before your weight does. A deficit of 500 to 1,000 kcal a day gives 0.5 to 1 kg a week. Interval training shifts visceral fat more effectively than steady cardio, strength work protects muscle along the way, and sleeping seven to nine hours supports the whole process where under six hours works against it.` },
  ],
  'raised-bed-calculator': [
    { question: `How deep should a raised bed be for growing vegetables?`, answer: `Most vegetables and flowers do well in 200 to 300 mm of soil, while root crops and fruit prefer deeper beds of 400 to 600 mm. Salad leaves and herbs get by on 150 to 200 mm, carrots and parsnips want 300 to 450 mm, and fruit bushes such as blueberries need 400 to 500 mm. The RHS suggests a fill of roughly 60 to 70% topsoil, 20 to 30% compost and 5 to 10% sharp sand or perlite for drainage.` },
    { question: `How many bulk bags of soil does a raised bed need?`, answer: `A 1.2 m by 2.4 m bed filled to 300 mm needs 0.86 m³ of soil, and a UK bulk bag holds 0.7 to 0.9 m³, so one bag typically fills one standard bed and may stretch to two smaller ones. The calculator reports the volume in litres and in bulk bags for whatever dimensions you enter. Allow for settling as well: beds lose 25 to 50 mm a year and need a top-up of 50 to 100 litres per bed, about one or two retail bags.` },
    { question: `What is the cheapest way to fill a large raised bed?`, answer: `Use the Hugelkultur method, putting wood and branches in the bottom 30 to 50% of the bed and topsoil and compost in the upper 50 to 70%, which saves 40 to 60% on filling. Subsoil from an excavation is free if you are already landscaping, and only the top 200 to 300 mm needs to be quality topsoil and compost. A 0.86 m³ bed filled with 0.5 m³ of wood or subsoil and 0.36 m³ of topsoil costs about £18 to £40, compared with £60 to £100 in bulk bags.` },
    { question: `How much does it cost to build a raised bed in the UK?`, answer: `Pressure-treated softwood is the budget choice at £40 to £120 for a 1.2 by 2.4 m bed and lasts 8 to 15 years. Cedar or larch costs £100 to £300 per bed and hardwoods such as oak or sweet chestnut £200 to £500. Composite or recycled plastic runs to £150 to £400 and galvanised metal £80 to £250, while brick is the most expensive but permanent. DIY scaffolding boards cost £30 to £70, or nothing if reclaimed. Filling the bed with bulk bags adds roughly £60 to £100.` },
    { question: `Which vegetables give the best yield in a raised bed?`, answer: `Courgettes lead the way, with 1 to 2 plants per bed producing 8 to 15 kg, followed by tomatoes at 5 to 10 kg per plant and climbing French beans at 3 to 5 kg per plant. Strawberries are perennial and easy. Salad leaves give multiple cuts a year, radishes are ready 4 weeks from sowing, and spring onions and herbs such as parsley, basil and coriander need little attention. Sweetcorn, pumpkins and cauliflower are poor choices, because they yield little for the space or are fussy to grow.` },
  ],
  'fence-paint-calculator': [
    { question: `How far does a litre of fence paint go?`, answer: `On rough-sawn timber, which soaks up more, a litre of fence paint typically covers 4 to 6 m², rising to 8 to 10 m² per litre on smooth or previously painted wood. Water-based paints dry in one to two hours, against four to six for solvent-based treatments. Closeboard and overlap panels need 15 to 20% added to the nominal panel area, because the overlapping boards carry more surface than the outline suggests.` },
    { question: `How many litres do I need for a 12m fence?`, answer: `Take the panel height by the run length by the number of sides. A 12m run at 1.8m high painted on 2 sides is 43.2 m², and 2 coats means 86.4 m² of coverage, which at 9 m² per litre works out at 9.6 L. Add posts and gravel boards as extra area, and add 15 to 20% for the overlap on closeboard panels. UK fence paints come in 5 L and 9 L tins, and the larger sizes cost less per litre.` },
    { question: `When is the best weather to paint a garden fence?`, answer: `Dry, warm conditions of 10 to 25°C with no rain forecast for 24 to 48 hours are what you want, which in the UK usually means April to May or September. Direct hot sun dries the film too fast, freezing weather wrecks adhesion and damp timber refuses to bond. Newly erected fencing needs 4 to 6 months for the moisture to leave the wood before its first coat. Allow 2 to 4 hours between coats.` },
    { question: `Is expensive fence paint worth it over budget stain?`, answer: `Usually yes, once you count the labour. Budget paint at around £20 for 5L lasts 3 to 5 years, so a 12m fence needs about 5 repaints over 20 years at roughly £100 in materials and 3 hours of work each time. Premium paint at £50 to £60 for 5L lasts 7 to 10 years, meaning 3 repaints, about £180 and 9 hours. Cuprinol Ducksback carries a 5 year guarantee and Sadolin Superdec claims 10 years on suitable timber.` },
  ],
  'clothing-size-converter': [
    { question: `What is a UK size 12 in EU and US sizes?`, answer: `A UK 12 is an EU 40, a US 8 and an Italian 44. The pattern moves in steps of two, so a UK 8 is EU 36 and US 4, a UK 10 is EU 38 and US 6, and a UK 14 is EU 42 and US 10. In body terms a UK 12 assumes a bust of about 91 cm (36 in) and a waist of about 73 cm (29 in). Brands vary by 1-2 sizes around those numbers, so the specific size guide is worth checking.` },
    { question: `How do I measure myself for the right clothing size?`, answer: `Measure over underwear, standing relaxed. Women's dresses are cut to bust, waist and hip, and a UK 10 assumes 87-90cm bust, 68-72cm waist and 93-96cm hip. Men's shirts use the chest taken around the fullest part, trousers use waist and inside leg, and shoes use foot length from heel to longest toe together with width. If you fall between two sizes, the larger one can be taken in, and Marks & Spencer and John Lewis alter suits free in store.` },
    { question: `Which clothing brands run small compared with UK sizes?`, answer: `Italian and Spanish labels such as Zara and Mango run small, so one size up is usually the right call, and Asian brands such as Uniqlo are cut slim as well. French names including Sandro and Sezane are narrow through the body. American brands such as Gap and J.Crew broadly match UK norms, although vanity sizing has made some labels generous. M&S and Next have a reputation for consistent, true-to-size fit.` },
    { question: `Do children's clothes match my child's age?`, answer: `For about 80% of UK children they do, and the rest need a size up or down. Babywear runs 0-3 months, 3-6, 6-9, 9-12, 12-18 and 18-24, and after that sizes are labelled by year from 2-3 upwards. From around age 5 the label also carries a height, such as 110cm, 116cm or 122cm, and that figure is more reliable than the age. School uniforms tend to run small, so allow for it when buying.` },
  ],
  'volume-converter': [
    { question: `Why is a UK pint bigger than a US pint?`, answer: `Because the two countries kept different gallons. A UK pint is 568 ml and a US pint 473 ml, since a UK gallon of 4.546 litres divides into 8 pints while the US gallon is only 3.785 L. The same split runs through the cups, where the older UK cup is 284 ml against 237 ml in the US. In metric terms, 1 litre is 1.760 UK pints or 0.220 UK gallons, so a litre bottle is a little under two pints.` },
    { question: `Do UK pubs have to serve beer in pints?`, answer: `Draught beer and cider must legally be sold in pints or half pints, and milk in returnable glass bottles keeps the pint as well, while fuel has been sold in litres since 1995. The glass itself is regulated, holding 568 ml within ±2% and carrying the HM Government crown stamp. A half pint is 284 ml. Spirit measures are separate, at 25 or 35 ml in England and Wales, with Scotland defaulting to 25 ml.` },
    { question: `How many glasses of wine are in a bottle?`, answer: `Six medium glasses, since a standard bottle holds 750 ml and the medium pub measure is 175 ml. A small glass is 125 ml, so the bottle goes further, and a large 250 ml glass empties it faster. Champagne pours 6 flutes from the same 750 ml. Spirits are bottled at 700 ml, and a single measure is 25 or 35 ml depending on where you are drinking, with Scotland defaulting to the smaller pour.` },
    { question: `How much water does an average UK household use?`, answer: `Between 100-150 m³ a year. Water bills are metered in cubic metres, where 1,000 L makes 1 m³, so the figure is easier to picture as litres than as a cube. For scale, an Olympic swimming pool holds 2,500 m³ and a road petrol tanker carries about 38,000 L. Domestic heating oil tanks are far smaller, at 1,200-1,800 L, with most suppliers setting a minimum delivery of 500 L.` },
  ],
  'birthday-calculator': [
    { question: `What is the most common birthday in the UK?`, answer: `26 September, which falls nine months after Christmas and New Year, and the whole stretch from mid-September into early October is busy. The rarest dates are 25-27 December and 1 January, since planned caesareans are avoided over the holidays and inductions are rarely booked then. Tuesday and Thursday are the most common days of the week to be born on, and Saturday and Sunday the least. The UK records 600,000-700,000 births a year, and the number is falling.` },
    { question: `Why do 23 people give a 50% chance of shared birthdays?`, answer: `Because you are comparing pairs, not people. Twenty-three people form 253 different pairs, and with each pair carrying a 1/365 chance of matching, the odds of no match anywhere come to (364/365)^253, or about 0.493. That leaves a 50.7% chance of at least one shared birthday. The probability then climbs quickly, reaching 70.6% at 30 people, 97% at 50 and 99.9% at 70, which is why most school classes contain a pair.` },
    { question: `How do I apply for a 100th birthday card from the King?`, answer: `Apply through gov.uk rather than waiting for one to arrive, because the cards are no longer sent out automatically. A relative or friend submits the request roughly 8 weeks before the birthday and supplies proof of age, normally the birth certificate. Cards then follow every year after 100, so 101, 102, 103 and onwards, with special designs for the 105th and 110th. The UK has more than 16,000 centenarians. Diamond wedding anniversaries at 60 years qualify too, along with 65, 70 and 75.` },
    { question: `When can I take money out of my pension?`, answer: `From 55 for a defined contribution pension, though the minimum age rises to 57 in April 2028, which matters a great deal if your birthday falls either side of that change. The State Pension is a separate thing and starts at 66. Other money dates sit around them. National Insurance contributions begin at 16, the adult ISA allowance of £20,000 replaces the Junior ISA at 18, and the full National Living Wage applies from 25.` },
  ],
  'car-insurance-estimate-calculator': [
    { question: `Why is my car insurance premium so high?`, answer: `Insurers weigh factors such as your age (younger drivers pay far more), where you live (urban areas cost more), the car's insurance group from 1 to 50, your claims history and your no-claims bonus. The ABI puts the average price paid for comprehensive cover at £566 in Q2 2026, but it swings widely by driver profile, and postcode alone can double the price between one town and another.` },
    { question: `How much is a no-claims bonus actually worth in pounds?`, answer: `Enough to change the shape of the bill. Take a driver in their thirties with a group 15 car, comprehensive cover and 8,000 miles a year, where the calculator starts from £1,400 before any discount. Five years of no claims, worth 60%, removes £840 and leaves £560 a year, about £46.67 a month before any interest for paying monthly. Losing that bonus to a single at-fault claim is why paying £30-£80 to protect it is often worth doing.` },
    { question: `Why can the top level of cover cost less than third party only?`, answer: `Because pricing follows the people who buy each product, not just the risk being covered. Third party only is chosen disproportionately by drivers insurers regard as high risk, so the pool it is priced against is expensive. Fuller cover attracts lower-risk drivers, which drags the average claim cost down. Uswitch found comprehensive averaged £631 against £1,610 for third party only between February and April 2026. The practical lesson is to quote for all three levels rather than assuming the cheapest-sounding one is cheapest.` },
    { question: `Will a black box policy really cut a young driver's premium?`, answer: `Usually, by around 20-40%. On Confused.com's Q3 2026 average quote of £1,860 for a driver aged 17-20, that is roughly £370 to £745 a year. The box logs speed, braking, cornering, mileage and when you drive, so the discount is conditional on the score staying good, and a poor one can push the price back up. Cautious learners and low-mileage students do well out of it. Night-shift workers and long-distance commuters often do not.` },
  ],
  'home-insurance-calculator': [
    { question: `What is the difference between buildings and contents insurance?`, answer: `Buildings insurance covers the structure itself, its walls, roof and fixtures, and lenders insist on it as a mortgage condition, whereas contents insurance protects your possessions. The buildings figure should be based on the rebuild cost rather than the property's market value, and contents on what it would cost to replace everything inside from scratch.` },
    { question: `How do I work out the rebuild cost of my house?`, answer: `Insurers start from the ABI's average rebuild costs per square metre, which vary by region and property type. A 3-bedroom semi typically comes out at £150,000-£250,000. A quicker sanity check is that rebuild cost tends to sit at 60-80% of the purchase price once the land value is excluded, so a £400k house might rebuild for £250-£320k. Setting the figure too low risks the insurer scaling down a settlement.` },
    { question: `Does home insurance cover subsidence and flood damage?`, answer: `Both are covered by a standard policy, but with conditions. Subsidence normally carries its own excess of around £1,000, which is much higher than the excess on other claims. Flood cover has become expensive for properties in flood-prone areas, though the Flood Re scheme keeps it available through 2039. What is never covered is gradual damage, so wear and tear, slow deterioration and pre-existing damp or structural problems fall outside any policy.` },
    { question: `How can I bring down my home insurance premium?`, answer: `Raising the voluntary excess from £150 to £500 takes 15-25% off, and buying buildings and contents together saves another 10-20%. An alarm, deadlocks and window locks are worth 5-15%, with more for a police-approved monitored system. Paying annually avoids 5-10% in interest. The biggest single saving is switching at renewal, worth 30-50%, and the biggest avoidable cost is claiming for small losses and giving up a no-claims discount worth 30-50%.` },
  ],
  'critical-illness-calculator': [
    { question: `What happens if I am diagnosed with a critical illness?`, answer: `Being diagnosed with one of the serious illnesses named in the policy, such as cancer, a heart attack, stroke or multiple sclerosis, triggers a tax-free lump sum, and most plans list 40 to 60 conditions. The payment is made once, on first diagnosis, and the policy then ends. Many people put the money towards clearing a mortgage, funding treatment or covering the gap while they recover.` },
    { question: `Should I buy critical illness cover or income protection?`, answer: `They answer different questions. Critical illness pays a single lump sum on diagnosis of a listed condition, which suits a mortgage you want cleared outright. Income protection pays a monthly income whenever any illness keeps you off work, including the long absences that never appear on a critical illness list. If you can only fund one and your worry is monthly bills, income protection covers more ground. If the worry is a large debt, the lump sum does more.` },
    { question: `How much does critical illness cover cost each month?`, answer: `Broker quotes published by iam insured (September 2026) put £50,000 of level cover over 25 years at £15.79 a month for a 35-year-old non-smoker, so £100,000 costs roughly £32 and £200,000 about £63. The average life and critical illness policy costs £25.16 a month for £50,000 of cover. Smokers paid 40-80% more on those quotes, and a BMI of 30 or above pushes the premium up by 25-100%. Between 45 and 50, prices climb about 12% for each year you put the decision off, which is why buying early costs less over the life of the policy.` },
    { question: `Are all cancers covered by critical illness insurance?`, answer: `Not automatically. Policies use the ABI standard definitions, which cover cancer of a specified severity, so the least advanced grades can fall outside the wording. DCIS is the usual example, and it is treated differently by different insurers. The same applies to transient ischaemic attacks and partial paralysis. Aviva, Legal & General and Vitality all define these borderline cases in their own way, so the Conditions Booklet is worth reading before you buy rather than at claim time.` },
  ],
  'property-cgt-calculator': [
    { question: `What rate of capital gains tax applies when I sell a second home?`, answer: `For 2026/27, gains on residential property are taxed at 18% for basic-rate taxpayers and 24% for higher and additional-rate taxpayers, the same rates that have applied to other assets since 30 October 2024. The £3,000 annual exempt amount is deducted before those rates apply. Because the gain is added to your other income, a single sale can straddle both rates, with the slice sitting inside the basic rate band charged at 18% and the rest at 24%.` },
    { question: `When do I have to report and pay CGT on a property sale?`, answer: `Within 60 days of completion, using HMRC's Capital Gains Tax on UK property service, and the tax is payable in the same window rather than at the usual Self Assessment date. Late filing costs £100 straight away, then £10 for each day once the return is 3 months overdue, plus interest on the tax itself. Non-resident owners face the same 60-day deadline on UK residential property.` },
    { question: `Does Private Residence Relief cover a home I moved out of?`, answer: `Partly. Private Residence Relief covers the period the property was your home, and the final 9 months of ownership always count even if you had already left, with the remaining period taxable in proportion. Letting Relief can take up to £40,000 off the gain, but since April 2020 it only applies where you lived in the property at the same time as your tenants, so letting out a former home after moving out does not qualify.` },
    { question: `Which costs can I deduct from a property gain?`, answer: `The purchase price, legal fees on both the purchase and the sale, the stamp duty you paid when you bought, estate agent fees and capital improvements such as an extension, a new kitchen or a new boiler. Those come off the sale price to give the gain, and the £3,000 annual exempt amount is deducted after that. Gifts between spouses and civil partners are outside CGT altogether, while a cheap sale to another relative can be recalculated by HMRC at market value.` },
  ],
  'weighted-grade-calculator': [
    { question: `How is a weighted degree average worked out from module credits?`, answer: `Each module mark is multiplied by its credit value, the results are added together and the total is divided by the number of credits, so a 30-credit module counts for twice as much as a 15-credit one. With a standard year of 120 credits, that means a weak result in a large module drags the average down considerably further than the same mark in a small one.` },
    { question: `Which years count towards my final degree classification?`, answer: `Most UK universities classify on the second and third years and treat the first as qualifying only. The usual weightings are Year 2 at 33% with Year 3 at 67%, or Year 2 at 25% with Year 3 at 75%, though some institutions include all three years and Oxford and Cambridge weight the final examinations at 100%. The resulting average maps to a First at 70%, a 2:1 at 60%, a 2:2 at 50% and a Third at 40%.` },
    { question: `Do all A-level papers carry the same weighting?`, answer: `No, and the differences are worth checking before you plan revision. AQA Biology and Physics both run three papers at 33%, 33% and 34%, whereas OCR Chemistry is 37%, 37% and 26%. AQA English Literature weights two papers at 40% each with 20% on the non-examined assessment, and modern languages typically put 50% on writing with 25% each on speaking and listening. Your own board's specification is the place to confirm it.` },
    { question: `What mark do I need in my last paper to hit my target?`, answer: `Work backwards from the weights. If Paper 1 scored 75 and carries 40%, and Paper 2 scored 78 and carries 30%, then reaching 80% overall requires 88.7% on the final paper. Running that sum before the exam rather than after results day tells you whether the target is still within reach, and how much of the revision time left should go to that one paper.` },
  ],
  'cost-of-living-comparison-calculator': [
    { question: `Why is London so much more expensive than other UK cities?`, answer: `Housing is the main driver: rents in London can reach two or three times the cost of similar accommodation in cities such as Liverpool, Sheffield or Newcastle. A one-bedroom flat runs £1,800 to £2,500 a month in London against £600 to £900 in Newcastle. Eating out adds another 30 to 50%, but groceries, energy and broadband barely differ.` },
    { question: `What salary do I need to match a London wage elsewhere?`, answer: `Roughly two thirds of it further north. On the index, where the UK average is 100, London sits at 145 against Manchester at 92 and Newcastle at 82, so £60k in London compares with £40k to £45k in Manchester or £35k in Newcastle. The trade runs both ways, since London salaries are 20 to 30% higher to begin with, which is why the comparison is worth making before you negotiate.` },
    { question: `Which UK cities are cheapest to live in?`, answer: `At the bottom of the index sit Sunderland at 73 and Hull at 75, followed by Sheffield at 80, Newcastle at 82 and Liverpool at 85, all against a UK average of 100. London at 145 is 95% more expensive than Sunderland for an equivalent lifestyle. Rent explains most of the difference, with a one-bedroom flat at £450 to £650 a month in Sunderland and a two-bedroom flat to buy at £75k to £140k.` },
    { question: `Do groceries and bills really cost less outside London?`, answer: `Far less than housing does. Supermarket prices vary by only 5 to 10% nationally, Lidl and Aldi are 25 to 30% cheaper wherever you shop, and energy bills hardly move because the Ofgem cap applies across the country. Broadband and streaming cost the same everywhere. Petrol is 4 to 5p a litre cheaper in the North, public transport swings by 10 to 20%, and eating out in London runs 30 to 50% above regional cities.` },
  ],
  'pension-annual-allowance-calculator': [
    { question: `Can I carry forward unused pension allowance from previous years?`, answer: `Yes, unused allowance from the previous three tax years can be carried forward, used oldest year first, provided you belonged to a registered pension scheme in those years. It sits on top of the current year's allowance, so someone with £70k unused could pay in £130k in one go. Contributions from all sources still count towards the £60,000 for the year itself.` },
    { question: `When does the tapered annual allowance apply to me?`, answer: `Both income tests have to be met. Threshold income, broadly your net income after deducting personal contributions paid through relief at source, must exceed £200,000, and adjusted income, which adds back all pension contributions including your employer's, must exceed £260,000. Once both apply, the £60,000 allowance falls by £1 for every £2 of adjusted income above £260,000, reaching its floor of £10,000 at £360,000. If threshold income stays below £200,000, the full allowance remains whatever the adjusted figure comes to.` },
    { question: `What triggers the Money Purchase Annual Allowance?`, answer: `Flexibly accessing taxable income from a defined contribution pension does it, which usually means starting drawdown or taking an uncrystallised funds pension lump sum. Once triggered, your contributions to money purchase schemes are capped at £10,000 a year for good. Defined benefit accrual is unaffected and keeps a separate £50,000 allowance under the alternative annual allowance rules.` },
    { question: `What replaced the Lifetime Allowance after April 2024?`, answer: `Two lump sum limits took its place. The Lump Sum Allowance of £268,275 caps the tax-free cash you can take across all your pensions, and the Lump Sum and Death Benefit Allowance of £1,073,100 covers death benefits and serious ill-health payments. There is no longer any limit on the value a pension can reach, so the old £1,073,100 ceiling has gone, along with its excess charges of 55% on lump sums and 25% on income, which stopped in April 2023.` },
  ],
  'state-pension-age-calculator': [
    { question: `When does the State Pension age rise to 67?`, answer: `State Pension age currently stands at 66 and is legislated to climb to 67 between May 2026 and March 2028, phased by date of birth, with a further rise to 68 due between 2044 and 2046. The phasing is fine-grained enough that people born a day apart can reach pension age months apart.` },
    { question: `Can I claim my State Pension before State Pension age?`, answer: `No. The age is set by law and cannot be brought forward for any reason. Other pensions can bridge the gap instead: private and workplace defined contribution pots are accessible from 55, rising to 57 from April 2028, and some defined benefit schemes permit an earlier start under their own rules. There is also a serious ill health route, which pays a tax-free lump sum where life expectancy is under 12 months.` },
    { question: `Is it worth deferring my State Pension?`, answer: `For every 9 weeks you defer, the pension rises by 1%, which is 5.8% over a full year, so five years of deferral means 29% more for life. Breakeven, where the increases have made up for the payments you skipped, comes about 17 years after payments start, so in your mid-80s. It works best if you are still working past State Pension age and would lose much of the money to income tax, or you are in good health and expect to reach 85 and beyond. Poor health or an immediate need for cash both argue against it.` },
    { question: `How many National Insurance years do I need for the full State Pension?`, answer: `Thirty-five qualifying years earn the full £241.30 a week for 2026/27, and every year short of that costs £6.89 a week, or £358 a year, permanently. Voluntary Class 3 contributions at £18.40 a week, around £957 for a full year, can fill a gap, and the outlay is usually recovered within about 2.7 years of drawing the pension. Check your record at gov.uk/check-state-pension-and-fill-gaps before the older years become harder to buy back.` },
  ],
  'student-loan-early-repay-calculator': [
    { question: `Is paying off my student loan early actually worth it?`, answer: `Only if you were going to clear the balance anyway. If the loan is heading for write-off, an overpayment simply hands money back to the government and buys nothing. The test is whether your projected repayments clear the balance and its interest before the write-off date. On a Plan 2 balance of £30,000 and a £50,000 salary rising 4% a year, repayments total £50,288 and the loan clears after 16 years 4 months, so a £5,000 overpayment cuts the total paid by £7,155. On a £35,000 salary with a £45,000 balance, the loan is written off whatever you do, and a £10,000 lump sum simply adds £10,000 to what you pay.` },
    { question: `Would investing the lump sum beat repaying my loan?`, answer: `It depends on the interest you avoid and the return you expect. In the worked example, £5,000 invested at 5% grows to £11,093 by the time the loan would have cleared, while repaying and investing the freed-up repayments builds £13,033, because Plan 2 interest at that salary is above 5%. On Plans 1, 4 and 5, which charge RPI only (4.1% in 2026/27), a 5% return usually comes out ahead. A pension can beat both, since a £100 gross contribution costs a basic-rate taxpayer £80 and a higher-rate taxpayer £60.` },
    { question: `When is my student loan written off?`, answer: `It depends on the plan. Plan 1 is written off 25 years after the April you were first due to repay if your first loan was taken on or after 1 September 2006, or at age 65 if it was taken before then. Plan 2 (English students starting from 1 September 2012 to 31 July 2023, and Welsh students from 1 September 2012) and Plan 4 in Scotland run 30 years from the April you were first due to repay, and Plan 5 (English students from 1 August 2023) runs 40 years. Postgraduate loans run 30 years. Loans are cancelled on death, with no claim against the estate, and may be cancelled if you claim certain disability benefits.` },
    { question: `Is a lump sum better than monthly overpayments?`, answer: `A lump sum does more per pound because it cuts the balance that interest is charged on immediately. £5,000 off a Plan 2 loan charging 5.77%, the 2026/27 rate on a £50,000 salary, avoids about £288 of interest in the first year, and the saving compounds from there. Monthly overpayments work the same way, but each one only starts saving interest from the month it is paid, so the same total spread over years saves less. Both only make sense if you would otherwise repay the loan in full.` },
  ],
  'pension-pot-calculator': [
    { question: `How big a pension pot do I need for a £20,000 retirement income?`, answer: `Under the 4% rule a £20,000 annual income needs a pot of £500,000, since £20,000 divided by 0.04 gives the target. Buying an annuity whose income rises each year, at the 5.5% starting rate the calculator uses, would take about £363,636. A level annuity at about 8.2%, the best rate for a healthy 65-year-old in September 2026, would take about £245,000, but its income never rises. Neither figure allows for the State Pension, which reduces what your own savings have to produce.` },
    { question: `What counts as a comfortable retirement income in the UK?`, answer: `Pensions UK (formerly the PLSA) puts its 2026 comfortable standard at £45,400 a year for a single person and £62,700 for a couple, after tax, which stretches to multiple holidays and replacing the car every 5 years. Below that, the moderate standard of £32,700 and £45,400 covers an annual holiday and hobbies, and the minimum standard of £13,900 and £22,500 covers essentials only. Comfortable generally means a pot of £600k or more on top of a full State Pension.` },
    { question: `What percentage of my salary should I save for retirement?`, answer: `A common rule of thumb takes half your age when you start: 12.5% at 25, 17.5% at 35, 22.5% at 45. An employer match of 3 to 5% counts towards that, leaving you to find 7.5 to 19.5% yourself. The State Pension replaces only about 25 to 30% of average UK earnings, so replacing 70% of your pre-retirement income means workplace and personal pensions covering 40 to 45%, which takes 15 to 20% of salary sustained over 40 years.` },
    { question: `How much difference does starting ten years earlier make?`, answer: `Roughly double the pot, at every stage. Paying £100 a month from age 25 at a 7% real return produces £262k by 65, whereas the same £100 started at 35 produces £121k and from 45 just £52k. Growth, not contributions, does most of the work, accounting for more than 70% of the final pot over 30 years, which is why late catching-up is so much harder than it looks.` },
  ],
  'junior-isa-calculator': [
    { question: `How much can I pay into a Junior ISA each year?`, answer: `Up to £9,000 can go in per child each tax year, counting contributions from parents, grandparents and anyone else combined. The limit applies to the child rather than to each giver, so relatives paying in separately still share the same allowance. The child takes control of the money at 18.` },
    { question: `Should I choose a Cash or a Stocks and Shares Junior ISA?`, answer: `It depends mostly on how many years are left before the child turns 18. A Cash JISA pays a fixed or variable rate and suits a short horizon. A Stocks and Shares JISA holds funds or shares and is the usual choice from birth, because 18 years smooths out short-term falls. On £100 a month from birth, a 7% real return works out at about £42,500, against roughly £30,500 in cash at 4% AER.` },
    { question: `What happens to a Junior ISA when my child turns 18?`, answer: `The account converts to an adult ISA automatically, with no loss of tax treatment, and control passes to the child. They can leave it invested, withdraw it, or move it into a Lifetime ISA before 40 for the 25% government bonus towards a first home or retirement at 60. Transfers into a LISA are limited to £4,000 a year, so shifting a large pot takes several tax years.` },
    { question: `Can grandparents pay in without an inheritance tax problem?`, answer: `The £3,000 annual gift exemption and the £250 small gifts allowance per recipient both cover payments into a grandchild's Junior ISA, so contributions inside those limits carry no inheritance tax consequences. Regular payments can also qualify for the gifts out of income exemption if they are structured properly. Anyone can contribute, but everything from every source counts towards the same £9,000 annual limit.` },
  ],
  'zero-hours-calculator': [
    { question: `Do zero-hours workers get holiday pay and the minimum wage?`, answer: `Even without guaranteed hours, workers keep statutory rights such as the National Minimum Wage, 5.6 weeks of paid annual leave pro rata to the hours worked, rest breaks, Statutory Sick Pay if eligible and protection from discrimination. A written statement of terms is also due from day 1 of the engagement, setting out how you will be paid and how holiday is handled.` },
    { question: `How is holiday pay worked out on a zero-hours contract?`, answer: `Entitlement builds at 12.07% of the hours you work, which reproduces the statutory 5.6 weeks once 28 days of leave is spread over 232 working days. Every £1,000 of earnings therefore accrues £121 of holiday pay. Your contract must say whether that is rolled up into each pay packet or banked for you to take as leave, and where hours are irregular the payment has to reflect a 52-week reference period of normal pay.` },
    { question: `Can my employer stop me working for someone else?`, answer: `No. Exclusivity clauses in zero-hours contracts have been unenforceable since May 2015, so an employer offering you no guaranteed hours cannot also stop you taking work elsewhere. Any such clause in your paperwork has no effect. Less clear-cut pressure is more common in practice, such as hours being quietly reduced after you decline shifts, which is harder to challenge but still worth documenting.` },
    { question: `What is changing for zero-hours workers?`, answer: `The Employment Rights Act 2025 will require employers to offer qualifying zero-hours and low-hours workers guaranteed hours that reflect what they regularly work, instead of leaving workers to ask. It also brings a right to reasonable notice of shifts and payment when shifts are cancelled or cut short at short notice. The government's September 2026 timeline puts these measures in 2027, with dates to follow consultation, so they are not yet in force.` },
  ],
  'agency-worker-calculator': [
    { question: `What am I entitled to after 12 weeks as an agency worker?`, answer: `Once you complete a 12-week qualifying period in the same role with the same hirer, you gain the right to equal pay and conditions as though the firm had taken you on directly. That covers basic pay, overtime rates, holiday entitlement, rest periods and night work limits. It does not cover occupational sick pay, pension schemes, redundancy pay or maternity leave beyond the statutory minimum, so parity is real but not complete.` },
    { question: `Does a break between assignments reset the 12-week clock?`, answer: `It depends on how long the break lasts. Anything under 6 weeks leaves the count untouched. A gap of 6-28 weeks pauses the clock without wiping it where the reason is protected, sickness or parental leave among them. A gap of 28 weeks or more starts you from zero. If a hirer ends your assignment for a period specifically to keep you short of the qualifying period, that is unlawful avoidance and you can bring a claim.` },
    { question: `How much does the agency take from my hourly rate?`, answer: `Agency commission usually runs at 15-25% of the rate the hirer pays, and where an umbrella company sits in the chain it deducts a further 5-12% to cover employer NI, holiday accrual and the apprenticeship levy. In practice a hirer paying £25 an hour might pass £21 to the umbrella, which pays you £17-£18 after its own deductions. Going direct on the agency's PAYE, with no umbrella in between, generally leaves you slightly better off.` },
    { question: `Do agency workers get holiday pay and sick pay?`, answer: `Yes. Temping does not affect the statutory floor, so you build up 5.6 weeks of paid holiday a year, 28 days pro rata against full-time hours, and you qualify for Statutory Sick Pay and statutory maternity and paternity pay on the usual conditions. Holiday must be paid when you take the leave rather than rolled into your hourly rate. Your agency also has to give you a written statement of terms by day 1 of the assignment.` },
  ],
  'settlement-agreement-calculator': [
    { question: `How much of my settlement agreement is tax-free?`, answer: `Redundancy and ex-gratia pay are normally free of income tax up to £30,000 under sections 401 to 403 of the Income Tax (Earnings and Pensions) Act 2003. That sits alongside the other parts of the package, such as notice pay, redundancy pay, holiday pay and a contribution towards your legal fees, which are treated differently. Anything above £30k is taxed at your marginal rate. Employees never pay NI on it; since 6 April 2020 the employer pays Class 1A NI on the excess over £30,000.` },
    { question: `How much should I expect to be offered to leave?`, answer: `There is no set formula. An amicable departure often settles around 1 to 3 months' salary, an exit tied to performance concerns at 3 to 6 months, and a case with a live discrimination claim at 6 to 12 months or more, plus injury to feelings under the Vento bands of £1,300 to £62,900 and above. Length of service, salary, your age and how quickly you could find similar work all move the number, as does how much the employer wants to avoid a hearing.` },
    { question: `Do I have to take legal advice before signing?`, answer: `Yes, and without it the agreement does not validly waive your tribunal claims, which is as much the employer's problem as yours. Employers therefore pay a contribution toward the cost, usually £500 to £1,500. Use the appointment for more than a signature: it is the moment to check whether the offer reflects the strength of any claim, and to raise references, share options and pro-rata bonus before the document is finalised.` },
    { question: `Is notice pay taxed in a settlement agreement?`, answer: `Pay in lieu of notice is always taxable, whatever the agreement calls it, and accrued holiday pay is taxed in the same way as ordinary earnings. Any payment attributed to a restrictive covenant is taxed separately again. Only the genuine ex-gratia compensation element qualifies for the £30,000 exemption, which is why the way the package is split between headings in the drafting has a direct effect on your net figure.` },
  ],
  'buy-to-let-mortgage-calculator': [
    { question: `What rental income do lenders want to see for a buy-to-let mortgage?`, answer: `Lenders apply a rental coverage ratio, usually 125-145%, and test it against a stressed interest rate rather than the rate you are paying. A £200k buy-to-let mortgage tested at 5.5%, for example a 5-year fix at that rate, costs £916.67 a month in interest, so a landlord tested at 145% needs rent of £1,329.17 a month to pass. On a 2-year fix at 5.5% the stress rate is 7.5% and the rent needed rises to £1,812.50. Limited company borrowers are generally assessed at 125%. Where the rent falls slightly short, some lenders permit top-slicing, using your personal income to bridge the difference.` },
    { question: `Is it cheaper to buy through a limited company or in my own name?`, answer: `There is no universal answer, since it turns on your tax band and how much you borrow. A personally held property is taxed at income tax rates of 20-45% with only 20% relief on mortgage interest (22-47% with 22% relief from 6 April 2027 in England, Wales and Northern Ireland), so a higher-rate landlord with a large loan pays tax on money that went to the lender. A company pays Corporation Tax at 19-25% after deducting that interest in full, typically saving £2,000-£5,000 a year per property. Incorporation costs £100-£300 and accountancy £800-£1,500 a year, which is why the route usually makes sense from around 3+ properties.` },
    { question: `What deposit do I need for a buy-to-let mortgage?`, answer: `Typically 25%, giving a 75% LTV ceiling. Experienced landlords occasionally reach 80% LTV on a 20% deposit, and a few specialist lenders stretch to 85% at much higher rates. Limited company lending sits at the same 75% cap. Houses in multiple occupation and multi-unit blocks need 30-40% down. First-time landlords face stricter terms, often a 25-30% deposit, personal income of £25-£30k+, and sometimes a requirement to live in the area or show property management experience.` },
    { question: `How much extra stamp duty do I pay on a buy-to-let?`, answer: `Additional properties attract the standard Stamp Duty Land Tax rates plus a surcharge of 5%, raised from 3% in October 2024. That is cash payable on completion, sitting on top of a deposit that is usually 25% of the price, so the upfront requirement is far heavier than on a residential purchase. It also drags on the return, because money spent on tax is capital that never earns rent.` },
  ],
  'house-price-sqft-calculator': [
    { question: `How do you work out the price per square foot of a house?`, answer: `Divide the asking price by the total internal floor area in square feet, so a £300,000 home measuring 1,000 sq ft works out at £300 per square foot. If the particulars quote metres, convert first. The figure only earns its keep when you compare it with recent sales of similar homes on nearby streets, rather than against a national average that blends the whole country together.` },
    { question: `What counts as a good price per square foot?`, answer: `It depends entirely on where you are looking. The national average is roughly £260-£320/sqft, so a figure below that looks keen nationally yet would be extraordinary in London, where £700+/sqft is normal and £1,000+/sqft marks prime stock. Under £400/sqft in the outer London zones is genuinely good value, while in Liverpool, where the range is £140-£240/sqft, the same number would be steep. Benchmark against comparable streets, not headlines.` },
    { question: `Why are new-build homes in the UK so small?`, answer: `The average new-build completed in 2024 measured 76 m², or 818 sqft, the smallest in Europe. France averages 113 m², equal to 1,216 sqft, and Germany 109 m² or 1,173 sqft. The reason is commercial, because UK developers maximise the number of homes they can fit on a plot. London is tighter again, with two-bed flats averaging 60-70 m². Older housing gives more room per pound, with a 1930s semi at 80-100 m² and a Victorian terrace at 90-130 m².` },
    { question: `How do I convert square metres to square feet?`, answer: `Multiply the square metres by 10.764. A 120 sq m property is therefore 1,292 sq ft, and at £425,000 that works out at £329 per square foot, or £3,542 per square metre. UK particulars have historically used square feet while newer listings often quote metres, so converting before you compare keeps you from measuring one property against another on a different scale.` },
  ],
  'lease-extension-calculator': [
    { question: `What makes up the premium for extending a lease?`, answer: `Three parts make up the premium: the landlord's lost ground rent over the remaining term, the lost reversion, meaning the property's value when the lease expires, and half of the marriage value the extension creates. The capitalisation and deferment rates applied to the first two are matters of professional judgement, which is why two valuers can reach different figures on the same flat.` },
    { question: `Why should I extend before the lease drops below 80 years?`, answer: `Below 80 years the freeholder becomes entitled to marriage value, half of the uplift the extension creates, and that single element reshapes the bill. On a £400k flat the premium is around £8,000 with 80 years left, £15,000-£25,000 once the lease has fallen to 70 years, and £40,000-£70,000 at 50 years. Since the lease shortens by a year every year, the deadline arrives quietly, and many leaseholders only check the number when a sale or remortgage forces them to.` },
    { question: `What is the difference between a statutory and an informal lease extension?`, answer: `The statutory route runs on a Section 42 notice under the Leasehold Reform, Housing and Urban Development Act 1993. It adds 90 years to your current term and cuts the ground rent to a peppercorn, though you need to have owned the flat for 2+ years to qualify. An informal extension is a private deal with the freeholder, often a fresh 99-year lease replacing the existing one, typically cheaper up front but leaving you paying ground rent throughout.` },
    { question: `Will the 2024 leasehold reforms make extensions cheaper?`, answer: `That is the intention. The Leasehold and Freehold Reform Act 2024 took royal assent in May 2024, with full implementation expected in 2026, and it abolishes marriage value, lengthens the statutory addition to 990 years and brings in peppercorn ground rents. For a lease with 80+ years still to run, holding on until implementation could cut the cost by 30-50%. Where the lease is already near the 80-year line, waiting risks far more than the reform would save.` },
  ],
  'student-loan-interest-calculator': [
    { question: `How is the interest rate on my Plan 2 student loan set?`, answer: `It runs from RPI up to RPI plus 3%, depending on what you earn, subject to an overall 6% ceiling. While you are studying it sits at the top of that range. After graduation it scales, so income of £29,385 or below attracts RPI alone and income of £52,885 or above attracts the maximum, with a sliding margin between the two. With RPI at 4.1% from 1 September 2026 that means 4.1% at the bottom and the capped 6% at the top. Plan 5 works differently, with interest capped at RPI and no income-based margin at all.` },
    { question: `Why does my student loan balance keep growing?`, answer: `Because the repayment is set by income rather than by the balance. On Plan 2 with £45,000 outstanding and a £35,000 salary, the deduction is (£35,000 − £29,385) × 9% ÷ 12, which is £42.11 a month or £505.35 a year. Interest at roughly 4.55% on £45,000 comes to about £2,049 over the same period, so the balance climbs by about £1,544 a year. For many graduates that continues until the loan is written off.` },
    { question: `What are the repayment thresholds for each student loan plan?`, answer: `Plan 1 takes 9% of income above £26,900 and Plan 2 takes 9% above £29,385. Plan 4, for Scottish borrowers, has the highest threshold at £33,795, while Plan 5 starts at £25,000. A Postgraduate Loan takes 6% above £21,000 and sits on top of any undergraduate deduction, so both can run at once and take 15% of income above the shared threshold.` },
    { question: `Is Plan 5 cheaper overall than Plan 2?`, answer: `Not necessarily, despite the lower interest rate. A £45k career earner with a £50k starting loan repays around £1,405 a year on Plan 2, roughly £117 a month, and with a 30-year write-off pays back about £60-£80k. On Plan 5 the £25k threshold lifts the annual deduction to £1,800 and the 40-year term keeps the deduction running for another decade, pushing the lifetime total towards £90-£120k.` },
    { question: `How much interest builds up while I am still studying?`, answer: `More than most students expect, because interest starts on the day each instalment is paid out. A £40,000 loan gathers roughly £1,640 in its first year on Plan 5, where the rate is RPI only, and up to £2,400 on Plan 2, where studying attracts RPI plus 3% subject to the 6% ceiling. Across a 4-year course the balance at graduation, including accrued interest, is typically £55,000-£75,000.` },
  ],
  'debt-consolidation-calculator': [
    { question: `Will consolidating my debts actually save me money?`, answer: `Only when the new loan's interest rate is lower than the weighted average rate across your existing credit cards, overdrafts and store cards, and when you compare total interest over the full term rather than just the monthly figure. Moving an £8,000 debt onto a 4-year loan at 7.9% can cut the monthly outgoing and still save interest, as the worked example shows, but a longer term at a similar rate simply spreads the cost. The single monthly payment simplifies things either way.` },
    { question: `Is a 0% balance transfer card better than a consolidation loan?`, answer: `For credit card debt of £3,000-£10,000 it often is. Balance transfer cards offer 24-32 months at 0% for a one-off fee of about 2.9-3.9% of the balance, so a £10,000 transfer at 3% costs £300, and paying £360 a month clears it within the 28 months of the promotion. You need a good credit score, the balance should stay under 90% of the card limit, and you must clear it before the 0% period ends or the standard rate applies to whatever is left.` },
    { question: `Should I use a secured homeowner loan to consolidate debts?`, answer: `Secured loans are cheaper, typically 6-12% APR against 7-15% for an unsecured loan with good credit, but they turn unsecured card and overdraft debt into debt secured on your home. If you default, you can lose the property. Homeowners in negative equity cannot use this route at all, and anyone whose spending habits have not changed risks rebuilding the card balances while still carrying the secured loan.` },
    { question: `Where can I get free debt advice in the UK?`, answer: `StepChange, the largest UK debt charity, can be reached on 0800 138 1111, and National Debtline on 0808 808 4000. Citizens Advice and PayPlan also offer free help. All of them can set up Debt Management Plans, arrange an IVA or advise on bankruptcy and Debt Relief Orders at no cost to you. Commercial debt management companies charge 15-30% of your repayments as fees for the same service, so avoid them as a first port of call.` },
  ],
  'postgraduate-loan-calculator': [
    { question: `Do I repay a postgraduate loan on top of my undergraduate one?`, answer: `Yes, they are separate deductions taken at the same time. The postgraduate loan takes 6% of income above £21,000 while an undergraduate loan takes 9% above its own threshold, so together they can reach 15% of earnings above the two thresholds. On a £40k salary with a Plan 5 loan that comes to £1,350 and £1,140, or £2,490 a year, which is a net £207 a month off your pay.` },
    { question: `How much can I borrow for a Master's degree?`, answer: `Up to £13,206 for 2026/27, paid as a single loan covering both tuition and living costs rather than split between the two. There is no means-testing on household income, so the full amount is open to anyone eligible, meaning under 60, resident in the UK and taking a first Master's. Doctoral study runs on a different scheme, with a Doctoral Loan of up to £31,122 spread over 3 years.` },
    { question: `Does the postgraduate loan cover the full cost of a Master's?`, answer: `Usually not. Tuition often runs £8-£15k and living costs add £10k+, so a realistic total of £18-£25k sits well above the £13k maximum. The gap is normally filled with scholarships, employer sponsorship, savings, a career development loan or family help, and studentships if you are heading for a PhD. Applications open through gov.uk from May for a course starting in September, which leaves time to line the rest up.` },
    { question: `Is a Master's worth the debt in earnings terms?`, answer: `UK Master's graduates typically earn £4,000-£10,000 a year more than equivalent undergraduate-only peers, and the lifetime premium ranges from £100k-£400k. The field matters more than the average. STEM, finance, law and medicine tend to pay back a £13k loan plus a £5k contribution within 2-5 years, while humanities and arts can take 8-15 years. Graduates on £40k+ generally clear the balance and interest within 15-20 years.` },
  ],
  'epc-calculator': [
    { question: `When do I need an EPC for my property?`, answer: `You need one whenever you sell or let a property in England and Wales, and when a new property is built. It grades energy efficiency from A down to G on a 1 to 100 scale, taking in the construction, insulation, heating system, lighting and any renewable features, and it stays valid for 10 years.` },
    { question: `What EPC rating do I need to let out a property?`, answer: `The current legal minimum for a rental is Band E. F and G rated homes have been barred from letting under the Minimum Energy Efficiency Standards since 2018 and cannot be let until they are improved. The government confirmed in January 2026 that all privately rented homes must reach Band C by 1 October 2030, one deadline for new and existing tenancies, with landlords' required spending capped at £10,000 per property.` },
    { question: `Which improvements raise an EPC rating for the least money?`, answer: `Insulation gives the most bands per pound. Loft insulation costs a few hundred pounds and cavity wall insulation £500-£1,500, and together they often move a home up a band. LED lighting costs about £100 for around half a band. Solar panels (£6-£9k) add 1-2 bands and a heat pump (£10-£15k) adds 1-3 bands, so they move the score further but at a far higher cost per band.` },
    { question: `Are there grants to help pay for EPC improvements?`, answer: `Yes. The Boiler Upgrade Scheme pays £7,500 towards a heat pump. ECO4 is winding down during 2026 and the Great British Insulation Scheme closed on 31 March 2026, so the main route now is the Warm Homes: Local Grant, run by councils in England for privately owned and privately rented homes rated D to G where household income is usually £36,000 or less. Your local council can check eligibility.` },
    { question: `How does a low EPC rating affect selling or getting a mortgage?`, answer: `RICS data suggests a low EPC knocks 2-5% off a property's value at sale. Lenders are increasingly reluctant to offer mortgages on F and G rated homes and some refuse them altogether, which shrinks the pool of buyers. A poor rating also leaves the owner exposed to future tightening of the minimum standards.` },
  ],
  'bathroom-cost-calculator': [
    { question: `How much does a new bathroom cost in the UK?`, answer: `A basic refit that keeps the existing layout runs £3,000 to £6,000, a mid-range project £8,000 to £15,000, and a luxury finish with a freestanding bath or underfloor heating £15,000 to £25,000 and beyond. Measured by area, that is £1,500 to £4,000 per m². The Which? survey put the average British refit in 2026 at £6,500, which is about what a mid-range room costs once labour is counted.` },
    { question: `What makes a bathroom refit cost more than expected?`, answer: `Changing the layout is the usual culprit, because relocating waste pipes and water supply is slow, disruptive work. Structural jobs come next, such as strengthening a floor to take a cast-iron bath. A wet room needs the whole floor tanked and level, adding £3,000 to £8,000, and a house with low mains pressure needs a pump at £200 to £500 before a decent shower will run at all.` },
    { question: `Do I need an electrician for bathroom lighting and heating?`, answer: `Yes. Electrical work in a bathroom falls under Building Regulations Part P and must be carried out by a qualified electrician, which takes in the extractor fan, a heated mirror and underfloor heating. Electric underfloor heating costs £40 to £80 per m² fitted and adds £400 to £800 to the project. An extractor with a humidity sensor is £80 to £200 and prevents mould work that later costs £500 to £2,000.` },
    { question: `Which tiles give the best value in a bathroom?`, answer: `Ceramic at £15 to £40 per m² is the budget choice, porcelain at £25 to £70 wears better, natural stone runs £40 to £120 and a mosaic feature £30 to £200. Allow another £100 to £300 for adhesive and grout. Tiling to half height with paint above cuts the tile bill by 30 to 40%, but the shower zone has to be tiled fully, with water-resistant adhesive and epoxy grout.` },
  ],
  'kitchen-cost-calculator': [
    { question: `How much does a new kitchen cost in the UK?`, answer: `Budget kitchens with flat-pack units and laminate worktops land between £5,000 and £10,000, mid-range fit-outs with solid-wood doors and quartz run £10,000 to £20,000, and premium bespoke work can top £25,000 to £40,000. Fitting is charged on top at £3,000 to £8,000. The Which? survey put the average British kitchen in 2026 at £12,500, which works out at £700 to £3,000 per linear metre of run.` },
    { question: `Which worktop material lasts longest for the money?`, answer: `Quartz is usually the answer, at £200 to £500 per m² with a life beyond 25 years and good resistance to stains. Laminate at £25 to £80 is far cheaper but lasts 8 to 15 years. Granite at £150 to £500 is harder still, though it stains if the sealer fails, marble at £250 to £700 scratches, and solid wood at £80 to £200 needs oiling to survive daily use.` },
    { question: `What costs get missed when budgeting a kitchen refit?`, answer: `Everything around the units. Plumbing alterations are £400 to £1,500, electrical work £800 to £3,000, plastering after the strip-out £400 to £1,500, flooring £1,500 to £4,000, a splashback £300 to £2,000, lighting £500 to £2,000, decoration £400 to £1,500 and a skip £200 to £400. Adding 15 to 25% to the quoted price covers most of it, and the room stays unusable for 2 to 4 weeks.` },
    { question: `Can I just replace the kitchen doors instead?`, answer: `Where the carcasses are sound, new doors cost £1,500 to £3,000 against £8,000 and up for a full set of units, and the result looks new from the outside. Pair that with LVT flooring at 30 to 50% of wood prices and B&Q LED downlights at £5 to £15 rather than £50 designer fittings, then put the saving into the worktop, sink and taps.` },
  ],
  'timber-calculator': [
    { question: `How do board feet convert to metric for UK timber?`, answer: `Structural timber here is normally sold by the linear metre, or by the cubic metre in bulk, while one board foot from a North American plan equals 0.00236 m³. If you are working from an imported drawing, convert the volume first and then check the section against British stock sizes, which include 47 by 100 mm C16 joists, 47 by 150 mm and 47 by 200 mm.` },
    { question: `What is the difference between C16 and C24 timber?`, answer: `Both are strength grades under BS EN 14081. C16 is the standard load-bearing grade for general structural work, while C24 is stronger and specified where joists or rafters carry longer spans. Grade says nothing about durability outdoors, which is a separate question: external timber is pressure-treated to BS 8417, at Use Class 3 above ground or Use Class 4 in ground contact, and green Tanalised stock carries a 15 to 30 year rating.` },
    { question: `How many studs do I need for a partition wall?`, answer: `Divide the wall length by the stud spacing and add one, then allow top and bottom plates at twice the wall length. A wall 3.6 m long at 600 mm centres comes out at 7 studs, and at 2.4 m high that is 16.8 m of timber plus 7.2 m of plates, so 24 m of 100 by 47 mm CLS. Add 10 to 15% for waste, plus a header and doubled studs at any doorway.` },
    { question: `What does structural timber cost at UK merchants now?`, answer: `A 2.4 m length of 38 by 89 mm CLS is £4 to £8, C16 47 by 100 mm in 3 m runs £8 to £14, and C24 47 by 150 mm in 4.2 m £20 to £35. Decking boards of 32 by 144 mm cost £15 to £25 each, 18 mm plywood sheets £40 to £70 and 18 mm OSB £25 to £40. Prices climbed 30 to 50% through 2021 and 2022 before settling down again.` },
  ],
  'underfloor-heating-calculator': [
    { question: `Should I choose wet or electric underfloor heating?`, answer: `Wet systems pipe warm water from a boiler or heat pump through the floor and suit whole-house heating, especially in a new build or extension where the screed is being laid anyway. Electric cables or mats work out better for a single room such as a bathroom or kitchen, because they are cheaper to install and add very little to the floor height. The calculator weighs both against install cost and running cost so you can see which wins for your room.` },
    { question: `How much does electric underfloor heating cost to run per day?`, answer: `It depends on the wattage, the hours of use and your tariff. At 26.32p/kWh, a typical 100W/m² system running 4 hours a day in a 30 m² room uses 12 kWh and costs about £3.16 a day, which is why electric UFH is rarely used for whole-house heating. A small bathroom mat drawing 200W for 1 hour a day costs roughly 5p, so occasional use in one room is cheap.` },
    { question: `Can wet underfloor heating be retrofitted into an existing house?`, answer: `It is possible but often impractical. A wet system needs 50-65mm of screed on top of insulation, so floor levels rise by 80-100mm, which causes problems with door clearances and stairs. That is why wet UFH is normally fitted during a new build or major renovation. For an existing bathroom, an electric mat retrofit of 5-10 m² typically costs £400-£900 fitted and barely changes the floor height.` },
    { question: `Which floor covering works best over underfloor heating?`, answer: `Tile and stone are best, because their high thermal conductivity spreads heat evenly. Engineered wood is designed for the stability UFH demands, and LVT gives excellent conductivity with comfort underfoot. Laminate is usable with a UFH-rated underlay, while solid wood is not ideal because it expands and contracts. Carpet is the worst option, acting as an insulating layer that cuts heat output by 30-50%. Always check the manufacturer's UFH compatibility first.` },
    { question: `Is underfloor heating more efficient with a heat pump than a gas boiler?`, answer: `Yes. UFH runs at 35-45 C rather than the 60-80 C radiators need, which is exactly the range a heat pump delivers efficiently. A wet system on a heat pump costs 50-70% less to run than the same floor fed by a gas boiler. On a gas boiler, wet UFH costs about the same as radiators but feels more comfortable. The best combination is wet UFH with a heat pump in a well-insulated home.` },
  ],
  'student-allowance-calculator': [
    { question: `What makes up my total student finance package?`, answer: `Your funding usually stacks a tuition fee loan of up to £9,790 for 2026/27, paid straight to the university, a means-tested maintenance loan paid to you, and any grants or bursaries you qualify for. Some students also receive Disabled Students' Allowances or a Childcare Grant. The tuition fee loan is not means-tested, so household income affects only the maintenance loan and the grants sitting alongside it.` },
    { question: `Which parts of my student finance do I have to repay?`, answer: `Loans are repayable and grants are not. The tuition fee loan and the maintenance loan both have to be paid back once you are earning, whereas an NHS Bursary, Disabled Students' Allowance, the care leaver package, hardship fund awards and merit scholarships are yours to keep. Since the tuition fee loan goes straight to the university, the money actually reaching your account is the maintenance loan plus any grants, in three termly instalments.` },
    { question: `Can I claim an NHS bursary as well as a maintenance loan?`, answer: `Yes. Nursing, midwifery and allied health students in England get the NHS Learning Support Fund, a £5,000 a year training grant that sits alongside student finance rather than replacing it, and medical and dental students receive the NHS Bursary in later years, up to £3,447 a year means-tested in London plus a £1,081 grant. Disabled Students' Allowance works the same way, covering equipment and support up to £27,783 a year, and care leavers have a separate package worth up to £14,000.` },
    { question: `How much of my living costs does the maintenance loan cover?`, answer: `Usually 60 to 90% of them. Living costs run to £8,000 to £12,000 a year outside London and £10,000 to £14,000 in London, against a maximum loan of £10,830 outside London and £14,135 inside it. Rent decides the outcome, at £4,500 to £10,500 for halls or £4,000 to £9,000 in private accommodation, and anything left uncovered has to come from work, family support or savings.` },
  ],
  'night-shift-calculator': [
    { question: `Do I have a legal right to extra pay for night shifts?`, answer: `There is no statutory right to enhanced night pay in the UK, so any premium comes down to your contract. Common top-ups run from roughly 10% to a third. NHS Agenda for Change staff get time plus 30% for night hours in Bands 4 to 9, rising to 35% in Band 3, 41% in Band 2 and 47% in Band 1, fire and police roles tend to add 25%, and warehouse work often uses a flat uplift of £1 to £3 an hour instead. The National Living Wage applies whatever the hour, so the premium builds on top of it.` },
    { question: `What counts as night work under UK law?`, answer: `The Working Time Regulations 1998 define the night period as 11pm to 6am, and you are a night worker if you normally work at least three hours within it. That means a regular rota rather than an occasional late finish. The distinction matters because night worker status is what brings in the extra entitlements, including the hours cap and the right to a health assessment paid for by your employer.` },
    { question: `How many hours can I be made to work on night shifts?`, answer: `Night working is limited to an average of 8 hours in any 24-hour period, averaged over 17 weeks, so a run of longer shifts has to be balanced out. You are also entitled to 11 hours of rest between shifts, 24 hours off each week, and one uninterrupted 20-minute break when you work more than 6 hours (30 minutes after 4.5 hours if you are under 18). If night work is damaging your health, you have the right to transfer to day work, and pregnant workers can require a transfer or paid leave.` },
    { question: `Is my night shift premium taxed differently?`, answer: `No. The premium is treated as ordinary earnings, so income tax and NI come off it exactly as they do from your basic pay, and it counts for pension auto-enrolment too. State Pension contributions accrue normally, and night premiums count in the average weekly earnings used for Statutory Sick Pay, paid from the first day of sickness at £123.25 a week or 80% of those earnings if lower. Travel or meal costs may attract relief when the site is not your normal workplace.` },
  ],
  'benefits-in-kind-calculator': [
    { question: `How is tax on company benefits like medical insurance worked out?`, answer: `HMRC turns each benefit into a cash equivalent value and taxes it at your marginal rate, with the valuation method set per benefit under the Income Tax (Earnings and Pensions) Act 2003. For medical cover the cash equivalent is simply the premium your employer pays. Your employer reports the figures on a P11D each year, and your tax code is adjusted to collect what is owed through PAYE, which is why a new benefit often shows up as a code change rather than a bill.` },
    { question: `How much company car tax will I pay on an electric car?`, answer: `Zero-emission cars are charged at 4% of list price for 2026/27, up from 3% in 2025/26 and 2% before April 2025, then 5% in 2027/28 and eventually 7% and 9%. On a £40k electric car the benefit is £1,600, giving an annual tax bill of £320 at basic rate, £640 at higher rate and £720 at additional rate. A £40k petrol car emitting 180g/km falls on 30% instead, a £12,000 benefit and £2,400 to £5,400 of tax.` },
    { question: `Which employee benefits are completely tax-free?`, answer: `Employer pension contributions, one mobile phone, the £6 a week homeworking allowance, a cycle to work bike and accessories, eye tests for screen users, flu vaccinations, workplace parking, a workplace nursery place and some training all escape the charge. Annual staff events are exempt up to £150 a head a year, and long service awards after 20 years are worth £50 per year of service up to £1,000. A second mobile phone, gym membership and most other employer-funded perks are taxable.` },
    { question: `When does my employer report benefits to HMRC?`, answer: `The P11D for each employee and the P11D(b) summary are due by 6 July following the end of the tax year, after which HMRC adjusts your tax code in the next year to collect what is owed. Section 336 changes that from 2026, moving collection into payroll in real time and removing the lag between receiving a benefit and paying tax on it. A significant benefit can also pull you into Self Assessment even where payroll is already collecting the tax.` },
  ],
  'regular-savings-calculator': [
    { question: `Why does a regular saver pay less than its headline rate?`, answer: `Because each monthly deposit sits in the account for a different spell. The first earns a full 12 months of interest while the last earns only one, so the effective return on your total works out at roughly half the advertised rate. Regular savers usually take fixed payments of £1 to £500 a month.` },
    { question: `Which UK banks pay the best regular saver rates in 2026?`, answer: `The top rates go to existing customers. First Direct pays 7% on £25 to £300 a month, the Nationwide Flex Regular Saver 6.5% on up to £200, the Lloyds Club account 6.25% on £25 to £400, and HSBC 5% to its own customers. Accounts open to anyone, from Atom, Coventry Building Society or Skipton, sit nearer 4% to 5%. Cash ISA regular savers pay a similar range tax-free.` },
    { question: `Can I have more than one regular saver at the same time?`, answer: `Yes, generally one per institution, and stacking them is a common tactic. Running accounts at First Direct, Nationwide, Lloyds and HSBC at £200 to £400 a month each puts £800 to £1,500 a month to work, worth perhaps £400 to £800 a year more than standard savings. Each usually requires a current account with that bank, most wanting £500 to £2,000 paid in monthly.` },
    { question: `What happens to my regular saver after 12 months?`, answer: `The promotional term ends and the account normally reverts to the bank's standard saver rate, which can be as low as 0.5% or 1%. That makes a diary note at the 12-month mark worth setting, so the balance can be moved rather than left earning almost nothing. A Cash ISA paying 4% to 5% on the full £20,000 allowance is the usual next step.` },
  ],
  'business-mileage-calculator': [
    { question: `Will the 55p mileage rate cover my actual running costs?`, answer: `For cars and vans, HMRC lets your employer reimburse 55p a mile on the first 10,000 business miles and 25p a mile after that, all free of tax. Those rates are meant to cover fuel, insurance, wear and tear and depreciation, so whether you come out ahead depends on your own costs. The first-10,000 rate went up from 45p on 6 April 2026, the first change since 2011, which narrowed the gap for most drivers.` },
    { question: `What can I claim if my employer pays less than 55p a mile?`, answer: `You can claim Mileage Allowance Relief on the difference. Take the AMAP value of your business miles, subtract what your employer actually reimbursed, and claim tax relief on the shortfall using form P87 online or through your Self Assessment return. HMRC can also give the relief by adjusting your tax code. If your employer pays above the approved rates instead, the excess is treated as a taxable benefit and appears on your P11D.` },
    { question: `Does driving to work count as business mileage?`, answer: `No. The journey between home and your permanent workplace is ordinary commuting and never qualifies, no matter how long it takes. Business mileage covers travel between offices, to client sites, to training and to meetings away from your normal base, plus travel to a temporary workplace where the assignment is expected to last under 24 months. If you divert from your commute for business, only the additional miles beyond the commute can be claimed.` },
    { question: `What mileage records does HMRC expect me to keep?`, answer: `A log entry for every journey showing the date, start and end postcodes, the business purpose and the distance, kept for 5 years after the relevant return is filed. HMRC asks for samples during compliance checks, and rounded approximations put together later will not stand up. Apps like MileIQ, TripLog and QuickBooks Self-Employed record trips automatically using GPS for around £5 to £10 a month, which is usually cheaper than the time spent reconstructing a year of driving.` },
  ],
  'wealth-growth-calculator': [
    { question: `How does the projector handle money split across a pension, ISA and savings?`, answer: `Starting from your current net worth, the model adds monthly contributions across pension, ISA and general savings, applies a different growth rate to each portion, and rolls the total forward year by year. Pension contributions get a tax relief uplift and ISA growth is treated as tax-free. Salary rises, windfalls, a shift from equities into bonds with age and the contribution limits are all reflected.` },
    { question: `Why is the first £100,000 the hardest to reach?`, answer: `Compound growth on a small base adds very little, so almost all the early progress comes from what you pay in. At £500 a month growing at 7%, the first £100,000 takes roughly 11 years, the second only 6 more and the third about 4. The pot does more of the work as it gets larger, which is why the early years feel disproportionately slow.` },
    { question: `What annual return should I assume for a UK portfolio?`, answer: `History gives a reasonable baseline. The FTSE All-Share has returned about 7% to 9% a year in total return terms over 30 years and more, with the S&P 500 nearer 10%. UK property has produced 4% to 6% real, gilts 3% to 5% nominal and cash 2% to 4% nominal. A mix of 60% equities and 40% bonds sits at 5% to 7% nominal. None of it is guaranteed, but long averages beat guesswork.` },
    { question: `How big a pension pot do I need to retire comfortably?`, answer: `The Retirement Living Standards from Pensions UK (formerly the PLSA), updated in June 2026, put a comfortable retirement at £45,400 a year for a single person and £62,700 for a couple, with a moderate lifestyle at £32,700 and £45,400. Using a 4% drawdown rule, £25k of income needs about £625k and £40k needs roughly £1M. The full new State Pension covers £12,547.60 of that, and the average pot at 65 was £107,300 according to DWP figures for 2023.` },
  ],
  'cgt-on-shares-calculator': [
    { question: `When I sell shares, what counts as my cost basis?`, answer: `All shares of the same class in one company are pooled together under section 104 of TCGA 1992, giving a single average cost per share. When you sell, the gain is the sale proceeds minus that pooled average cost multiplied by the number of shares sold. Broker commission and the stamp duty paid on purchase come off as allowable expenses.` },
    { question: `What rate of capital gains tax do I pay on shares?`, answer: `The first £3,000 of gains each tax year is free under the annual exempt amount. Beyond that, gains sitting within your basic-rate band are taxed at 18% and anything above it at 24%, the rates in force since 30 October 2024. Gains stack on top of income, so one disposal can be taxed partly at each rate where it crosses the basic-rate limit.` },
    { question: `What is the 30-day bed and breakfasting rule?`, answer: `If you sell shares and buy the same type back within the following 30 days, the disposal is matched against that repurchase rather than against the section 104 pool. It stops people banking a loss on paper while keeping the holding. Sales are matched first against same-day purchases, then against the 30-day window, and only then against the pooled average cost.` },
    { question: `Can I carry a loss on shares forward to a later tax year?`, answer: `Yes. Losses first offset gains made in the same tax year, and anything left over carries forward indefinitely against future gains. The condition is that you claim the loss within 4 years of the end of the tax year in which it arose, through Self Assessment. Only realised disposals count, so a holding that has fallen in value but has not been sold gives you nothing to claim.` },
  ],
  'dividend-income-calculator': [
    { question: `How do I estimate the dividends my portfolio will pay?`, answer: `At a 4% yield, a £100,000 portfolio pays around £4,000 a year, worked out as shares multiplied by dividend per share, or the yield applied to the total value. Yields vary widely, from under 1% on growth stocks to about 3.4% forecast for the FTSE 100 as a whole in 2026 (AJ Bell Dividend Dashboard, June 2026) and above 6% on some high-yield investment trusts.` },
    { question: `How much tax will I pay on £8,000 of dividends?`, answer: `It depends on your other income. A higher-rate taxpayer on a £60,000 salary with a £200,000 portfolio yielding 4% receives £8,000 in dividends. The first £500 is covered by the allowance, leaving £7,500 taxable at the higher dividend rate of 35.75%, which comes to £2,681.25. A basic-rate taxpayer would pay 10.75% on the part that still fits inside the basic band.` },
    { question: `Is it better for a company director to take salary or dividends?`, answer: `A £12,570 salary uses the personal allowance with no income tax or employee NI, but employer NI at 15% applies above £5,000, costing the company £1,135.50, and a company whose only employee is the director cannot claim the Employment Allowance. Above £12,570, 8% employee and 15% employer NI combine to 23%, and dividends carry no NI at all. On £80,000 of profit before the director's pay, a £12,570 salary and its employer NI leave £66,294.50 of taxable profit, corporation tax with marginal relief takes £13,818.04, and the £52,476.46 paid as dividends bears £9,281.58 of dividend tax, leaving about £55,760. The all-salary route leaves about £51,280, roughly £4,480 less.` },
    { question: `Do dividends inside an ISA count towards the £500 allowance?`, answer: `No. Dividends paid inside a Stocks and Shares ISA or a pension are tax-free permanently, do not use any part of the £500 dividend allowance, and do not push your other income into a higher band. A £50,000 ISA yielding 4% pays £2,000 a year with nothing to declare, where the same holding outside a wrapper would leave £1,500 taxable.` },
  ],
  'non-dom-tax-calculator': [
    { question: `Who qualifies for the four-year foreign income exemption?`, answer: `People in their first four years of UK residence after at least ten tax years of non-residence. They can claim to pay no UK tax on foreign income and foreign gains for those years, at the cost of the Personal Allowance and the Capital Gains Tax annual exempt amount for each year they claim. Anyone who arrived in 2022/23 or later after such a gap can use the years left from 2025/26. There is no domicile test, so returning British nationals qualify too, while existing long-term residents fall outside it.` },
    { question: `What happens after the four years of FIG protection end?`, answer: `From the fifth year of UK residence, worldwide income and gains are taxable in the UK in the ordinary way, with no remittance basis to fall back on. Some people plan to leave before that point, others accept the change and stay. The Temporary Repatriation Facility separately allows foreign income and gains from the old remittance basis years to be brought in at 12% in 2025/26 and 2026/27, rising to 15% in 2027/28, after which it closes on 5 April 2028.` },
    { question: `Does the new regime change Inheritance Tax for non-doms?`, answer: `Yes, and it is arguably the bigger change. Inheritance Tax now follows residence rather than domicile. Anyone UK resident for at least ten of the previous twenty years is liable on worldwide assets, where a non-domiciled person used to be liable only on UK assets. The liability does not end the day you leave either. It runs on for 3 years after 10 to 13 years of residence, one more year for each further year, up to 10 years for someone resident for 20 years or more.` },
    { question: `Can I bring foreign money into the UK under FIG?`, answer: `Yes, freely. Under the four-year regime the exemption depends on where the income arose, not on whether you remit it, so foreign income and gains can be brought into the UK and spent here without triggering a charge. That is the main practical difference from the old remittance basis, which taxed the money once it entered the country. Keep records showing the foreign source, because that is what the exemption rests on.` },
  ],
  'annual-investment-allowance-calculator': [
    { question: `When is spending on plant and machinery fully deductible?`, answer: `Under the Annual Investment Allowance, qualifying plant and machinery is 100% deductible from taxable profits in the year you buy it, up to £1,000,000 of spend per year per business. That covers machinery, tools, computers, software, office furniture, vans, lorries and certain fixtures, second-hand or new, bought by a sole trader, partnership or limited company. The claim has to be made on your Self Assessment return or CT600. Spend above the cap can still get full expensing or a first-year allowance if the assets are new and qualify, and anything else moves into the writing down allowance pools at 14% or 6%.` },
    { question: `Can I claim AIA on a car bought for my business?`, answer: `No. Cars are excluded from the Annual Investment Allowance, so a car bought through the business goes into the capital allowance pools instead, at 14% for the main rate or 6% for the special rate, and the relief is spread over years. The exception is new zero-emission cars, which get a 100% First Year Allowance if bought by 31 March 2027 for Corporation Tax or 5 April 2027 for Income Tax. Claiming AIA on a car is one of the most common AIA mistakes.` },
    { question: `How does Full Expensing differ from the Annual Investment Allowance?`, answer: `Full Expensing is open to companies only and has no £1M cap: main rate plant and machinery is 100% deductible in the first year, and special rate assets such as integral features get 50% up front then 6% reducing balance. It started on 1 April 2023 and was made permanent at the Autumn Statement 2023. AIA, by contrast, is available to sole traders and partnerships as well as companies but stops at £1,000,000 a year. Above that, sole traders and partnerships can claim a 40% first-year allowance on new main-rate plant bought from 1 January 2026. Cars are excluded from all three.` },
    { question: `What happens to the AIA limit if my accounting period is not 12 months?`, answer: `The £1,000,000 limit is scaled to the length of the period, so a 6-month accounting period carries a £500,000 limit, and a period that straddles two AIA limit periods is apportioned between them. If an asset is used partly for private purposes, the allowance is also reduced in proportion to the business use. Whatever the limit, spend above it is not lost: it can still get full expensing or a first-year allowance where it qualifies, or falls into the 14% or 6% writing down pools.` },
  ],
  'mortgage-interest-rate-calculator': [
    { question: `Why does a small rate change cost so much over a mortgage?`, answer: `Over a 25 or 30-year term, interest compounds every month on the gradually reducing balance, so even a small rate difference builds into a large gap in total cost. Payments follow a standard annuity formula based on the principal, the monthly rate and the number of repayments. On a £250,000 mortgage over 25 years, a 0.5% difference is worth about £74-£77 a month and £22,000-£23,000 across the term at today's rates of 5% to 6%.` },
    { question: `Is a mortgage arrangement fee worth paying for a lower rate?`, answer: `On a large loan it often is. A £999 fee attached to a 4.0% rate frequently beats a fee-free deal at 4.4%, because the rate applies to the whole balance every month while the fee is paid once. The honest comparison is total cost across the fixed period, meaning the monthly payment multiplied by the number of months, plus the product fee. On a smaller mortgage the same fee is harder to justify, since there is less balance for the lower rate to work on.` },
    { question: `What happens when my fixed rate ends?`, answer: `The mortgage reverts automatically to the lender's Standard Variable Rate, which averaged 7.13% in mid-September 2026 against 5.73% for an average two-year fix (Moneyfacts). A borrower who does nothing therefore pays considerably more from the month the deal expires. Switching earlier, while the fix is still running, can trigger an Early Repayment Charge, so the comparison worth making is the cost of that charge against the interest saved over the remaining period.` },
    { question: `Why do lenders test my mortgage at a higher rate than I will pay?`, answer: `Lenders check whether you could still pay if rates rose, usually by testing at 1-3 percentage points above the rate offered or at their reversion rate, so a 5.7% deal might be assessed at 6.7% to 8.7%. The Bank of England's fixed 3-point test was withdrawn in August 2022 and many lenders eased their stress rates in 2025, but the FCA still requires the check on deals fixed for less than five years. It hits first-time buyers near their affordability ceiling hardest, while higher earners with headroom barely notice it.` },
  ],
  'sipp-calculator': [
    { question: `How does tax relief top up what I pay into a SIPP?`, answer: `Pay in £800 and the provider reclaims 20% basic rate relief from HMRC to make it £1,000 gross in the pension. Higher and additional rate taxpayers claim a further 20% or 25% through self-assessment. The relief applies to whatever the SIPP then holds, whether that is funds, shares, ETFs, investment trusts or commercial property.` },
    { question: `What can I hold in a SIPP that a workplace pension will not allow?`, answer: `A workplace scheme normally limits you to 10 to 20 pre-selected funds. A SIPP opens up UK and international funds, individual shares, bonds, REITs and, on premium plans, commercial property. That range is the reason to pay the higher platform fee of 0.2 to 0.45% rather than the 0.1 to 0.3% a workplace scheme charges, and it tends to earn its keep only for investors who are genuinely interested and hold £20k or more.` },
    { question: `How much do SIPP platform fees actually cost?`, answer: `It depends on the provider and the size of the pot. Hargreaves Lansdown charges 0.35% on the first £250k (cut from 0.45% in March 2026) for a premium service, AJ Bell 0.25% and Vanguard 0.15%, though Vanguard offers only its own funds and works out cheapest below £80k. Interactive Investor uses a flat £12 a month, which beats percentage charging once a pot passes £50k. Fund charges sit on top of all of these, so compare the combined figure rather than the headline platform rate.` },
    { question: `When can I start taking money out of a SIPP?`, answer: `From 55 at present, rising to 57 in April 2028 under the Finance Act 2022. At that point you can take 25% as a tax-free lump sum and draw the rest as taxable income through flexi-access drawdown. There is no obligation to take anything at that age, and leaving the pot invested for longer shortens the number of years it later has to support.` },
  ],
  'tax-credits-calculator': [
    { question: `Can I still claim Working Tax Credit in 2026?`, answer: `No. Tax credits ended on 5 April 2025, when the remaining Working Tax Credit and Child Tax Credit claimants moved to Universal Credit, and no new claims had been accepted since 2019. For reference, the final 2024/25 rules required at least 30 hours of work a week for someone aged 25 to 59 without children, 16 hours for a lone parent, a disabled worker or anyone 60 or over, and 24 hours between a couple with children with one of them working 16. The basic element was £2,435 and the couple and lone parent element £2,500.` },
    { question: `What happens when I get a Migration Notice?`, answer: `Migration Notices were the DWP's formal instruction to move from tax credits onto Universal Credit, sent from 2024 and each giving 3 months to claim. Tax credits ended on 5 April 2025, so no more notices are being issued and nobody still receives Working Tax Credit or Child Tax Credit. If you missed your deadline or your circumstances have changed since, claim Universal Credit directly at gov.uk/universal-credit.` },
    { question: `Will my income drop when I move to Universal Credit?`, answer: `Transitional protection is designed to stop that happening. Your Universal Credit award cannot start below what your old benefits paid, and the difference is added as a top-up that erodes over time as UC rates rise. Migrating voluntarily before your notice arrives forfeits the protection. Once awarded, it ends if a joint claim becomes single or a single claim becomes joint, if earnings that started at or above the administrative earnings threshold fall below it for three assessment periods in a row, or if the award ends for any reason other than higher earnings. Waiting for the notice was the safer course, and protection already awarded continues until one of those events ends it.` },
    { question: `How is Child Tax Credit reduced by my income?`, answer: `Child Tax Credit paid £3,455 per child for the first two children (more only for children born before 6 April 2017 or where an exception applied), plus a family element of £545 if a child was born before that date, and the total, together with any Working Tax Credit, was then cut by 41% of household income above the relevant threshold. Under the final 2024/25 rules that threshold was £7,955 for anyone receiving both Working Tax Credit and Child Tax Credit, or £19,995 for Child Tax Credit only. A couple on £25,000 with 2 children, working 35 hours a week, lost £6,988.45 from a maximum entitlement of £13,405, leaving £6,416.55 for the year.` },
  ],
  'stocks-shares-isa-calculator': [
    { question: `What tax does a Stocks and Shares ISA actually save me?`, answer: `Up to £20,000 a year of investments sits free from income tax on dividends, capital gains tax on profits, and income tax on bond fund distributions. Returns are not guaranteed the way a Cash ISA is, though UK equities have averaged roughly 7 to 8% nominal over the long term.` },
    { question: `How much do platform and fund charges cost me over time?`, answer: `Charges are deducted as an annual percentage of the portfolio, combining a platform fee of 0.15% to 0.45% with a fund ongoing charge figure of 0.07% for a tracker up to over 1.5% for active management. On £100,000, the gap between 0.22% and 1.50% of total charges is about £1,280 a year, and compounded over decades that runs into tens of thousands of pounds.` },
    { question: `Should I use a Cash ISA or a Stocks and Shares ISA?`, answer: `For money you need within 5 years, a Cash ISA at 4% to 5% AER is the safer home. Over 10 years or more, equities have historically recovered from falls and gone on to beat cash. Across 25 years, £20k at 8% becomes roughly £137k against £67k at 4%, and that £70k gap is the reward for tolerating short-term volatility.` },
    { question: `Can I sell and rebuy inside an ISA without paying tax?`, answer: `Yes. There is no capital gains tax and no dividend tax inside the wrapper, so positions can be sold and the portfolio rebuilt with no tax consequence at all. Most platforms allow fund and share switches free of charge, which makes annual rebalancing straightforward. It is also what makes a bed and ISA move work, selling a taxable holding and rebuilding it inside the ISA.` },
  ],
  'epc-rating-comparison-calculator': [
    { question: `How much could a better EPC band save on energy bills?`, answer: `A Band C home typically costs £300 to £600 a year less to run than a Band D, and £600 to £1,200 less than a Band E. What you actually save depends on the property size, its heating system and local energy prices.` },
    { question: `What do the EPC bands from A to G actually mean?`, answer: `The scale is a points score. A is 92 and above, B is 81 to 91, C is 69 to 80, D is 55 to 68, E is 39 to 54, F is 21 to 38 and G is 1 to 20. D is the UK average, usually a post-1960s house with cavity wall insulation, while F and G are typically pre-1920s solid-wall homes that have never been retrofitted.` },
    { question: `Which upgrades raise an EPC rating the most?`, answer: `Solid wall insulation is the single largest gain at 15 to 25 points. Cavity wall insulation and double glazing add 5 to 10 points each, a condensing boiler and 270mm of loft insulation 3 to 7, a smart thermostat 2 to 3, LED bulbs 1 to 2 and a hot water tank jacket 1. Fitting a heat pump removes gas from the assessment and usually moves the property 2 to 3 bands.` },
    { question: `Do landlords have to reach EPC band C?`, answer: `Yes, by 1 October 2030. The government confirmed in January 2026 that every privately rented home must reach EPC C by that date, one deadline for new and existing tenancies, with landlords' required spending capped at £10,000 per property. Letting a property rated F or G has already been illegal since 2018, apart from limited exemptions, and councils can fine landlords who let non-compliant homes. That makes the current-to-potential gap on the certificate a buying consideration for landlords rather than a nicety.` },
    { question: `Does a higher EPC rating add to what a house is worth?`, answer: `Rightmove research from 2024 suggests each band improvement adds roughly 3 to 6% to a UK property price, and that a C-rated home commands a premium of 6 to 12% over a G-rated equivalent. That uplift is why the gap between a certificate's current and potential rating often matters more to a buyer than the current score on its own.` },
  ],
  'help-to-save-calculator': [
    { question: `Who can open a Help to Save account?`, answer: `Anyone on Universal Credit whose take-home pay was £1 or more in their last monthly assessment period is eligible, a rule that replaced the old test of 16 hours a week at the National Living Wage on 6 April 2025. The older Working Tax Credit route closed when tax credits moved to Universal Credit in April 2025. You cannot open an account once you reach state pension age, while in prison, or under certain immigration restrictions.` },
    { question: `How is the Help to Save bonus actually calculated?`, answer: `Two bonuses are paid, each worth 50% of a highest-balance figure rather than of what you deposited. The first, at the end of year 2, is 50% of the highest balance in months 1 to 24, so £50 a month gives a high point of £1,200 and a £600 bonus. The second, at year 4, is 50% of the growth in the highest balance since then, adding another £600 at the maximum.` },
    { question: `Does taking money out reduce my Help to Save bonus?`, answer: `You can withdraw at any time without losing eligibility, but it can cost you. Since both bonuses are measured against the highest balance reached, money taken out before a bonus is worked out lowers the figure it is based on. Once the year 2 bonus has been paid, a withdrawal cannot claw it back, though it still affects the highest balance used for the second calculation.` },
    { question: `What should I do when my Help to Save account closes?`, answer: `The account ends after four years, with up to £3,600 in it made up of £2,400 in deposits and £1,200 in bonuses. The usual next homes are a regular savings account, a Cash ISA, or a Lifetime ISA if you are under 40. With Cash ISA rates around 4% in 2026, nothing quite replaces a 50% bonus, so it is worth planning where the money works hardest next.` },
  ],
  'ns-i-savings-calculator': [
    { question: `How safe is money held with NS&I compared with a bank?`, answer: `Backed by HM Treasury, NS&I products carry a 100% government guarantee rather than the £120,000 FSCS limit that has covered ordinary bank deposits since 1 December 2025. The range spans Income Bonds, Direct Saver, Green Savings Bonds and Premium Bonds, each with its own rate and access rules.` },
    { question: `How does the Premium Bonds prize rate actually work?`, answer: `Every £1 buys a bond and an entry into the monthly draw, with holdings capped at £50,000. Prizes run from £25 up to two £1 million jackpots each month, and the September 2026 draw also paid 95 prizes of £100,000 and 192 of £50,000. The 4.35% prize rate, from the September 2026 draw, is an average, not a return you are owed, so most holders do worse. At odds of 21,000 to 1 per bond, a £50k holding averages about 2.4 wins a month.` },
    { question: `Do I pay tax on interest from NS&I accounts?`, answer: `It depends on the product. Premium Bond prizes are entirely tax-free, and the NS&I Direct ISA and Junior ISA are sheltered inside the ISA wrapper. Direct Saver, Income Bonds and British Savings Bonds pay interest gross with nothing deducted at source, so it counts against your Personal Savings Allowance of £1,000 at the basic rate or £500 at the higher rate, and is taxable above that. Savings tax rates rise by 2 points in every band from 6 April 2027.` },
    { question: `Is NS&I worth using if I have more than £120,000 saved?`, answer: `That is the case where it makes most sense. Bank deposits are protected only to £120,000 per institution, so larger sums have to be split across several banks to stay covered, whereas the Treasury guarantee behind NS&I has no ceiling. The trade-off is a rate typically 10% to 25% behind the best on the market, with Direct Saver at 3.75% against about 4.55% on the best easy access accounts in late September 2026.` },
  ],
  'bmi-children-calculator': [
    { question: `Does a child's BMI mean the same thing as an adult's?`, answer: `Not exactly. The sum is the same as for adults, weight in kg divided by height in m squared, but the result is plotted on age and sex specific growth charts to give a centile. Because what counts as healthy shifts as a child grows, no single number marks overweight or obese the way 18.5 and 25 do for adults.` },
    { question: `What do the centiles mean on a child's BMI chart?`, answer: `A centile shows how your child compares with others of the same age and sex. Above the 91st centile is classified as overweight and above the 98th as obese, while below the 2nd may indicate underweight, and everything in between is a healthy weight. A girl of 10 weighing 35 kg at 140 cm has a BMI of 17.9, which falls around the 65th centile and sits comfortably in the healthy range.` },
    { question: `What happens after the school weighs my child?`, answer: `Measurements are taken through the National Child Measurement Programme in Reception and again in Year 6, and the results go to parents. A result flagged as overweight or obese usually comes with an offer of support, whether that is a conversation with your GP or a local service such as HENRY for under-fives, MEND for ages 6 to 13, or Beezee Bodies. More severe cases can be referred on to an NHS Tier 3 paediatric weight management clinic.` },
    { question: `When should I take my child to the GP about weight?`, answer: `If your child sits consistently above the 91st or 98th centile it is worth an appointment rather than waiting to see. Childhood obesity raises the lifetime risk of type 2 diabetes by five to seven times and heart disease by two to three times, and intervention before the age of 12 is considerably more effective. Sudden weight loss, restrictive eating, vomiting after meals or excessive exercise call for a referral just as urgently, and weight worries often travel alongside anxiety or low mood.` },
  ],
  'offset-mortgage-calculator': [
    { question: `How does offsetting my savings cut the mortgage interest?`, answer: `Linking your savings account to the mortgage means interest applies only to the difference between the balances, so £30,000 in savings against a £200,000 mortgage leaves you paying on £170,000. The savings earn nothing, yet the tax-free interest you avoid works like a return on them. The effect also shortens the mortgage term if you keep paying the standard amount, and on a £250,000 mortgage at 4.5% with £40,000 offset it is worth about 3 years 11 months off a 25-year term.` },
    { question: `Which UK lenders still offer offset mortgages?`, answer: `Choice has been limited since the 2008 crisis. Yorkshire Building Society is the largest specialist, alongside Coventry Building Society and Family Building Society. Scottish Widows Bank, part of Lloyds, stopped taking new offset customers in November 2023. Expect to pay 0.2-0.5% more than an equivalent standard mortgage, so 4.8% where a standard product is 4.5%. That premium is worth accepting once the offset balance is big enough for the interest saved to exceed it.` },
    { question: `How much in savings do I need for an offset to be worth it?`, answer: `As a rough threshold, an offset balance of about £30k or more usually covers the 0.2-0.5% rate premium and leaves you ahead. Below £10-£20k the benefit is thin, and with nothing in the account it is zero. Your tax rate matters just as much, because a 40% or 45% taxpayer gains far more from tax-free interest saving than a basic-rate payer who still has a £1,000 Personal Savings Allowance to use up.` },
    { question: `Is an offset better than a cash ISA or Premium Bonds?`, answer: `It depends what the money is for. Premium Bonds have an average prize rate of 4.35% from the September 2026 draw, tax-free but not guaranteed, while a stocks and shares ISA has returned 5-7% and tends to beat a mortgage rate over 10+ years, which makes it the stronger long-term home for money you will not touch. Ordinary savings are simplest, though the interest is taxable. An offset earns nothing on paper, saves at the higher mortgage rate, and leaves the money available at any moment, which suits a short-term buffer.` },
  ],
  'ground-rent-calculator': [
    { question: `Do I still have to pay ground rent on a lease granted today?`, answer: `For a new residential long lease granted since 30 June 2022, the Leasehold Reform (Ground Rent) Act 2022 limits ground rent to a peppercorn, effectively nothing. Leases already in place are unaffected and may still charge ground rent, frequently with escalation clauses. The same peppercorn treatment now applies when an existing lease is extended, so an extension removes the charge as well as adding years.` },
    { question: `Can I get out of an escalating ground rent?`, answer: `There are several routes, none of them free. A statutory lease extension adds 90+ years and permanently reduces the rent to a peppercorn, at a cost of £8-£40k. A voluntary variation, where the freeholder simply agrees to lower the rent, usually costs £2-£10k, and some freeholders accept a one-off payment of £1,000-£5,000 to move to a peppercorn. Leaseholders can also club together through Right to Manage or collective enfranchisement to buy the freehold. Take advice before committing to a property with an escalating clause rather than afterwards.` },
    { question: `What is the difference between ground rent and a service charge?`, answer: `They are separate payments that are easily confused. Ground rent is an annual sum paid to the freeholder for the land, while the service charge covers shared building maintenance. Only the service charge is subject to Section 20 consultation on qualifying major works. Ground rent rarely accounts for more than 1-5% of what a leaseholder pays each year, yet an onerous clause does far more damage, because it is the biggest single threat to the value of the flat.` },
    { question: `Will the reforms scrap ground rent on existing leases?`, answer: `That is the direction of travel. The Leasehold Reform (Ground Rent) Act 2022 only covered new residential leases granted from 30 June 2022, leaving existing leases, commercial property and community-led housing outside it. The Leasehold and Freehold Reform Act 2024, given royal assent in May 2024, is meant to extend peppercorn rents to existing leases, with implementation expected in 2026-2027 and a transitional cap of £250 on existing ground rents until then.` },
  ],
  'service-charge-calculator': [
    { question: `What is covered by a leasehold service charge?`, answer: `Common charges cover building insurance, cleaning, gardening, lift maintenance, communal lighting and management company fees, along with money set aside in a reserve fund for major works. Larger developments add concierge, building security and sometimes district heating. Annual bills range broadly, from roughly £500 to £5,000 or more, and the biggest single driver is how many facilities the block has to run.` },
    { question: `Can I challenge a service charge that seems too high?`, answer: `Yes. Under the Landlord and Tenant Act 1985 charges must be reasonable, and the First-tier Tribunal (Property Chamber) hears disputes for a £100 fee and can reduce a charge it finds unreasonable. Start by asking for the annual accounts and budget and comparing them with similar buildings. Management fees above 15% of the service charge, commission taken by the freeholder on the insurance and services that are never delivered are the usual grounds, and transparency rules from 2024 have strengthened what you can demand to see.` },
    { question: `What is a Section 20 consultation for major works?`, answer: `It is the formal consultation a landlord must run before carrying out works that cost any single leaseholder more than £250. Roof replacements, lift refurbishments, external decorations and structural repairs are the usual triggers. The sums involved are serious, since a £100,000 roof on a 20-flat building comes to £5,000 each. Section 20 applies to the service charge alone, so it has no bearing on ground rent.` },
    { question: `How much is a typical service charge on a flat?`, answer: `In 2026 a typical block costs £1,500-£3,500 a year, while premium developments with concierge and extensive facilities run £2,500-£8,000 or more. Within that total, building insurance is usually £200-£1,500 per flat, the managing agent takes £150-£400, a lift costs £400-£1,200 a year to maintain across the block and the reserve fund absorbs £200-£2,000. Across the market as a whole the figures stretch from £500 to £5,000 or more.` },
  ],
  'pension-consolidation-calculator': [
    { question: `Over 25 years, how much can pension fees really cost me?`, answer: `Even a 0.5% yearly gap changes the outcome substantially. A £100,000 pot growing at 5% over 25 years, with the charge taken off the return each year, is left at about £236,300 under a 1.5% charge but about £300,500 under a 0.5% charge. Since platform fees run from 0.2 to 0.5% and fund charges from 0.1 to 1.5%, adding up what each of your pots costs now and comparing it with one combined pot shows the size of the prize.` },
    { question: `Which old pensions should I never transfer?`, answer: `Final salary pensions come first on that list, along with any policy carrying a guaranteed annuity rate, protected tax-free cash above 25%, or life cover that ends on transfer. A guarantee of 8 to 12% is hard to replace when open market annuity rates sit at 6 to 7%. The Pension Schemes Act 2015 makes regulated advice compulsory before transferring safeguarded benefits worth more than £30,000, including defined benefit pensions, which is a sign of how rarely these are worth moving.` },
    { question: `How do I find a pension I have lost track of?`, answer: `Start with the Pension Tracing Service on gov.uk, which is free and will point you to the provider holding an old scheme. Once you have the contact details, ask for the current fund value, the charges and what the money is invested in, since those three figures decide whether the pot is worth moving. Transfers themselves normally take 4 to 12 weeks once the forms are in, and providers handle them electronically between each other.` },
    { question: `Does it cost anything to transfer my pensions into one pot?`, answer: `Usually nothing, since providers handle transfers electronically and most modern schemes make no charge. The exception is exit charges on older plans. For savers aged 55 or over these have been capped at 1% of the value since 2017, and plans started since then cannot charge them, but a younger saver on an older contract can still face more, enough to wipe out several years of fee savings. Defined benefit transfers are a different matter, because the compulsory advice alone typically costs £2,000 to £5,000.` },
  ],
  'employer-pension-contribution-calculator': [
    { question: `Are pension contributions worked out on my whole salary?`, answer: `No. Auto-enrolment uses qualifying earnings, the slice of gross pay between £6,240 and £50,270 for 2026/27, rather than your full salary. Your employer adds at least 3% of that band and you add 5%, giving a minimum of 8%. On a £30,000 salary the qualifying slice is £23,760, so the employer's minimum works out at £712.80 a year rather than 3% of the whole salary.` },
    { question: `What counts as a good employer pension contribution in the UK?`, answer: `Anything meaningfully above the 3% statutory minimum. A good employer typically matches 5 to 6%, tech and finance firms often pay 8 to 15%, and professional services regularly go past 10%. Public sector defined benefit schemes are in another category again, with the civil service equivalent to roughly 15 to 30% of salary and the NHS scheme worth something like 20 to 25%.` },
    { question: `Why should I contribute enough to get the full employer match?`, answer: `Because the matched money only exists if you claim it. Sacrifice £100 a month where your employer adds £250 and the arrangement costs you about £60 after tax while £350 goes into the pension. That holds for a basic-rate taxpayer just as much as for anyone paying more. No fund, platform or investment strategy comes close to that, so filling the match should always come before extra saving elsewhere.` },
    { question: `Can I negotiate a higher employer pension contribution?`, answer: `Often, yes, and it is most likely to work in tech, finance, professional services and senior roles. An extra 1% on the pension match is worth more after tax than an extra 1% on salary, so raise it alongside base pay rather than afterwards. Employers tend to respond in one of three ways: matching another 1 to 2% above the minimum, offering a flat 8 to 10% with no match required, or moving you onto salary sacrifice with National Insurance passback.` },
  ],
  'right-to-buy-calculator': [
    { question: `Can a Right to Buy discount reach the full 70%?`, answer: `Yes, though 70% is the ceiling and the cash cap usually stops you well short of it. Houses begin at 35% off after three years of tenancy and gain 1% for every extra year, while flats start at 50% and rise 2% a year, both stopping at 70%. Whatever percentage you reach, the discount cannot exceed the regional cash cap of £16,000 to £38,000.` },
    { question: `How much of the Right to Buy discount do I repay if I sell early?`, answer: `Selling within 5 years triggers repayment on a sliding scale. In year 1 you repay 100% of the discount, in year 2 it is 80%, year 3 is 60%, year 4 is 40% and year 5 is 20%. From the sixth year onwards nothing is owed. With an £80k discount, a sale after 2 years means handing £64k back to the council. The rule also applies if you sell or transfer the home to a family member during the repayment period.` },
    { question: `What is the maximum Right to Buy discount in London?`, answer: `Since 21 November 2024 the maximum cash discount has been a regional figure between £16,000 and £38,000, and across most of London it is £16,000. That is a steep cut from the previous London cap of £136,400 (the rest of England was £102,400). The percentage discount still applies, but the cash cap overrides it, so a London tenant entitled to 70% off a valuable flat will still receive no more than £16,000.` },
    { question: `Can I get a mortgage to buy my council house under Right to Buy?`, answer: `Yes, most UK lenders offer Right to Buy mortgages that treat the discount as gifted equity, and the loan-to-value is measured against the purchase price rather than the market value. Buying a £200k home for £162k with a 25% deposit of £40,500 gives a 75% LTV, although the loan is only about 61% of the market value. Halifax, Barclays and Nationwide offer competitive rates from 4.5% in 2026, but some lenders decline these applications, so a broker who knows the scheme helps.` },
    { question: `Does Right to Buy still exist in Wales and Scotland?`, answer: `No. Wales abolished Right to Buy in 2019 and Scotland ended it in 2016, so this calculator applies to council tenants in England only. Northern Ireland runs a similar House Sales Scheme. In England, former council tenants whose homes were transferred to a housing association may still qualify through the Preserved Right to Buy.` },
  ],
  'staircasing-calculator': [
    { question: `How is the price of extra shares set when I staircase?`, answer: `Each new share is priced on the property's current market value at the moment you staircase, not the price you originally paid, which is why an independent RICS valuation is mandatory. Purchases usually come in steps of 10% or more, all the way up to full ownership at 100%. If the property has risen in value since you bought, every percentage point costs more than it did at the outset.` },
    { question: `What fees will I pay when staircasing my shared ownership home?`, answer: `Budget for an independent RICS valuation at £300-£500 and solicitor fees of £500-£1,000. If you need a new or extended mortgage, expect mortgage fees of £999-£1,500 plus lender legal fees of £150-£300. Taken together, a typical staircasing transaction adds £1,500-£2,500 in fees on top of the price of the share itself, and SDLT may also be due once your total share passes the relevant threshold.` },
    { question: `Do I pay stamp duty when I staircase above 80%?`, answer: `It depends on the election you made when you first bought. If you paid SDLT in full upfront, as most buyers do, there is nothing more to pay. If you chose to pay only on your initial share and the rent, SDLT falls due once your total share exceeds 80%, and it is calculated on the current market value. A buyer who paid on a £75k 25% share and staircases to 90% owes SDLT on the extra 65% at today's price.` },
    { question: `How much does my rent fall after staircasing?`, answer: `Rent is charged only on the share the housing association still owns, so buying more of the property cuts it in proportion. On a £300k flat, a 25% owner paying roughly £10k a year in rent on the other 75% would see that fall to about £5k a year after staircasing to 50%. At 100% the rent disappears completely, although the mortgage payment rises to cover the larger loan.` },
    { question: `Is staircasing cheaper than selling up and buying another home?`, answer: `Usually, yes. Staircasing avoids moving costs, carries lower commission than a full sale and keeps the EPC rating and improvements you have paid for, so it typically comes out £3-£8k cheaper than selling and buying elsewhere. Selling gives you full access to the open market, but you pay SDLT on the new property and estate agent fees of £3-£8k on the sale. The exception is when a change of location would genuinely improve your position.` },
  ],
  'pension-lump-sum-calculator': [
    { question: `Can I take part of my pension tax-free?`, answer: `Up to 25% of your crystallised pot can be taken completely free of income tax through the Pension Commencement Lump Sum, from age 55 (rising to 57 in April 2028). Crystallising in stages, known as phased drawdown, lets you take that tax-free 25% from each tranche and can beat cashing everything in at once, because the untouched portion keeps growing free of tax.` },
    { question: `How is the part of my pension above the 25% taxed?`, answer: `Anything drawn beyond the tax-free 25% is treated as earned income for the year. It is added to your salary or State Pension and then run through the normal bands: nothing on the first £12,570, 20% up to £50,270, 40% up to £125,140 and 45% above that. In the calculator's example, someone on a £30,000 salary who takes an extra £20,000 lump sum has total income of £50,000, so the whole withdrawal falls in the basic-rate band and costs £4,000 in tax. Providers often apply an emergency tax code to a first withdrawal, so more may be deducted initially than you owe, and the excess has to be reclaimed.` },
    { question: `What is the difference between UFPLS and flexi-access drawdown?`, answer: `With UFPLS you take money straight from an uncrystallised pot without moving into drawdown, and every payment is split 25% tax-free and 75% taxable, which suits phased lump sums while the rest stays invested. With flexi-access drawdown you take the whole 25% tax-free sum upfront and then draw the remaining 75% as taxable income over the years, which suits someone who wants a large sum now and a modest income later. Taking a UFPLS payment triggers the £10,000 Money Purchase Annual Allowance, which limits what you can pay into pensions afterwards.` },
    { question: `Is there a limit on total tax-free pension cash?`, answer: `Yes. Since April 2024 the Lifetime Allowance has been replaced by a Lump Sum Allowance of £268,275, which is the most tax-free cash you can take across all your pensions over your lifetime and equals 25% of the old standard limit. If your pots are worth more than £1.073M in total, the tax-free element is still capped at £268,275. Below that level the usual 25% applies to each pot or tranche you crystallise.` },
    { question: `What happens to my pension pot when I die?`, answer: `If you die before 75, the pot can pass to your nominated beneficiaries free of tax, provided it is within the £1.073M death benefit allowance. If you die after 75, the beneficiaries pay income tax at their own marginal rate on what they draw. Pensions sit outside your estate for inheritance tax only until 5 April 2027. Under the Finance Act 2026, unused funds count towards the estate for deaths from 6 April 2027, so leaving the pension untouched and spending other savings first no longer avoids inheritance tax.` },
  ],
  'elm-payment-calculator': [
    { question: `What replaced the Basic Payment Scheme in England?`, answer: `Environmental Land Management schemes took over from the EU's Basic Payment Scheme in England. The Sustainable Farming Incentive rewards environmental actions run alongside food production, while Countryside Stewardship targets outcomes such as habitat creation and flood risk management.` },
    { question: `What does SFI pay per hectare for common actions?`, answer: `Herbal leys pay £224/ha and low-input grassland £151/ha, while multi-species winter cover crops pay £129/ha, legume fallow £532/ha, companion crops £55/ha and a no-insecticide commitment £45/ha. Hedgerow management is paid by length at £13/100m for one side. Buffer strips pay most, at £515/ha for a 4-12m grass strip and £707/ha alongside a watercourse.` },
    { question: `Can I stack SFI actions on the same field?`, answer: `Yes, where the actions are compatible, and the rates then add together on that land. Incompatible combinations are not paid twice, because the Rural Payments service deducts the overlapping area. On an 80 ha arable holding, legume fallow on 10 ha, winter cover crops on 20 ha, companion cropping on 30 ha, 2,000 m of hedgerow management and 4 ha of winter bird food adds up to £12,402 a year, which is far more than any single action would return.` },
    { question: `How do I apply for SFI and how long does an agreement run?`, answer: `Applications go through the Rural Payments service on gov.uk using your RPA-registered land details, though both SFI26 windows have now closed: the first, for small farms, on 28 August 2026 and the second, for all farmers, early on 22 September 2026. You select actions parcel by parcel, most actions last 3 years and each agreement is capped at £100,000 a year. The RPA checks a sample of agreements and can reduce or recover payments where actions are not carried out.` },
    { question: `When does the Basic Payment Scheme stop completely?`, answer: `BPS itself has already gone: since 2024 farms have received delinked payments, based on a 2020 to 2022 reference period rather than active farming. For 2026 and 2027 they are cut by 98% on the first £30,000 of the reference amount and 100% above it, so no farm gets more than £600, and 2027 is the final payment.` },
  ],
  'farm-tenancy-calculator': [
    { question: `Which type of farm tenancy gives me the most security?`, answer: `Three main types exist in England and Wales: Agricultural Holdings Act 1986 tenancies with full security, Farm Business Tenancies under the Agricultural Tenancies Act 1995 with limited security, and grazing or seasonal licences for short-term use. The 1986 agreements offer the strongest protection, but no new ones have been granted since 1995.` },
    { question: `What rent should I expect to pay for arable land?`, answer: `Arable land in the East of England may let for £200 to £400/ha, while grassland in the West sits nearer £80 to £150/ha. Permanent pasture runs £80 to £180/ha, mixed ground £120 to £200/ha, and premium land, irrigated or close to London, £300 to £500/ha. A farmhouse in the deal adds £6,000 to £15,000 a year, and seasonal grazing lets go for £80 to £120/ha.` },
    { question: `How long does a Farm Business Tenancy last?`, answer: `Terms typically run 5 to 15 years, with a minimum of 2 years before the arrangement drops back to an annual periodic tenancy. There is no statutory maximum, though very long terms can complicate mortgageability. Notice periods are usually 12 to 24 months, and rent reviews come round at the stated intervals, most often every 3 years, settled on open-market value.` },
    { question: `What am I paid for improvements when a tenancy ends?`, answer: `Tenant Right covers drainage, fencing, hedging, manure built up on the holding, growing crops and fixtures, compensated at the end of the tenancy on fairly rough valuations. Anything installed without the landlord's consent cannot be recovered, so agree it in writing first. Disturbance compensation, typically 1 to 2 years' rent, applies only on AHA tenancies and only where the notice to quit is not fault-based.` },
    { question: `Can I run glamping or holiday lets on tenanted farmland?`, answer: `Only if the tenancy allows it. A Farm Business Tenancy can specify which non-farm uses are permitted or prohibited, naming Airbnb, glamping and holiday lets directly, and sub-letting is normally barred without consent. Income from those activities is subject to income tax and may attract business rates once the use counts as commercial, so check the agreement and the rating position before investing in the buildings.` },
  ],
  'ev-salary-sacrifice-calculator': [
    { question: `Why is leasing an EV through salary sacrifice so cheap?`, answer: `Payments come straight out of gross salary before income tax and National Insurance, so the money is never taxed as pay, and the only charge on the car itself is a small Benefit in Kind percentage. That rate is 2% for 2024/25, 3% for 2025/26 and 4% for 2026/27. For a higher-rate taxpayer the combined effect is usually a saving of 40% to 50% against leasing the identical car privately.` },
    { question: `What happens to my EV lease if I leave my job?`, answer: `The car belongs to the scheme rather than to you, so leaving normally means paying off what remains on the lease, which can be a substantial sum early in a 2-4 year contract. Some employers cover that cost as part of the package and others do not, so it is worth confirming before you commit, particularly if you are likely to move on. It is the single biggest risk in an otherwise low-risk arrangement, and it is set by your employer's scheme rules rather than by tax law.` },
    { question: `Is salary sacrifice actually cheaper than leasing an EV myself?`, answer: `On a £50k car, a gross lease cost of around £700 a month typically nets down to £400 to £500 for a higher-rate taxpayer. Financing the same car personally runs to roughly £800 a month before you add about £700 a year of insurance and £500 for servicing, MOT and breakdown, all of which the scheme includes. The difference is ownership: at the end of a personal deal you may keep the car, whereas the sacrifice car goes back.` },
    { question: `Can salary sacrifice take my pay below the minimum wage?`, answer: `No, and this is a hard limit rather than a guideline. Your remaining pay after the sacrifice has to stay above £12.71 an hour for the hours you work, which rules the scheme out for lower earners or restricts them to cheaper cars. Since the commitment runs for years rather than months, employers check the headroom against your contracted hours at the outset, and a cut in hours later on can create a problem the scheme has to resolve.` },
  ],
  'ulez-calculator': [
    { question: `What happens if my car does not meet ULEZ standards?`, answer: `You pay £12.50 for each day the vehicle is driven anywhere inside Greater London, at any time of day. Miss the payment deadline and the penalty is £180, reduced to £90 if you pay within 14 days. Petrol cars generally need Euro 4, roughly those registered after January 2006, and diesels Euro 6, roughly after September 2015, so a car of the wrong vintage costs £1,950 a year on a three-day-a-week commute.` },
    { question: `How do I check whether my vehicle is ULEZ compliant?`, answer: `Put your registration number into TfL's Check Your Vehicle tool, which returns a definite answer rather than a guess based on age. The standards are Euro 4 for petrol cars, Euro 6 for diesels and Euro 3 for motorcycles and mopeds, while vans and minibuses under 3.5 tonnes follow the car standards. Vehicles over 3.5 tonnes, buses and coaches come under the separate Low Emission Zone and need Euro VI.` },
    { question: `How long do I have to pay the ULEZ charge after driving in?`, answer: `The window runs from 90 days before the journey to midnight on the third day after it, so paying a day or two late is not a penalty as long as you stay inside that period. Enforcement is by ANPR camera, and many drivers only learn they entered the zone when a notice lands weeks afterwards. Setting up AutoPay registers your card and bills you monthly for the days detected, which removes the risk of forgetting entirely.` },
    { question: `Do other UK cities charge older vehicles to drive in?`, answer: `Several do. Bath charges £9 to £100 a day but exempts private cars, while Birmingham charges £8 to £50 a day and includes them. Bradford, Bristol, Portsmouth, Sheffield and Tyneside (Newcastle and Gateshead) run Class B, C or D zones of their own. Glasgow (from 2023) and Edinburgh (from 2024) took a different approach, banning non-compliant vehicles altogether with £60 fines and no daily charge option.` },
    { question: `Is there help towards replacing a non-compliant car?`, answer: `Not from TfL any more: London's ULEZ scrappage scheme closed to new applicants on 8 September 2024. Some Clean Air Zone cities have run local support schemes, so check with the council. A compliant replacement means an EV, a Euro 6 diesel or a Euro 4 or later petrol, from about £3k to £5k used.` },
  ],
  'car-import-duty-calculator': [
    { question: `How much tax will I owe to import a car into the UK?`, answer: `Customs duty on a passenger car is 10% of its value including shipping and insurance, with VAT at 20% charged on the vehicle and the duty combined. On a £22,000 customs value that is £2,200 of duty and £4,840 of VAT. A car made in the EU can qualify for zero duty under the UK-EU Trade and Cooperation Agreement, and cars made in Japan, South Korea or Turkey can also come in at 0%, provided they meet the rules of origin and you have the proof to support it.` },
    { question: `What is NOVA and when do I have to file it?`, answer: `The Notification of Vehicle Arrivals tells HMRC that an imported vehicle has entered the country, and it has to be filed through gov.uk within 14 days of arrival. It comes first in the sequence, before the IVA application, the C88 customs declaration for duty and VAT, DVLA registration at £55 and plates at about £25. Without it the DVLA will not register the car.` },
    { question: `Does my imported car need an IVA test?`, answer: `Cars up to 10 years old need it unless they already hold EU type approval, in which case Mutual Recognition may cover them. Cars over 10 years old are exempt from vehicle approval. The statutory IVA inspection for a car costs £199 in working hours or £294 outside them, with a re-test at £40. Expect to convert the headlight beam pattern and fit a speedometer reading in mph to pass. There is no 25-year import rule in Great Britain; that is a US restriction.` },
    { question: `Can I bring my own car when I move to the UK without paying tax?`, answer: `Transfer of Residence relief removes both duty and VAT if you have owned the vehicle for six months or more and lived abroad for at least twelve. The application goes through gov.uk within twelve months of arriving. It typically saves £3k to £10k. The conditions bite afterwards too: sell the car within twelve months of importing it and the relief is withdrawn, leaving the tax payable.` },
    { question: `How long does the whole import process take?`, answer: `Usually four to twelve weeks from the car landing to being road legal. Shipping time sits on top of that and depends on the route, at £800 to £2,000 for roll-on roll-off from the United States, £1,800 to £3,500 for a container, £1,500 to £3,500 from Japan or £200 to £800 from the EU. The IVA appointment is normally the step that sets the pace.` },
  ],
  'road-trip-cost-calculator': [
    { question: `How do I estimate the fuel bill for a road trip?`, answer: `Divide the total distance by your car's MPG, convert to litres by multiplying by 4.546, then multiply by the price per litre. On that basis a 500-mile trip in a 40 MPG car at £1.72 a litre, the UK average for petrol in the week commencing 21 September 2026, comes to about £98 of fuel. Working in pence per mile is quicker for comparisons: at that price a 40 MPG car costs 19.5p a mile, so a 1,000-mile round trip is £195.` },
    { question: `Which UK roads and bridges still charge a toll?`, answer: `Not many. The M6 Toll is £12 for a car over the full length (£10.20 with a Breeze account), the Dartford Crossing £3.50 (£2.80 pre-pay), the Humber Bridge £2, the Mersey Gateway £2.40 and the Tyne Tunnel £2.60. Dartford and the Mersey Gateway have no booths, so pay online by midnight the next day or face a fine. The Severn bridges have been free since 2018 and the Skye Bridge since 2004. City charges matter more now, at £18 a day in central London and £8 in Birmingham.` },
    { question: `What should I budget per night for accommodation?`, answer: `A bed and breakfast costs £80 to £150 a night, a budget hotel £60 to £100, a mid-range hotel £100 to £200 and a premium one £200 to £500, so five nights usually falls between £400 and £1,000. Pubs with rooms at £60 to £100 often include breakfast, and a self-catering cottage at £200 to £500 for a week is better value for four or more people. Camping starts around £15 a night.` },
    { question: `Is an electric car practical for a long UK road trip?`, answer: `Yes, with planning. Premium EVs cover 250 to 350 real-world miles and a rapid stop of 20 to 30 minutes takes the battery from 10 to 80%. Rapid charging at 60 to 80p per kWh works out at 15 to 20p a mile, much the same as petrol, so leave home fully charged. Ionity is the most reliable network at 95%, ahead of BP Pulse at 91% and Pod Point at 88%. Zap-Map and A Better Routeplanner are worth having in rural Scotland and Wales.` },
    { question: `What is the easiest way to cut the cost of a UK road trip?`, answer: `Change when you go. September to May costs 30 to 50% less than peak summer, and mid-week hotel rates are 20 to 40% below weekend ones. After that, self-catering rather than eating out saves £15 to £30 per person per day, National Trust and English Heritage membership at £80 to £120 covers entry and parking at more than 350 properties, and fuel price apps trim 5 to 10p a litre. Five days for £300 to £500 a head is achievable.` },
  ],
  'making-tax-digital-calculator': [
    { question: `When does Making Tax Digital start for landlords and the self-employed?`, answer: `It begins in April 2026 for self-employed people and landlords with gross income above £50,000, measured across self-employment and property combined. Quarterly digital summaries of income and expenses replace the single annual return, with a final declaration at the end. Anyone with income between £30,000 and £50,000 is brought in from April 2027, and those between £20,000 and £30,000 from April 2028. There is no start date yet for anyone below £20,000.` },
    { question: `How often do I have to submit figures under MTD?`, answer: `Four times a year, plus a final declaration. The update periods end on 5 July, 5 October, 5 January and 5 April, and each summary is due on the 7th of the following month. For the first MTD year that means 7 August 2026, 7 November 2026, 7 February 2027 and 7 May 2027, with the final declaration due by 31 January 2028. Late updates earn penalty points, and 4 points trigger a £200 penalty, although HMRC will not apply points to late quarterly updates during 2026/27.` },
    { question: `Which software do I need for Making Tax Digital?`, answer: `Anything on HMRC's approved list. FreeAgent is free with NatWest and RBS business banking, QuickBooks starts around £10/month, Xero and Sage sit at about £14/month, and FreshBooks is another option. If your affairs are very simple, a spreadsheet with bridging software will do the job for less. Look for a cloud package with a bank feed, and for landlord features if you let property, since the bank feed also satisfies the digital link rule.` },
    { question: `What records do I have to keep digitally?`, answer: `Every item of income and expenditure, with the date, the amount and a description, kept in the software rather than typed up at year end. VAT-registered businesses also record input and output VAT. Receipts can be scanned in or kept on paper for 5 years. The digital link rule means no manual re-keying between your records and the return, so figures must flow through electronically from source to submission.` },
  ],
  'tax-bracket-visualizer': [
    { question: `Why is my income taxed at several different rates instead of one?`, answer: `Income tax is charged slice by slice, so each part of your earnings meets its own band rate rather than one flat percentage covering the lot. The first £12,570 is tax-free under the Personal Allowance, 20% applies up to £50,270, 40% up to £125,140 and 45% above that. Someone on £85,000 is often described as a 40% taxpayer, but the effective rate across the whole salary is 25.2%.` },
    { question: `What is the 60% tax trap between £100,000 and £125,140?`, answer: `Once income passes £100,000 the Personal Allowance is withdrawn at £1 for every £2 earned above it, so you lose tax-free income while paying 40% on the extra. The combined effect is a 60% marginal rate on the slice up to £125,140, where the allowance has gone completely. Adding the 2% National Insurance takes the true figure to 62%. Pension contributions and Gift Aid that bring income back below £100,000 are unusually efficient for that reason.` },
    { question: `How much more income tax do Scottish taxpayers pay?`, answer: `Scotland has six bands to the rest of the UK's four, and the pinch is where the 42% rate begins, at £43,663 rather than £50,270. A Scottish taxpayer earning £50k pays £8,982 in income tax against £7,486 elsewhere in the UK, a difference of £1,496. Lower earners fare slightly better, because the starter rate of 19% applies from £12,571 to £16,537 before the basic rate takes over.` },
    { question: `Should I use my effective or marginal rate for planning?`, answer: `Use the effective rate, total tax divided by total income, for budgeting and for comparing job offers, since it tells you what actually leaves your pay. Use the marginal rate, the cost of the next pound, when deciding whether to make a pension contribution, take salary sacrifice, accept overtime or claim Marriage Allowance. On £30k the marginal rate is 28%, so a £1,000 pension contribution costs £720 net and saves £280.` },
  ],
  'business-mileage-record-calculator': [
    { question: `How much can I claim per mile when I use my own car for work?`, answer: `Cars and vans are claimed at 55p a mile for the first 10,000 business miles in the tax year, a rate that rose from 45p on 6 April 2026, then 25p a mile beyond that. Motorcycles run at 24p and bicycles at 20p with no threshold, and a colleague travelling on the same business trip adds a passenger supplement of 5p a mile. Electric cars are claimed at the same rates as petrol ones.` },
    { question: `Does driving to my normal workplace count as business mileage?`, answer: `No. Ordinary commuting between home and a permanent workplace is private travel, as are personal detours and lunchtime trips. Travel to a temporary workplace, meaning somewhere you expect to attend for less than 24 months, does qualify, and site-based workers with no fixed office can treat every journey from home as business mileage. Where home is genuinely your main base, the drive to a client counts from the moment you leave.` },
    { question: `What can I claim if my employer pays less than 55p?`, answer: `Mileage Allowance Relief covers the gap, claimed through Self Assessment or on form P87. Someone paid 25p a mile from the first mile who covers 5,000 business miles claims relief on those miles at the difference between 55p and 25p, giving £1,500 of relief and £600 of tax saved at the higher rate. Where an employer pays more than the approved rates, the excess runs the other way and is taxed as income through PAYE.` },
    { question: `How long do I need to keep my mileage records?`, answer: `Five years after the end of the tax year the claim relates to. Each trip needs its date, the start address and destination, the business reason and the miles covered, whether that sits in a paper logbook, a spreadsheet or an app such as MileIQ, TripLog or Hurdlr at roughly £40 to £80 a year. Weak records let HMRC disallow a claim in full, and anything above 15,000 miles a year draws closer attention.` },
  ],
  'pension-sharing-divorce-calculator': [
    { question: `How is a pension valued when a couple divorces?`, answer: `Division is based on the Cash Equivalent Transfer Value, the present-day capital value of the future benefits worked out by the scheme's actuary from age, expected payouts and life expectancy. For a defined contribution pension that is just the current pot value. For a defined benefit scheme the CETV can sit well below the value of the income it replaces, which makes a fair split harder to judge, and the figure is only valid for 3 months.` },
    { question: `Is a pension always split 50/50 in a divorce?`, answer: `No. The court sets the percentage using the Section 25 factors, which cover the length of the marriage, the ages of both parties, contributions and needs. After a short marriage of under 5 years, pension built up beforehand is usually excluded altogether. After 15 years or more an even split of what accrued during the marriage is common, so a £400k pension built over 20 years would often go £200k each. A younger spouse can be awarded more where the other is close to retirement.` },
    { question: `Is there tax to pay when a pension is shared on divorce?`, answer: `Not at the point of the split, which attracts neither capital gains tax nor income tax. The share simply moves into the recipient's name, grows there, and is taxed as pension income when it is eventually drawn, with the 25% tax-free lump sum applying to their whole pot including the transferred part. The costs are procedural instead: £62 to file the financial consent order, and sometimes £100 to £500 for the provider to implement the share within 4 months.` },
    { question: `What is pension offsetting and when does it backfire?`, answer: `Offsetting leaves the pension with one spouse and gives the other more cash or property to compensate, often the family home. It backfires when the pension being kept is a public sector defined benefit scheme, since those can be worth two or three times the transfer value used in the negotiation. Trading guaranteed inflation-linked income for an asset that produces none rarely balances out, so anything above £100k warrants independent actuarial advice before agreeing.` },
  ],
  'working-hours-benefits-calculator': [
    { question: `If I take on extra hours, how much of the pay do I actually keep?`, answer: `Universal Credit is cut by 55p for every additional £1 you earn above your work allowance, and because the taper applies to pay after 20% income tax and 8% National Insurance, a basic-rate taxpayer keeps only about 32p of each extra £1. A single parent on £12.71 an hour moving from 16 to 25 hours gains about £182 a month, an effective £4.66 an hour for the extra time.` },
    { question: `How many hours do I need for Working Tax Credit?`, answer: `None now, because Working Tax Credit ended on 5 April 2025 and everyone who was on it moved to Universal Credit. It used to need 16 or 30 hours a week depending on circumstances, which made the step from 15 to 16 hours unusually valuable. Universal Credit has no hours threshold at all, tapering on earnings instead, so 16 hours at £12.71 gives £203 a week and would usually still leave a UC entitlement.` },
    { question: `What is the minimum wage for my age in 2026/27?`, answer: `The National Living Wage for workers aged 21 and over is £12.71 an hour from April 2026. 18-20 year-olds get £10.85, and under-18s and apprentices in their first year get £8.00. The rate applies whether the job is part-time or full-time. A 35-hour week at £12.71 comes to £445, or £23,132 a year. HMRC enforces the minimum and publicly names employers that underpay.` },
    { question: `What is the maximum number of hours I can work?`, answer: `The Working Time Regulations 1998 cap the working week at 48 hours averaged over 17 weeks, unless you have signed an opt-out in writing. Night workers are limited to 8 hours per shift over the same averaging period. Alongside the cap you are entitled to 11 hours of rest between shifts, 24 hours of weekly rest or 48 hours a fortnight, a 20-minute break on any shift over 6 hours, and 5.6 weeks of holiday. Doctors and emergency services have their own exceptions.` },
  ],
  'inheritance-tax-pension-calculator': [
    { question: `When do unused pension pots start counting towards Inheritance Tax?`, answer: `For deaths from 6 April 2027, under the Finance Act 2026, which became law on 18 March 2026. Death-in-service benefits and dependants' scheme pensions stay outside. Until then most defined contribution pots pass outside the estate, and beneficiaries receive them free of Inheritance Tax, although income tax can apply where the holder died after 75. Once the pension is inside the estate, anything above the £325,000 nil-rate band, plus the £175,000 residence nil-rate band where it applies, is taxed at 40%.` },
    { question: `Who pays the Inheritance Tax due on a pension pot?`, answer: `The personal representatives, meaning the executors or administrators of the estate, are liable. They can ask the pension scheme to hold back up to 50% of the benefits for up to 15 months, or to pay HMRC directly out of the fund, so they are not left to find the money elsewhere. That means the sum your beneficiaries actually receive is the pot after tax, not the figure on the annual statement, which is worth explaining to anyone you have nominated.` },
    { question: `Is a pension left to my spouse free of Inheritance Tax?`, answer: `Yes. Transfers between spouses and civil partners are exempt from Inheritance Tax without any limit, and that covers pensions as well as the rest of the estate, so a £1m pot passing to a husband or wife attracts nothing at the first death. The charge arrives at the second death, when the combined assets go to children or others, and the April 2027 rules apply then too.` },
    { question: `Can I reduce Inheritance Tax on my pension before 2027?`, answer: `The options being discussed include drawing the pot down faster, using the 25% tax-free lump sum and regular withdrawals, then giving money away within the £3k annual allowance or under the 7-year rule. Buying an annuity removes the money from the estate. Spending the pension first and leaving an ISA or the family home instead can work, since the home may attract the residence nil-rate band. Leaving 10% of the net estate to charity cuts the rate from 40% to 36%.` },
  ],
  'mtd-readiness-calculator': [
    { question: `Who has to start keeping digital tax records under Making Tax Digital?`, answer: `Self-employed people and landlords with qualifying income above £50,000 are in from April 2026, and the £30,000 to £50,000 band follows in April 2027. From then, records are kept digitally and quarterly updates go to HMRC through compatible software, each due on the 7th of the month after the quarter ends. A Final Declaration replaces the old Self Assessment return at the end of the year; the End of Period Statement in the original design was scrapped. The £20,000 to £30,000 band joins in April 2028.` },
    { question: `When are the MTD quarterly updates actually due?`, answer: `Quarters end on 5 July, 5 October, 5 January and 5 April, and each update is due on the 7th of the following month, so 7 August, 7 November, 7 February and 7 May. For anyone in the first wave the opening update was due on 7 August 2026, covering 6 April to 5 July 2026. The Final Declaration for the year then follows on 31 January.` },
    { question: `What is the penalty for a late quarterly update?`, answer: `Late submissions collect points rather than an immediate fine. Each one adds a point, and reaching the threshold of 4 points for quarterly obligations triggers a £200 penalty for that submission and for every late submission afterwards. Late payment is penalised separately, as a percentage of the unpaid tax. HMRC has said it will not apply penalty points for late quarterly updates during 2026/27, the first MTD year, but the updates must still be sent before you can file the tax return. The structure follows the regime already running for MTD for VAT, so anyone filing VAT digitally will find it familiar.` },
    { question: `Can I keep using spreadsheets under Making Tax Digital?`, answer: `Yes, provided the spreadsheet is linked to HMRC through bridging software, and free options such as Bridge Software and 100PcVATFreeBridge exist for exactly that. The catch is the digital links rule, which means figures have to move from source records to submission without being re-typed by hand. Full packages such as FreeAgent, Xero, QuickBooks, Sage and FreshBooks handle that automatically, and HMRC publishes a list of what is approved.` },
  ],
  'congestion-charge-calculator': [
    { question: `What does it cost to drive into central London's charging zone?`, answer: `At £18 a day, a rate set on 2 January 2026, the charge covers driving inside the central zone between 7am and 6pm on weekdays and 12pm to 6pm at weekends and on bank holidays. Pay by midnight on the travel day and it stays £18; leave it until midnight three days later and it rises to £21. Auto Pay handles it automatically for regular drivers.` },
    { question: `Do I have to pay ULEZ and the Congestion Charge on the same day?`, answer: `Yes, if both apply. They are separate schemes: ULEZ is £12.50 a day, covers all of Greater London since August 2023, runs around the clock and catches only vehicles that fail the emission standards, while the Congestion Charge is £18 a day for central London during its operating hours and applies to every vehicle. A non-compliant car driven into the centre on a weekday therefore costs £30.50 for that day.` },
    { question: `Which vehicles avoid the Congestion Charge altogether?`, answer: `Zero-emission capable electric vehicles registered with TfL are exempt under the Cleaner Vehicle Discount, as are licensed black taxis, buses, motorcycles and mopeds, and vehicles registered to Blue Badge holders. Some hybrids qualify for a discount rather than full exemption. Residents of the zone get 90% off, usually for four to five years. Exemptions and discounts generally have to be registered with TfL in advance rather than claimed afterwards.` },
    { question: `What is the penalty if I forget to pay the charge?`, answer: `£180, reduced to £90 if you settle within 14 days. Because enforcement is by camera and there is no barrier at the boundary, occasional drivers often find out weeks later when the notice arrives. Paying by midnight of the third day after travel costs £21 rather than £18 and avoids the penalty entirely, and Auto Pay removes the problem by charging your card on each day your vehicle is detected.` },
    { question: `Do any other UK cities charge to drive into the centre?`, answer: `Several charge older vehicles rather than all traffic. Bath asks £9 a day from private cars in its Class D zone and up to £100 from HGVs, Birmingham charges £8 a day for cars and commercial vehicles, and Bristol, Sheffield and Portsmouth set their own rates. Manchester cancelled its scheme in 2022. Glasgow bans non-compliant vehicles outright with a £60 fine instead of a daily charge, so there is no option to pay and drive in.` },
  ],
  'a-level-grade-calculator': [
    { question: `How are my separate A-level paper marks turned into a final grade?`, answer: `Grades run from A* to E, with boundaries set by the exam boards once marking is finished. Individual paper marks, plus any coursework or practical endorsement, are combined using your board's weighting to give the overall grade, which then converts into UCAS tariff points. Since the boundaries are set after the papers are marked, any estimate made beforehand rests on last year's figures.` },
    { question: `Do AS-level results count towards my final A-level grade?`, answer: `No. A-levels have been linear since 2017, with all the exams sat at the end of year 13 and no AS contribution to the final grade. The AS is now a qualification in its own right, worth 40% of a full A-level on the UCAS Tariff, so an A at AS scores 20 points against the 48 an A at A-level would bring.` },
    { question: `How do T-Levels and BTECs compare with A-levels?`, answer: `An A-level is a two-year academic qualification assessed entirely by exam. A T-Level also runs for two years but is industry-focused and includes a nine-week placement, counting as three A-levels, so a Distinction* is worth 168 UCAS points, the same as A*A*A*. A BTEC is vocational and mixes coursework with exams, and the Extended Diploma is likewise worth three A-levels. Universities accept all three, though specific courses prefer particular routes.` },
    { question: `What happens if I miss my predicted grades?`, answer: `Conditional offers rest on predictions, and research by UCL found that most predicted grades turn out higher than the grades achieved, so falling short is common. If you miss the conditions on your firm offer you may still be accepted by your insurance choice, which is usually set one or two grades lower, and Clearing is the route beyond that. Beating your predictions no longer opens Adjustment, which UCAS scrapped in 2022; with an unconditional firm offer you can use Decline my place to enter Clearing instead.` },
  ],
  'student-loan-plan4-calculator': [
    { question: `Am I on Plan 4 if I moved to Scotland after taking out my loan?`, answer: `No. Plan 4 covers Scottish-domiciled borrowers who took their loans from SAAS, and the plan is fixed by who lent the money and when you borrowed it. Moving from England or Wales to Scotland afterwards does not move you onto Plan 4. The rule works both ways, so a Plan 4 borrower who moves to England keeps the £33,795 threshold and the 9% rate for life.` },
    { question: `How much less do Plan 4 graduates repay than Plan 2?`, answer: `£396.90 a year on any salary above £33,795, because the Plan 4 threshold sits £4,410 above Plan 2's, and less between the two thresholds. On £40,000 a Plan 4 borrower repays 9% of the £6,205 above the threshold, which is £558.45 a year or £46.54 a month. The same salary on Plan 2, with its £29,385 threshold, produces £955.35 a year or £79.61 a month. Plan 4 also caps interest at the lower of RPI or the base rate plus 1%.` },
    { question: `When is a Plan 4 student loan written off?`, answer: `For loans paid on or after 1 August 2007, 30 years after the April you were first due to repay. Older Plan 4 loans are written off at 65 or after 30 years, whichever comes first. Because the £33,795 threshold is high and Scottish graduate balances are comparatively small, at £15-£20k against £45-£50k in England, 73%+ of Plan 4 borrowers never clear the balance before that date. Voluntary overpayments therefore rarely make sense unless you are confident of repaying in full.` },
    { question: `How does Plan 4 appear on my payslip?`, answer: `As a Student Loan deduction taking 9% of pay above the threshold, which is £33,795 a year, £2,816 a month or £649 a week. Employers apply it automatically through PAYE once your earnings pass that point. If you have two jobs, each one is assessed separately against the threshold, so a second job below it attracts nothing. Self-employed income is collected through Self Assessment instead.` },
  ],
  'crypto-carf-calculator': [
    { question: `Will my crypto exchange report my transactions to HMRC?`, answer: `Yes. Under the Crypto Asset Reporting Framework, UK crypto asset service providers such as Coinbase UK, Kraken, Crypto.com, Revolut and eToro have collected data since 1 January 2026 and must pass details of their users' transactions to HMRC, with the first reports due by 31 May 2027, and foreign exchanges with UK customers report as well. HMRC then shares that information with tax authorities in other countries under the OECD standard, and it checks the data against what you put on your Self Assessment return.` },
    { question: `How much Capital Gains Tax do I pay on crypto in 2026/27?`, answer: `Crypto gains are taxed at 18% if you are a basic-rate taxpayer and 24% if you pay higher rate, after deducting the £3,000 Annual Exempt Amount. A higher-rate taxpayer with a £20,000 gain therefore hands over £4,080. Your cost basis comes from the Section 104 pool, the average price of all your purchases of that asset, and if you sell and buy back within 30 days the repurchase is matched to the original cost instead.` },
    { question: `Are stablecoin swaps and crypto-to-crypto trades taxable disposals?`, answer: `Yes. Swapping one crypto asset for another is a disposal for Capital Gains Tax even though no pounds change hands, and that includes stablecoin trades such as USDC to USDT. Wrapping or unwrapping a token such as WBTC counts as a disposal too, as do NFT sales. These swaps are also reportable under CARF, so HMRC will see the gross value of each one alongside your crypto-to-fiat sales.` },
    { question: `Do I pay income tax on staking rewards and mining?`, answer: `Staking rewards are treated as miscellaneous income and taxed at your marginal rate, so £5k of rewards costs a 40% taxpayer £2k. Mining income is either a trading profit (20-45% income tax plus Class 4 National Insurance) or miscellaneous income, depending on scale. Airdrops are income only if you received them in return for something or as part of a trade; otherwise nothing is due on receipt and CGT applies when you sell. Interest from lending protocols such as Aave or Compound is miscellaneous income as well.` },
    { question: `Can I claim a loss if I have lost my private key?`, answer: `If the crypto is genuinely lost, you can make a negligible value claim, which treats the asset as disposed of for nothing and produces a capital loss. That loss can be set against future gains, which is worth doing given the £3,000 Annual Exempt Amount is small. Keep evidence of the loss, because HMRC cross-references CARF data against your return and will query unexplained disappearances of assets it has seen you acquire.` },
  ],
  'employer-ni-rise-calculator': [
    { question: `What changed for employer National Insurance in April 2025?`, answer: `Two things moved at once. The employer rate went from 13.8% to 15%, and the Secondary Threshold at which it starts fell from £9,100 to £5,000 a year. Cutting the threshold costs the same amount on every employee, so the change bears hardest on lower-paid roles, while the rate rise scales with salary. The Treasury expects around £25 billion a year from it, making it the largest UK employer tax rise in 30 years.` },
    { question: `How much extra does the NI rise cost per employee?`, answer: `It depends on the salary, but most small and medium employers are paying £900 to £3,000 more per employee a year. On £25,000 the bill rises from £2,194 to £3,000, an extra £806. On £35,000 it goes from £3,574 to £4,500, up £926. On £55,000 it moves from £6,334 to £7,500, an increase of £1,166. Proportionally, staff in the £25-£35k band cost employers the most extra.` },
    { question: `Who can claim the £10,500 Employment Allowance?`, answer: `Most employers, since the £100,000 cap on the previous year's NI bill was scrapped from 6 April 2025 and size no longer matters. The allowance rose to £10,500 at the same time, up from £5,000, and it is deducted from the total employer NI bill. Limited companies with a single director and no other employees cannot claim, only one company in a connected group can claim, and most public sector employers are excluded too. For a firm that already claimed the old £5,000, only the extra £5,500 offsets the rise.` },
    { question: `Which sectors are hit hardest by the employer NI rise?`, answer: `Anywhere with a lot of staff in the £20-£35k range. Hospitality is the clearest case, with a typical pub or restaurant paying £8,000 to £25,000 a year more, and retail follows a similar pattern. Social care combines thin margins with high headcount, and warehouse and logistics operators can be £15,000 to £40,000 worse off. Construction is affected less, and technology and professional services least per head, because most of those salaries sit above £50k.` },
  ],
  'pay-per-mile-calculator': [
    { question: `Beyond fuel, what makes up the true cost of a mile?`, answer: `Fuel is only part of it: a mile also has to carry insurance, road tax, MOT, servicing, tyres, breakdown cover and depreciation, which is why the AA puts the average UK figure at 30 to 50p. Depreciation is usually the single biggest slice and the one most drivers leave out. On a Ford Focus doing 10,000 miles a year it accounts for 25.0p of a 54.5p total, with petrol at £1.72 a litre.` },
    { question: `How will pay-per-mile charging for electric cars work?`, answer: `From April 2028 the Electric Vehicle Excise Duty (eVED) charges battery electric cars 3p a mile and plug-in hybrids 1.5p, rising with CPI from 2029-30, on top of the normal Vehicle Excise Duty. Petrol and diesel cars keep paying fuel duty and are not charged per mile, and vans are outside the scheme at launch. The driver behind it is the £26 billion of annual fuel duty that disappears as the fleet goes electric.` },
    { question: `How much will eVED cost me?`, answer: `It depends on your mileage, and it comes on top of the £200 standard rate of Vehicle Excise Duty. At 3p a mile, a battery electric car doing 5,000 miles pays £150 a year, 8,000 miles £240, 10,000 miles £300 and 15,000 miles £450; a plug-in hybrid pays half that. For comparison, a 40 mpg petrol car covering 8,000 miles pays about £580 in fuel duty and the VAT on it.` },
    { question: `How will the government know how many miles I have driven?`, answer: `Not by tracking you. You declare your expected annual mileage when you renew your vehicle tax, and the DVLA checks it against the odometer reading recorded at each MOT, with no GPS or telematics involved. The government dropped an earlier idea of separate mileage checks for cars too new to need an MOT, to keep the scheme simple.` },
    { question: `What do electric cars pay in road tax now?`, answer: `Electric vehicles paid nothing until April 2025. Since then they pay £10 in the first year and then the standard rate, £200 in 2026/27, the same as a petrol car. The expensive car supplement of £440 a year for five years applies above a £40,000 list price for petrol and diesel and, from April 2026, above £50,000 for electric cars. The next step is eVED, a per-mile charge on electric cars and plug-in hybrids from April 2028, paid on top of VED.` },
  ],
  'high-council-tax-calculator': [
    { question: `Which homes will be hit by the new £2m council tax surcharge?`, answer: `The High Value Council Tax Surcharge starts in April 2028 and falls on the owner of any English home worth £2 million or more, charged on top of ordinary Council Tax at between £2,500 and £7,500 a year. It reaches fewer than 1% of properties and is expected to raise around £430 million annually.` },
    { question: `Are the surcharge bands final, or can they still change?`, answer: `The four bands are set out as policy: £2,500 for homes worth £2m to £2.5m, £3,500 for £2.5m to £3.5m, £5,000 for £3.5m to £5m and £7,500 above £5m, each rising with CPI from 2029/30. The consultation that ran from 19 May to 14 July 2026 asked about liability, deferral, exemptions and appeals rather than the bands, and the government had not published its response by late September 2026, so check gov.uk before relying on the details.` },
    { question: `Does the landlord or the tenant pay the high-value surcharge?`, answer: `The owner pays, which is the reverse of ordinary Council Tax. A landlord letting out a home with a market value of £2 million or more would meet the surcharge themselves, on top of whatever Council Tax the occupier is billed for. It is an annual charge, so it recurs every year the property stays above the threshold rather than falling due once on sale.` },
    { question: `How will a property's £2m value actually be assessed?`, answer: `Existing Council Tax bands still rest on 1991 values, so a fresh assessment is needed for the surcharge. The Valuation Office will value the properties concerned at 2026 levels before the charge starts in April 2028, then revalue them every five years, the first revaluation falling in 2033. Your existing band is not changed by that exercise, and the surcharge sits alongside it rather than replacing it.` },
    { question: `Which English areas charge the most council tax in 2026/27?`, answer: `Dorset has the highest average Band D bill at £2,765, against an England average of £2,392 and a London average of £2,068. Wandsworth is the lowest at £1,028, with Westminster also near the bottom. The £1,737 gap between Wandsworth and Dorset applies to identical bands, so two similar homes can carry very different bills depending only on the council.` },
  ],
  'sole-trader-vs-ltd-comparison-calculator': [
    { question: `How does take-home pay compare for a sole trader versus a limited company?`, answer: `The table sets net take-home and total tax alongside each other at profit levels from £20,000 to £100,000. The sole trader column runs each figure through Income Tax at 20%, 40% and 45% above the £12,570 Personal Allowance, with Class 4 National Insurance at 6% between £12,570 and £50,270 and 2% above. The company column assumes a £12,570 salary with the balance drawn as dividends after Corporation Tax, then deducts the running costs a company cannot avoid.` },
    { question: `Does incorporating still cut my tax bill in 2026/27?`, answer: `Not for an owner drawing all the profit out each year. At £50,000 the sole trader pays £9,732 against £12,006 for the company, a gap of £2,274, and at £100,000 it is £30,689 against £35,357. The company figures include £1,200 of accountancy and £1,136 of employer NI on the director's salary, which is where much of the difference comes from. The remaining case for a company rests on retained profit, pension contributions and limited liability.` },
    { question: `What extra filings does a limited company have to make?`, answer: `A company files annual statutory accounts, a CT600 Corporation Tax return and a Confirmation Statement, runs payroll for any salary, and the director still submits a personal Self Assessment covering the dividends. Filing accounts at Companies House is free and the Confirmation Statement costs £50 online or £110 on paper, with accountancy on top at £1,000 to £2,000 a year. A sole trader files one Self Assessment and nothing else.` },
    { question: `Does IR35 affect whether I should incorporate?`, answer: `For contractors it largely decides the answer. Inside the off-payroll working rules a contract is taxed as employment, so the company structure gains nothing, while outside them the usual treatment applies. Medium and large clients have made that determination since April 2021, and where the client is small, with turnover under £15M, the contractor decides. The CEST tool on gov.uk gives an initial view without binding either side, and sole traders sit outside IR35 entirely.` },
  ],
  'apprenticeship-levy-calculator': [
    { question: `Does my business actually have to pay the Apprenticeship Levy?`, answer: `Only where the total annual pay bill tops £3,000,000. The charge is 0.5% of that pay bill, meaning everything subject to Class 1 secondary National Insurance, but a £15,000 annual allowance is set against it, so smaller employers end up with nothing to pay. It is calculated and settled monthly through PAYE with the rest of your payroll deductions rather than arriving as one annual bill.` },
    { question: `How do I work out the levy due each month?`, answer: `Take 0.5% of the month's pay bill and subtract £1,250, which is one twelfth of the annual allowance. A negative figure means nothing is payable that month. Connected employers under common ownership share one £15,000 allowance, and the split has to be declared to HMRC at the start of the tax year. Over a full year a £4m pay bill produces £5,000 of levy, while £10m produces £35k.` },
    { question: `What can levy funds actually be spent on?`, answer: `Approved apprenticeship training and assessment bought from registered providers, and from August 2026 apprenticeship units, which are short courses in a specific skill. The apprentice's wages cannot come out of the fund, only the training cost paid to the provider. What you pay in arrives as digital funds in your apprenticeship service account. The 10% government top-up ended on 1 August 2026, and funds entering the account from then expire 12 months after they appear (24 months for older funds), so money left unspent is a tax that was never reclaimed.` },
    { question: `What help is there if my pay bill is under £3m?`, answer: `Smaller employers pay no levy but still get funding. Government pays the full training cost for apprentices aged 16 to 24 and 95% for those aged 25 and over, leaving you to find 5%. You get £1,000 for taking on an apprentice aged 16 to 18, and from 1 October 2026 a hiring payment of up to £2,000 for a new apprentice aged 16 to 24. Levy payers can also transfer up to 50% of their unused funds to non-levy payers, applied for through apprenticeships.gov.uk.` },
  ],
  'shared-parental-pay-calculator': [
    { question: `Can both parents share statutory pay after our baby arrives?`, answer: `Eligible parents can share up to 37 weeks of statutory pay once the mother ends her maternity leave and pay to free up the entitlement. Shared Parental Pay is set at £194.32 a week or 90% of average weekly earnings for 2026/27, whichever comes out lower, with each parent's rate based on their own earnings. A parent averaging under £129 a week gets no ShPP. The blocks can be taken one after the other or at the same time.` },
    { question: `How do we work out how many ShPP weeks are left?`, answer: `Start from 39 weeks and subtract the weeks of maternity pay the mother has already taken. Ten weeks of maternity pay leaves 29 weeks of ShPP for the two of you to divide however you choose, so the family still gets 39 paid weeks in total. ShPP tops out at 37 weeks only because the mother must take the first 2 weeks after the birth as maternity leave. Converting costs no paid time, although ending SMP within the first 6 weeks gives up its uncapped 90% rate.` },
    { question: `Do both parents have to qualify for shared parental pay?`, answer: `Yes, and the tests are different for each. The parent taking the pay needs 26 weeks of continuous employment with their employer by the end of the 15th week before the due week, and average earnings of at least £129 a week. The other parent has to have worked, employed or self-employed, in at least 26 of the 66 weeks before the due week and earned at least £390 in total in any 13 of those weeks, which is a looser test designed to cover self-employment and changes of job.` },
    { question: `Can we take shared parental leave at the same time?`, answer: `You can. Parents may be off together for some or all of the shared weeks, take one continuous block each, or split the time into as many as 3 separate blocks per parent. Every block needs 8 weeks' notice to the employer. There are two documents involved: a Notice of Entitlement and Intention to Take that sets out the plan, then a Period of Leave Notice confirming each block before it starts.` },
  ],
  'home-buying-total-cost-calculator': [
    { question: `Besides the deposit, what costs come with buying a home?`, answer: `Alongside the deposit and price, buyers should budget for stamp duty (or LBTT/LTT), solicitor fees of £1,000 to £2,000, a survey at £400 to £1,500, searches around £250 to £400 and a land registry fee of £100 to £500. A mortgage arrangement fee of up to £2,000 and a valuation fee can add to that, and removals typically cost another £500 to £1,500 with £50 to £100 for redirected mail.` },
    { question: `How much stamp duty does a first-time buyer pay in 2026/27?`, answer: `Nothing on the first £300,000, then 5% on the portion between £300,001 and £500,000. A £400k purchase therefore costs £5,000 and a £500k purchase £10,000. Above £500,000 the relief is lost altogether, so a £700k first-time buyer pays the standard £25,000. For comparison, a standard buyer at £300k pays £5,000 and a second-home buyer at £300k pays £20,000 including the 5% surcharge.` },
    { question: `How much cash do I need beyond the deposit on a £300,000 home?`, answer: `Around £5,379 for a first-time buyer, taking the total upfront to £35,379 with a 10% deposit of £30,000. That figure covers £1,500 for the solicitor, £600 for a HomeBuyer Report, a £999 mortgage arrangement fee, £900 for removals, £80 for an EPC, £300 for the first year of buildings insurance and £1,000 for initial decoration or repairs. A mortgage broker, if you use one, adds £0-£500 on top.` },
    { question: `What does a £300,000 house cost to run each month?`, answer: `Roughly £2,100-£2,500 a month in total. A £270k mortgage at 4.5% over 25 years costs about £1,500, council tax £100-£250 depending on the band, buildings and contents insurance £25-£50, gas and electricity £150-£250, water £30-£50, broadband £25-£40 and the TV licence £15. Setting aside 1% of the property value each year for maintenance adds around £250 a month.` },
    { question: `Which government schemes cut the cost for first-time buyers?`, answer: `A Lifetime ISA adds a 25% bonus on up to £4,000 saved a year, worth up to £1,000 annually. First Homes gives a 30-50% discount on new builds for households earning under £80k (£90k in London). Shared Ownership lets you buy a 25-75% share and rent the rest, the Mortgage Guarantee Scheme supports 95% LTV mortgages, and Family Springboard or Deposit Boost products let a parent's savings act as security. Used together these can save £10,000-£30,000 or more.` },
  ],
  'council-tax-reduction-calculator': [
    { question: `Do I qualify for a reduction on my council tax bill?`, answer: `Council Tax Reduction helps people on low incomes, and because each English council runs its own scheme the rules, income limits and top discount vary from one area to the next. A working-age claimant might get a partial reduction, or cover for the whole bill in more generous areas, while many councils insist on a minimum payment of 8-25%. Pension-age claimants sit under a national scheme instead and can reach 100%.` },
    { question: `How much can I have in savings and still get CTR?`, answer: `In most working-age schemes, capital below £6,000 is disregarded completely and between £6,000 and £16,000 it is treated as generating £1 a week of income for every £250 above the lower figure, which shrinks your award without ending it. For pension-age claimants the lower limit is £10,000 and it is £1 a week for every £500 above it. Above £16,000 you normally get nothing at all, except that anyone receiving the Pension Credit Guarantee has their capital ignored entirely. Your main home is not counted.` },
    { question: `Does Universal Credit automatically give me Council Tax Reduction?`, answer: `No, and this catches people out. CTR needs its own application, although some councils link to DWP data and open a claim on your behalf. UC income is counted, so a single person on the £424.90 monthly standard allowance is assessed on £98 a week. How much reduction that leaves depends on your council's income rules. If you work as well, the UC taper and the CTR taper stack and the combined effective marginal rate often sits between 70% and 85%.` },
    { question: `How long does a Council Tax Reduction claim take to process?`, answer: `Councils typically take 4-8 weeks. Have ready the National Insurance numbers for you and any partner, proof of income such as payslips, benefit letters or pension statements, two months of bank statements, proof of identity and your council tax account number. Awards are usually backdated one month, or three months where you can show good cause such as illness or missing paperwork, so applying as soon as your income falls protects money you cannot claw back afterwards.` },
    { question: `Can pensioners get their whole council tax bill covered?`, answer: `Often, yes. The pension-age scheme is national rather than local, applies from State Pension age (66, rising to 67 by 2028) and normally covers the full bill for anyone on Pension Credit. Income above the Pension Credit threshold gives a tapered reduction instead, with the upper limit set by your council. Up to 910,000 eligible pensioner households do not claim Pension Credit (DWP, 2023/24), which is worth £3,000 to £4,000 a year by itself before CTR, Housing Benefit and a free TV licence are counted. Claim Pension Credit from DWP first and CTR follows automatically in many areas.` },
  ],
  'student-budget-planner-calculator': [
    { question: `Why do so many students run out of money by spring term?`, answer: `Maintenance loans land in three lump sums, in September, January and April, while rent and food go out every month, so first-term overspending often leaves the pot short by spring. Mapping income and expenses month by month across the academic year shows where the gaps fall before they bite, which is the point of dividing the annual total by 12 rather than spending each instalment as it arrives.` },
    { question: `How much should I budget each month as a student?`, answer: `Outside London a realistic figure is £900 to £1,800 a month, and in London £1,200 to £2,200. Rent takes the largest share at £400 to £900, averaging around £600, with food at £200 to £300, bills at £80 to £150 where halls do not include them, transport at £40 to £100 and going out at £80 to £200. Books and equipment add a further £15 to £35.` },
    { question: `Which UK cities are cheapest to study in?`, answer: `Sunderland is the most affordable at around £12k a year, with Hull at £12.5k, Stoke £13k, Liverpool £13.5k and Sheffield £14k. Cardiff and Newcastle sit at £14.5k, Leeds and Glasgow at £15k. At the other end London passes £22k, Oxford and Cambridge run to £18k or £20k, and Edinburgh reaches £17k. Each figure covers accommodation, food, bills, transport and social spending across the year.` },
    { question: `How much can I earn from a term-time job?`, answer: `A job of 8 to 15 hours a week during term brings in £400 to £900 a month, and full-time work over the summer adds £2,500 to £5,000 towards the following year. Some 65% of UK students work in term time, according to NUS figures from 2024, which is unsurprising given that the gap between the maintenance loan and real costs typically runs to £2,000 to £5,000 a year.` },
  ],
  'minimum-wage-calculator': [
    { question: `Does the minimum wage I'm owed depend on my age?`, answer: `Yes. The rate you are legally owed depends on your age band: £12.71 an hour for 21 and over (the National Living Wage), £10.85 for 18 to 20, and £8.00 for under-18s and eligible apprentices. Enter your age group and hours and the calculator shows the minimum pay as weekly, monthly and annual figures. On a 39-hour week the annual minimums are £25,775, £22,004 and £16,224 respectively.` },
    { question: `What counts as working time for the minimum wage?`, answer: `Working time includes hours spent working, travel between work assignments (but not your regular commute), training during normal hours, on-call time when you must remain at the workplace and time spent putting on a mandated uniform. It excludes the commute, voluntary unpaid overtime and rest breaks. On sleep-in shifts, following the 2018 Mencap Supreme Court ruling, only the hours you are actually working count. Piece workers must be paid so that they average at least 120% of the minimum wage for the expected output under Fair Piece Rate rules.` },
    { question: `Can my employer count tips towards the minimum wage?`, answer: `No. Tips, including those pooled and shared out through a tronc, cannot be used to top up base pay to reach the minimum wage. Since 1 October 2024 the Tipping Act 2023 has required employers to pass all tips to workers in full, on top of wages. Your hourly pay before tips must on its own meet the rate for your age band, and the calculator checks your pay on that basis.` },
    { question: `Can salary sacrifice take my pay below the minimum wage?`, answer: `No. A salary sacrifice for a pension, cycle-to-work or electric vehicle scheme reduces your contractual gross pay, and the pay left after the sacrifice must still be at least the minimum wage for every hour you work. An employer cannot agree to an arrangement that breaches this. For a 37.5-hour week on the £12.71 National Living Wage, that means post-sacrifice pay of at least £476.63 a week, or £24,785 a year.` },
    { question: `How do I report being paid below the minimum wage?`, answer: `You can report suspected underpayment confidentially to ACAS on 0300 123 1100 or through the gov.uk NMW complaints form. HMRC investigates, can demand records and can force the employer to pay the arrears with a penalty of up to 200% (capped at £20,000 per worker). Employers are also named publicly on the government's NMW Underpayment List. You are protected from victimisation under the Employment Rights Act, and claims for unpaid wages can go back 6 years.` },
  ],
  'first-homes-scheme-calculator': [
    { question: `Do I have to be a first-time buyer to use the First Homes scheme?`, answer: `Yes. Only first-time buyers in England qualify, and they get a discount of at least 30% off a new-build home, rising to 50% with some councils. After the reduction the property must cost no more than £250,000, or £420,000 in London, and you must take a mortgage for at least 50% of the discounted price rather than buying outright.` },
    { question: `What is the household income limit for First Homes?`, answer: `Your household income must be below £80,000, or £90,000 if the home is in London. Councils can layer local rules on top, such as living or working in the area for 3 or more years, key worker status (NHS, teacher, police or armed forces) or a place on the housing waiting list. For the first 3 months of marketing, homes are often reserved for local residents before opening to a wider area.` },
    { question: `What happens to the First Homes discount when I sell?`, answer: `The same percentage discount is written into the title and applies to every future sale. If you bought at 30% off a £280,000 valuation, paying £196,000, and the property is later worth £350,000, you must sell at £245,000. The discount then passes to the next buyer. This keeps the home affordable in perpetuity but caps the capital gain you can take out, which is why the scheme suits people planning to stay more than 5 years.` },
    { question: `Which lenders offer mortgages on First Homes properties?`, answer: `Halifax, Barclays, Nationwide and Skipton are among the lenders that accept First Homes, although the choice is narrower than for a full-price purchase. The mortgage is based on the discounted price, so on a £196,000 purchase you borrow against £196,000 rather than the £280,000 market value, and a typical deposit of 5-10% comes to £10k-£20k instead of £14k-£28k. A broker can confirm which lenders are active on a particular development.` },
    { question: `How does First Homes compare with Shared Ownership?`, answer: `With First Homes you own 100% of the property from day one at a 30-50% discount, whereas Shared Ownership means buying a 25-75% share and paying rent on the rest. First Homes replaced Help to Buy in April 2023 when the equity loan ended. Both can be combined with a Lifetime ISA, which adds a 25% government bonus on up to £4,000 a year, and first-time buyers pay no SDLT below £300,000 under either route.` },
  ],
  'shared-ownership-affordability-calculator': [
    { question: `Can I afford a shared ownership home on my income?`, answer: `The provider and your mortgage adviser add the mortgage on the share you buy, the rent on the share you do not own and the service charge, then check the total against your budget. Until August 2024 Homes England guidance capped those costs at 45% of take-home household income; providers now set their own minimum surplus income instead, but 45% is still a useful rough guide. Lenders typically cap the mortgage at about 4.5 times gross income. On £45,000 with a £14,000 deposit, a 35% share of a £350,000 home costs £1,302.62 a month at 5.73%, 43.5% of take-home pay, while a 40% share goes just over the guide.` },
    { question: `Who is eligible to buy a shared ownership home?`, answer: `In England your household income must be £80,000 or less, or £90,000 or less in London, and you must be unable to afford a suitable home outright. You also need to be a first-time buyer, a former homeowner who cannot afford to buy now, forming a new household, an existing shared owner who wants to move, or a homeowner who cannot afford a home that meets your needs. Homeowners must have a sale agreed and complete it on or before completing the shared ownership purchase. Some homes need a local connection, and you apply through the organisation selling the home.` },
    { question: `How much rent do I pay on the share I do not own?`, answer: `For new-build homes rent is limited to 3% a year of the value of the landlord's share, and 2.75% is the calculator's default. It rises each year: leases from before 12 October 2023 cap the increase at RPI plus 0.5%, while newer leases use either RPI plus up to 0.5% or CPI plus 1%, so it can climb faster than a fixed mortgage payment. The service charge comes on top and varies widely by building, and both count towards your housing costs in the affordability check.` },
    { question: `Can I buy a bigger share of my shared ownership home later?`, answer: `Yes, through staircasing. You can usually buy extra shares of 10% or more at any time, or 5% or more on newer leases, priced from a RICS valuation. Homes sold on the newer model since April 2021 also allow 1% a year for the first 15 years, priced from the original price adjusted by the House Price Index, with no administration fee. Some protected rural areas cap ownership at 80%. Stamp duty is not due on staircasing until your share goes above 80%, unless you paid it on the full market value at the start.` },
    { question: `What are the hidden costs of shared ownership?`, answer: `You pay for repairs and maintenance whatever share you own, although newer-model homes have an initial repair period, usually 10 years, in which the landlord covers essential structural and external repairs and you can claim up to £500 a year for fittings such as boilers and pipes. When you sell, the landlord first gets 4, 8 or 12 weeks to find a buyer. Lease length is a quiet risk: homes funded under the 2021-2026 Affordable Homes Programme have leases of at least 990 years, but older leases can be far shorter, and extending one below 80 years costs much more, so check the remaining term before you commit.` },
  ],
  'invoice-profit-calculator': [
    { question: `How do I work out the real profit on a single job or invoice?`, answer: `Start from the invoice total excluding VAT, since that VAT belongs to HMRC rather than to you. Take off the direct materials used and the direct labour, including the employer NI and pension on those wages, then allocate a share of overheads such as rent, insurance, software and vehicle costs. What is left is the net profit the job earned, and following it invoice by invoice shows which clients and services actually pay.` },
    { question: `What is the difference between profit margin and markup?`, answer: `Margin measures profit against revenue, dividing net profit by the invoice total, while markup measures it against costs, dividing net profit by what the job cost you. They describe the same job with different numbers, so a 25% markup is a 20% margin. Quoting on one and reporting on the other is a reliable way to end up disappointed, particularly on work where subcontractor and material costs dominate.` },
    { question: `What must a UK invoice legally include?`, answer: `The word Invoice, a unique sequential number, the date it was issued, your name, address and contact details, and the customer's name and address. Add a description of the goods or services, quantities and unit prices, and the total. VAT-registered businesses also show the VAT rate, the VAT amount and their VAT registration number. Payment terms usually run to 30 days, though many small businesses set 7 to 14 days instead.` },
    { question: `Can I charge interest on an invoice paid late?`, answer: `Yes. The Late Payment of Commercial Debts (Interest) Act 1998 gives a statutory right to interest at 8% above the Bank of England base rate, 3.75% since December 2025, so 11.75% in total, running from the day after payment fell due. Fixed compensation of £40 to £100 per overdue invoice can be added. Both apply automatically after 30 days unless your contract sets different terms, which matters when average payment runs to 56 days.` },
  ],
  'employee-vs-contractor-calculator': [
    { question: `Am I better off as an employee or a contractor?`, answer: `Employing someone costs far more than salary. Employer NI runs at 15% above the £5,000 threshold, auto-enrolment pension adds at least 3%, and recruitment, training, insurance and equipment push the total roughly 20% to 35% above gross pay. Setting that full cost against a contractor arrangement is the only fair comparison. On the worker's side an outside-IR35 contractor usually keeps more, at the price of holiday, sick pay and pension cover.` },
    { question: `How much more does a contractor cost than an employee?`, answer: `Roughly 30% to 50% more in cash terms, though that comparison hides as much as it shows. An employee on £50k costs £59,250 once £6,750 of employer NI and £2,500 of pension are added, while the same role at £400 a day over 220 days runs to £88k. Against that, the contractor brings no holiday, sick or maternity cost, no employment law exposure and no redundancy liability, and can be scaled with the workload.` },
    { question: `What benefits do I lose by contracting instead of employment?`, answer: `The employer pension match goes, along with 25 to 30 days of paid holiday plus bank holidays, statutory sick pay of £123.25 a week and any enhancement on top, up to 39 weeks of maternity pay or 2 weeks of paternity pay, private medical cover where it is offered, and bonus, share and commission schemes. Income protection has to be bought privately at £20 to £60 a month, the pension becomes entirely your own responsibility, and time off is simply unpaid.` },
    { question: `Who decides my IR35 status, me or the client?`, answer: `Since April 2021 medium and large clients determine the status of each engagement themselves. Where the client is small, with turnover under £15M, the contractor makes the call. HMRC's CEST tool gives an initial view, and the underlying tests look at control, the right of substitution, mutual obligation and financial risk, with disputes settled at tribunal. Inside IR35 the work is taxed as employment, which is why many contractors accept it only at a premium of 20% to 30%.` },
  ],
  'standing-charge-savings-calculator': [
    { question: `How much am I paying in standing charges before I use any energy?`, answer: `Standing charges are fixed daily fees that hit your bill whatever your usage, averaging 54.83p a day for electricity and 29.68p for gas under the Ofgem price cap for 1 October to 31 December 2026. That adds up to roughly £308 a year before a single unit is used.` },
    { question: `Is a zero standing charge tariff worth it for my home?`, answer: `It depends entirely on how much you use. Utilita and OVO have offered these tariffs since 2024, charging 2 to 3p more per kWh in exchange for dropping the daily fee. They suit holiday homes, single occupants and any property under 1,500 kWh of electricity a year. A family home on 3,000 kWh or more, or anything on electric heating, usually pays more overall.` },
    { question: `How do I work out the breakeven point on a no-standing-charge tariff?`, answer: `Divide the annual standing charge by the extra pence charged per unit, and the result is the yearly kWh figure below which the zero-charge deal wins. A £200 standing charge set against 2.5p extra per kWh breaks even at 8,000 kWh. Because most households use more than that, the majority still come out better off on a tariff that keeps the daily fee.` },
    { question: `Why have standing charges risen so steeply?`, answer: `The combined daily fee was 25 to 30p in 2020 and has since doubled. Part of it covers network maintenance and transmission, and part spreads the cost of supplier failures across all customers, a burden that grew after Bulb collapsed in 2021. Because the fee ignores consumption, it falls hardest on low-energy users, pensioners and owners of second homes.` },
    { question: `Is Ofgem going to scrap standing charges?`, answer: `A consultation across 2024 and 2025 looked at making a zero standing charge tariff the default, driven by the argument that light users subsidise infrastructure used mostly by heavy ones. The proposal would swap the flat daily fee for progressive use-based pricing. Suppliers resist because the charge funds the last-resort regime that rehoused 4 million Bulb customers in 2021. Standing charges look likely to stay, but fall 10 to 20% by 2028.` },
  ],
  'gas-cost-calculator': [
    { question: `What will my annual gas bill come to from my kWh usage?`, answer: `Your yearly bill combines the units you burn at 7.97p per kWh with a daily standing charge of 29.68p under the October to December 2026 cap, shaped by boiler efficiency, thermostat settings, insulation and house size. Feed in your usage, unit rate and standing charge to see the total.` },
    { question: `How much gas does a three-bed semi use in a year?`, answer: `A typical 3-bed semi gets through 12,000 to 14,000 kWh a year, which is £700 to £950 of gas. A well-insulated 1-bed flat uses 6,000 to 8,000 kWh at £350 to £550, a 4-bed detached 16,000 to 20,000 kWh at £900 to £1,400, and a solid-wall Victorian terrace with poor insulation 18,000 to 25,000 kWh at £1,000 to £1,750.` },
    { question: `Does turning the thermostat down one degree really save money?`, answer: `It does, and by more than most people expect. Dropping 1 degree C, usually from 20°C to 19°C, cuts up to 10% off the heating bill, worth £80 to £120 a year for a typical home. In the worked example of a 3-bed semi burning 12,000 kWh, that single degree is worth about £93, which is comparable to the £130 saved by fitting a 93% efficient boiler.` },
    { question: `What cuts a gas heating bill fastest?`, answer: `Loft insulation at 270mm saves £200 to £500 a year and cavity wall insulation £300 to £500, so the fabric of the house comes first. Draught-proofing adds £40 to £120, a hot water tank jacket £50, thermostatic radiator valves £100 to £200 and a smart thermostat from Nest or Hive £50 to £150. Stacked together these measures save a typical home £600 to £1,200 a year.` },
    { question: `Is a heat pump cheaper to run than a gas boiler?`, answer: `Roughly comparable, and sometimes cheaper. Electricity at 26.32p per kWh looks more than three times dearer than gas at 7.97p, but a heat pump produces 3 to 4 kWh of heat per 1 kWh of electricity, so the effective cost is 7 to 9p per kWh of heat. On Octopus Cosy with off-peak power at 12p it drops to 3 to 4p and undercuts gas. Installation runs £8,000 to £14,000 before the £7,500 grant.` },
  ],
  'exponent-calculator': [
    { question: `What does raising a number to a power actually mean?`, answer: `A power such as a^n means multiplying a by itself n times, so the exponent counts how many times the base is repeated. That gives 5² = 25, 2³ = 8 and 10⁴ = 10,000. Positive, negative and fractional exponents are all covered, along with expressions that mix several operations, and each result comes with step-by-step working.` },
    { question: `What do negative and fractional exponents mean?`, answer: `A negative exponent gives a reciprocal, so a^(−n) = 1/a^n and 5⁻² works out at 1/25. A fractional exponent gives a root, so a^(1/2) is the square root, making 9^(1/2) equal to 3, and a^(1/3) is the cube root. UK GCSE Maths deals with integer exponents, while fractional and irrational ones appear at A-level.` },
    { question: `What are the index laws for multiplying and dividing powers?`, answer: `Powers of the same base add when multiplied and subtract when divided, so 2³ × 2⁴ = 2⁷ = 128 and 5⁵ ÷ 5² = 5³ = 125. Raising a power to another power multiplies the exponents, giving (3²)³ = 3⁶ = 729, and a bracketed product distributes as (ab)^n = a^n × b^n. Anything to the power 0 comes out at 1, provided the base is not zero.` },
    { question: `How do exponents work in compound interest calculations?`, answer: `Future value is the principal multiplied by (1 + rate)^years, so the exponent is simply the number of years. £10,000 at 5% for 30 years is multiplied by 1.05³⁰, a factor of 4.32, ending at £43,219, while 7% over the same 30 years multiplies by 7.61 and ends at £76,123. The rule of 72 gives a rough doubling time, dividing 72 by the rate, which puts 5% at 14.4 years and 10% at 7.2.` },
  ],
  'logarithm-calculator': [
    { question: `What is a logarithm actually telling me?`, answer: `To what power the base must be raised to reach a given number. That is why log base 10 of 1000 is 3, because 10^3 is 1000, and why log₂(8) is 3. Common logs (base 10), natural logs (base e, written ln) and custom bases are all covered, and the same relationship read the other way is simply exponentiation.` },
    { question: `What is the difference between log and ln on a calculator?`, answer: `The 'log' button on most UK calculators means log₁₀, the common logarithm, while 'ln' means the natural logarithm, which has base e, roughly 2.718. Both appear throughout A-Level Maths. The change-of-base formula log_b(x) = ln(x) / ln(b) lets you reach any other base from either button, and that is how custom bases are handled here.` },
    { question: `How do I solve an equation such as 3^x = 100?`, answer: `Take logs of both sides. That turns the exponent into a multiplier, so x × log(3) = log(100), and dividing gives x = 2/0.477, which is 4.19. Natural logs would produce the same answer. Finance uses the identical move to work out time horizons, since ln(future/present) ÷ ln(1+r) returns the number of years a sum needs in order to grow to a target.` },
    { question: `Why are the Richter and decibel scales logarithmic?`, answer: `Because the quantities involved span enormous ranges, and a logarithmic scale compresses them into readable numbers. Each step stands for a multiple rather than an addition, so a magnitude 7 earthquake is 10 times larger than a magnitude 6, a 10 dB rise means 10 times louder, and pH 5 is ten times more acidic than pH 6. Star brightness and information theory, where bits equal log₂ of the possibilities, work on the same principle.` },
  ],
  'employee-cost-breakdown-calculator': [
    { question: `What does an employee really cost on top of their salary?`, answer: `The statutory items come first. Employer National Insurance takes 15% of earnings above £5,000, a workplace pension adds at least 3% of qualifying earnings, and employer's liability insurance is compulsory, which together put roughly 18% to 20% on the gross salary. Recruitment, training, equipment and office space then push the real figure higher, so a £40k salary tends to cost £45k to £48k in practice.` },
    { question: `Does salary sacrifice save the employer money too?`, answer: `It does. Salary sacrificed into a pension is no longer subject to employer National Insurance at 15%, or to the 0.5% Apprenticeship Levy where the pay bill is large enough, so £1,000 sacrificed saves the employer £155. The better arrangement passes that saving back as an additional pension contribution, so £1,000 becomes £1,155 in the employee's pot. Beyond the administration it costs the business nothing and improves the package without raising salaries.` },
    { question: `Is a contractor cheaper than a permanent hire?`, answer: `Not usually on cost alone. A contractor at £450 a day across 220 days comes to £99,000, against about £94k for a permanent hire on £75k once everything is loaded in. The contractor takes no holiday or sick pay, carries no pension liability and starts productive, so short engagements under 6 months and peaks in demand favour that route. For steady long-term work the employee is generally 10% to 15% cheaper at full utilisation.` },
    { question: `What does statutory sick pay cost an employer?`, answer: `Statutory sick pay is £123.25 a week and can run for up to 28 weeks, which is a meaningful liability for a small team even though no single hire is likely to need all of it. Maternity and paternity pay is largely reclaimed from government, so the long-run cost is smaller than it first looks, but the money leaves the business before it comes back and has to be carried in the meantime.` },
  ],
  'contractor-vs-perm-calculator': [
    { question: `What day rate do I need to match my permanent salary?`, answer: `Both sides have to be reduced to annual take-home before they can be compared. The day rate is multiplied by the days actually billed, usually 220 to 230 after holidays and gaps between contracts, then Corporation Tax, salary, employer NI, pension, accountancy and insurance come off. As a benchmark, £400 a day gives £88,000 of revenue and matches a permanent salary of roughly £62k to £68k once holiday, pension and sick pay are valued.` },
    { question: `How much less do I take home inside IR35?`, answer: `Roughly 12% to 17% less than the same contract would pay outside the rules. Inside IR35 the engagement is taxed as employment, with PAYE, employee NI and employer NI deducted at source, and the effective rate lands between 40% and 48%. None of the employment benefits come with it either, which is why many contractors take inside-IR35 work only at a premium of 20% to 30% over a permanent role.` },
    { question: `What insurance does a contractor need each year?`, answer: `Professional indemnity cover runs at £60 to £200 a year and public liability at £50 to £150, with IR35 enquiry insurance a further £200 to £400 for anyone working through a limited company. These are business costs, so they come off revenue before Corporation Tax, alongside accountancy fees. Set against a permanent role, where the employer carries the equivalent risks, they are part of what the day rate premium is paying for.` },
    { question: `How many days a year can I realistically bill?`, answer: `Plan on 220 to 230 once holidays and unpaid gaps are removed, which most contractors express as an 80% utilisation target, meaning 44 weeks worked and 8 unpaid. Gaps of 1 to 4 weeks between contracts are normal, and 2 to 4 weeks a year should go on training so skills do not go stale. Holding a 6 month emergency fund, rather than the 3 months an employee might keep, follows from that pattern.` },
  ],
  'postgraduate-loan-cost-calculator': [
    { question: `How much will my postgraduate loan cost me over the full 30 years?`, answer: `Repayments run at 6% of anything you earn above £21,000, and interest builds at RPI plus 3%, held at the 6% ceiling, on the outstanding balance across the 30-year term. On a £40,000 salary that is £1,140 a year, rising to £2,340 on a £60k salary and £3,540 on an £80k one, so projecting your salary across three decades is what produces the lifetime figure. Anything left at the end of the term is written off.` },
    { question: `Do I repay a postgraduate and an undergraduate loan at the same time?`, answer: `Yes, and both come out of the same payslip. Plan 5 takes 9% of income above £25k while the postgraduate loan takes 6% above £21,000, so once you are past both thresholds the combined marginal rate is 15%. On a £50k salary that means £2,250 on the undergraduate loan and £1,740 on the postgraduate one, £3,990 a year in total, which is worth working into a budget before starting a Master's.` },
    { question: `How much is the postgraduate loan and what will it cover?`, answer: `The Master's loan is worth up to £13,206 a year and is paid to you, so it can go towards tuition, living costs or both. Home tuition typically runs at £8,000 to £15,000 and living costs at £12,000 to £15,000, since a Master's covers 12 months rather than an academic year, giving a total of £20,000 to £30,000. The loan therefore meets 40 to 65% of the cost, with the rest coming from scholarships, savings, an employer or family.` },
    { question: `Who can apply for a UK postgraduate loan?`, answer: `You need to be a UK resident, under 60, and studying for a first Master's. Applications open on gov.uk from May for a September start. Doctoral study has its own loan of up to £31,122 spread across three years. Repayment sits on Plan 3, beginning once income passes £21,000 and running for 30 years, after which any remaining balance is written off.` },
  ],
  'wedding-cost-calculator': [
    { question: `How much does an average UK wedding cost?`, answer: `The Hitched 2025 survey put the average at £20,775, excluding rings and the honeymoon, with the median couple spending £18,500. The venue takes 35-40% of that, food and drink 25-30%, photography 8-12%, dress and attire 6-10%, flowers 4-7%, entertainment 4-6% and transport 2-3%. Add a honeymoon at £3,500-£8,000 and rings at £1,000-£3,000, with the engagement ring averaging £2,750 on its own. London runs 40-60% above average, while Scotland and the North East sit 20% below.` },
    { question: `Can I have a UK wedding for £10,000?`, answer: `Yes, at around 60 guests. The biggest line is venue and catering at roughly £4,500, which works out at £75 a head, with photography next at £1,000. A budget of this size then typically allows £600 for the dress and £200 for the groom, £600 for rings, £400 each for flowers, decor and music, and £1,500 for the honeymoon, holding £400 back as contingency. Marrying midweek or off-season and using a dry-hire venue with your own caterer does most of the work, and help from friends with the cake, hair or photographs saves £1,000-£3,000.` },
    { question: `Is wedding insurance worth buying?`, answer: `For most couples it is, because the deposits are the real exposure. Suppliers commonly take 25-50% non-refundable deposits, so cancelling can cost £5,000-£10,000 before anything has happened. A policy at £80-£250 covers cancellation through illness, supplier failure, venue closure, weather on some policies, and public liability up to £2M, but never a change of heart. Paying deposits by credit card adds Section 75 protection on purchases over £100 if a supplier goes under.` },
    { question: `Are wedding gifts from parents free of inheritance tax?`, answer: `Gifts made in consideration of marriage carry their own exemption, at £5,000 from each parent, £2,500 from each grandparent and £1,000 from anyone else. Anything larger falls back on the £3,000 annual exemption. Gifts are not taxable income for the couple receiving them, and honeymoon registry payments count as gifts in the same way. Marriage Allowance is worth £252 a year where one partner is a non-taxpayer and the other pays basic rate, and it can be backdated 4 years. Civil partnerships have been treated identically since 2014.` },
  ],
  'time-duration-calculator': [
    { question: `How do I work out the hours between two times?`, answer: `Convert both times to minutes, subtract, then convert back. From 9:15 AM to 5:45 PM that is (17×60 + 45) − (9×60 + 15), or 1065 − 555, which leaves 510 minutes. Divide by 60 and it reads as 8h 30min, or 8.50 decimal hours for a timesheet. Spans that cross midnight behave the same way once the later time is treated as belonging to the next day, which the calculator handles for you.` },
    { question: `How many hours a week can I legally work in the UK?`, answer: `The Working Time Regulations cap the average at 48 hours a week, measured over a 17-week reference period, unless you have opted out in writing. A standard full-time week is 35-40 hours, and once holiday, bank holidays and some sickness are taken off, a full-time year comes to roughly 1,700-1,800 hours rather than the theoretical 2,080. Overtime carries no statutory premium in the UK, so it is paid at whatever rate your contract specifies.` },
    { question: `How much holiday am I entitled to in the UK?`, answer: `5.6 weeks of your normal working week, which is 28 days for someone working five days, and the 8 bank holidays can be counted inside that figure. Part-time entitlement is pro-rated on the same basis, so a 22.5-hour week earns 16.8 days. Because the entitlement is expressed in weeks rather than days, it adjusts to irregular patterns, and it is a statutory minimum rather than a limit on what an employer may offer.` },
    { question: `How long does it take to buy a house in the UK?`, answer: `Usually 12-16 weeks from accepted offer to completion, with selling taking about 22 weeks measured from the listing date. Other timelines are worth planning around too. A mortgage offer holds for 90-180 days before reassessment, probate takes 8-16 weeks and occasionally past 6 months, and an HMRC refund lands in 2-12 weeks. A passport renewal is 3-10 weeks, or about 1 week on the priority service.` },
  ],
  'split-bill-calculator': [
    { question: `How much should I tip in a UK restaurant?`, answer: `Between 10-12.5% at a table-service restaurant if no service charge has been added, and up to 15% where the service was particularly good. If a charge is already printed on the bill it is usually 12.5%, or 15% in upmarket London places, and there is no expectation of tipping on top of it. Cafés and counter service treat the tip jar as optional, and nobody tips for drinks ordered at a pub bar.` },
    { question: `Can I refuse to pay a service charge in the UK?`, answer: `Yes. A service charge has been optional in the UK since the 1980s, and you can ask for it to be taken off for any reason, including on a large-group booking where house policy calls it mandatory. What has changed is where the money ends up. Since October 2024 the Employment (Allocation of Tips) Act 2023 has required employers to pass 100% of tips to staff. Cash tips reach staff most directly, while card tips travel through the restaurant's tronc.` },
    { question: `How do you split a bill fairly with non-drinkers?`, answer: `An even split stops being fair once drinks are 30-50% of the total. Three approaches work. Everyone pays for their own drinks and the food is split evenly, or the drinkers take a 30% larger share, or the bill is itemised in an app such as Splitwise or Tricount. British custom also holds that the birthday person does not pay and the rest cover that share. Where orders differ sharply, agree the method before ordering rather than when the bill arrives.` },
    { question: `Can I claim a client lunch against my UK tax?`, answer: `No. Entertaining clients has not been deductible against Corporation Tax since 1965, and the VAT on it cannot be recovered either. Meals bought while travelling away from your normal workplace are a different matter and can be deducted by sole traders and employees. Staff entertaining is also allowed, with annual social events such as the Christmas party deductible up to £150 per head per year and the VAT recoverable, apportioned if clients attend as well.` },
  ],
  'speed-distance-time-calculator': [
    { question: `How do I calculate speed from distance and time?`, answer: `Divide the distance by the time, keeping the units consistent. Driving 150 miles in 2 hours 30 minutes means 150 ÷ 2.5, which gives 60 mph, or 96.56 km/h and 26.82 m/s. The same relationship rearranges to Distance = Speed × Time and Time = Distance ÷ Speed. For a journey made in several legs at different speeds, use total distance over total time rather than averaging the speeds, because the two answers are not the same.` },
    { question: `What is the stopping distance at 70 mph in the UK?`, answer: `96m, or 315ft, according to the Highway Code, and that figure doubles on a wet road. At 60 mph it is 73m (240ft), and at 30 mph 23m (75ft), so the distance grows a good deal faster than the speed. Reaction time makes up 0.7s of the total before the brakes do anything, which is where the two-second gap rule comes from. Motorway and dual carriageway limits are 70 mph, with 60 mph on a single carriageway.` },
    { question: `How long does it take to drive from London to Manchester?`, answer: `About 3.5 hours of motorway driving for the 200 miles, plus breaks. That allows for realistic averages rather than the posted limit, since traffic pulls motorway driving down to 60-65 mph, rural A-roads run at 35-45 mph, and urban driving averages 12-20 mph, with London closer to 12 mph. London to Edinburgh takes around 8 hours by road against 4.5 hours by train.` },
    { question: `How do I convert mph to km/h and m/s?`, answer: `Multiply by 1.609 to go from mph to km/h. One metre per second is 3.6 km/h or 2.237 mph, and a knot is 1.852 km/h or 1.151 mph. The handiest anchor is 60 mph, which is one mile a minute, 88 ft per second, 26.8 m/s and close to 100 km/h, while 100 km/h is 27.78 m/s or 62.1 mph. Higher up the scale, Mach 1 at sea level is 1,235 km/h or 767 mph.` },
    { question: `What pace do I need to run 10 km in 50 minutes?`, answer: `5:00 per kilometre, which is the same thing as a 12 km/h average. Pace and speed carry the same information written the other way up, one as time per unit of distance and the other as distance per unit of time. For comparison, the average UK Parkrun finish of 28:30 over 5K is 5:42/km, and a marathon of 42.195km in 4 hours works out at 10.55 km/h. Recreational running sits around 6 mph, a 10 min/mile pace, against 10 mph at 6 min/mile for a competitive runner.` },
  ],
  'profit-and-loss-calculator': [
    { question: `How is gross profit worked out on a P&L statement?`, answer: `Gross profit is revenue, or turnover, minus the cost of goods sold. COGS covers the direct costs of delivering what you sell, meaning materials, direct labour, manufacturing overheads and freight-in, and nothing beyond that. Dividing gross profit by revenue gives the gross margin, which is the measure of pricing power and product economics. Overheads, interest and tax come off further down the statement to reach operating and net profit.` },
    { question: `What is the difference between operating profit and net profit?`, answer: `Operating profit, or EBIT, is what remains after overheads such as rent, salaries of non-production staff, marketing and insurance come off the gross profit, so it measures how well the business runs day to day. Net profit is what survives interest and tax as well, and is the return shareholders actually see. Both are worth watching, since a falling operating margin points at overhead bloat while a falling net margin alone usually means interest or tax.` },
    { question: `How much Corporation Tax will my company pay on profit?`, answer: `The Small Profits Rate of 19% applies below £50,000 and the main rate of 25% above £250,000, with Marginal Relief sliding the effective rate between the two in between. A company on £75k pays £15,725, an effective 21%. At £150k the bill is £34,225, or 22.8%, and at £300k the flat 25% produces £75,000. Plenty of small companies sit inside the Marginal Relief band, where timing expenditure carefully is worth real money.` },
    { question: `Why is my business profitable but short of cash?`, answer: `Because a profit and loss statement runs on the accrual basis, counting revenue when it is earned and costs when they are incurred, rather than when money actually moves. You can show a healthy profit while £150k sits unpaid by customers and a supplier bill falls due tomorrow. Companies House data attributes 80% of small business failures to cash flow rather than profitability, which is why a 13-week rolling cash forecast belongs next to the P&L.` },
  ],
  'freelance-quote-calculator': [
    { question: `What goes into a freelance quote besides my hourly rate?`, answer: `Estimate the hours across research, production, revisions and project management, multiply by your hourly rate, then add materials and third-party costs at what they actually cost. A buffer of 10% to 20% on the hours protects against scope creep. Overhead recovery for software, insurance and workspace comes next, then the profit margin, and VAT last if you are registered. Showing labour, materials, expenses and VAT separately lets the client see how the total was built.` },
    { question: `How do I work out my minimum hourly rate?`, answer: `Divide your annual income target by the hours you can genuinely bill. Targeting £60k over 220 working days at 6 chargeable hours a day gives 1,320 hours, so the bare minimum is £45 an hour. That takes no account of tax at around 30%, business expenses, the roughly 25% of hours lost to unpaid admin, or 4 weeks of unpaid holiday and sickness. Netting £60k in practice takes something closer to £75 to £90 an hour.` },
    { question: `Do I have to add VAT to my quote?`, answer: `Only if you are VAT-registered, which becomes compulsory above £90,000 of turnover. Registered freelancers add 20% to the quoted fee and show it as a separate line rather than folding it into the price, sitting alongside labour, materials and expenses so the client can see exactly how the total was reached. A quote should also say plainly whether the headline number includes VAT, since that is a common source of argument at invoice stage.` },
    { question: `How much should I set aside for tax?`, answer: `Between 25% and 35% of profit is the usual working figure, covering Income Tax and Class 4 National Insurance at 6% on profits between £12,570 and £50,270. First-year freelancers get caught out by Payments on Account, which add 50% of the year's tax in advance on top of the tax itself. A £1,000 Trading Allowance covers small side income, and pension contributions reduce the bill at your marginal rate.` },
  ],
  'tax-code-checker': [
    { question: `What does tax code 1257L mean?`, answer: `Tax code 1257L is the most common UK tax code for 2026/27. The number 1257 means your tax-free Personal Allowance is £12,570, since the figure is the allowance divided by 10. The letter L confirms the standard allowance with no adjustments. Spread over a year that gives you £1,047.50 of tax-free pay a month before the 20% basic rate starts.` },
    { question: `What does the letter at the end of my tax code mean?`, answer: `L is the standard Personal Allowance. M and N deal with Marriage Allowance, M for the person receiving the transfer and N for the person making it. T means HMRC is reviewing your affairs. S applies Scottish rates and C Welsh ones. BR, D0 and D1 tax all of that income at 20%, 40% and 45% respectively, which is usual for a second job, while 0T means no allowance at all.` },
    { question: `Why does my tax code start with the letter K?`, answer: `A K code means your untaxed income and benefits come to more than your allowances, so the balance is added to your taxable pay instead of being deducted from it. K500 adds £5,000 to the amount you are taxed on. Company cars, fuel and private medical benefits, pension over-funding charges, tax owed from a previous year, and State Pension paid while you are still working are the usual triggers. A K code cannot take more than 50% of your gross pay.` },
    { question: `Why is my tax code wrong after changing jobs?`, answer: `The most common cause is a benefit from the old employer, a company car or private medical cover, that HMRC has not yet removed from your record, so you carry on being taxed on something you no longer receive. New starters are also often put on 1257L with an M1 marker, which taxes each pay period separately instead of cumulatively and usually collects too little at first. Call HMRC on 0300 200 3300 with your employer details to have it corrected.` },
  ],
  'car-depreciation-calculator': [
    { question: `How much does a new car depreciate in the first year?`, answer: `New cars typically lose 15 to 25% of their value in the first year, and 50 to 60% by the end of the third. Because depreciation works on the declining balance, each later year costs less in pounds than the one before, so the steepest part of the curve is over early. Buying at one or two years old skips that phase and saves £5,000 to £10,000 on a car that listed at £30,000.` },
    { question: `Which cars hold their value best in the UK?`, answer: `Models with steady demand and a reputation for lasting: the Toyota Hilux, Land Rover Defender and Porsche 911 lose only 30 to 40% over five years against an average of 60 to 70%. Popular mainstream choices such as the Toyota RAV4 and Volkswagen Golf GTI, along with much of the Volkswagen Group range, also resell strongly. Limited-edition models tend to hold up well, while premium saloons like the BMW 7 Series and Mercedes S-Class lose 65 to 75%.` },
    { question: `Do electric cars depreciate faster than petrol ones?`, answer: `They have done through 2024 to 2026, because battery technology keeps improving and supply has outpaced demand, which makes older models feel dated and unsettles buyers worried about ageing packs. A two or three-year-old Tesla Model 3 is 40 to 50% down and a Polestar 2 around 50 to 60%, against 45 to 55% for a three-year-old petrol Ford Focus. Cheaper EVs such as the MG4 already track petrol closely, and the gap should narrow as the used market matures.` },
    { question: `How does depreciation affect a PCP deal?`, answer: `It sets the payment. A Personal Contract Purchase splits the price into the Guaranteed Minimum Future Value the finance company expects the car to be worth at the end, and the amount you fund monthly, which is the difference plus interest. A model that holds its value has a higher guaranteed value and therefore cheaper monthly payments, so understanding the curve for your chosen car gives you something concrete to negotiate with.` },
  ],
  'mpg-calculator': [
    { question: `How do I work out my car's real MPG?`, answer: `Fill the tank to the brim, reset the trip meter, drive normally until the tank is low, then refill and note the litres. Divide the litres by 4.546 to get UK gallons, or multiply by 0.22, then divide your trip miles by that figure. A 350-mile run on 40 litres is 8.80 gallons and 39.8 MPG. The dashboard readout is usually optimistic by 5 to 15%, so the manual calculation is the honest one.` },
    { question: `How far off are the official WLTP economy figures?`, answer: `Manufacturer figures typically exceed real-world MPG by 10 to 25%, so a car quoted at 60 MPG under WLTP realistically returns 50 to 54 in mixed driving. WLTP has applied to new UK cars since 2017; the older NEDC cycle was worse, and cars from 2010 to 2017 often undershot by 25 to 30%. What Car? True MPG, Honest John Real MPG and Autocar publish measured figures worth checking before you buy.` },
    { question: `What is the difference between UK and US miles per gallon?`, answer: `The gallon itself. A UK gallon is 4.546 litres against 3.785 in the United States, so the same car always scores higher in UK figures. Multiply a UK number by 0.833 for the US equivalent, or a US number by 1.201 to convert the other way. A Toyota Prius rated at 64 MPG in Britain is 53 MPG in America, which catches people out when they read American reviews.` },
    { question: `Does a higher MPG always mean a cheaper car to run?`, answer: `No, because fuel prices differ. At the UK averages for the week commencing 21 September 2026 (DESNZ), a 50 MPG diesel at £1.96 a litre costs 17.8p a mile, while a 45 MPG petrol at £1.72 costs 17.4p, so the less economical car is the cheaper one to run. An electric car doing 4 miles per kWh on an 8p home tariff costs 2p. Compare pence per mile rather than MPG. Over 7,400 miles a year that is £1,286 of petrol against £148 of home charging, a difference of more than £1,100.` },
  ],
  'carer-allowance-calculator': [
    { question: `How much is Carer's Allowance in 2026/27?`, answer: `For 2026/27 Carer's Allowance pays £86.45 a week, which is £4,495.40 over a year, up from £83.30 a week before April 2026. It is paid weekly or every 4 weeks by bank transfer. The money counts as taxable income as far as HMRC is concerned, although no National Insurance is charged on it, and it is treated as income in Universal Credit and other income-related benefit calculations.` },
    { question: `What is the earnings limit for Carer's Allowance?`, answer: `Your net weekly earnings must not exceed £204 per week to receive Carer's Allowance. Net earnings are calculated after deducting income tax, National Insurance and 50% of your pension contributions, plus up to half your net earnings if you pay someone other than a close relative to provide care while you work. Self-employed carers use their weekly profit after allowable expenses. The limit is absolute rather than tapered, so a week in which you net £205 pays no Carer's Allowance at all, which is why many carers move pay into a pension to stay below the line.` },
    { question: `Can I claim Carer's Allowance if I receive a State Pension?`, answer: `If your State Pension is the same amount as or higher than Carer's Allowance (£86.45 a week), you cannot receive both, and only the higher of the two is paid. The full State Pension of £241.30 a week comfortably exceeds it. You can still be 'underlying entitled' to Carer's Allowance, which triggers the Carer Element in Universal Credit (£209.34 a month in 2026/27) and improves Pension Credit and Council Tax Reduction calculations, so the claim remains worth making.` },
    { question: `What is Carer's Credit and who can claim it?`, answer: `Carer's Credit is for people who care for 20 or more hours a week but cannot claim Carer's Allowance, usually because the person they look after does not receive a qualifying disability benefit. It pays no cash. What it awards instead is free Class 3 National Insurance credits, which protect your State Pension record for the years you spend caring. Apply on form CC1 through gov.uk/carers-credit, and claims can be backdated by up to 1 tax year.` },
  ],
  'employers-liability-calculator': [
    { question: `Is employers' liability insurance compulsory for a small business?`, answer: `Yes. Under the Employers' Liability (Compulsory Insurance) Act 1969, virtually all UK businesses with at least one employee must hold EL cover with a minimum of £5 million. The exemptions are narrow: an unincorporated family business where every employee is a close relative (the exemption does not apply to a family business run as a limited company), a company whose only employee is its owner holding 50% or more of the shares, and most public bodies. The fine for trading without a policy runs to £2,500 per day, so the exposure builds quickly.` },
    { question: `What does employers' liability insurance actually cover?`, answer: `It covers compensation claims from employees, or former employees, who suffer injury, illness or death because of their work. That spans accidents, occupational diseases such as repetitive strain injury, asbestos-related illness and hearing loss from noise exposure. It does not extend to third parties, so a claim from a customer or a member of the public falls to public liability insurance instead, which has to be bought separately.` },
    { question: `How is the employers' liability premium worked out?`, answer: `Insurers apply a percentage to your annual wage bill, picked from your industry risk classification. A ten-employee professional services firm with a £350,000 payroll, at the calculator's office rate of 0.35%, comes to about £1,225 a year. A construction business on the same payroll, at 2.5%, would pay about £8,750, around seven times as much. Claims history then moves the real quote up or down.` },
  ],
  'blind-persons-allowance-calculator': [
    { question: `What is Blind Person's Allowance for 2026/27?`, answer: `For 2026/27 the allowance is £3,250, an increase on the £3,130 available in 2025/26. It is added to the standard Personal Allowance of £12,570, lifting the point at which income tax starts to £15,820. The cash value depends on your tax band, so it saves £650 a year at the basic rate and £1,300 at the higher rate.` },
    { question: `Who qualifies for Blind Person's Allowance?`, answer: `In England and Wales you qualify if you are registered with your local council as blind or severely sight impaired and have a certificate saying so, usually the Certificate of Vision Impairment issued by a consultant, or a similar document from your doctor. In Scotland and Northern Ireland the test is that you cannot do work for which eyesight is essential. Partial sight is a separate category and does not qualify.` },
    { question: `Can I transfer Blind Person's Allowance to my spouse?`, answer: `Yes. If your income is below £15,820 you will not use the full allowance, and the unused part can be transferred to a spouse or civil partner who does not have to be registered blind themselves. Form 575 makes the transfer. Someone earning £10,000, for example, can pass the whole £3,250 across, saving a higher-rate partner up to £1,300 a year. Marriage Allowance is a separate scheme worth £252.` },
    { question: `Can Blind Person's Allowance be backdated?`, answer: `Yes. Tell HMRC the date you were added to the register and the allowance can be backdated by up to 4 tax years, which can produce a useful refund where registration happened some time ago. Once granted it runs for life, so there is no annual re-application to make. You can claim through Self Assessment or by contacting HMRC online or on 0300 200 3301.` },
  ],
  'teachers-pension-calculator': [
    { question: `How is the Teachers' Pension calculated?`, answer: `Under the 2015 career average scheme you earn 1/57th of your pensionable salary each year as pension, and that amount is then revalued annually by CPI plus 1.6% until you retire. A year on £40,000 therefore adds £701.75 to your annual pension, and that slice keeps growing with inflation plus 1.6% every year afterwards, which is what stops early service losing its value over a long career.` },
    { question: `What are the Teachers' Pension contribution rates for 2026/27?`, answer: `Member rates for 2026/27 are 7.4% up to £36,198.99, 8.9% from £36,199 to £48,727, 9.9% from £48,728 to £57,776, 10.5% from £57,777 to £76,572, 11.6% from £76,573 to £104,413, and 12% above £104,414. Employers pay 28.68%, which includes the 0.08% administration levy. All contributions attract income tax relief, so the net cost to you is lower than the headline percentage suggests.` },
    { question: `When can I access my Teachers' Pension?`, answer: `Normal Pension Age for the 2015 career average scheme is linked to State Pension Age, currently 67 and rising to 68 from 2044. You can take the pension earlier with an actuarial reduction, or later with an enhancement, and it is CPI-linked once it starts. Ill-health retirement is paid in full with no reduction where you are permanently unable to teach.` },
    { question: `Does the Teachers' Pension pay a tax-free lump sum?`, answer: `Not automatically in the career average scheme. You can create one by commuting pension for cash at a rate of £12 of lump sum for every £1 of annual pension given up, up to 25% of the total value of your benefits, which is 30/7 of the pension. On a £14,035 pension that means a lump sum of up to £60,150, leaving £9,023 a year. Final salary service works differently: teachers who joined before 1 January 2007 built up an automatic lump sum of three times the pension alongside 1/80th a year, while those who joined later accrued 1/60th a year with no automatic lump sum.` },
  ],
  'student-loan-total-cost-calculator': [
    { question: `Will I repay my student loan in full?`, answer: `Roughly half will. Department for Education forecasts from July 2026 expect 55% of full-time undergraduates who started in 2025/26, on Plan 5, to repay in full before the 40-year write-off, so 45% will not; Plan 2 graduates from 2012 to 2022 face a 30-year one. Whether you clear the balance depends on lifetime earnings rather than on the amount borrowed. High earners repay everything plus interest, while those on median earnings often have a substantial balance written off at the end of the term.` },
    { question: `How much interest is charged on a Plan 5 student loan?`, answer: `Plan 5 loans accrue interest at the rate of RPI inflation only, whatever your income, and that interest runs from the day the money is drawn down rather than from graduation. It is more favourable than Plan 2, which adds up to 3% above RPI on higher incomes, subject to a 6% cap from 1 September 2026. The RPI rate is set annually and published by the Student Loans Company, and it is 4.1% for the year from 1 September 2026.` },
    { question: `Is it worth making voluntary student loan overpayments?`, answer: `For most Plan 2 and Plan 5 borrowers, no, unless you expect to clear the full balance before the write-off date. Where the loan will never be repaid in full, an overpayment reduces the amount eventually cancelled rather than your lifetime cost. The exception is higher earners, above £75k on Plan 2 or £60k and above on Plan 5, who can save £5k to £15k in interest. Run the projection before committing.` },
    { question: `What happens if I never earn above the repayment threshold?`, answer: `Nothing is deducted. Below £25,000 on Plan 5, or £29,385 on Plan 2, you pay nothing at all, while interest keeps building and the balance grows until it is written off at 40 or 30 years. The loan stays off your credit file, so it does not affect your credit score, and most mortgage lenders ignore the outstanding balance. Repayments also pause on their own if your income falls during a career break or redundancy.` },
  ],
  'ni-salary-sacrifice-2029-calculator': [
    { question: `How does salary sacrifice save National Insurance?`, answer: `When you make pension contributions through salary sacrifice, your contractual salary is reduced by the contribution amount before NI is calculated. That lowers the NI base for both you and your employer. At the 2026/27 employer NI rate of 15%, every £1,000 directed to a pension saves the employer £150 in NI, and many employers share that saving with employees as a bigger pension contribution. Your own saving comes from avoiding 8% employee NI and income tax on the same slice of pay.` },
    { question: `What changes for salary sacrifice NI in April 2029?`, answer: `The National Insurance Contributions (Employer Pensions Contributions) Act 2026 became law on 29 April 2026. From 6 April 2029, the first £2,000 a year of pension contributions made by salary sacrifice stays free of NI, and anything above that is treated as pay for both employee and employer NI. Income tax relief does not change. On a £50,000 salary with a £5,000 sacrifice, the employee loses £240 a year (8% of the £3,000 excess) and the employer bill moves from £6,000 to £6,450, an extra £450 a year.` },
    { question: `Should I increase my salary sacrifice pension before 2029?`, answer: `Until 5 April 2029 the whole sacrifice is free of NI, and after that the first £2,000 a year still is, so sacrifice keeps an edge over other ways of paying in. The NI saving on anything above £2,000 ends in April 2029, and with it the employer's 15% saving on that part, which some employers pass on as an enhanced contribution. Weigh that against the effect on mortgage borrowing, maternity pay and death-in-service cover, all of which follow the reduced salary. Review your arrangement with a financial adviser before making a significant change.` },
    { question: `Can salary sacrifice reduce my mortgage borrowing or maternity pay?`, answer: `It can. Lenders usually assess borrowing against the post-sacrifice salary, so a large sacrifice cuts the amount you can raise. Maternity pay is calculated on the reduced salary unless your contract overrides that, and death-in-service cover based on salary pays out less. The new State Pension is flat-rate, so it is only affected if your pay after sacrifice falls below the Lower Earnings Limit (£6,708 in 2026/27). Your pay also cannot fall below the National Living Wage after the sacrifice. Universal Credit runs the opposite way, because it looks at salary after sacrifice and entitlement may rise.` },
    { question: `When can I take money from a pension I have sacrificed into?`, answer: `The minimum age for accessing a defined contribution pension is 55, rising to 57 from 6 April 2028. Anyone born after 6 April 1973 will therefore wait until 57 rather than 55. Lifetime ISA withdrawals remain available from 60. If you intend to stop work before reaching that age, the gap has to be funded from elsewhere, most often ISA savings, a Lifetime ISA or income from property.` },
  ],
  'mortgage-early-repayment-calculator': [
    { question: `What is an Early Repayment Charge on a mortgage?`, answer: `An ERC is the penalty a lender charges if you overpay above your annual allowance (usually 10%) or repay the loan in full during a fixed or discounted period. It is normally a percentage of the amount repaid, tapering each year: on a typical 5-year fix it runs 5% in year 1, 4% in year 2, 3% in year 3, 2% in year 4 and 1% in year 5. With £200k outstanding, 3 years left and a 3% ERC, full repayment costs £6,000. Your mortgage offer sets out the exact schedule.` },
    { question: `When is it worth paying the ERC to switch mortgage?`, answer: `It pays when the interest you save on a new rate exceeds the charge over the time left on your fix. Suppose you owe £200k at 6%, a 4% deal is available, 18 months remain and the ERC is 3% (£6,000). The 2% saving on £200k is £4,000 a year, or £6,000 over 1.5 years, so you roughly break even on the rate alone, and the cheaper payments on the new 5-year deal continue after that. As a rule of thumb, a move is worthwhile once rates have shifted 2% or more in your favour.` },
    { question: `How can I avoid paying an Early Repayment Charge?`, answer: `Porting lets you carry your existing rate to a new home without an ERC, and most lenders allow a 10% overpayment each year free of charge. Once you have moved onto the Standard Variable Rate there is no ERC at all, and drop-lock mortgages let you fix mid-tracker without penalty. Lenders sometimes waive charges in cases of bereavement or genuine financial hardship, but they are not obliged to. The simplest route is to time your remortgage so it completes just after the fix expires.` },
    { question: `Should I overpay my mortgage or invest the money instead?`, answer: `Clearing a 4% mortgage gives a guaranteed 4% return, but the money is then tied up in the property. If you can reliably earn more than your mortgage rate in a stocks and shares ISA, investing may leave you better off, although those returns are never guaranteed while the saving from an overpayment is. Anyone who values certainty, or who would be uncomfortable watching investments fall, usually leans towards the overpayment.` },
  ],
  'care-cost-calculator': [
    { question: `What is the care home means-test threshold in England?`, answer: `In England, if your total assessable assets exceed £23,250 (the upper capital limit), you are fully self-funded and must pay the full cost of your care. Below that, the council charges you from your income only, leaving you £31.80 a week for personal expenses in a care home, or the Minimum Income Guarantee (£241.45 a week for a single person at Pension Credit age) if you get care at home. Between £14,250 and £23,250, you also contribute £1 per week for every £250, or part of £250, above £14,250.` },
    { question: `Is my home included in the care home means test?`, answer: `Your home is included in the means test if it will be empty when you enter permanent residential care. It is disregarded if a spouse or civil partner, a dependent child under 18, a disabled child, a relative over 60, or a qualifying carer lives there. Even where it is included, its value is ignored for the first 12 weeks of permanent care, and a Deferred Payment Agreement with the council lets you delay selling until after death, with the council taking a legal charge on the property instead.` },
    { question: `What happened to the £86,000 care cost cap?`, answer: `The Dilnot Commission first proposed a lifetime cap of £35,000 back in 2011, and the figure was revised to £86,000 in 2021 and written into the Health and Care Act 2022. It was due to take effect in October 2023, was delayed to October 2025, and has since been indefinitely postponed. As of April 2026, the existing means-test thresholds of £23,250 upper and £14,250 lower remain in force with no cap in place.` },
    { question: `Can the NHS pay for my care home fees?`, answer: `It can, through NHS Continuing Healthcare, but only where your primary need is a health need rather than a social care need. Where that test is met the NHS covers 100% of the cost, with no income cap and no capital test at all. Eligibility is assessed with the Decision Support Tool, which scores 12 domains including mobility, cognition, behaviour and continence, and referrals usually start with your GP. Most applications are refused first time, so the appeal stage is where many successful claims are won.` },
  ],
  'council-tax-calculator': [
    { question: `How is my Council Tax band decided?`, answer: `Your band reflects what the property would have sold for on 1 April 1991 in England and Scotland, or 1 April 2003 in Wales, not what it is worth today. In England, Band A covers 1991 values up to £40,000 and Band H anything above £320,000, with six bands in between. For a new build, the Valuation Office Agency estimates a notional 1991 value. You can find your band on gov.uk/council-tax-bands, and it determines the fraction of the Band D charge you pay, from 6/9 for Band A to 18/9 for Band H.` },
    { question: `How can I challenge my Council Tax band?`, answer: `Challenges go to the Valuation Office Agency in England and Wales, or the Scottish Assessors. Start by comparing your neighbours' bands through the gov.uk postcode lookup, then estimate your home's 1991 value using Nationwide House Price Index history. If you have owned the property for less than 6 months you can make a formal proposal, which gives stronger rights; otherwise you submit a request for review. Roughly 15% of challenges succeed, and the VOA can also raise your band, so document your reasoning before you apply.` },
    { question: `Which council tax discounts and exemptions can I claim?`, answer: `The most common is the 25% single adult discount if you live alone. Full-time students are exempt, and an all-student household pays nothing. A home adapted for a disabled resident is charged at the band below yours, and an annexe occupied by a family member gets a 50% reduction. Empty homes are treated differently by each council, sometimes free for the first month and then subject to a 100 to 300% surcharge, while many councils now charge a 200% premium on second homes and holiday lets (up to 300% in Wales). Apply through your council's website.` },
    { question: `Can I get Council Tax Reduction if I am on a low income?`, answer: `Yes, if your income is low or you receive benefits. Council Tax Reduction replaced Council Tax Benefit in 2013 and each council runs its own scheme, so the rules differ by area. Working-age claimants on Universal Credit, JSA, ESA or low earnings can qualify, and pension-age claimants on Pension Credit Guarantee usually get a 100% reduction, often automatically. Capital limits typically disregard the first £6,000 and cut off at £16,000. The scheme is underclaimed, with about 1.3 million eligible pensioners missing out, so it is worth applying via your council's website.` },
  ],
  'landlord-tax-calculator': [
    { question: `How does Section 24 affect my landlord profits?`, answer: `For a basic-rate landlord it makes almost no difference, because the 20% credit matches the rate that would otherwise have applied. Higher-rate landlords lose out, since interest no longer comes off income taxed at 40% or 45% and earns relief at 20% instead. The restriction also inflates the profit figure on your return, which can push part of your income into the next band even though your bank balance has not changed. On a heavily mortgaged letting the effective rate can reach 63%.` },
    { question: `Should I use a limited company for buy-to-let?`, answer: `Not for a single flat. The structure tends to pay from around 2-3 properties or £30k of rental income, and mostly for higher-rate taxpayers whose mortgage interest is large enough for Section 24 to bite. Weigh the running costs against the saving first, since accounts run to between £1,000 and £1,800 a year on top of incorporation. Be careful about moving property you already own into a company, because that transfer attracts SDLT including the 5% surcharge. Incorporation relief may be available but it is complex enough to need specialist advice.` },
    { question: `What expenses can landlords claim?`, answer: `Agent fees, typically 8-12% of rent, insurance at around £200-£500 a year, repairs but not improvements, accountancy, gas safety certificates at £80-£120, an EPC at £45-£120 which lasts 10 years, and council tax or utilities where the landlord pays them. Replacement Furniture Relief covers like-for-like replacements only, never the first purchase. Mortgage capital repayments are not allowable, and improvements are not either, though they reduce the gain when you sell.` },
    { question: `When do I pay Capital Gains Tax on a rental property?`, answer: `Within 60 days of completion. You file a CGT return and pay at the same time, rather than waiting for the Self Assessment deadline. Residential property gains are taxed at 18% at basic rate and 24% at higher rate, after the £3,000 annual exempt amount. Principal Private Residence relief applies if the property was once your main home, but since April 2020 Letting Relief only applies where you lived in the property at the same time as your tenant.` },
  ],
  'pension-drawdown-calculator': [
    { question: `How much can I safely withdraw from my pension each year?`, answer: `The often-cited Trinity Study rule takes 4% of the pot in year one, then raises the amount by 2-3% a year for inflation, which historically sustained a 30-year retirement with a high probability of success. On a £500,000 pot that is £20,000 in the first year. UK studies point to a more conservative 3.5-3.7% given higher inflation and lower bond yields. Above 4.5%, an early market fall can exhaust the pot ten years sooner than expected, while below 3% the pot survives but the income may not cover what you need.` },
    { question: `How is money taken from pension drawdown taxed?`, answer: `A quarter of the pot is tax-free, up to a lifetime limit of £268,275, and the remaining three-quarters is taxed as income at 20, 40 or 45% when you draw it. State Pension of £12,000 plus £25,000 of drawdown makes £37,000 of income and around £4,886 of tax, all within the basic rate. Keeping total income under £50,270 avoids the higher-rate band, so phasing withdrawals over 10 to 20 years usually costs far less tax than emptying the pot in a few large payments.` },
    { question: `What is sequence of returns risk in drawdown?`, answer: `It is the way the order of returns, not just the average, decides how long a pot lasts once you are drawing income. Take a £500,000 pot at a 4% withdrawal rate with a 6% average return. If the first three years return minus 15%, minus 10% and minus 5% before the good years arrive, the pot runs dry in year 22. Reverse the order so it gains 20%, 15% and 10% first and the pot lasts 40 years or more. Holding one to two years of expenses in cash and cutting spending in down years both blunt the effect.` },
    { question: `At what age can I start taking pension drawdown?`, answer: `From 55 at present, rising to 57 from April 2028. At that point you can take the 25% Pension Commencement Lump Sum tax-free and move the rest into flexi-access drawdown, or leave the pot untouched and take Uncrystallised Funds Pension Lump Sums, where each withdrawal is a quarter tax-free and three-quarters taxable. The tax-free entitlement across all your pensions is capped at £268,275.` },
  ],
  'solar-panel-calculator': [
    { question: `How much do solar panels cost in the UK in 2026?`, answer: `A 3.5kW system, typical for a three-bedroom home, costs £6,000 to £8,500 fully installed including the inverter and basic battery monitoring. A 5kW system runs £8,500 to £12,000, and premium systems of 6kW and above £12,000 to £18,000 or more. Battery storage from Tesla or GivEnergy adds £4,000 to £10,000. Prices have fallen 60 to 70% since 2015, and residential solar has carried 0% VAT since April 2022, worth £1,200 to £3,000 on a typical installation.` },
    { question: `How much electricity will solar panels generate and save?`, answer: `A 3.5kW system in southern England generates 3,000 to 3,500 kWh a year, dropping to 2,500 to 3,000 kWh in northern England and Scotland. Without a battery you use 30 to 50% of that yourself, rising to 60 to 90% with one. Savings come to £500 to £900 a year against imported electricity at around 26p per kWh, plus £80 to £200 in Smart Export Guarantee payments. Most panels are guaranteed to retain 80% or more of their output at year 25.` },
    { question: `How much does the Smart Export Guarantee pay?`, answer: `The Smart Export Guarantee replaced the Feed-in Tariff in January 2020 and obliges energy suppliers to pay for solar electricity exported to the grid. Rates vary enormously, from Octopus Outgoing Agile at 15 to 20p per kWh down to British Gas at 6.4p and EDF at 5.6p, a threefold spread that makes the choice of supplier worth real attention. A smart meter is required to measure exports. On 3,500 kWh generated with half of it exported, 1,750 kWh at 15p brings in £262 a year.` },
    { question: `Is battery storage worth adding to a solar system?`, answer: `A battery of 5 to 10 kWh costs £4,000 to £8,000 and lifts the share of your own generation you use from 30 to 50% up to 70 to 90%, worth an extra £200 to £400 a year. Payback on the battery alone is 10 to 15 years against a typical 10-year warranty. Pairing it with a time-of-use tariff such as Octopus Cosy, charging at 7p and using that power against a 28p peak, adds £100 to £300 a year. It suits heavy users, people at home during the day and EV owners far more than lightly occupied properties.` },
  ],
  'mortgage-affordability-calculator': [
    { question: `How much can I borrow on a UK mortgage?`, answer: `Most lenders cap borrowing at 4-4.5 times income, and some mainstream high-street lenders such as Halifax, Nationwide and Santander will go to 5.5-6 times for high earners above £75,000. Maximum loan-to-value is 95% for first-time buyers and 90% on a standard remortgage. Whatever the multiple, each lender's own affordability check decides the final figure, since the fixed 3-point stress test was withdrawn in August 2022, and existing debts eat into it: every £100 a month of commitments removes about £16,000 of borrowing at today's average two-year fixed rate of 5.73%.` },
    { question: `What deposit do I need to buy a home in the UK?`, answer: `First-time buyers can borrow at 95% LTV, so 5% is the practical minimum, but 10-15% opens up noticeably better rates and the very best pricing sits at 60% LTV. On a £250k property that is £12,500 at 5%, £25,000 at 10% and £50,000 at 20%. A Lifetime ISA takes up to £4,000 a year and adds a 25% government bonus worth £1,000 a year. Gifted deposits from family are common, and the lender will want a letter confirming that no repayment is expected.` },
    { question: `What counts as income if I am self-employed?`, answer: `Sole traders are usually assessed on 2-3 years of Self Assessment SA302 forms, averaged out. Limited company directors are generally judged on salary plus dividends, although some lenders will consider retained profits. Day-rate contractors are often assessed as day rate times 5 times 46 weeks. With under 2 years of trading you are limited to specialist lenders such as Kensington or Pepper Money, at rates of 5.5-7%. A broker who handles self-employed cases, such as John Charcol or Habito, is worth the call.` },
    { question: `What should I budget beyond the monthly mortgage payment?`, answer: `The mortgage is only part of the bill. On £200k at 4.5% over 25 years the payment is £1,112 a month, and on top of that come buildings insurance at around £25, life cover at £15-£40, council tax of £100-£250, utilities of £150-£250 and a maintenance fund of £100-£200, which is roughly 1% of the property value a year. Leasehold flats add service charge and ground rent of £100-£400. Total housing costs for a £200k property land between £1,500 and £2,500 a month, and a common rule keeps them under 35% of gross income.` },
  ],
  'first-home-buyer-calculator': [
    { question: `How much can a first-time buyer borrow on a mortgage?`, answer: `Lenders work on income multiples of 4-4.5 times a single salary or 3.5-4 times joint income, with specialist lenders reaching 5.5-6 times for high earners on £75k+. On a £40k salary, 4.5 times gives a £180,000 mortgage, which with a 10% deposit buys up to a £200,000 property. A couple on £35k and £30k, so £65k between them, might borrow £247,000 at 3.8 times and add £15-25k of deposit. On fixes shorter than five years the lender stress-tests at a rate it sets, typically 1-3 points above the deal, and every £100 a month of existing debt cuts borrowing by roughly £13,000 to £16,000.` },
    { question: `What deposit do I actually need to buy my first home?`, answer: `The minimum is 5%, since 95% LTV mortgages exist, but 10-15% is realistic for decent pricing and the best rates sit at 60% LTV, meaning a 40% deposit. On a £250,000 property that is £12,500 at 5%, £25,000 at 10% and £62,500 at 25%. For a £200k purchase, total upfront cash of £15,000-£20,000 is a realistic minimum once fees are added. Keep 3-6 months of expenses in a separate emergency fund rather than putting every pound into the deposit.` },
    { question: `Do first-time buyers pay stamp duty?`, answer: `Not on the first £300,000, provided the property costs no more than £500,000. Above £300k the 5% rate applies to the slice up to £500k, and the relief disappears entirely on more expensive homes. Movers get no such break, with their nil-rate band starting at £125k, so the relief is worth real money on a typical purchase. On a £280,000 first home the stamp duty bill is £0.` },
    { question: `Is a Lifetime ISA better than a Help to Buy ISA?`, answer: `Of the two, only the Lifetime ISA is open to new savers, and the Help to Buy ISA is not an option regardless, having closed to new accounts in Nov 2019. A LISA pays a 25% bonus on up to £4,000 a year, so £1,000 a year at most, with no overall cap on what you collect, and it works on homes up to £450,000 anywhere in the country. The Help to Buy ISA capped the total bonus at £3,000 and the property at £250k outside London. Existing holders can transfer into a LISA, so speak to your provider. A new First Time Buyer ISA is planned to replace the LISA for new savers once it launches; LISAs already open carry on.` },
  ],
  'equity-release-calculator': [
    { question: `How much equity can I release from my home?`, answer: `Typically 20-60% of the property value, with the percentage rising as you get older. Lifetime mortgages, which make up more than 95% of the market, are available from age 55, while home reversion plans start at 65. The average release in the UK is £100,000, and more than £6 billion was taken out in 2025 on Equity Release Council figures. Your age and your property's value are what the calculation turns on.` },
    { question: `How fast does the debt grow if I make no payments?`, answer: `Quickly, because the interest compounds. At 6% a £100,000 loan doubles to £200,000 in roughly 12 years. Rates in 2026 typically sit at 6.0-7.5% and are fixed for life, so £100,000 released at 6.5% becomes a £352,000 debt after 20 years, and £100k at 5.5% reaches £382,000 after 25. Some plans let you make voluntary payments of 5-10% of the capital each year without penalty, which slows the compounding considerably.` },
    { question: `Will equity release affect my benefits or my children's inheritance?`, answer: `Both. The cash counts as capital for means-tested support including Council Tax Reduction and Pension Credit, and for NHS care home funding, where crossing the £23,250 capital threshold means paying full care costs. On the inheritance side, £100k released at 6% turns into a £321k debt after 20 years, which is £321k less for the estate. Some plans offer inheritance protection that guarantees a minimum percentage of the property value to your beneficiaries, in exchange for a higher rate.` },
    { question: `What are the alternatives to a lifetime mortgage?`, answer: `Downsizing usually frees £80-£150k tax-free, with no compounding interest and lower running costs, although it means moving. A retirement interest-only mortgage holds the debt at its original amount by charging monthly interest, but you need the income to qualify. A drawdown lifetime mortgage releases money in stages and charges interest only on what has been drawn, which is cheaper than a lump sum. A family loan, or selling and renting, can also work, each with its own drawbacks.` },
  ],
  'holiday-entitlement-calculator': [
    { question: `How much holiday am I entitled to in the UK?`, answer: `The statutory minimum is 5.6 weeks a year, which is 28 days for someone working 5 days a week and can include the 8 bank holidays. Part-time staff get a pro-rata share, so a 4-day worker receives 22.4 days, and irregular-hours workers accrue 12.07% of the hours they work. Many employers offer 25-30 days plus bank holidays, giving 33-38 days in total, and the public sector typically gives 26-30 plus bank holidays, or 34-38 days. Holiday accrues from your first day.` },
    { question: `How is holiday pay worked out for irregular-hours workers?`, answer: `Workers without fixed hours, such as zero-hours, casual, agency and term-time-only staff, have holiday pay based on a 52-week average of their earnings. Since April 2024 employers can instead use rolled-up holiday pay, adding 12.07% to each pay packet and showing it separately on the payslip. The weekly equivalent is found by multiplying gross weekly pay by 5.6 and dividing by 46.4. Tax and NI are deducted from holiday pay in the same way as from normal earnings.` },
    { question: `Can I carry unused holiday over to the next year?`, answer: `The first 4 weeks (20 days) of the 5.6-week entitlement cannot be carried over unless sickness, maternity or other family leave stopped you taking them, or your employer did not give you a reasonable chance to take them. Holiday carried over because of sickness must be used within 18 months of the end of the leave year it came from. The additional 1.6 weeks (8 days) can be carried for one year by agreement, and your contract may allow more. Untaken holiday at the end of employment is paid through the final payslip, and if an employee dies it passes to their estate. During employment holiday cannot be bought out, except as rolled-up holiday pay for irregular-hours and part-year workers.` },
    { question: `Are bank holidays included in my statutory holiday entitlement?`, answer: `Usually, yes. The 5.6 weeks can include bank holidays, so the common 28-day package is 20 days of leave plus the 8 bank holidays in England and Wales (occasionally 9 when an extra royal or historic day is added). Northern Ireland has 10 bank holidays and Scotland 9. Employers can require you to work on a bank holiday at normal pay unless your contract promises a premium, and time off in lieu is common but not a legal right. Check your contract on Good Friday and Easter Monday, as not every employer grants both.` },
    { question: `How is holiday pro-rated if I start part-way through the year?`, answer: `The calculator takes your full-year entitlement and scales it to the fraction of the leave year remaining. Someone working 3 days a week has a full-year entitlement of 16.8 days. Starting on 1 July in an April to March leave year leaves 9 of the 12 months, so the proportion is 0.75, giving 12.6 days, which rounds up to 13 for the rest of that leave year. If the leave year runs January to December, a 1 July start leaves 6 months, giving 8.4 days, or 8.5 rounded up to the nearest half day.` },
  ],
  'inflation-calculator': [
    { question: `What is the UK inflation rate in 2026?`, answer: `CPI has run between 2.6% and 3.3% through 2026 (3.1% in August), above the Bank of England's 2% target. It averaged 2.5% in 2024 and 3.4% in 2025. The peak of the recent cycle was 11.1% in October 2022, the highest reading in 41 years. RPI typically runs 0.5% to 1% above CPI, while CPIH, which includes owner-occupier housing costs, sits closer to what households actually experience. The Bank base rate has been 3.75% since December 2025, down from a 5.25% peak in 2023.` },
    { question: `How quickly does inflation erode my savings?`, answer: `Faster than most people expect, because the effect compounds. At 3% a year purchasing power halves in 24 years, at 5% in 14 and at 10% in 7. £100,000 saved in 2000 was worth about £49,000 in 2024 terms, and £100,000 put aside in 1980 had fallen to roughly £21,000 by then. The retirement version of the same sum is that £30k of income today needs about £55k in 20 years at 3% inflation to buy the same standard of living.` },
    { question: `What is the difference between CPI, CPIH and RPI?`, answer: `CPI excludes mortgage interest payments and council tax, averages prices geometrically rather than arithmetically, and covers a broader population including foreign visitors. It has been the main measure since 2003 and is the Bank of England's target index. CPIH adds owner-occupiers' housing costs and has been the ONS preferred measure since 2017. RPI is the older calculation, still used for index-linked gilts and some pensions, and typically runs 0.5% to 1% higher than CPI. All are published around the 15th of each month.` },
    { question: `How do I work out what £100 in 2000 is worth today?`, answer: `Divide the current CPI index value by the index value for the earlier date, then multiply by your original sum. CPI stood at 68.0 in January 2000 and approximately 136.0 in early 2026, a ratio of 2.0, so £100 then buys what £200 does now. The same method converts a salary, with £32,000 earned in 2010 becoming £39,776 at 2026 prices, a cumulative rise of 24.3% across the period.` },
    { question: `Which investments actually beat UK inflation over time?`, answer: `Equities have the strongest record, with the FTSE All-Share averaging a 7% real return since 1900 and long-run equity returns generally in the 4% to 6% range. Property has returned 3% to 5% in real terms with wide regional variation, bonds 0% to 2%, and cash somewhere between minus 1% and plus 1%. Index-linked gilts are designed to track inflation directly, though NS&I Index-Linked Savings Certificates are closed to new investors. Gold produces no real return over the long run but hedges currency debasement and crisis.` },
  ],
  'ev-savings-calculator': [
    { question: `How much does an EV save compared with petrol each year?`, answer: `At 12,000 miles a year a 40 mpg petrol car burning 1,364 litres at £1.72, the UK average in the week commencing 21 September 2026, costs £2,346 in fuel, while an EV doing 4 miles per kWh needs 3,000 kWh and costs £240 on an 8p off-peak tariff. That alone is £2,106. Road tax no longer adds to it, as most EVs have paid the same standard rate as petrol cars since April 2025, but servicing runs £100 to £200 a year cheaper, so most drivers finish about £2,200 to £2,300 ahead.` },
    { question: `How much does it cost to charge an electric car at home?`, answer: `On an off-peak tariff such as Octopus Go at 7.5p or EDF Go Electric at 9p, a 60 kWh battery fills for £4.50 to £5.40, which is about 2p a mile. Charging on a standard household rate of 24 to 28p costs £14 to £17 for the same battery, roughly 7p a mile. Timing your charging to the overnight window is therefore worth more than almost any other change you can make.` },
    { question: `How long does it take for a pricier EV to pay for itself?`, answer: `Around five years on typical numbers. A £35,000 EV against a £25,000 petrol equivalent starts £10k behind, and savings of about £2,000 a year close that gap by year five. Buying used shortens it considerably, since two or three-year-old EVs often sell 40 to 50% below list price. Salary sacrifice through an employer can remove the premium entirely from the first month.` },
    { question: `Do electric cars really cost less to service?`, answer: `Yes, though not dramatically. Servicing runs £100 to £200 a year less than an equivalent petrol car because there is no clutch, exhaust, cambelt or conventional gearbox, and regenerative braking slows pad wear. Tyres can cost more, as EVs are heavier. Battery capacity fades about 1 to 2% a year and is covered by an 8 year or 100k mile warranty, and failures in modern cars under ten years old are rare.` },
    { question: `Are there enough public chargers to run an EV in the UK?`, answer: `There are roughly 70,000 public chargers in 2026, with more than 24,000 locations offering rapid charging at 50 kW or above through networks including BP Pulse, Pod Point, Ionity, Tesla Supercharger, Gridserve and InstaVolt, and the target is 300,000 by 2030. In practice more than 90% of EV journeys are home-charged, so the public network matters mainly for long trips.` },
  ],
  'shared-ownership-calculator': [
    { question: `How does shared ownership work in the UK?`, answer: `You buy a share of between 25% and 75% of a property and pay rent to a housing association on the rest, typically 2.75% of the unsold equity a year. The mortgage and deposit apply only to your share, with the deposit usually 5-10% of the share value. On a £300,000 home with a 50% share, the rent comes to £344 a month and a £150k mortgage at 5% over 25 years adds £877, totalling £1,221 against £1,754 to buy the whole property.` },
    { question: `How does staircasing work and what does it cost?`, answer: `Staircasing means buying further shares, normally after a year in the property, in steps of at least 10%, or 1% a year under the model introduced in 2021 at fixed RPI-linked valuations. Costs stack up on each transaction: a revaluation at £200-£500, a solicitor at £800-£1,500 and mortgage fees of £999-£1,500. Going from 25% to 50% on a £300k flat now valued at £350k means finding £87,500 plus around £2,000 in fees, so a rising market pushes the price of each step up.` },
    { question: `Who is eligible for shared ownership in 2026/27?`, answer: `Household income must be under £80,000, or £90,000 in London, and you must be unable to buy a comparable home outright. Applicants are generally first-time buyers, existing shared owners staircasing, or home movers who cannot afford a full purchase. Some developments give priority to people with a local connection or to key workers. You apply to the housing association, council or other organisation selling the home (usually with a reservation fee of up to £500), and because supply is limited, homes are often allocated within weeks of release.` },
    { question: `How do I sell a shared ownership property?`, answer: `The housing association normally gets the first 8 weeks to find a buyer, known as the nomination period, after which you can market the property freely. You receive your percentage of the current market value, so an owner of 50% gets 50%, and growth on the unowned share belongs to the housing association. Staircasing to 100% first and then selling on the open market usually produces the best outcome, subject to any Section 106 restrictions attached to the property.` },
  ],
  'winter-fuel-payment-calculator': [
    { question: `Who qualifies for the Winter Fuel Payment in winter 2026/27?`, answer: `You qualify if you have reached State Pension age by the end of the qualifying week, 21 to 27 September 2026, and live in England, Wales or Northern Ireland, with Scotland paying the equivalent Pension Age Winter Heating Payment. Because State Pension age is rising from 66 to 67 between April 2026 and March 2028 under the Pensions Act 2014, the effective date-of-birth cutoff falls in mid-1960. Someone born in April 1960 reaches State Pension age at 66 years and 1 month, with one month added for each later monthly cohort. Payment is automatic for anyone receiving the State Pension or most DWP benefits.` },
    { question: `How does the £35,000 income test work?`, answer: `Since winter 2025/26 the Winter Fuel Payment is kept only by pensioners whose individual taxable income is £35,000 or less. The test is per person rather than per household, so each partner's share is assessed against their own income. There is no taper, meaning income even £1 over the limit costs you your entire share. Taxable income includes the State Pension, private and workplace pensions, employment earnings, rental profits and taxable savings interest. Recovery is automatic: for PAYE taxpayers HMRC changes the tax code in January 2027 to start collecting the 2026 payment, and again in April 2027, when it also starts collecting the 2027 payment in advance, while Self Assessment filers have it added to their return.` },
    { question: `Can I opt out of the Winter Fuel Payment?`, answer: `Yes, but not for this winter. The opt-out window for winter 2026/27 closed in September 2026, so if your income is over £35,000 you will receive the payment and HMRC will take it back. You can opt out for winter 2027/28 from 21 December 2026, online or through the Winter Fuel Payment Centre on 0800 731 0160. Opting out is per person and stays in place for future winters until you opt back in. It is purely administrative convenience, because the financial outcome is identical to receiving the payment and repaying it through your tax code.` },
    { question: `How much is the Winter Fuel Payment and how is it split for couples?`, answer: `The household amount is £200, rising to £300 where someone in the household is aged 80 or over during the qualifying week. How it is divided depends on benefits. Households receiving Pension Credit, or another income-related benefit such as income-related ESA, receive the full amount with their benefit. Where both partners qualify independently and neither is on an income-related benefit, each receives their own share: £100 each if both are under 80, £150 each if both are 80 or over, and £200 for the older partner with £100 for the younger where only one has reached 80. Each half is then separately subject to that partner's own £35,000 income test, so one partner can keep their share while the other repays theirs.` },
  ],
  'pro-rata-salary-calculator': [
    { question: `What does "pro rata" mean on a job advert?`, answer: `It means the advertised salary is the full-time-equivalent figure, and your actual pay will be scaled in proportion to the hours you work. If an advert says "£35,000 pro rata" and the full-time week is 37.5 hours, working 22.5 hours pays £21,000 a year. Your hourly rate is identical to a full-time colleague's, you are simply paid for fewer hours. Under the Part-time Workers Regulations 2000, part-time staff must not be treated less favourably per hour than comparable full-timers. Source: GOV.UK, ACAS.` },
    { question: `How is term-time-only (TTO) pay calculated?`, answer: `Term-time-only staff are paid for the weeks they actually work plus accrued statutory holiday, rather than the full year. Holiday is added at 5.6 divided by 46.4 of the weeks worked, so a 39-week school year accrues about 4.7 weeks and gives roughly 43.7 paid weeks. That figure is then divided by 52.14 and applied to your hours-adjusted salary. Divisors vary between employers, with 52, 52.14 and 52.143 all in use, so check your contract. Source: GOV.UK holiday entitlement guidance, local authority pay policies.` },
    { question: `How much holiday do part-time workers get?`, answer: `The statutory minimum is the same 5.6 weeks for everyone, and it scales with your working pattern rather than being reduced. Someone working 22.5 hours a week accrues 126 hours of paid holiday a year, and someone working 3 days a week gets 16.8 days. The entitlement is capped at 28 days for those working 6 or 7 days a week. If full-time staff get a more generous contractual package, say 30 days plus bank holidays, you are entitled to the same, pro-rated by your hours. Source: GOV.UK.` },
    { question: `Is take-home pay also proportional to hours?`, answer: `No, it is proportionally better for part-time workers. The tax-free Personal Allowance of £12,570 and the National Insurance threshold do not shrink when your hours do, so a larger share of a part-time salary escapes tax altogether. After income tax and NI at 2026/27 rates, a £35,000 full-time salary takes home about 82% of gross (£28,720), while the same role at 60% hours, paying £21,000, keeps about 89% (£18,640), before any pension contributions. That is why dropping a day a week usually costs less in net pay than the headline salary cut implies. Source: HMRC.` },
  ],
  'pension-emergency-tax-calculator': [
    { question: `Why was so much tax taken from my pension withdrawal?`, answer: `Your provider applied the emergency code 1257L on a Month 1 basis, which HMRC requires for a first flexible withdrawal when your correct code is not held. Month 1 treats the single payment as one month of an ongoing salary, so only £1,047.50 is tax-free, the next £3,141.67 is taxed at 20%, the next £7,286.67 at 40%, and everything above that at 45%. On a £15,000 taxable withdrawal that means £5,128.88 withheld even though most people owe a fraction of it for the year. The overpayment is fully reclaimable.` },
    { question: `Which form reclaims emergency pension tax, P55, P53Z or P50Z?`, answer: `It depends on whether the withdrawal emptied your pot and whether you have other taxable income this year. P55 is for a partial withdrawal where you are not taking regular payments. P53Z is for an emptied pot where you have other taxable income, such as a job, State Pension or another pension. P50Z is for an emptied pot with no other taxable income this tax year. All three are free to file through your Personal Tax Account on GOV.UK, and HMRC aims to refund within 30 days.` },
    { question: `Did the April 2025 HMRC change fix emergency tax on pensions?`, answer: `Partly. From April 2025 HMRC replaces temporary codes with cumulative ones far faster for people newly receiving pension income, so repeat withdrawals now correct themselves within a payment or two instead of waiting until the year end. The first flexible payment from a new arrangement is still normally taxed on the Month 1 basis, because the provider has no code for you when it runs payroll. The workaround remains a token first withdrawal, say £100, to trigger a proper code before taking the real amount.` },
    { question: `Do Scottish tax rates apply to my pension withdrawal?`, answer: `Yes, if you are a Scottish taxpayer, meaning your main home is in Scotland and your code carries an S prefix. The taxable part of a pension withdrawal is non-savings income, so it is taxed at the Scottish rates for 2026/27, which are 19% starter, 20% basic, 21% intermediate, 42% higher, 45% advanced and 48% top. The 25% tax-free entitlement and the reclaim forms are identical across the UK, and the emergency Month 1 mechanics work the same way on one twelfth slices of the Scottish bands.` },
  ],
  'tax-refund-calculator': [
    { question: `Am I due a tax refund if I stopped working part-way through the year?`, answer: `Very likely, if you paid tax while working. PAYE assumes your pay continues to 5 April, granting 1/12 of the £12,570 Personal Allowance each month. Stop earning mid-year and the unused months of allowance never get set against your earlier pay. Earn £18,000 by September with £2,200 deducted and then nothing, and the tax actually due on £18,000 for the whole year is £1,086, so £1,114 comes back. The same logic covers students who worked only over the summer, career breaks, new parents leaving work and anyone retiring mid-year.` },
    { question: `How do I actually claim a PAYE refund?`, answer: `There are four routes. Out of work for four weeks or more and not claiming taxable benefits, file form P50 online now with parts 2 and 3 of your P45. Claiming Jobseeker's Allowance or income-related ESA, the benefit office repays through the benefit system at year end or when your claim ends. Starting a new job, hand over your P45 and the cumulative code refunds the overpayment in your first payslip. Do nothing and HMRC reconciles after 5 April and sends a P800, some time between June and the following March. Never pay an agency 25 to 50% commission for free forms.` },
    { question: `How far back can I claim overpaid tax?`, answer: `Four tax years, plus the current one. In 2026/27 you can still claim for 2022/23, 2023/24, 2024/25 and 2025/26, and the 2022/23 window closes on 5 April 2027. It covers overpaid PAYE and the backdatable reliefs: uniform and tool flat-rate expenses of £60 to £140 a year by trade, business mileage paid below the approved 55p and 25p rates, working-from-home relief where your employer requires it, Marriage Allowance worth up to £252 a year, and professional subscriptions to HMRC-approved bodies. A four-year uniform claim alone is commonly worth £48 to £112 at basic rate.` },
    { question: `What is a P800 and when does it arrive?`, answer: `A P800 is HMRC's automatic end-of-year reconciliation letter, sent when their records show you paid the wrong amount of PAYE tax, either too much or too little. They go out in batches between June and March following the 5 April year end. If you are owed money, the letter tells you either to claim online, with the money paid to your bank within 5 working days, or that a cheque will be sent automatically, in which case it arrives within 14 days of the date on the letter. Underpayments are usually collected by adjusting next year's tax code. Self Assessment filers reconcile through their return and get no P800.` },
  ],
  'tax-year-comparison-calculator': [
    { question: `Why is my take-home pay the same in 2026/27 as last year?`, answer: `Because the rUK income tax thresholds are frozen. The Personal Allowance has been £12,570 and the higher-rate threshold £50,270 since April 2021, and both stay put until April 2031. Employee National Insurance (8% and 2%) and its thresholds are unchanged too. The freeze is a tax rise in disguise, known as fiscal drag: if your pay rises 4% with inflation but the tax-free and basic-rate bands do not move, a bigger slice of your income is taxed, and at higher rates. The OBR estimates the freeze, extended at Budget 2025, will pull millions of people into tax or into higher bands.` },
    { question: `What actually changed in April 2026?`, answer: `The genuine movers were these. Scottish starter and basic bands were uprated, starter now to £16,537 and basic to £29,526, slightly cutting Scottish bills. Student loan repayment thresholds rose with RPI, Plan 1 to £26,900, Plan 2 to £29,385 and Plan 4 to £33,795, reducing graduate repayments by up to £75.15, £82.35 and £94.50 a year respectively. Dividend tax rose 2 percentage points under Budget 2025, to 10.75% and 35.75%. The National Living Wage went from £12.21 to £12.71 an hour, and benefits, statutory pays and the State Pension were uprated. Employer NI stayed at 15% with the £5,000 secondary threshold.` },
    { question: `Who is worse off in 2026/27?`, answer: `Mainly people taking income as dividends. A company director drawing £30,000 in dividends pays £590 more tax than in 2025/26, because the 2-point rise to 10.75% and 35.75% applies to the £29,500 above the £500 allowance. Higher earners also lose more in real terms from the threshold freeze, since someone whose salary rose 5% into the £50,270 zone pays 40% on the increase where an uprated threshold would have spared part of it. Savers face the same frozen Personal Savings Allowance, and graduates on Plan 5 get no uprating either, theirs being frozen at £25,000 until 2027.` },
    { question: `Do Scottish taxpayers pay less income tax in 2026/27?`, answer: `A little, at most income levels. The starter band now runs to £16,537 and the basic band to £29,526, both uprated for 2026/27, which saves up to £31.75 a year, about £2.65 a month. The saving reaches that ceiling at £29,526 and grows no further, because the Scottish higher-rate threshold is frozen at £43,662. Choose Scotland in the calculator and both tax years are worked on Scottish bands, so the comparison reflects the Scottish position rather than the rUK one.` },
  ],
  'nhs-pension-calculator': [
    { question: `How does the NHS 2015 pension build up each year?`, answer: `It is a career-average scheme rather than a pot of invested money. Each scheme year you bank 1/54 of that year's pensionable pay as annual pension, which on £38,000 comes to £703.70. While you stay in NHS employment, everything already banked is revalued each April at CPI + 1.5%, so it grows faster than prices. After a full career the result is a guaranteed, index-linked income for life from State Pension age, alongside generous ill-health and death-in-service cover.` },
    { question: `Is the NHS pension worth the contributions on a tight budget?`, answer: `Contributions are deducted before tax, so a 9.8% headline rate nets down to roughly 7.8% of gross pay at basic rate, about £310 a month before relief and £248 after it. What that money buys is index-linked income for life: a year worked at £38,000 would cost £15,000 to £20,000 to replicate as an annuity on the open market. Add the 23.7% paid in by the employer and opting out means handing back a slice of your salary.` },
    { question: `What happens to my service before April 2022?`, answer: `It sits in the legacy 1995 or 2008 sections and is worked out on final-salary rules, with different Normal Pension Ages of 60 and 65, then paid in addition to your 2015 CARE pension. For the remedy period between April 2015 and March 2022, the McCloud age-discrimination ruling lets affected members pick whichever of the legacy or 2015 benefits is better for those seven years, decided at retirement. Your Total Reward Statement lists each element separately.` },
    { question: `Can I take my NHS pension before State Pension age?`, answer: `Yes, from age 55, rising to 57 from April 2028, though the 2015-scheme pension is actuarially reduced by roughly 4% to 5% for every year drawn early, so going five years ahead of State Pension age costs around 20% to 23% for life. Members soften that by buying Early Retirement Reduction Buy Out (ERRBO) during their career, by building AVCs or a SIPP to bridge the early years, or by using partial retirement, which since October 2023 allows up to 100% of the pension to be drawn while working reduced hours.` },
  ],
  'lgps-pension-calculator': [
    { question: `How much pension does a full LGPS career produce?`, answer: `Each scheme year you earn 1/49 of your actual pensionable pay, including non-contractual overtime, and everything already earned is revalued each April with CPI. A salary of £30,000 banks £612 of annual pension for the year. Over 30 years, with inflation protection running throughout, that compounds to roughly £20,000 a year or more, payable from your State Pension age. Membership before April 2014 was worked out on final-salary rules at 1/60 or 1/80 and is paid on top.` },
    { question: `What is the LGPS 50/50 section and how do I join it?`, answer: `It is the scheme's built-in affordability option: half the contribution rate for half the build-up. While you are in it you keep full death-in-service life cover at 3 times pay and full ill-health protection, which is what separates it from opting out altogether. Election is a simple form to your employer and you can switch back at any time. Because it exists to keep people in the scheme during a squeeze on household budgets, your employer must re-enrol you into the main section at each auto-enrolment cycle.` },
    { question: `Why do part-time LGPS members pay a lower contribution band?`, answer: `Bands in England and Wales are set on actual pay rather than the full-time-equivalent salary, so someone working part time on about £17,800 pays the 5.5% band even where the full-time rate for that job sits much higher. Rates climb to 12.5% above £203,000. Tax relief applies on the way in, so a 6.5% contribution really costs about 5.2% of gross at basic rate. Thresholds are uprated each April and your payslip shows the rate actually applied.` },
    { question: `Can I take my LGPS pension early without a reduction?`, answer: `Usually not, because drawing before Normal Pension Age cuts the pension by roughly 4% to 5% for each year taken early. Two exceptions matter. The rule of 85 may reduce or remove those reductions for members who joined before October 2006, and redundancy or dismissal on business-efficiency grounds from age 55 triggers immediate unreduced payment. Flexible or partial retirement from 55 is also possible with your employer's consent, letting you draw part of the pension while still working.` },
  ],
  'adoption-pay-calculator': [
    { question: `Who qualifies for Statutory Adoption Pay?`, answer: `You must be an employee, or an agency worker with employee-level earnings, with 26 weeks of continuous service by the end of the matching week, the week the adoption agency officially matches you with a child. You also need average earnings at or above the Lower Earnings Limit across the 8 weeks before matching. Only one partner in a couple can claim SAP for a placement, while the other may claim statutory paternity pay. Self-employed adopters do not qualify at all. Source: GOV.UK.` },
    { question: `How much is adoption pay and for how long?`, answer: `The first 6 weeks are paid at 90% of your average weekly earnings with no upper cap, then 33 further weeks at £194.32 a week in 2026/27, or 90% of earnings if that is lower. That gives 39 paid weeks in total out of a possible 52 weeks of leave, leaving the final 13 unpaid at statutory level. Pay starts when your leave starts, which can be up to 14 days before the placement date for UK adoptions. Source: GOV.UK.` },
    { question: `Can we share adoption leave between partners?`, answer: `Yes. The primary adopter can curtail their adoption leave and pay and convert the balance into Shared Parental Leave and Pay, giving up to 50 weeks of leave and 37 weeks of pay to divide between you, taken together or in turns and in up to three blocks each. The other partner separately has the right to 2 weeks of statutory paternity pay at the placement, which does not depend on any of the shared arrangements. Source: GOV.UK.` },
  ],
}
